// src/data/hsk5Vocab.ts
var hsk5Vocab = [];

// src/data/hsk6Vocab.ts
var hsk6Vocab = [];

// src/data/vocab.ts
var vocabByLevel = {
  1: hsk1Vocab,
  2: hsk2Vocab,
  3: hsk3Vocab,
  4: hsk4Vocab,
  5: hsk5Vocab,
  6: hsk6Vocab
};
var allVocab = [
  ...hsk1Vocab,
  ...hsk2Vocab,
  ...hsk3Vocab,
  ...hsk4Vocab,
  ...hsk5Vocab,
  ...hsk6Vocab
];
var getVocabByLevel = (level) => vocabByLevel[level] ?? [];

// src/lib/mcp/tools/search-vocabulary.ts
var search_vocabulary_default = defineTool({
  name: "search_vocabulary",
  title: "Search HSK vocabulary",
  description: "Search the HSK 1-6 vocabulary bank of HSK Hub by hanzi, pinyin or English meaning. Optionally filter by HSK level.",
  inputSchema: {
    query: z.string().describe("Hanzi, pinyin or English meaning to search for. Leave empty to browse by level."),
    level: z.number().int().optional().describe("HSK level filter, 1 to 6."),
    limit: z.number().int().optional().describe("Maximum number of words to return (default 20, max 100).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, level, limit }) => {
    const max = Math.min(Math.max(limit ?? 20, 1), 100);
    const pool = level && level >= 1 && level <= 6 ? getVocabByLevel(level) : allVocab;
    const q = (query ?? "").trim().toLowerCase();
    const matches = (q ? pool.filter(
      (w) => w.hanzi.includes(q) || w.pinyin.toLowerCase().includes(q) || w.meaning.toLowerCase().includes(q)
    ) : pool).slice(0, max);
    const rows = matches.map((w) => ({
      hanzi: w.hanzi,
      pinyin: w.pinyin,
      pos: w.pos,
      meaning: w.meaning,
      level: w.level,
      example: w.example
    }));
    return {
      content: [
        {
          type: "text",
          text: rows.length === 0 ? "No matching vocabulary found." : rows.map((r) => `HSK${r.level} ${r.hanzi} (${r.pinyin}) [${r.pos}] \u2014 ${r.meaning}
  \u4F8B: ${r.example.chinese} \u2014 ${r.example.english}`).join("\n")
        }
      ],
      structuredContent: { count: rows.length, words: rows }
    };
  }
});

