var allGrammar = [
  ...hsk1Grammar,
  ...hsk2Grammar,
  ...hsk3Grammar,
  ...hsk4Grammar,
  ...hsk5Grammar,
  ...hsk6Grammar
];
var getGrammarByLevel = (level) => allGrammar.filter((g) => g.level === level);

// src/lib/mcp/tools/search-grammar.ts
var search_grammar_default = defineTool2({
  name: "search_grammar",
  title: "Search HSK grammar points",
  description: "Search HSK Hub's HSK 1-6 grammar reference by pattern, name or explanation, with structure formula and examples.",
  inputSchema: {
    query: z2.string().describe("Pattern, keyword or English explanation to search for. Leave empty to browse by level."),
    level: z2.number().int().optional().describe("HSK level filter, 1 to 6."),
    limit: z2.number().int().optional().describe("Maximum number of grammar points to return (default 10, max 40).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, level, limit }) => {
    const max = Math.min(Math.max(limit ?? 10, 1), 40);
    const pool = level && level >= 1 && level <= 6 ? getGrammarByLevel(level) : allGrammar;
    const q = (query ?? "").trim().toLowerCase();
    const matches = (q ? pool.filter(
      (g) => g.pattern.toLowerCase().includes(q) || g.name.toLowerCase().includes(q) || g.explanation.toLowerCase().includes(q) || g.structure.toLowerCase().includes(q)
    ) : pool).slice(0, max);
    const rows = matches.map((g) => ({
      level: g.level,
      pattern: g.pattern,
      name: g.name,
      category: g.category,
      structure: g.structure,
      explanation: g.explanation,
      examples: g.examples.slice(0, 3)
    }));
    return {
      content: [
        {
          type: "text",
          text: rows.length === 0 ? "No matching grammar point found." : rows.map(
            (r) => `HSK${r.level} ${r.pattern} \u2014 ${r.name}
  Structure: ${r.structure}
  ${r.explanation}
` + r.examples.map((e) => `  \u4F8B: ${e.chinese} (${e.pinyin}) \u2014 ${e.english}`).join("\n")
          ).join("\n\n")
        }
      ],
      structuredContent: { count: rows.length, grammar: rows }
    };
  }
});

