var SHUOSHUO_BANGKOK_MORNING_V6SRJHDISDS_TRANSLATIONS = [
  `N\u1EBFu ph\u1EA3i n\xF3i v\u1EC1 th\xF3i quen bu\u1ED5i s\xE1ng c\u1EE7a t\xF4i,`,
  `Th\xEC t\xF4i ph\u1EA3i n\xF3i v\u1EC1 th\xF3i quen bu\u1ED5i chi\u1EC1u c\u1EE7a t\xF4i tr\u01B0\u1EDBc.`,
  `\xC0i. Th\xF3i quen bu\u1ED5i chi\u1EC1u c\u1EE7a t\xF4i r\u1EA5t \u0111\u01A1n gi\u1EA3n:`,
  `Ng\u1EE7, ch\u01A1i \u0111i\u1EC7n tho\u1EA1i,`,
  `Xem TV. B\u1EA1n \u0111\u1EBFn mu\u1ED9n kh\xF4ng \u1EDF \u0111\xF3.`,
  `T\xF4i bi\u1EBFt nhi\u1EC1u ng\u01B0\u1EDDi th\xE0nh c\xF4ng th\xEDch d\u1EADy r\u1EA5t s\u1EDBm,`,
  `Nh\u01B0ng, \u1EEBm \u1EEBm, \u0111\xE2y kh\xF4ng ph\u1EA3i l\xFD do t\xF4i d\u1EADy s\u1EDBm.`,
  `L\xFD do t\xF4i d\u1EADy l\xFAc 5 r\u01B0\u1EE1i s\xE1ng m\u1ED7i ng\xE0y r\u1EA5t \u0111\u01A1n gi\u1EA3n,`,
  `\u0110\xF3 l\xE0 \u2014 sau khi \u0103n tr\u01B0a t\xF4i kh\xF4ng th\u1EC3 l\xE0m vi\u1EC7c,`,
  `Kh\xF4ng th\u1EC3 h\u1ECDc, kh\xF4ng th\u1EC3 \u0111\u1ECDc s\xE1ch,`,
  `Kh\xF4ng th\u1EC3 l\xE0m b\u1EA5t c\u1EE9 \u0111i\u1EC1u g\xEC.`,
  `T\xF4i \u0111\xE1nh r\u0103ng trong nh\xE0 v\u1EC7 sinh.`,
  `T\xF4i r\u1EEDa m\u1EB7t trong nh\xE0 v\u1EC7 sinh.`,
  `T\xF4i \u0111i v\u1EC7 sinh trong nh\xE0 v\u1EC7 sinh.`,
  `B\xE2y gi\u1EDD t\xF4i s\u1EBD \u0111un n\u01B0\u1EDBc,`,
  `pha c\xE0 ph\xEA. T\xF4i kh\xF4ng d\xF9ng m\xE1y pha c\xE0 ph\xEA,`,
  `v\xEC t\xF4i th\u1EA5y n\xF3 kh\xE1 phi\u1EC1n ph\u1EE9c,`,
  `n\xEAn t\xF4i d\xF9ng n\u01B0\u1EDBc n\xF3ng pha tr\u1EF1c ti\u1EBFp.`,
  `T\xF4i r\u1EA5t th\xEDch c\u1EE5m t\u1EEB "n\u01B0\u1EDBc s\xF4i r\u1ED3i",`,
  `th\u1EADt th\xFA v\u1ECB. N\u01B0\u1EDBc s\xF4i l\xE0 n\u01B0\u1EDBc n\xF3ng,`,
  `r\u1EA5t n\xF3ng r\u1ED3i,`,
  `100 \u0111\u1ED9 r\u1ED3i.`,
  `B\u1EA1n nh\xECn h\xECnh d\xE1ng n\u01B0\u1EDBc s\xF4i xem,`,
  `c\xF3 gi\u1ED1ng nh\u01B0 r\u1EA5t nhi\u1EC1u b\xF4ng hoa \u0111ang n\u1EDF kh\xF4ng?`,
  `V\xEC v\u1EADy, t\xF4i th\u1EA5y c\u1EE5m t\u1EEB n\xE0y \u0111\u1EB7c bi\u1EC7t th\xFA v\u1ECB.`,
  `Ch\xE0o bu\u1ED5i s\xE1ng nha, \u0111\xE2y l\xE0 kho\u1EA3ng th\u1EDDi gian t\xF4i y\xEAu th\xEDch nh\u1EA5t trong ng\xE0y.`,
  `Ng\u1ED3i tr\xEAn ban c\xF4ng,`,
  `v\u1EEBa u\u1ED1ng c\xE0 ph\xEA v\u1EEBa \u0111\u1ECDc s\xE1ch.`,
  `B\xEAn ngo\xE0i nh\xE0 t\xF4i b\xE2y gi\u1EDD c\xF3 r\u1EA5t nhi\u1EC1u t\xF2a nh\xE0 cao t\u1EA7ng,`,
  `t\xF2a nh\xE0 r\u1EA5t cao. Tr\u01B0\u1EDBc \u0111\xE2y t\xF4i s\u1ED1ng \u1EDF n\u01A1i kh\xE1c,`,
  `B\xEAn ngo\xE0i nh\xE0 t\xF4i l\xE0 m\u1ED9t ng\u1ECDn n\xFAi.`,
  `T\xF4i r\u1EA5t th\xEDch n\u01A1i \u0111\xF3.`,
  `C\xF2n b\u1EA1n? N\u1EBFu b\u1EA1n ng\u1ED3i tr\xEAn ban c\xF4ng,`,
  `B\u1EA1n mu\u1ED1n nh\xECn th\u1EA5y nh\u1EEFng t\xF2a nh\xE0 cao t\u1EA7ng hay nh\u1EEFng ng\u1ECDn n\xFAi?`,
  `Ph\xF2ng n\xE0y l\xE0 studio l\xE0m vi\u1EC7c c\u1EE7a t\xF4i.`,
  `Tr\u01B0\u1EDBc \u0111\xE2y \u0111\xE2y l\xE0 m\u1ED9t ph\xF2ng ng\u1EE7.`,
  `B\u1EA1n th\u1EA5y \u0111\u1EA5y, \u1EDF \u0111\xE2y v\u1EABn c\xF2n m\u1ED9t c\xE1i t\u1EE7 qu\u1EA7n \xE1o,`,
  `l\xE0 c\xE1i t\u1EE7 \u0111\u1EC3 qu\u1EA7n \xE1o.`,
  `Nh\u01B0ng b\xE2y gi\u1EDD,`,
  `n\xF3 l\xE0 studio l\xE0m vi\u1EC7c c\u1EE7a t\xF4i.`,
  `H\xE0ng ng\xE0y t\xF4i l\xE0m vi\u1EC7c \u1EDF \u0111\xE2y,`,
  `d\u1EA1y h\u1ECDc, quay video,`,
  `d\u1EF1ng video. M\u1ED7i s\xE1ng,`,
  `l\xE0 l\xFAc \u0111\u1EA7u \xF3c t\xF4i minh m\u1EABn nh\u1EA5t.`,
  `V\xEC v\u1EADy, bu\u1ED5i s\xE1ng t\xF4i s\u1EBD l\xE0m nh\u1EEFng vi\u1EC7c c\u1EA7n suy ngh\u0129,`,
  `c\xF4ng vi\u1EC7c c\u1EA7n \u0111\u01B0\u1EE3c t\u1EA1o ra.`,
  `V\xED d\u1EE5, ngh\u0129 xem video c\u1EE7a t\xF4i s\u1EBD quay v\u1EC1 c\xE1i g\xEC,`,
  `v\xED d\u1EE5, thi\u1EBFt k\u1EBF kh\xF3a h\u1ECDc c\u1EE7a m\xECnh,`,
  `l\xE0m th\u1EBF n\xE0o \u0111\u1EC3 kh\xF3a h\u1ECDc c\u1EE7a t\xF4i v\u1EEBa h\u1EEFu \xEDch v\u1EEBa th\xFA v\u1ECB.`,
  `\u1EEAm \u1EEBm, \u0111\xE3 thay m\u1ED9t b\u1ED9 \u0111\u1ED3 kh\xE1c.`,
  `Thay m\u1ED9t b\u1ED9 \u0111\u1ED3 kh\xE1c.`,
  `B\xE2y gi\u1EDD l\xE0 bu\u1ED5i s\xE1ng,`,
  `Xem n\xE0o, 7 gi\u1EDD 07 ph\xFAt.`,
  `8 gi\u1EDD r\u01B0\u1EE1i s\xE1ng t\xF4i c\xF3 m\u1ED9t ti\u1EBFt h\u1ECDc,`,
  `v\xEC v\u1EADy t\u1EEB b\xE2y gi\u1EDD \u0111\u1EBFn 8 r\u01B0\u1EE1i l\xE0 th\u1EDDi gian l\xE0m vi\u1EC7c c\u1EE7a t\xF4i.`,
  `S\xE1ng nay t\xF4i ph\u1EA3i ho\xE0n th\xE0nh nh\u1EEFng c\xF4ng vi\u1EC7c n\xE0y.`,
  `B\xE2y gi\u1EDD t\xF4i \u0111ang d\xF9ng ph\u01B0\u01A1ng ph\xE1p Pomodoro n\xE0y.`,
  `T\u1EE9c l\xE0 t\xF4i s\u1EBD l\xE0m vi\u1EC7c 35 ph\xFAt,`,
  `sau \u0111\xF3 t\xF4i s\u1EBD ngh\u1EC9 5 ph\xFAt.`,
  `C\xF3 th\u1EC3 \u0111\u1EE9ng d\u1EADy \u0111i l\u1EA1i m\u1ED9t ch\xFAt,`,
  `C\xF3 th\u1EC3 t\u1EADp th\u1EC3 d\u1EE5c, ho\u1EB7c nh\xECn ra ngo\xE0i v\xE0 m\u01A1 m\u1ED9ng.`,
  `B\xE2y gi\u1EDD l\xE0 8 gi\u1EDD 25 ph\xFAt,`,
  `5 ph\xFAt n\u1EEFa t\xF4i s\u1EBD b\u1EAFt \u0111\u1EA7u ti\u1EBFt h\u1ECDc.`,
  `\u0110\xE2y l\xE0 m\u1ED9t l\u1EDBp h\u1ECDc tr\xECnh \u0111\u1ED9 trung c\u1EA5p v\xE0 cao c\u1EA5p.`,
  `H\u1ECDc sinh c\u1EE7a t\xF4i c\xF3 tr\xECnh \u0111\u1ED9 HSK5,`,
  `6. \xD4ng ch\u1EE7 n\xE0y, b\u1EA1n mu\u1ED1n nh\xE2n vi\xEAn c\u1EE7a m\xECnh l\xE0m vi\u1EC7c ch\u0103m ch\u1EC9 h\u01A1n,`,
  `V\xEC v\u1EADy b\u1EA1n s\u1EBD n\xF3i m\u1ED9t s\u1ED1 \u0111i\u1EC1u b\u1EA1n c\xF3 th\u1EC3 nh\u1EADn \u0111\u01B0\u1EE3c,`,
  `V\xED d\u1EE5, sau khi b\u1EA1n th\xE0nh c\xF4ng, b\u1EA1n c\xF3 th\u1EC3 nh\u1EADn \u0111\u01B0\u1EE3c n\xF3.`,
  `V\u1EBD th\xF4i. \xC0, anh \u1EA5y v\u1EBD m\u1ED9t c\xE1i b\xE1nh hay m\u1ED9t t\u1EA3ng b\u0103ng?`,
  `B\u0103ng. Hahaha.`,
  `B\xE1nh. N\xE0y, b\xE1nh. B\xE1nh quy.`,
  `B\xE1nh quy. V\u1EBD b\xE1nh (ve\u0303 vo\u0300ng).`,
  `K\u1EBFt th\xFAc gi\u1EDD h\u1ECDc r\u1ED3i. B\xE2y gi\u1EDD t\xF4i ph\u1EA3i \u0111\u1EBFn qu\xE1n c\xE0 ph\xEA l\xE0m vi\u1EC7c ngay,`,
  `B\u1EDFi v\xEC n\u1EBFu t\xF4i l\xE0m vi\u1EC7c \u1EDF nh\xE0,`,
  `T\xF4i s\u1EBD mu\u1ED1n ngh\u1EC9 ng\u01A1i.`,
  `N\u1EBFu t\xF4i ngh\u1EC9 ng\u01A1i,`,
  `H\xF4m nay t\xF4i s\u1EBD kh\xF4ng l\xE0m vi\u1EC7c \u0111\u01B0\u1EE3c,`,
  `V\xEC v\u1EADy t\xF4i s\u1EBD thu d\u1ECDn \u0111\u1ED3 \u0111\u1EA1c ngay,`,
  `V\xE0 \u0111i \u0111\u1EBFn qu\xE1n c\xE0 ph\xEA \u0111\u1EC3 l\xE0m vi\u1EC7c.`,
  `B\xE2y gi\u1EDD l\xE0 10 gi\u1EDD 27 ph\xFAt s\xE1ng.`,
  `T\xF4i s\u1EBD l\xE0m vi\u1EC7c \u1EDF \u0111\xE2y cho \u0111\u1EBFn 12 gi\u1EDD r\u01B0\u1EE1i,`,
  `Sau \u0111\xF3 t\xF4i c\xF3 th\u1EC3 ngh\u1EC9 ng\u01A1i.`,
  `V\u1EADy \u0111\xF3 l\xE0 th\xF3i quen c\u1EE7a t\xF4i t\u1EEB 5 gi\u1EDD s\xE1ng \u0111\u1EBFn 12 gi\u1EDD tr\u01B0a.`,
  `C\xF2n b\u1EA1n? Th\xF3i quen c\u1EE7a b\u1EA1n c\xF3 gi\u1ED1ng t\xF4i kh\xF4ng?`,
  `B\u1EA1n th\xEDch ho\xE0n th\xE0nh m\u1ECDi vi\u1EC7c v\xE0o bu\u1ED5i s\xE1ng,`,
  `Hay th\xEDch l\xE0m t\u1EEB t\u1EEB m\u1ED9t ch\xFAt v\xE0o bu\u1ED5i s\xE1ng,`,
  `M\u1ED9t ch\xFAt v\xE0o bu\u1ED5i chi\u1EC1u,`,
  `V\xE0 m\u1ED9t ch\xFAt n\u1EEFa v\xE0o bu\u1ED5i t\u1ED1i?`,
  `Ch\xE0o m\u1EEBng b\u1EA1n chia s\u1EBB v\u1EDBi ch\xFAng t\xF4i trong ph\u1EA7n b\xECnh lu\u1EADn.`,
  `V\u1EADy th\xEC ch\xFAng ta g\u1EB7p nhau \u1EDF video ti\u1EBFp theo nh\xE9.`,
  `T\u1EA1m bi\u1EC7t.`
];
