var TEDED_GREAT_WALL_2G0HCWRL2Y8_TRANSLATIONS = [
  `M\u1ED9t con r\u1ED3ng \u0111\u1EA5t \u0111\xE1 d\xE0i 13.000 d\u1EB7m,`,
  `u\u1ED1n l\u01B0\u1EE3n gi\u1EEFa nh\u1EEFng v\xF9ng n\xF4ng th\xF4n Trung Qu\u1ED1c.`,
  `L\u1ECBch s\u1EED c\u1EE7a n\xF3 c\u0169ng l\xE2u d\xE0i v\xE0 quanh co nh\u01B0 ch\xEDnh c\u1EA5u tr\xFAc c\u1EE7a n\xF3.`,
  `V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh ban \u0111\u1EA7u l\xE0 m\u1ED9t t\u1EADp h\u1EE3p c\xE1c b\u1EE9c t\u01B0\u1EDDng \u0111\u1EA5t n\u1EC7n,`,
  `\u0111\u01B0\u1EE3c x\xE2y d\u1EF1ng b\u1EDFi c\xE1c qu\u1ED1c gia phong ki\u1EBFn \u0111\u1ED9c l\u1EADp trong th\u1EDDi Xu\xE2n Thu Chi\u1EBFn Qu\u1ED1c,`,
  `\u0111\u1EC3 ch\u1ED1ng l\u1EA1i nh\u1EEFng k\u1EBB x\xE2m l\u01B0\u1EE3c du m\u1EE5c t\u1EEB mi\u1EC1n b\u1EAFc Trung Qu\u1ED1c v\xE0 c\xE1c qu\u1ED1c gia kh\xE1c.`,
  `N\u0103m 221 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn,`,
  `khi T\u1EA7n Th\u1EE7y Ho\xE0ng th\u1ED1ng nh\u1EA5t Trung Qu\u1ED1c,`,
  `cao nguy\xEAn Thanh T\u1EA1ng v\xE0 Th\xE1i B\xECnh D\u01B0\u01A1ng tr\u1EDF th\xE0nh r\xE0o c\u1EA3n t\u1EF1 nhi\xEAn c\u1EE7a qu\u1ED1c gia,`,
  `nh\u01B0ng c\xE1c d\xE3y n\xFAi ph\xEDa b\u1EAFc v\u1EABn r\u1EA5t d\u1EC5 b\u1ECB ng\u01B0\u1EDDi M\xF4ng C\u1ED5,`,
  `Th\u1ED5 Nh\u0129 K\u1EF3 v\xE0 Hung N\xF4 x\xE2m l\u01B0\u1EE3c.`,
  `\u0110\u1EC3 ch\u1ED1ng l\u1EA1i ngo\u1EA1i x\xE2m,`,
  `T\u1EA7n Th\u1EE7y Ho\xE0ng \u0111\xE3 m\u1EDF r\u1ED9ng c\xE1c b\u1EE9c t\u01B0\u1EDDng nh\u1ECF \u0111\u01B0\u1EE3c x\xE2y d\u1EF1ng tr\u01B0\u1EDBc \u0111\xF3,`,
  `c\u1EE7ng c\u1ED1 ch\xFAng,`,
  `v\xE0 n\u1ED1i ch\xFAng l\u1EA1i v\u1EDBi nhau.`,
  `C\u1EA5u tr\xFAc t\u01B0\u1EDDng th\xE0nh b\u1EAFt \u0111\u1EA7u t\u1EEB L\xE2m Thao \u1EDF ph\xEDa T\xE2y,`,
  `K\u1EBFt th\xFAc \u1EDF Li\xEAu \u0110\xF4ng ph\xEDa \u0110\xF4ng,`,
  `C\u1EA3 hai \u0111\u01B0\u1EE3c g\u1ECDi l\xE0 "V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh".`,
  `\u0110\u1EC3 ho\xE0n th\xE0nh c\xF4ng tr\xECnh n\xE0y,`,
  `T\u1EA7n Th\u1EE7y Ho\xE0ng \u0111\xE3 tri\u1EC7u t\u1EADp binh l\xEDnh v\xE0 th\u01B0\u1EDDng d\xE2n,`,
  `Vi\u1EC7c n\xE0y th\u01B0\u1EDDng kh\xF4ng d\u1EF1a tr\xEAn s\u1EF1 t\u1EF1 nguy\u1EC7n.`,
  `Trong s\u1ED1 h\xE0ng ng\xE0n th\u1EE3 x\xE2y \u0111\u01B0\u1EE3c ghi nh\u1EADn d\u01B0\u1EDBi th\u1EDDi T\u1EA7n,`,
  `Nhi\u1EC1u ng\u01B0\u1EDDi l\xE0 n\xF4ng d\xE2n b\u1ECB c\u01B0\u1EE1ng b\u1EE9c lao \u0111\u1ED9ng,`,
  `M\u1ED9t s\u1ED1 kh\xE1c l\xE0 t\xF9 nh\xE2n \u0111ang trong th\u1EDDi gian ch\u1EA5p h\xE0nh \xE1n.`,
  `V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh ti\u1EBFp t\u1EE5c \u0111\u01B0\u1EE3c m\u1EDF r\u1ED9ng d\u01B0\u1EDBi th\u1EDDi nh\xE0 H\xE1n,`,
  `K\xE9o d\xE0i 3700 d\u1EB7m,`,
  `T\u1EEB \u0110\xF4n Ho\xE0ng \u0111\u1EBFn B\u1ED9t H\u1EA3i.`,
  `Lao \u0111\u1ED9ng c\u01B0\u1EE1ng b\u1EE9c ti\u1EBFp t\u1EE5c d\u01B0\u1EDBi th\u1EDDi H\xE1n V\u0169 \u0110\u1EBF,`,
  `Do \u0111\xF3, b\u1EE9c t\u01B0\u1EDDng th\xE0nh n\u1ED5i ti\u1EBFng l\xE0 n\u01A1i ch\u1ECBu \u0111\u1EF1ng \u0111au kh\u1ED5.`,
  `Th\u01A1 ca v\xE0 truy\u1EC1n thuy\u1EBFt th\u1EDDi k\u1EF3 \u0111\xF3 m\xF4 t\u1EA3 nh\u1EEFng ng\u01B0\u1EDDi lao \u0111\u1ED9ng b\u1ECB ch\xF4n v\xF9i trong nh\u1EEFng ng\xF4i m\u1ED9 t\u1EADp th\u1EC3 g\u1EA7n \u0111\xF3,`,
  `Th\u1EADm ch\xED c\u1EA3 b\xEAn trong Tr\u01B0\u1EDDng Th\xE0nh.`,
  `Tuy nhi\xEAn, b\xEAn trong t\u01B0\u1EDDng th\xE0nh kh\xF4ng t\xECm th\u1EA5y m\u1ED9 t\u1EADp th\u1EC3 ch\u1EE9a h\xE0i c\u1ED1t ng\u01B0\u1EDDi,`,
  `\u0110i\u1EC1u n\xE0y cho th\u1EA5y h\u1EA7u h\u1EBFt nh\u1EEFng ng\u01B0\u1EDDi lao \u0111\u1ED9ng \u0111\xE3 ch\u1EBFt v\xEC tai n\u1EA1n,`,
  `\u0110\xF3i kh\xE1t v\xE0 ki\u1EC7t s\u1EE9c.`,
  `V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh th\u1EADt \u0111\xE1ng s\u1EE3,`,
  `Nh\u01B0ng kh\xF4ng ph\u1EA3i l\xE0 kh\xF4ng th\u1EC3 v\u01B0\u1EE3t qua.`,
  `Th\xE0nh C\xE1t T\u01B0 H\xE3n v\xE0 con trai H\u1ED1t T\u1EA5t Li\u1EC7t \u0111\xE3 v\u01B0\u1EE3t qua \u0111\u01B0\u1EE3c b\u1EE9c t\u01B0\u1EDDng th\xE0nh khi M\xF4ng C\u1ED5 x\xE2m l\u01B0\u1EE3c v\xE0o th\u1EBF k\u1EF7 13.`,
  `Sau khi nh\xE0 Minh l\xEAn n\u1EAFm quy\u1EC1n v\xE0o n\u0103m 1368,`,
  `H\u1ECD b\u1EAFt \u0111\u1EA7u s\u1EED d\u1EE5ng g\u1EA1ch v\xE0 \u0111\xE1 nung t\u1EEB c\xE1c l\xF2 \u0111\u1ECBa ph\u01B0\u01A1ng,`,
  `\u0110\u1EC3 c\u1EE7ng c\u1ED1 v\xE0 gia c\u1ED1 l\u1EA1i V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh.`,
  `Tr\u01B0\u1EDDng Th\xE0nh c\xF3 chi\u1EC1u cao trung b\xECnh 7 m\xE9t,`,
  `R\u1ED9ng 6 m\xE9t. D\u1ECDc theo b\u1EE9c t\u01B0\u1EDDng th\xE0nh d\xE0i 5500 d\u1EB7m c\xF3 c\xE1c th\xE1p canh,`,
  `M\u1ED9t khi ph\xE1t hi\u1EC7n qu\xE2n x\xE2m l\u01B0\u1EE3c, c\xE1c th\xE1p canh s\u1EBD truy\u1EC1n t\xEDn hi\u1EC7u b\u1EB1ng kh\xF3i v\xE0 l\u1EEDa`,
  `Cho \u0111\u1EBFn khi qu\xE2n ti\u1EBFp vi\u1EC7n \u0111\u1EBFn.`,
  `C\xE1c l\u1ED7 nh\u1ECF tr\xEAn t\u01B0\u1EDDng th\xE0nh cho ph\xE9p cung th\u1EE7 b\u1EAFn xuy\xEAn qua nh\u1EEFng k\u1EBB x\xE2m l\u01B0\u1EE3c,`,
  `L\u1ED7 l\u1EDBn d\xF9ng \u0111\u1EC3 n\xE9m \u0111\xE1 ho\u1EB7c c\xE1c v\u1EADt kh\xE1c.`,
  `Nh\u01B0ng ngay c\u1EA3 b\u1EE9c t\u01B0\u1EDDng th\xE0nh c\u1EA3i ti\u1EBFn n\xE0y v\u1EABn ch\u01B0a \u0111\u1EE7 t\u1ED1t.`,
  `N\u0103m 1644,`,
  `ng\u01B0\u1EDDi M\xE3n Ch\xE2u t\u1EEB ph\xEDa b\u1EAFc l\u1EADt \u0111\u1ED5 nh\xE0 Minh,`,
  `th\xE0nh l\u1EADp nh\xE0 Thanh,`,
  `\u0111\u1ED3ng th\u1EDDi s\xE1p nh\u1EADp M\xF4ng C\u1ED5.`,
  `Do \u0111\xF3, \u0111\xE2y l\xE0 l\u1EA7n th\u1EE9 hai Trung Qu\u1ED1c b\u1ECB cai tr\u1ECB b\u1EDFi ngo\u1EA1i bang m\xE0 h\u1ECD t\u1EEBng mu\u1ED1n \u0111\u1EA9y l\xF9i b\u1EB1ng V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh.`,
  `Khi bi\xEAn gi\u1EDBi \u0111\u1EBF ch\u1EBF m\u1EDF r\u1ED9ng ra ngo\xE0i V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh,`,
  `Nh\u1EEFng c\xF4ng s\u1EF1 n\xE0y m\u1EA5t \u0111i m\u1EE5c \u0111\xEDch ban \u0111\u1EA7u,`,
  `Kh\xF4ng \u0111\u01B0\u1EE3c gia c\u1ED1 \u0111\u1ECBnh k\u1EF3,`,
  `T\u01B0\u1EDDng th\xE0nh h\u01B0 h\u1ECFng n\u1EB7ng,`,
  `\u0110\u1EA5t n\u1EC7n b\u1ECB x\xF3i m\xF2n,`,
  `G\u1EA1ch v\xE0 \u0111\xE1 b\u1ECB \u0111\xE1nh c\u1EAFp l\xE0m v\u1EADt li\u1EC7u x\xE2y d\u1EF1ng,`,
  `Nh\u01B0ng s\u1EE9 m\u1EC7nh c\u1EE7a V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh v\u1EABn ch\u01B0a k\u1EBFt th\xFAc.`,
  `Trong Th\u1EBF chi\u1EBFn th\u1EE9 hai,`,
  `Trung Qu\u1ED1c s\u1EED d\u1EE5ng m\u1ED9t ph\u1EA7n V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh \u0111\u1EC3 ch\u1ED1ng l\u1EA1i s\u1EF1 x\xE2m l\u01B0\u1EE3c c\u1EE7a Nh\u1EADt B\u1EA3n,`,
  `m\u1ED9t ph\u1EA7n c\u1EE7a V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh v\u1EABn \u0111\u01B0\u1EE3c \u0111\u1ED3n \u0111\u1EA1i l\xE0 \u0111\u01B0\u1EE3c s\u1EED d\u1EE5ng cho hu\u1EA5n luy\u1EC7n qu\xE2n s\u1EF1.`,
  `Tuy nhi\xEAn, ng\xE0y nay v\u0103n h\xF3a m\u1EDBi l\xE0 m\u1EE5c \u0111\xEDch ch\xEDnh c\u1EE7a V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh.`,
  `L\xE0 m\u1ED9t trong nh\u1EEFng c\xF4ng tr\xECnh nh\xE2n t\u1EA1o l\u1EDBn nh\u1EA5t tr\xEAn Tr\xE1i \u0110\u1EA5t,`,
  `V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh \u0111\xE3 \u0111\u01B0\u1EE3c UNESCO c\xF4ng nh\u1EADn l\xE0 Di s\u1EA3n Th\u1EBF gi\u1EDBi v\xE0o n\u0103m 1987.`,
  `V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh ban \u0111\u1EA7u \u0111\u01B0\u1EE3c x\xE2y d\u1EF1ng \u0111\u1EC3 ph\xF2ng th\u1EE7, ng\u0103n ch\u1EB7n ng\u01B0\u1EDDi ngo\xE0i x\xE2m nh\u1EADp Trung Qu\u1ED1c,`,
  `nh\u01B0ng ng\xE0y nay \u0111\xF3n h\xE0ng tri\u1EC7u du kh\xE1ch m\u1ED7i n\u0103m.`,
  `Th\u1EF1c t\u1EBF, l\u01B0\u1EE3ng l\u1EDBn du kh\xE1ch \u0111\xE3 khi\u1EBFn V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh ng\xE0y c\xE0ng h\u01B0 h\u1EA1i,`,
  `bu\u1ED9c ch\xEDnh ph\u1EE7 Trung Qu\u1ED1c ph\u1EA3i kh\u1EDFi \u0111\u1ED9ng c\xE1c bi\u1EC7n ph\xE1p b\u1EA3o v\u1EC7.`,
  `N\xF3 c\u0169ng th\u01B0\u1EDDng \u0111\u01B0\u1EE3c tuy\xEAn b\u1ED1 l\xE0 c\xF4ng tr\xECnh nh\xE2n t\u1EA1o duy nh\u1EA5t c\xF3 th\u1EC3 nh\xECn th\u1EA5y t\u1EEB kh\xF4ng gian.`,
  `Kh\xF4ng may, tuy\xEAn b\u1ED1 n\xE0y kh\xF4ng ho\xE0n to\xE0n ch\xEDnh x\xE1c.`,
  `T\u1EEB qu\u1EF9 \u0111\u1EA1o Tr\xE1i \u0110\u1EA5t, nhi\u1EC1u c\xF4ng tr\xECnh kh\xE1c nhau nh\u01B0 c\u1EA7u,`,
  `\u0111\u01B0\u1EDDng cao t\u1ED1c v\xE0 s\xE2n bay \u0111\u1EC1u c\xF3 th\u1EC3 nh\xECn th\u1EA5y,`,
  `trong khi V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh l\u1EA1i m\u1EDD \u1EA3o,`,
  `v\xE0 ho\xE0n to\xE0n kh\xF4ng th\u1EC3 nh\xECn th\u1EA5y t\u1EEB M\u1EB7t Tr\u0103ng.`,
  `Nh\u01B0ng d\xF9 th\u1EBF n\xE0o \u0111i n\u1EEFa,`,
  `Tr\xE1i \u0111\u1EA5t m\u1EDBi l\xE0 n\u01A1i ch\xFAng ta n\xEAn nghi\xEAn c\u1EE9u k\u1EF9 V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh,`,
  `v\xEC c\u1EE9 v\xE0i n\u0103m l\u1EA1i c\xF3 nh\u1EEFng \u0111o\u1EA1n m\u1EDBi \u0111\u01B0\u1EE3c ph\xE1t hi\u1EC7n,`,
  `ch\xFAng m\u1EDF r\u1ED9ng t\u1EEB ph\u1EA7n ch\xEDnh,`,
  `kh\xF4ng ng\u1EEBng k\xE9o d\xE0i k\u1EF3 t\xEDch v\u0129 \u0111\u1EA1i n\xE0y, m\u1ED9t minh ch\u1EE9ng cho th\xE0nh t\u1EF1u c\u1EE7a nh\xE2n lo\u1EA1i.`,
  `Cung ho\xE0ng \u0111\u1EA1o c\u1EE7a b\u1EA1n l\xE0 g\xEC?`,
  `Trong 12 con gi\xE1p Trung Qu\u1ED1c,`,
  `n\u0103m sinh t\u01B0\u01A1ng \u1EE9ng v\u1EDBi m\u1ED9t con v\u1EADt,`,
  `t\u1EA5t c\u1EA3 \u0111\u1EC1u b\u1EAFt ngu\u1ED3n t\u1EEB m\u1ED9t cu\u1ED9c thi l\u1EDBn.`,
  `H\xE3y xem video n\xE0y,`,
  `\u0111\u1EC3 hi\u1EC3u s\xE2u h\u01A1n v\u1EC1 ngu\u1ED3n g\u1ED1c c\u1EE7a 12 con gi\xE1p Trung Qu\u1ED1c.`
];
