var TEDED_VALUE_PARADOX_F8XB3W31XCW_TRANSLATIONS = [
  `Gi\u1EA3 s\u1EED trong m\u1ED9t ch\u01B0\u01A1ng tr\xECnh \u0111\u1ED1 vui c\xF3 th\u01B0\u1EDFng,`,
  `B\u1EA1n c\xF3 hai gi\u1EA3i th\u01B0\u1EDFng \u0111\u1EC3 ch\u1ECDn:`,
  `M\u1ED9t vi\xEAn kim c\u01B0\u01A1ng v\xE0 m\u1ED9t chai n\u01B0\u1EDBc.`,
  `Vi\u1EC7c l\u1EF1a ch\u1ECDn gi\u1EEFa ch\xFAng r\u1EA5t d\u1EC5 d\xE0ng,`,
  `R\xF5 r\xE0ng gi\xE1 tr\u1ECB c\u1EE7a kim c\u01B0\u01A1ng cao h\u01A1n n\u01B0\u1EDBc.`,
  `B\xE2y gi\u1EDD h\xE3y h\xECnh dung b\u1EA1n \u0111\u1ED1i m\u1EB7t v\u1EDBi l\u1EF1a ch\u1ECDn t\u01B0\u01A1ng t\u1EF1,`,
  `Nh\u01B0ng l\u1EA7n n\xE0y b\u1EA1n kh\xF4ng \u1EDF trong m\u1ED9t ch\u01B0\u01A1ng tr\xECnh \u0111\u1ED1 vui c\xF3 th\u01B0\u1EDFng,`,
  `M\xE0 l\xE0 \u0111ang \u0111i xuy\xEAn qua sa m\u1EA1c nhi\u1EC1u ng\xE0y v\xE0 c\u01A1 th\u1EC3 thi\u1EBFu n\u01B0\u1EDBc tr\u1EA7m tr\u1ECDng.`,
  `S\u1EF1 l\u1EF1a ch\u1ECDn c\u1EE7a b\u1EA1n c\xF3 kh\xE1c kh\xF4ng?`,
  `T\u1EA1i sao? Ch\u1EB3ng l\u1EBD gi\xE1 tr\u1ECB c\u1EE7a kim c\u01B0\u01A1ng v\u1EABn kh\xF4ng cao h\u01A1n n\u01B0\u1EDBc sao?`,
  `\u0110\xE2y ch\xEDnh l\xE0`,
  `\u0110\u01B0\u1EE3c \u0111\u1EC1 xu\u1EA5t l\u1EA7n \u0111\u1EA7u b\u1EDFi Adam Smith, nh\xE0 ti\xEAn phong kinh t\u1EBF h\u1ECDc.`,
  `\xD4ng \u1EA5y n\xF3i v\u1EDBi ch\xFAng ta r\u1EB1ng,`,
  `Vi\u1EC7c x\xE1c \u0111\u1ECBnh gi\xE1 tr\u1ECB th\u1EF1c ra kh\xF4ng \u0111\u01A1n gi\u1EA3n nh\u01B0 v\u1EBB ngo\xE0i c\u1EE7a n\xF3.`,
  `Trong ch\u01B0\u01A1ng tr\xECnh \u0111\u1ED1 vui c\xF3 th\u01B0\u1EDFng, b\u1EA1n \u0111ang xem x\xE9t gi\xE1 tr\u1ECB trao \u0111\u1ED5i c\u1EE7a m\xF3n \u0111\u1ED3,`,
  `\u0110\xF3 ch\xEDnh l\xE0 gi\xE1 tr\u1ECB b\u1EA1n c\xF3 th\u1EC3 nh\u1EADn \u0111\u01B0\u1EE3c t\u1EEB n\xF3 sau n\xE0y.`,
  `Nh\u01B0ng trong c\xE1c t\xECnh hu\u1ED1ng kh\u1EA9n c\u1EA5p,`,
  `v\xED d\u1EE5 nh\u01B0 c\u1EA3nh sa m\u1EA1c \u0111\xE3 \u0111\u1EC1 c\u1EADp tr\u01B0\u1EDBc \u0111\xF3,`,
  `gi\xE1 tr\u1ECB s\u1EED d\u1EE5ng c\u1EE7a v\u1EADt ph\u1EA9m tr\u1EDF n\xEAn quan tr\u1ECDng h\u01A1n,`,
  `t\u1EE9c l\xE0 v\u1EADt ph\u1EA9m \u0111\xF3 c\xF3 th\u1EC3 gi\xFAp \xEDch cho b\u1EA1n \u0111\u1EBFn m\u1EE9c n\xE0o trong ho\xE0n c\u1EA3nh hi\u1EC7n t\u1EA1i.`,
  `V\xEC ch\u1EC9 c\xF3 th\u1EC3 ch\u1ECDn m\u1ED9t trong s\u1ED1 \u0111\xF3,`,
  `n\xEAn ch\xFAng ta c\u0169ng ph\u1EA3i xem x\xE9t chi ph\xED c\u01A1 h\u1ED9i,`,
  `t\u1EE9c l\xE0 n\u1EBFu t\u1EEB b\u1ECF c\xE1c l\u1EF1a ch\u1ECDn kh\xE1c,`,
  `ch\xFAng ta s\u1EBD m\u1EA5t g\xEC.`,
  `X\xE9t cho c\xF9ng, n\u1EBFu b\u1EA1n kh\xF4ng th\u1EC3 tho\xE1t kh\u1ECFi sa m\u1EA1c,`,
  `th\xEC vi\u1EC7c vi\xEAn kim c\u01B0\u01A1ng b\xE1n \u0111\u01B0\u1EE3c bao nhi\xEAu ti\u1EC1n c\u0169ng kh\xF4ng quan tr\u1ECDng.`,
  `Khi n\xF3i v\u1EC1 ngh\u1ECBch l\xFD gi\xE1 tr\u1ECB,`,
  `h\u1EA7u h\u1EBFt c\xE1c nh\xE0 kinh t\u1EBF hi\u1EC7n \u0111\u1EA1i s\u1EBD t\xEDch h\u1EE3p c\xE1c y\u1EBFu t\u1ED1 c\xE2n nh\u1EAFc n\xE0y v\xE0o kh\xE1i ni\u1EC7m "ti\u1EC7n \xEDch\u201D,`,
  `ngh\u0129a l\xE0 m\u1EE9c \u0111\u1ED9 v\u1EADt ph\u1EA9m th\u1ECFa m\xE3n mong mu\u1ED1n ho\u1EB7c nhu c\u1EA7u c\xE1 nh\xE2n.`,
  `T\u1EEB nhu c\u1EA7u c\u01A1 b\u1EA3n v\u1EC1 th\u1EE9c \u0103n cho \u0111\u1EBFn c\u1EA3m gi\xE1c vui v\u1EBB khi nghe nh\u1EA1c y\xEAu th\xEDch,`,
  `Hi\u1EC7u d\u1EE5ng c\xF3 th\u1EC3 \u0111\u01B0\u1EE3c \xE1p d\u1EE5ng cho b\u1EA5t c\u1EE9 th\u1EE9 g\xEC,`,
  `t\u1EF1 nhi\xEAn c\u0169ng kh\xE1c nhau t\xF9y ng\u01B0\u1EDDi, t\xF9y c\u1EA3nh.`,
  `Kinh t\u1EBF th\u1ECB tr\u01B0\u1EDDng cung c\u1EA5p cho ch\xFAng ta m\u1ED9t c\xE1ch \u0111\u01A1n gi\u1EA3n \u0111\u1EC3 "theo d\xF5i hi\u1EC7u d\u1EE5ng",`,
  `n\xF3i \u0111\u01A1n gi\u1EA3n, hi\u1EC7u d\u1EE5ng c\u1EE7a m\u1ED9t m\xF3n \u0111\u1ED3 c\xF3 th\u1EC3 \u0111\u01B0\u1EE3c ph\u1EA3n \xE1nh qua gi\xE1 tr\u1ECB b\u1EA1n s\u1EB5n l\xF2ng chi tr\u1EA3 cho n\xF3.`,
  `B\xE2y gi\u1EDD gi\u1EA3 s\u1EED b\u1EA1n tr\u1EDF l\u1EA1i sa m\u1EA1c,`,
  `nh\u01B0ng l\u1EA7n n\xE0y c\u1EE9 sau 5 ph\xFAt b\u1EA1n s\u1EBD nh\u1EADn \u0111\u01B0\u1EE3c m\u1ED9t vi\xEAn kim c\u01B0\u01A1ng m\u1EDBi ho\u1EB7c m\u1ED9t chai n\u01B0\u1EDBc m\u1EDBi.`,
  `N\u1EBFu b\u1EA1n gi\u1ED1ng nh\u01B0 h\u1EA7u h\u1EBFt m\u1ECDi ng\u01B0\u1EDDi,`,
  `b\u1EA1n s\u1EBD ch\u1ECDn \u0111\u1EE7 n\u01B0\u1EDBc d\xF9ng cho to\xE0n b\u1ED9 h\xE0nh tr\xECnh tr\u01B0\u1EDBc,`,
  `sau \u0111\xF3 ch\u1ECDn c\xE0ng nhi\u1EC1u kim c\u01B0\u01A1ng c\xE0ng t\u1ED1t.`,
  `\u0110\xE2y l\xE0 v\xEC c\xF3 hi\u1EC7u d\u1EE5ng bi\xEAn,`,
  `t\u1EE9c l\xE0 khi c\xE2n nh\u1EAFc kim c\u01B0\u01A1ng v\xE0 n\u01B0\u1EDBc,`,
  `b\u1EA1n s\u1EBD so s\xE1nh hi\u1EC7u d\u1EE5ng c\u1EE7a m\u1ED7i chai n\u01B0\u1EDBc th\xEAm v\xE0 m\u1ED7i vi\xEAn kim c\u01B0\u01A1ng th\xEAm.`,
  `M\u1ED7i l\u1EA7n nh\u1EADn \u0111\u01B0\u1EE3c n\u01B0\u1EDBc v\xE0 kim c\u01B0\u01A1ng, b\u1EA1n s\u1EBD so s\xE1nh nh\u01B0 v\u1EADy:`,
  `Chai n\u01B0\u1EDBc \u0111\u1EA7u ti\xEAn \u0111\u1ED1i v\u1EDBi b\u1EA1n c\xF3 gi\xE1 tr\u1ECB ng\xE0n v\xE0ng kh\xF3 \u0111\u1ED5i,`,
  `nh\u01B0ng cu\u1ED1i c\xF9ng b\u1EA1n s\u1EBD c\xF3 \u0111\u1EE7 n\u01B0\u1EDBc.`,
  `M\u1ED9t th\u1EDDi gian sau, m\u1ED7i chai n\u01B0\u1EDBc d\u01B0 th\u1EEBa tr\u1EDF th\xE0nh g\xE1nh n\u1EB7ng.`,
  `L\xFAc n\xE0y, b\u1EA1n b\u1EAFt \u0111\u1EA7u ch\u1ECDn kim c\u01B0\u01A1ng thay v\xEC n\u01B0\u1EDBc.`,
  `\u0110i\u1EC1u n\xE0y kh\xF4ng ch\u1EC9 \xE1p d\u1EE5ng cho nh\u1EEFng nhu y\u1EBFu ph\u1EA9m nh\u01B0 n\u01B0\u1EDBc,`,
  `m\xE0 c\xF2n \u0111\xFAng v\u1EDBi h\u1EA7u h\u1EBFt c\xE1c m\u1EB7t h\xE0ng.`,
  `B\u1EA1n c\xE0ng nh\u1EADn \u0111\u01B0\u1EE3c nhi\u1EC1u,`,
  `t\u1EF7 l\u1EC7 th\u1ECFa m\xE3n ho\u1EB7c l\u1EE3i \xEDch thu \u0111\u01B0\u1EE3c tr\xEAn m\u1ED7i \u0111\u01A1n v\u1ECB t\u0103ng th\xEAm s\u1EBD gi\u1EA3m d\u1EA7n.`,
  `\u0110\xE2y ch\xEDnh l\xE0 quy lu\u1EADt l\u1EE3i \xEDch c\u1EADn bi\xEAn gi\u1EA3m d\u1EA7n.`,
  `Mua hai ho\u1EB7c ba ph\u1EA7n m\xF3n \u0103n y\xEAu th\xEDch,`,
  `c\xF3 th\u1EC3 b\u1EA1n s\u1EBD r\u1EA5t vui;`,
  `\u0111\u1EBFn ph\u1EA7n th\u1EE9 t\u01B0 b\u1EA1n s\u1EBD b\u1EAFt \u0111\u1EA7u th\u1EA5y ch\xE1n gh\xE9t;`,
  `\u0111\u1EBFn ph\u1EA7n th\u1EE9 100 c\xF3 th\u1EC3 b\u1EA1n s\u1EBD kh\xF4ng bao gi\u1EDD mu\u1ED1n \u0103n n\u1EEFa;`,
  `ho\u1EB7c b\u1EA1n c\xF3 th\u1EC3 b\u1ECF ti\u1EC1n \u0111i xem c\xF9ng m\u1ED9t b\u1ED9 phim,`,
  `cho \u0111\u1EBFn khi ch\xE1n ho\u1EB7c h\u1EBFt s\u1EA1ch ti\u1EC1n.`,
  `D\xF9 l\xE0 tr\u01B0\u1EDDng h\u1EE3p n\xE0o,`,
  `cu\u1ED1i c\xF9ng b\u1EA1n s\u1EBD \u0111\u1EA1t \u0111\u1EBFn \u0111i\u1EC3m m\xE0 l\u1EE3i \xEDch c\u1EADn bi\xEAn c\u1EE7a vi\u1EC7c mua th\xEAm m\u1ED9t v\xE9 xem phim b\u1EB1ng 0.`,
  `L\u1EE3i \xEDch kh\xF4ng ch\u1EC9 \xE1p d\u1EE5ng khi mua s\u1EAFm m\xE0 c\xF2n cho m\u1ECDi quy\u1EBFt \u0111\u1ECBnh c\u1EE7a ch\xFAng ta.`,
  `C\xF3 m\u1ED9t c\xE1ch \u0111\u01A1n gi\u1EA3n \u0111\u1EC3 t\u1ED1i \u0111a h\xF3a l\u1EE3i \xEDch v\xE0 tr\xE1nh quy lu\u1EADt l\u1EE3i \xEDch c\u1EADn bi\xEAn gi\u1EA3m d\u1EA7n,`,
  `\u0111\xF3 l\xE0 kh\xF4ng ng\u1EEBng thay \u0111\u1ED5i c\xE1ch ch\xFAng ta s\u1EED d\u1EE5ng th\u1EDDi gian v\xE0 t\xE0i nguy\xEAn.`,
  `Sau khi \u0111\xE1p \u1EE9ng c\xE1c nhu c\u1EA7u c\u01A1 b\u1EA3n,`,
  `v\u1EC1 l\xFD thuy\u1EBFt, ch\xFAng ta s\u1EBD quy\u1EBFt \u0111\u1ECBnh ch\u1EC9 \u0111\u1EA7u t\u01B0 v\xE0o s\u1ED1 l\u01B0\u1EE3ng h\xE0ng h\xF3a mang l\u1EA1i l\u1EE3i \xEDch ho\u1EB7c ni\u1EC1m vui cho m\xECnh.`,
  `T\u1EA5t nhi\xEAn, vi\u1EC7c m\u1ED7i ch\xFAng ta t\u1ED1i \u0111a h\xF3a l\u1EE3i \xEDch hi\u1EC7u qu\u1EA3 nh\u01B0 th\u1EBF n\xE0o trong cu\u1ED9c s\u1ED1ng th\u1EF1c l\u1EA1i l\xE0 m\u1ED9t v\u1EA5n \u0111\u1EC1 kh\xE1c,`,
  `nh\u01B0ng \u0111i\u1EC1u quan tr\u1ECDng c\u1EA7n nh\u1EDB l\xE0,`,
  `ngu\u1ED3n g\u1ED1c cu\u1ED1i c\xF9ng c\u1EE7a gi\xE1 tr\u1ECB l\xE0 ch\xFAng ta,`,
  `nh\u1EEFng nhu c\u1EA7u chung c\u1EE7a ch\xFAng ta, nh\u1EEFng g\xEC ch\xFAng ta y\xEAu th\xEDch v\xE0 nh\u1EEFng l\u1EF1a ch\u1ECDn c\u1EE7a ch\xFAng ta.`,
  `B\u1EA1n \u0111\xE3 s\u1EB5n s\xE0ng ti\u1EBFp t\u1EE5c h\u1ECDc h\u1ECFi ch\u01B0a?`,
  `Xem c\xE1c video n\xE0y \u0111\u1EC3 th\u1EED th\xE1ch nh\u1EADn th\u1EE9c c\u1EE7a b\u1EA1n,`,
  `ho\u1EB7c n\u1EAFm v\u1EEFng ki\u1EBFn th\u1EE9c m\xE0 b\u1EA1n ch\u01B0a bi\u1EBFt,`,
  `\u0111\u0103ng k\xFD v\xE0 lu\xF4n t\xF2 m\xF2.`
];
