var TEDED_ANIMAL_VISION_EMW_DRGFOA8_TRANSLATIONS = [
  `Trong v\u01B0\u01A1ng qu\u1ED1c \u0111\u1ED9ng v\u1EADt t\u1ED3n t\u1EA1i h\xE0ng ngh\xECn lo\u1EA1i m\u1EAFt phi th\u01B0\u1EDDng.`,
  `C\xF3 con c\xF3 th\u1EC3 \u0111i\u1EC1u khi\u1EC3n m\u1ED9t m\u1EAFt xoay chuy\u1EC3n,`,
  `c\xF3 con l\u1EA1i c\xF3 \u0111\u1ED3ng t\u1EED h\xECnh l\u01B0\u1EE3n s\xF3ng.`,
  `C\xF3 con \u0111\u01B0\u1EE3c b\u1EA3o v\u1EC7 b\u1EB1ng m\xED m\u1EAFt,`,
  `l\u1EA1i c\xF3 con phun m\xE1u t\u1EF1 v\u1EC7.`,
  `Nh\u01B0ng lo\xE0i n\xE0o c\xF3 th\u1EC3 nh\xECn xa h\xE0ng d\u1EB7m?`,
  `Ai c\xF3 th\u1EC3 nh\xECn xuy\xEAn b\xF3ng t\u1ED1i,`,
  `ai nh\xECn th\u1EA5u m\u1ECDi chi ti\u1EBFt?`,
  `Ai c\xF3 th\u1EC3 c\u1EA3m nh\u1EADn \u0111\u01B0\u1EE3c d\u1EA3i m\xE0u r\u1ED9ng nh\u1EA5t?`,
  `V\xE0 ai c\xF3 th\u1EC3 n\u1EAFm b\u1EAFt chuy\u1EC3n \u0111\u1ED9ng nhanh nh\u1EB9n nh\u1EA5t?`,
  `S\xF3ng \xE1nh s\xE1ng t\u1EA1o ra c\u1EA3m gi\xE1c trong m\u1EAFt,`,
  `m\u1EAFt t\u1EADp trung \xE1nh s\xE1ng n\xE0y v\xE0o c\xE1c th\u1EE5 th\u1EC3 \xE1nh s\xE1ng,`,
  `chuy\u1EC3n \u0111\u1ED5i th\xE0nh m\u1ECDi th\u1EE9 ch\xFAng ta th\u1EA5y.`,
  `Nh\u1EEFng t\u1EBF b\xE0o n\xE0y bi\u1EBFn \xE1nh s\xE1ng th\xE0nh t\xEDn hi\u1EC7u th\u1EA7n kinh,`,
  `v\xE0 g\u1EEDi ch\xFAng \u0111\u1EBFn n\xE3o b\u1ED9 \u0111\u1EC3 x\u1EED l\xFD.`,
  `\u0110\xF4i m\u1EAFt nh\xECn r\xF5 nh\u1EA5t trong b\xF3ng t\u1ED1i`,
  `c\xF3 kh\u1EA3 n\u0103ng thu nh\u1EADn nhi\u1EC1u \xE1nh s\xE1ng nh\u1EA5t c\xF3 th\u1EC3.`,
  `Nh\xE3n c\u1EA7u c\u1EE7a m\u1EF1c colossal to b\u1EB1ng s\xE2n b\xF3ng \u0111\xE1,`,
  `l\xE0 lo\u1EA1i l\u1EDBn nh\u1EA5t t\u1EEBng \u0111\u01B0\u1EE3c bi\u1EBFt \u0111\u1EBFn tr\xEAn th\u1EBF gi\u1EDBi.`,
  `\u0110i\u1EC1u n\xE0y c\xF3 l\u1EBD gi\xFAp ch\xFAng \u0111\u1ECBnh v\u1ECB c\xE1 nh\xE0 t\xE1ng ph\xE1t ra \xE1nh s\xE1ng l\u1EDD m\u1EDD \u0111\u1EC3 g\xE2y nhi\u1EC5u c\xE1c lo\xE0i v\u1EADt ph\xE1t quang kh\xE1c.`,
  `M\u1ED9t s\u1ED1 lo\xE0i c\xE1 c\xF2n c\xF3 g\u01B0\u01A1ng trong m\u1EAFt, \u0111\xE2y l\xE0 \u0111i\u1EC1u \u0111\u1ED9c \u0111\xE1o trong s\u1ED1 c\xE1c lo\xE0i \u0111\u1ED9ng v\u1EADt c\xF3 x\u01B0\u01A1ng s\u1ED1ng.`,
  `C\xE1 m\u0169i nh\u1ECDn (telescopefish),`,
  `s\u1EED d\u1EE5ng c\xE1c t\u1EA5m tinh th\u1EC3 nh\u1ECF t\u1EADp trung \xE1nh s\xE1ng hi\u1EC7u qu\u1EA3,`,
  `t\u1EA1o th\xE0nh m\u1ED9t c\u1EB7p g\u01B0\u01A1ng tr\xEAn v\xE0 d\u01B0\u1EDBi trong m\u1EAFt.`,
  `Ch\xFAng c\xF3 th\u1EC3 quan s\xE1t \u0111\u1ED3ng th\u1EDDi c\u1EA3 ph\xEDa tr\xEAn v\xE0 ph\xEDa d\u01B0\u1EDBi,`,
  `v\xE0 ngay c\u1EA3 \u1EDF d\u01B0\u1EDBi bi\u1EC3n s\xE2u,`,
  `c\u0169ng c\xF3 th\u1EC3 nh\xECn r\xF5 h\xECnh d\u1EA1ng \u1EDF xa.`,
  `Tu\u1EA7n l\u1ED9c tr\xEAn c\u1EA1n \u1EDF B\u1EAFc C\u1EF1c,`,
  `c\xF3 th\u1EC3 th\xEDch nghi v\u1EDBi b\xF3ng t\u1ED1i k\xE9o d\xE0i h\xE0ng th\xE1ng tr\u1EDDi.`,
  `N\xF3 c\xF3 th\u1EC3 thay \u0111\u1ED5i m\xE0u s\u1EAFc \u1EDF ph\xEDa sau m\u1EAFt,`,
  `M\xF9a h\xE8 chuy\u1EC3n sang m\xE0u v\xE0ng kim, m\xF9a \u0111\xF4ng chuy\u1EC3n sang m\xE0u xanh lam.`,
  `M\u1EAFt xanh nh\u1EA1y c\u1EA3m v\u1EDBi \xE1nh s\xE1ng ng\u01B0\u1EE3c g\u1EA5p 1000 l\u1EA7n,`,
  `gi\xFAp nai s\u1EEBng t\u1EA5m c\xF3 th\u1EC3 nh\u1EADn bi\u1EBFt nh\u1EEFng v\u1EADt quan tr\u1ECDng tr\xEAn tuy\u1EBFt,`,
  `ch\u1EB3ng h\u1EA1n nh\u01B0 n\u01B0\u1EDBc ti\u1EC3u c\u1EE7a \u0111\u1ED9ng v\u1EADt v\xE0 DE.`,
  `Khi n\xF3i \u0111\u1EBFn th\u1ECB l\u1EF1c tinh t\u01B0\u1EDDng nh\u1EA5t,`,
  `lo\xE0i chim \u0111\u1EE9ng h\xE0ng \u0111\u1EA7u.`,
  `C\xE0ng nhi\u1EC1u th\u1EE5 th\u1EC3 \xE1nh s\xE1ng trong m\u1EAFt,`,
  `c\xE0ng c\xF3 th\u1EC3 n\u1EAFm b\u1EAFt nhi\u1EC1u chi ti\u1EBFt h\u01A1n,`,
  `kh\u1EA3 n\u0103ng x\u1EED l\xFD th\u1ECB gi\xE1c c\u0169ng t\u1EEB \u0111\xF3 m\xE0 t\u0103ng l\xEAn.`,
  `Chim s\u0103n m\u1ED3i c\xF3 h\u1ED1 trung t\xE2m r\u1EA5t s\xE2u,`,
  `h\u1ED1 n\xE0y c\xE0ng s\xE2u th\xEC c\xE0ng ch\u1EE9a \u0111\u01B0\u1EE3c nhi\u1EC1u th\u1EE5 th\u1EC3 \xE1nh s\xE1ng.`,
  `V\xEC v\u1EADy, th\u1ECB l\u1EF1c c\u1EE7a ch\xFAng s\u1EAFc n\xE9t g\u1EA5p \u0111\xF4i so v\u1EDBi con ng\u01B0\u1EDDi.`,
  `Ch\xFAng c\xF3 th\u1EC3 kh\xF3a m\u1EE5c ti\xEAu m\u1ED9t con th\u1ECF t\u1EEB kho\u1EA3ng c\xE1ch 3 km.`,
  `Sinh v\u1EADt n\xE0o c\xF3 kh\u1EA3 n\u0103ng c\u1EA3m nh\u1EADn m\xE0u s\u1EAFc t\u1ED1t nh\u1EA5t?`,
  `C\xE2u h\u1ECFi n\xE0y h\u01A1i kh\xF3.`,
  `Nh\u1EEFng t\u1EBF b\xE0o c\u1EA3m nh\u1EADn \xE1nh s\xE1ng kh\xE1c nhau s\u1EBD nh\u1EA1y c\u1EA3m v\u1EDBi c\xE1c b\u01B0\u1EDBc s\xF3ng \xE1nh s\xE1ng c\u1EE5 th\u1EC3,`,
  `ngh\u0129a l\xE0 m\xE0u s\u1EAFc ch\xFAng ta nh\xECn th\u1EA5y ph\u1EE5 thu\u1ED9c ph\u1EA7n l\u1EDBn v\xE0o lo\u1EA1i t\u1EBF b\xE0o c\u1EA3m nh\u1EADn \xE1nh s\xE1ng m\xE0 ch\xFAng ta c\xF3.`,
  `Theo l\u1EBD th\u01B0\u1EDDng, c\xE0ng c\xF3 nhi\u1EC1u t\u1EBF b\xE0o c\u1EA3m nh\u1EADn \xE1nh s\xE1ng x\u1EED l\xFD c\xE1c lo\u1EA1i m\xE0u kh\xE1c nhau,`,
  `th\xEC kh\u1EA3 n\u0103ng nh\u1EADn bi\u1EBFt m\xE0u s\u1EAFc c\xE0ng t\u1ED1t.`,
  `Ch\xF3 ch\u1EC9 c\xF3 hai lo\u1EA1i t\u1EBF b\xE0o c\u1EA3m nh\u1EADn,`,
  `trong khi con ng\u01B0\u1EDDi c\xF3 ba lo\u1EA1i. V\u1EC1 m\u1EB7t n\xE0y,`,
  `chim, c\xE1 v\xE0 c\xF4n tr\xF9ng b\u1ECF xa ch\xFAng ta.`,
  `B\u01B0\u1EDBm xanh c\xF3 \xEDt nh\u1EA5t 15 lo\u1EA1i t\u1EBF b\xE0o c\u1EA3m nh\u1EADn \xE1nh s\xE1ng.`,
  `ch\u1EC9 ri\xEAng vi\u1EC7c ph\xE2n bi\u1EC7t m\xE0u xanh lam v\xE0 xanh l\u1EE5c`,
  `\u0111\xE3 c\xF3 7 lo\u1EA1i. C\xE1c nh\xE0 nghi\xEAn c\u1EE9u cho r\u1EB1ng \u0111i\u1EC1u n\xE0y c\xF3 th\u1EC3 gi\xFAp ch\xFAng \u0111\u1ECBnh v\u1ECB l\u1EABn nhau trong c\xE1c cu\u1ED9c r\u01B0\u1EE3t \u0111u\u1ED5i t\u1ED1c \u0111\u1ED9 cao.`,
  `T\xF4m t\xEDt c\xF3 t\u1EDBi 16 lo\u1EA1i th\u1EE5 th\u1EC3 c\u1EA3m quang,`,
  `trong \u0111\xF3 c\xF3 5 lo\u1EA1i d\xF9ng \u0111\u1EC3 nh\u1EADn bi\u1EBFt quang ph\u1ED5 tia c\u1EF1c t\xEDm m\xE0 m\u1EAFt ng\u01B0\u1EDDi kh\xF4ng nh\xECn th\u1EA5y \u0111\u01B0\u1EE3c.`,
  `Tuy nhi\xEAn, c\xE1c th\xED nghi\u1EC7m cho th\u1EA5y`,
  `kh\u1EA3 n\u0103ng \u0111\u1ED5i m\xE0u c\u1EE7a t\xF4m t\xEDt h\u1EA1n ch\u1EBF h\u01A1n nhi\u1EC1u so v\u1EDBi nh\u1EEFng g\xEC b\u1EA1n t\u01B0\u1EDFng.`,
  `C\xE1ch ch\xFAng s\u1EED d\u1EE5ng \u0111\xF4i m\u1EAFt k\xE9p v\u1EABn c\xF2n l\xE0 m\u1ED9t b\xED \u1EA9n.`,
  `Trong khi \u0111\xF3, c\xE1 v\xE0ng`,
  `d\xF9 ch\u1EC9 c\xF3 4 lo\u1EA1i t\u1EBF b\xE0o c\u1EA3m nh\u1EADn \xE1nh s\xE1ng,`,
  `nh\u01B0ng l\u1EA1i c\u1EF1c gi\u1ECFi ph\xE2n bi\u1EC7t nh\u1EEFng kh\xE1c bi\u1EC7t nh\u1ECF trong s\u1EAFc \u0111\u1ED9.`,
  `Cu\u1ED1i c\xF9ng, c\xF4n tr\xF9ng l\xE0 nh\u1EEFng b\u1EADc th\u1EA7y v\u1EC1 th\u1ECB gi\xE1c khi bay.`,
  `Chuy\u1EC3n \u0111\u1ED9ng nhanh \u0111\xF2i h\u1ECFi c\xE1c t\u1EBF b\xE0o c\u1EA3m nh\u1EADn \xE1nh s\xE1ng ph\u1EA3i nhanh ch\xF3ng nh\u1EADn bi\u1EBFt s\u1EF1 thay \u0111\u1ED5i c\u1EE7a \xE1nh s\xE1ng,`,
  `v\xE0 n\xE3o b\u1ED9 c\u0169ng c\u1EA7n x\u1EED l\xFD th\xF4ng tin n\xE0y c\u1EF1c nhanh.`,
  `M\u1ED9t b\u1ED9 phim t\u1ED1c \u0111\u1ED9 24 khung h\xECnh m\u1ED7i gi\xE2y \u0111\u1ED1i v\u1EDBi ch\xFAng ta g\u1EA7n nh\u01B0 li\u1EC1n m\u1EA1ch.`,
  `Nh\u01B0ng n\u1EBFu cho c\xF4n tr\xF9ng xem th\xEC \u0111\xF3 l\u1EA1i l\xE0 m\u1ED9t lo\u1EA1t \u1EA3nh t\u0129nh.`,
  `C\xE1c t\u1EBF b\xE0o c\u1EA3m nh\u1EADn \xE1nh s\xE1ng c\u1EE7a ru\u1ED3i ghi nh\u1EADn s\u1EF1 thay \u0111\u1ED5i nhanh g\u1EA5p 10 l\u1EA7n c\u1EE7a ch\xFAng ta,`,
  `\u0111\xF3 l\xE0 l\xFD do t\u1EA1i sao ch\xFAng r\u1EA5t kh\xF3 b\u1EAFt.`,
  `Nh\u1EEFng lo\xE0i \u0111\u1ED9ng v\u1EADt n\xE0y \u0111\u1EC1u c\xF3 th\u1ECB gi\xE1c c\u1EF1c t\u1ED1t,`,
  `nh\u01B0ng kh\xF4ng c\xF3 ng\u01B0\u1EDDi chi\u1EBFn th\u1EAFng ho\xE0n h\u1EA3o.`,
  `B\u1EDFi v\xEC c\xF3 s\u1EF1 \u0111\xE1nh \u0111\u1ED5i gi\u1EEFa c\xE1c kh\u1EA3 n\u0103ng kh\xE1c nhau,`,
  `m\u1ED7i lo\xE0i ch\u1EC9 v\u01B0\u1EE3t tr\u1ED9i \u1EDF m\u1ED9t s\u1ED1 l\u0129nh v\u1EF1c c\u1EE5 th\u1EC3.`,
  `Do \u0111\xF3, m\u1ED9t s\u1ED1 \u0111\xF4i m\u1EAFt c\xF3 n\u0103ng l\u1EF1c chuy\xEAn bi\u1EC7t,`,
  `Ng\u01B0\u1EDDi nh\u01B0 ch\xFAng ta,`,
  `l\u1EA1i l\xE0 chuy\xEAn gia t\u1ED5ng h\u1EE3p nhi\u1EC1u l\u0129nh v\u1EF1c.`,
  `Cho d\xF9 l\xE0 qu\u1EA3 b\xF3ng \u0111\xE1 l\u1EDBn,`,
  `hay l\xE0 \u0111\xF4i m\u1EAFt c\xF3 th\u1EC3 nh\xECn th\u1EA5y tia c\u1EF1c t\xEDm,`,
  `c\xE1ch nh\xECn th\u1EBF gi\u1EDBi c\u0169ng mu\xF4n h\xECnh v\u1EA1n tr\u1EA1ng nh\u01B0 sinh m\u1EC7nh.`,
  `Ch\xFAng t\xF4i cam k\u1EBFt cung c\u1EA5p n\u1ED9i dung gi\xE1o d\u1EE5c ch\u1EA5t l\u01B0\u1EE3ng cao mi\u1EC5n ph\xED cho c\xE0ng nhi\u1EC1u ng\u01B0\u1EDDi s\u1EED d\u1EE5ng nhi\u1EC1u ng\xF4n ng\u1EEF c\xE0ng t\u1ED1t.`,
  `H\xE3y gi\xFAp h\u1ED7 tr\u1EE3 s\u1EE9 m\u1EC7nh phi l\u1EE3i nhu\u1EADn c\u1EE7a ch\xFAng t\xF4i b\u1EB1ng c\xE1ch \u0111\xF3ng g\xF3p cho Patreon c\u1EE7a ch\xFAng t\xF4i,`,
  `v\xE0 \u0111\u1EEBng qu\xEAn \u0111\u0103ng k\xFD k\xEAnh n\xE0y.`
];
