var TEDED_PROCRASTINATION_FS5P8SJK818_TRANSLATIONS = [
  `B\xE2y gi\u1EDD l\xE0 5 gi\u1EDD chi\u1EC1u,`,
  `B\u1EA1n ch\u1EE3t nh\u1EADn ra b\u1EA3n b\xE1o c\xE1o b\u1EA1n tr\xEC ho\xE3n b\u1EA5y l\xE2u ph\u1EA3i n\u1ED9p v\xE0o ng\xE0y mai.`,
  `\u0110\xE3 \u0111\u1EBFn l\xFAc b\u1EAFt tay v\xE0o l\xE0m vi\u1EC7c ch\u0103m ch\u1EC9,`,
  `Th\u1EBF l\xE0 b\u1EA1n m\u1EDF m\xE1y t\xEDnh r\u1ED3i l\u01B0\u1EDBt \u0111i\u1EC7n tho\u1EA1i.`,
  `T\u1EA1i sao kh\xF4ng xem th\xEAm v\xE0i \u0111o\u1EA1n video YouTube y\xEAu th\xEDch c\u1EE7a b\u1EA1n nh\u1EC9?`,
  `Th\xE0nh th\u1EADt m\xE0 n\xF3i, c\xF3 l\u1EBD b\u1EA1n n\xEAn chu\u1EA9n b\u1ECB b\u1EEFa t\u1ED1i tr\u01B0\u1EDBc,`,
  `B\u1EA1n lu\xF4n th\xEDch n\u1EA5u \u0103n,`,
  `Nh\u01B0ng v\u1EDBi c\xF4ng vi\u1EC7c \u0111\xE8 n\u1EB7ng trong t\xE2m tr\xED, b\u1EA1n kh\xF3 c\xF3 th\u1EC3 t\u1EADn h\u01B0\u1EDFng ni\u1EC1m vui \u0111\xF3.`,
  `\xD4i, th\u1EF1c ra c\u0169ng \u0111\xE3 mu\u1ED9n r\u1ED3i,`,
  `C\xF3 l\u1EBD n\xEAn \u0111\u1EE3i \u0111\u1EBFn ng\xE0y mai.`,
  `\u0110\xE2y ch\xEDnh l\xE0 v\xF2ng lu\u1EA9n qu\u1EA9n c\u1EE7a s\u1EF1 tr\xEC ho\xE3n.`,
  `T\xF4i d\xE1m ch\u1EAFc t\u1EA5t c\u1EA3 ch\xFAng ta \u0111\u1EC1u \u0111\xE3 t\u1EEBng tr\u1EA3i qua \u0111i\u1EC1u n\xE0y.`,
  `Bi\u1EBFt r\xF5 tr\xEC ho\xE3n kh\xF4ng kh\xE1c g\xEC b\u1EA3n th\xE2n,`,
  `Nh\u01B0ng t\u1EA1i sao ch\xFAng ta kh\xF4ng th\u1EC3 v\u01B0\u1EE3t qua n\xF3?`,
  `C\u1EA7n l\xE0m r\xF5 m\u1ED9t \u0111i\u1EC3m,`,
  `Tr\xEC ho\xE3n h\xE0nh \u0111\u1ED9ng kh\xF4ng ph\u1EA3i l\xFAc n\xE0o c\u0169ng l\xE0 b\u1EC7nh l\u01B0\u1EDDi bi\u1EBFng.`,
  `Qu\u1EA3n l\xFD th\u1EDDi gian hi\u1EC7u qu\u1EA3 \u0111\xF2i h\u1ECFi ch\xFAng ta ph\u1EA3i x\xE1c \u0111\u1ECBnh nh\u1EEFng vi\u1EC7c kh\u1EA9n c\u1EA5p,`,
  `v\xE0 nh\u1EEFng vi\u1EC7c c\xF3 th\u1EC3 gi\u1EA3i quy\u1EBFt sau.`,
  `N\u1EBFu ch\xFAng ta \u0111\xE3 cam k\u1EBFt ho\xE0n th\xE0nh m\u1ED9t nhi\u1EC7m v\u1EE5,`,
  `v\xE0 bi\u1EBFt r\u1EB1ng kh\xF4ng ho\xE0n th\xE0nh nhi\u1EC7m v\u1EE5 s\u1EBD mang l\u1EA1i h\u1EADu qu\u1EA3 ti\xEAu c\u1EF1c,`,
  `nh\u01B0ng v\u1EABn tr\xE1nh n\xE9 nhi\u1EC7m v\u1EE5 \u0111\xF3 m\xE0 kh\xF4ng c\xF3 l\xFD do,`,
  `th\xEC \u0111\xE2y m\u1EDBi l\xE0 bi\u1EC3u hi\u1EC7n c\u1EE7a b\u1EC7nh l\u01B0\u1EDDi bi\u1EBFng.`,
  `Vi\u1EC7c th\u1EF1c hi\u1EC7n nh\u1EEFng \u0111i\u1EC1u m\xE0 r\xF5 r\xE0ng l\xE0 v\xF4 ngh\u0129a \u0111\u1ED1i v\u1EDBi b\u1EA3n th\xE2n l\xE0 kh\xF4ng h\u1EE3p l\xFD.`,
  `Tuy nhi\xEAn, \u0111i\u1EC1u \u0111\xE1ng ng\u1EA1c nhi\xEAn l\xE0 b\u1EC7nh l\u01B0\u1EDDi bi\u1EBFng l\u1EA1i do c\u01A1 ch\u1EBF t\u1EF1 b\u1EA3o v\u1EC7 c\u1EE7a c\u01A1 th\u1EC3 g\xE2y ra.`,
  `C\u1EE5 th\u1EC3, \u0111\xF3 l\xE0 vi\u1EC7c tr\xE1nh nh\u1EEFng nhi\u1EC7m v\u1EE5 m\xE0 ch\xFAng ta cho l\xE0 m\u1ED1i \u0111e d\u1ECDa.`,
  `B\u1EA1n nh\u1EADn ra m\xECnh c\u1EA7n b\u1EAFt tay v\xE0o vi\u1EBFt b\xE1o c\xE1o \u0111\xF3,`,
  `v\xE0 l\xFAc n\xE0y ph\u1EA3n \u1EE9ng c\u1EE7a n\xE3o b\u1ED9 b\u1EA1n gi\u1ED1ng nh\u01B0 \u0111\u1ED1i ph\xF3 v\u1EDBi m\u1ED9t m\u1ED1i \u0111e d\u1ECDa s\u1EAFp x\u1EA3y ra.`,
  `Trong n\xE3o c\xF3 m\u1ED9t nh\xF3m t\u1EBF b\xE0o th\u1EA7n kinh g\u1ECDi l\xE0 h\u1EA1ch h\u1EA1nh nh\xE2n,`,
  `c\xF3 li\xEAn quan \u0111\u1EBFn vi\u1EC7c qu\u1EA3n l\xFD c\u1EA3m x\xFAc,`,
  `v\xE0 nh\u1EADn di\u1EC7n m\u1ED1i \u0111e d\u1ECDa.`,
  `H\u1EA1ch h\u1EA1nh nh\xE2n gi\u1EA3i ph\xF3ng nhi\u1EC1u hormone, bao g\u1ED3m adrenaline, ch\u1EA5t c\xF3 th\u1EC3 g\xE2y ra ph\u1EA3n \u1EE9ng ho\u1EA3ng lo\u1EA1n.`,
  `C\u1EA3m gi\xE1c ho\u1EA3ng lo\u1EA1n do c\u0103ng th\u1EB3ng g\xE2y ra s\u1EBD l\u1EA5n \xE1t c\xE1c xung \u0111\u1ED9ng t\u1EEB v\u1ECF n\xE3o tr\u01B0\u1EDBc tr\xE1n,`,
  `Trong khi nh\u1EEFng xung \u0111\u1ED9ng n\xE0y th\u01B0\u1EDDng h\u1ED7 tr\u1EE3 t\u01B0 duy d\xE0i h\u1EA1n,`,
  `Gi\xFAp con ng\u01B0\u1EDDi ki\u1EC3m so\xE1t v\xE0 \u0111i\u1EC1u h\xF2a c\u1EA3m x\xFAc.`,
  `Trong s\u1EF1 lo l\u1EAFng c\u1EE7a ba ph\u1EA3n \u1EE9ng chi\u1EBFn \u0111\u1EA5u, b\u1ECF ch\u1EA1y,`,
  `\u0110\u1EE9ng im,`,
  `\u1EE8ng ph\xF3 v\u1EDBi m\u1ED1i \u0111e d\u1ECDa b\u1EB1ng c\xE1ch n\xE9 tr\xE1nh,`,
  `Quy\u1EBFt \u0111\u1ECBnh l\xE0m m\u1ED9t vi\u1EC7c g\xEC \u0111\xF3 \xEDt c\u0103ng th\u1EB3ng h\u01A1n.`,
  `C\xE1ch \u1EE9ng ph\xF3 n\xE0y c\xF3 v\u1EBB c\u1EF1c \u0111oan,`,
  `R\u1ED1t cu\u1ED9c, \u0111\xF3 ch\u1EC9 l\xE0 m\u1ED9t`,
  `Tuy nhi\xEAn, nh\u1EEFng c\xF4ng vi\u1EC7c m\xE0 ch\xFAng ta d\u1EC5 tr\xEC ho\xE3n nh\u1EA5t l\u1EA1i l\xE0 nh\u1EEFng c\xF4ng vi\u1EC7c g\xE2y ra c\u1EA3m x\xFAc ti\xEAu c\u1EF1c,`,
  `Ch\u1EB3ng h\u1EA1n nh\u01B0 s\u1EE3 h\xE3i, b\u1EA5t l\u1EF1c,`,
  `Thi\u1EBFu an to\xE0n, v.v.`,
  `Nghi\xEAn c\u1EE9u cho th\u1EA5y, sinh vi\xEAn \u0111\u1EA1i h\u1ECDc m\u1EAFc ch\u1EE9ng tr\xEC ho\xE3n th\u01B0\u1EDDng c\xF3 xu h\u01B0\u1EDBng tr\xEC ho\xE3n ho\xE0n th\xE0nh nh\u1EEFng nhi\u1EC7m v\u1EE5 h\u1ECDc t\u1EADp g\xE2y \xE1p l\u1EF1c ho\u1EB7c th\u1EED th\xE1ch \u0111\u1ED1i v\u1EDBi h\u1ECD.`,
  `Tuy nhi\xEAn, b\u1EA1n c\xE0ng tr\xEC ho\xE3n,`,
  `B\u1EA1n s\u1EBD c\xE0ng th\u1EA5y nh\u1EEFng nhi\u1EC7m v\u1EE5 n\xE0y kh\xF3 ho\xE0n th\xE0nh.`,
  `C\xF3 m\u1ED9t th\xED nghi\u1EC7m,`,
  `h\u1ECDc sinh li\xEAn t\u1EE5c nh\u1EADn \u0111\u01B0\u1EE3c tin nh\u1EAFn nh\u1EAFc nh\u1EDF h\u1ECD h\u1ECDc t\u1EADp trong m\u1ED9t ng\xE0y.`,
  `Trong qu\xE1 tr\xECnh h\u1ECDc, h\u1EA7u h\u1EBFt h\u1ECDc sinh ph\u1EA3n \u1EE9ng r\u1EB1ng t\xECnh h\xECnh kh\xF4ng qu\xE1 t\u1EC7,`,
  `nh\u01B0ng m\u1ED9t khi h\u1ECD tr\xEC ho\xE3n,`,
  `h\u1ECD s\u1EBD kh\u0103ng kh\u0103ng r\u1EB1ng \xFD ngh\u0129 h\u1ECDc t\u1EADp khi\u1EBFn h\u1ECD c\u1EA3m th\u1EA5y r\u1EA5t c\u0103ng th\u1EB3ng.`,
  `Do \u0111\xF3, vi\u1EC7c b\u1EAFt \u0111\u1EA7u h\u1ECDc tr\u1EDF n\xEAn v\xF4 c\xF9ng kh\xF3 kh\u0103n.`,
  `V\xEC s\u1EF1 tr\xEC ho\xE3n \u0111\u01B0\u1EE3c th\xFAc \u0111\u1EA9y b\u1EDFi c\u1EA3m x\xFAc ti\xEAu c\u1EF1c,`,
  `n\xEAn m\u1ED9t s\u1ED1 ng\u01B0\u1EDDi d\u1EC5 b\u1ECB \u1EA3nh h\u01B0\u1EDFng h\u01A1n.`,
  `\u0110\u1ED1i v\u1EDBi nh\u1EEFng ng\u01B0\u1EDDi g\u1EB7p kh\xF3 kh\u0103n trong vi\u1EC7c \u0111i\u1EC1u ch\u1EC9nh c\u1EA3m x\xFAc ho\u1EB7c c\xF3 l\xF2ng t\u1EF1 tr\u1ECDng th\u1EA5p,`,
  `b\u1EA5t k\u1EC3 kh\u1EA3 n\u0103ng qu\u1EA3n l\xFD th\u1EDDi gian c\u1EE7a h\u1ECD m\u1EA1nh \u0111\u1EBFn \u0111\xE2u,`,
  `h\u1ECD \u0111\u1EC1u d\u1EC5 m\u1EAFc ch\u1EE9ng tr\xEC ho\xE3n h\u01A1n.`,
  `Tuy nhi\xEAn, cho r\u1EB1ng nh\u1EEFng ng\u01B0\u1EDDi m\u1EAFc ch\u1EE9ng tr\xEC ho\xE3n \u0111\u1EC1u l\u01B0\u1EDDi bi\u1EBFng l\xE0 m\u1ED9t nh\u1EADn \u0111\u1ECBnh sai l\u1EA7m ph\u1ED5 bi\u1EBFn.`,
  `L\u01B0\u1EDDi bi\u1EBFng bi\u1EC3u hi\u1EC7n \u1EDF c\u01A1 th\u1EC3 v\xE0 n\xE3o b\u1ED9 b\u1EB1ng \u0111\u1EB7c \u0111i\u1EC3m thi\u1EBFu n\u0103ng l\u01B0\u1EE3ng v\xE0 th\u1EDD \u01A1 n\xF3i chung.`,
  `Khi b\u1EA1n c\u1EA3m th\u1EA5y l\u01B0\u1EDDi bi\u1EBFng, b\u1EA1n c\xF3 th\u1EC3 ng\u1ED3i y\xEAn m\xE0 kh\xF4ng l\xE0m g\xEC,`,
  `m\xE0 kh\xF4ng b\u1ECB ph\xE2n t\xE2m b\u1EDFi nh\u1EEFng vi\u1EC7c kh\xF4ng quan tr\u1ECDng.`,
  `Tr\xEAn th\u1EF1c t\u1EBF, nhi\u1EC1u ng\u01B0\u1EDDi ch\u1EA7n ch\u1EEB v\xEC h\u1ECD qu\xE1 lo l\u1EAFng.`,
  `Nh\u1EEFng ng\u01B0\u1EDDi m\u1EAFc ch\u1EE9ng tr\xEC ho\xE3n th\u01B0\u1EDDng n\xF3i r\u1EB1ng h\u1ECD r\u1EA5t s\u1EE3 th\u1EA5t b\u1EA1i,`,
  `s\u1EF1 ch\u1EA7n ch\u1EEB l\xE0 do s\u1EE3 ch\u1EA5t l\u01B0\u1EE3ng c\xF4ng vi\u1EC7c kh\xF4ng \u0111\u1EA1t \u0111\u01B0\u1EE3c ti\xEAu chu\u1EA9n cao m\xE0 h\u1ECD \u0111\u1EB7t ra.`,
  `B\u1EA5t k\u1EC3 nguy\xEAn nh\xE2n c\u1EE7a ch\u1EE9ng tr\xEC ho\xE3n l\xE0 g\xEC, k\u1EBFt qu\u1EA3 th\u01B0\u1EDDng gi\u1ED1ng nhau.`,
  `Nh\u1EEFng ng\u01B0\u1EDDi th\u01B0\u1EDDng xuy\xEAn tr\xEC ho\xE3n r\u1EA5t c\xF3 th\u1EC3 s\u1EBD ph\u1EA3i ch\u1ECBu \u0111\u1EF1ng s\u1EF1 lo l\u1EAFng v\xE0 tr\u1EA7m c\u1EA3m.`,
  `Ch\u1ECBu \u0111\u1EF1ng c\u1EA3m gi\xE1c x\u1EA5u h\u1ED5 li\xEAn t\u1EE5c, v\xE0 ph\u1EA3i ch\u1ECBu \xE1p l\u1EF1c l\u1EDBn h\u01A1n ng\u01B0\u1EDDi kh\xE1c,`,
  `c\u0169ng nh\u01B0 c\xE1c v\u1EA5n \u0111\u1EC1 s\u1EE9c kh\u1ECFe kh\xE1c nhau do c\u0103ng th\u1EB3ng g\xE2y ra.`,
  `\u0110i\u1EC1u t\u1ED3i t\u1EC7 nh\u1EA5t l\xE0, m\u1EB7c d\xF9 ch\u1EE9ng tr\xEC ho\xE3n s\u1EBD g\xE2y ra t\u1ED5n h\u1EA1i l\xE2u d\xE0i cho ch\xFAng ta,`,
  `nh\u01B0ng n\xF3 c\xF3 th\u1EC3 t\u1EA1m th\u1EDDi gi\u1EA3m b\u1EDBt c\u0103ng th\u1EB3ng cho ch\xFAng ta.`,
  `\u0110i\u1EC1u n\xE0y c\xE0ng c\u1EE7ng c\u1ED1 ph\u1EA3n \u1EE9ng tr\xEC ho\xE3n c\u1EE7a c\u01A1 th\u1EC3 khi \u0111\u1ED1i ph\xF3 v\u1EDBi c\xF4ng vi\u1EC7c \xE1p l\u1EF1c cao.`,
  `V\u1EADy, l\xE0m th\u1EBF n\xE0o ch\xFAng ta c\xF3 th\u1EC3 tho\xE1t kh\u1ECFi v\xF2ng lu\u1EA9n qu\u1EA9n c\u1EE7a ch\u1EE9ng tr\xEC ho\xE3n?`,
  `Quan ni\u1EC7m truy\u1EC1n th\u1ED1ng cho r\u1EB1ng,`,
  `nh\u1EEFng ng\u01B0\u1EDDi m\u1EAFc ch\u1EE9ng tr\xEC ho\xE3n c\u1EA7n ph\u1EA3i r\xE8n luy\u1EC7n kh\u1EA3 n\u0103ng t\u1EF1 ki\u1EC3m so\xE1t,`,
  `th\u1EF1c hi\u1EC7n m\u1ED9t k\u1EBF ho\u1EA1ch qu\u1EA3n l\xFD th\u1EDDi gian nghi\xEAm ng\u1EB7t.`,
  `Nh\u01B0ng gi\u1EDD \u0111\xE2y, nhi\u1EC1u nh\xE0 nghi\xEAn c\u1EE9u tin r\u1EB1ng \u0111i\u1EC1u ng\u01B0\u1EE3c l\u1EA1i m\u1EDBi \u0111\xFAng.`,
  `Vi\u1EC7c qu\xE1 kh\u1EAFt khe v\u1EDBi b\u1EA3n th\xE2n s\u1EBD l\xE0m t\u0103ng c\u1EA3m x\xFAc ti\xEAu c\u1EF1c li\xEAn quan \u0111\u1EBFn nhi\u1EC7m v\u1EE5,`,
  `khi\u1EBFn cho nhi\u1EC7m v\u1EE5 tr\u1EDF n\xEAn \u0111\xE1ng s\u1EE3 h\u01A1n.`,
  `\u0110\u1EC3 v\u01B0\u1EE3t qua ph\u1EA3n \u1EE9ng c\u0103ng th\u1EB3ng n\xE0y,`,
  `ch\xFAng ta c\u1EA7n \u0111\u1ED1i ph\xF3 v\xE0 gi\u1EA3m b\u1EDBt nh\u1EEFng c\u1EA3m x\xFAc ti\xEAu c\u1EF1c \u0111\xF3.`,
  `C\xF3 m\u1ED9t s\u1ED1 chi\u1EBFn l\u01B0\u1EE3c \u0111\u01A1n gi\u1EA3n, ch\u1EB3ng h\u1EA1n nh\u01B0 chia nh\u1ECF nhi\u1EC7m v\u1EE5.`,
  `Ho\u1EB7c ghi l\u1EA1i nh\u1EEFng l\xFD do g\xE2y lo l\u1EAFng,`,
  `sau \u0111\xF3 b\u1EAFt tay v\xE0o gi\u1EA3i quy\u1EBFt nh\u1EEFng lo ng\u1EA1i s\xE2u xa \u0111\xF3.`,
  `C\u1ED1 g\u1EAFng lo\u1EA1i b\u1ECF nh\u1EEFng y\u1EBFu t\u1ED1 d\u1EC5 g\xE2y tr\xEC ho\xE3n xung quanh b\u1EA1n.`,
  `M\u1ED9t c\xE1ch h\u1EEFu \xEDch h\u01A1n l\xE0`,
  `trau d\u1ED3i t\u01B0 duy t\u1EF1 nh\u1EADn th\u1EE9c.`,
  `Tha th\u1EE9 cho b\u1EA3n th\xE2n. L\xEAn k\u1EBF ho\u1EA1ch \u0111\u1EC3 c\u1EA3i thi\u1EC7n l\u1EA7n sau.`,
  `Quan ni\u1EC7m v\u0103n h\xF3a c\u1ED1 \u0111\u1ECBnh m\u1ED1i quan h\u1EC7 lu\u1EA9n qu\u1EA9n gi\u1EEFa \xE1p l\u1EF1c v\xE0 s\u1EF1 tr\xEC ho\xE3n`,
  `s\u1EBD g\xE2y ra t\xE1c h\u1EA1i l\xE2u d\xE0i cho t\u1EA5t c\u1EA3 m\u1ECDi ng\u01B0\u1EDDi.`,
  `Cam k\u1EBFt cung c\u1EA5p n\u1ED9i dung gi\xE1o d\u1EE5c ch\u1EA5t l\u01B0\u1EE3ng cao mi\u1EC5n ph\xED cho c\xE0ng nhi\u1EC1u ng\u01B0\u1EDDi s\u1EED d\u1EE5ng \u0111a ng\xF4n ng\u1EEF c\xE0ng t\u1ED1t.`,
  `H\xE3y \u1EE7ng h\u1ED9 s\u1EE9 m\u1EC7nh phi l\u1EE3i nhu\u1EADn c\u1EE7a ch\xFAng t\xF4i b\u1EB1ng c\xE1ch quy\xEAn g\xF3p tr\xEAn Patreon.`,
  `\u0110\u1EEBng qu\xEAn \u0111\u0103ng k\xFD k\xEAnh n\xE0y nh\xE9.`
];
