var TEDED_EV_HISTORY_15QB2VOEOZ0_TRANSLATIONS = [
  `N\u1EBFu b\u1EA1n mua m\u1ED9t chi\u1EBFc \xF4 t\xF4 v\xE0o n\u0103m 1899,`,
  `b\u1EA1n s\u1EBD c\xF3 ba l\u1EF1a ch\u1ECDn ch\xEDnh.`,
  `B\u1EA1n c\xF3 th\u1EC3 mua m\u1ED9t chi\u1EBFc \xF4 t\xF4 ch\u1EA1y b\u1EB1ng h\u01A1i n\u01B0\u1EDBc,`,
  `th\u01B0\u1EDDng \u0111\u01B0\u1EE3c \u0111\u1EA9y b\u1EB1ng n\u1ED3i h\u01A1i,`,
  `c\xF3 th\u1EC3 \u0111i \u0111\u01B0\u1EE3c bao xa t\xF9y th\xEDch.`,
  `V\u1EDBi \u0111i\u1EC1u ki\u1EC7n b\u1EA1n kh\xF4ng ng\u1EA1i mang th\xEAm n\u01B0\u1EDBc d\u1EF1 ph\xF2ng,`,
  `v\xE0 c\u0169ng kh\xF4ng ng\u1EA1i \u0111\u1EE3i 30 ph\xFAt \u0111\u1EC3 \u0111un n\u01B0\u1EDBc l\xE0m n\xF3ng m\xE1y.`,
  `B\u1EA1n c\u0169ng c\xF3 th\u1EC3 mua m\u1ED9t chi\u1EBFc \xF4 t\xF4 ch\u1EA1y b\u1EB1ng x\u0103ng,`,
  `tuy nhi\xEAn, \u0111\u1ED9ng c\u01A1 \u0111\u1ED1t trong c\u1EE7a nh\u1EEFng m\u1EABu xe n\xE0y c\u1EA7n ph\u1EA3i kh\u1EDFi \u0111\u1ED9ng b\u1EB1ng tay r\u1EA5t nguy hi\u1EC3m,`,
  `v\u1EDBi ti\u1EBFng \u1ED3n l\u1EDBn v\xE0 kh\xED th\u1EA3i kh\xF3 ch\u1ECBu tr\xEAn \u0111\u01B0\u1EDDng.`,
  `V\xEC v\u1EADy, l\u1EF1a ch\u1ECDn t\u1ED1t nh\u1EA5t c\u1EE7a b\u1EA1n c\xF3 l\u1EBD l\xE0 l\u1EF1a ch\u1ECDn th\u1EE9 ba,`,
  `m\u1ED9t chi\u1EBFc \xF4 t\xF4 \u0111i\u1EC7n ch\u1EA1y b\u1EB1ng pin.`,
  `Nh\u1EEFng chi\u1EBFc xe n\xE0y kh\u1EDFi \u0111\u1ED9ng nhanh,`,
  `th\xE2n thi\u1EC7n v\u1EDBi m\xF4i tr\u01B0\u1EDDng v\xE0 ch\u1EA1y \xEAm \xE1i.`,
  `N\u1EBFu b\u1EA1n s\u1ED1ng \u1EDF n\u01A1i c\xF3 \u0111i\u1EC7n,`,
  `R\u1EA5t d\u1EC5 s\u1EA1c v\xE0o ban \u0111\xEAm.`,
  `N\u1EBFu l\u1EF1a ch\u1ECDn c\xF3 v\u1EBB \u0111\u01A1n gi\u1EA3n,`,
  `b\u1EA1n kh\xF4ng ph\u1EA3i ng\u01B0\u1EDDi duy nh\u1EA5t ngh\u0129 v\u1EADy.`,
  `\u0110\u1EBFn cu\u1ED1i th\u1EBF k\u1EF7 19,`,
  `g\u1EA7n 40% \xF4 t\xF4 M\u1EF9 l\xE0 xe \u0111i\u1EC7n.`,
  `\u1EDE c\xE1c th\xE0nh ph\u1ED1 c\xF3 h\u1EC7 th\u1ED1ng \u0111i\u1EC7n ban \u0111\u1EA7u,`,
  `xe \u0111i\u1EC7n l\xE0 m\u1ED9t l\u1EF1a ch\u1ECDn ph\u1ED5 bi\u1EBFn v\xE0 \u0111\xE1ng tin c\u1EADy,`,
  `so v\u1EDBi c\xE1c \u0111\u1ED1i th\u1EE7 th\u1EC9nh tho\u1EA3ng ph\xE1t n\u1ED5.`,
  `Nh\u01B0ng xe \u0111i\u1EC7n c\xF3 m\u1ED9t v\u1EA5n \u0111\u1EC1 ch\xEDnh:`,
  `pin. Pin \xF4 t\xF4 \u0111\u1EDDi \u0111\u1EA7u \u0111\u1EAFt v\xE0 kh\xF4ng hi\u1EC7u qu\u1EA3,`,
  `nhi\u1EC1u nh\xE0 ph\xE1t minh bao g\u1ED3m Thomas Edison \u0111\xE3 c\u1ED1 g\u1EAFng t\u1EA1o ra lo\u1EA1i pin c\xF3 th\u1EC3 l\u01B0u tr\u1EEF nhi\u1EC1u \u0111i\u1EC7n h\u01A1n,`,
  `m\u1ED9t s\u1ED1 th\u1EADm ch\xED \u0111\xE3 x\xE2y d\u1EF1ng c\xE1c tr\u1EA1m \u0111\u1ED5i pin trong th\xE0nh ph\u1ED1 \u0111\u1EC3 thay th\u1EBF pin \u0111\xE3 h\u1EBFt.`,
  `Nh\u01B0ng nh\u1EEFng bi\u1EC7n ph\xE1p n\xE0y v\u1EABn ch\u01B0a \u0111\u1EE7 \u0111\u1EC3 xe \u0111i\u1EC7n \u0111i \u0111\u01B0\u1EE3c qu\xE3ng \u0111\u01B0\u1EDDng d\xE0i,`,
  `v\xE0 gi\xE1 b\xE1n \u0111\u1EAFt g\u1EA5p \u0111\xF4i xe x\u0103ng.`,
  `Nhi\u1EC1u ng\u01B0\u1EDDi kh\xF4ng \u0111\u1EE7 ti\u1EC1n mua nh\u1EEFng m\xF3n \u0111\u1ED3 xa x\u1EC9 n\xE0y.`,
  `\u0110\u1ED3ng th\u1EDDi, vi\u1EC7c ph\xE1t hi\u1EC7n ra d\u1EA7u m\u1ECF \u0111\xE3 l\xE0m gi\u1EA3m gi\xE1 x\u0103ng,`,
  `Nh\u1EEFng ti\u1EBFn b\u1ED9 c\xF4ng ngh\u1EC7 m\u1EDBi \u0111\xE3 l\xE0m cho \u0111\u1ED9ng c\u01A1 \u0111\u1ED1t trong tr\u1EDF n\xEAn h\u1EA5p d\u1EABn h\u01A1n.`,
  `H\u1EC7 th\u1ED1ng kh\u1EDFi \u0111\u1ED9ng \u0111i\u1EC7n thay th\u1EBF vi\u1EC7c \u0111\xE1nh l\u1EEDa b\u1EB1ng tay quay,`,
  `B\u1ED9 gi\u1EA3m thanh gi\xFAp \u0111\u1ED9ng c\u01A1 \xEAm h\u01A1n,`,
  `V\xE0 gi\xE1 \u0111\u1EE1 b\u1EB1ng cao su gi\xFAp \u0111\u1ED9ng c\u01A1 gi\u1EA3m rung.`,
  `N\u0103m 1908,`,
  `Ford \u0111\xE3 ra m\u1EAFt m\u1EABu xe Model T,`,
  `Chi\u1EBFc xe ch\u1EA1y b\u1EB1ng x\u0103ng ch\u1EA5t l\u01B0\u1EE3ng cao, gi\xE1 c\u1EA3 ph\u1EA3i ch\u0103ng n\xE0y \u0111\xE3 thu h\xFAt s\u1EF1 quan t\xE2m c\u1EE7a c\xF4ng ch\xFAng.`,
  `\u0110\u1EBFn n\u0103m 1915,`,
  `T\u1EF7 l\u1EC7 xe \u0111i\u1EC7n l\u01B0u th\xF4ng tr\xEAn \u0111\u01B0\u1EDDng \u0111\xE3 gi\u1EA3m m\u1EA1nh.`,
  `Trong 55 n\u0103m ti\u1EBFp theo,`,
  `\u0110\u1ED9ng c\u01A1 \u0111\u1ED1t trong \u0111\xE3 th\u1ED1ng tr\u1ECB c\xE1c con \u0111\u01B0\u1EDDng.`,
  `Ngo\u1EA1i tr\u1EEB m\u1ED9t s\u1ED1 lo\u1EA1i xe chuy\xEAn d\u1EE5ng,`,
  `Xe \u0111i\u1EC7n g\u1EA7n nh\u01B0 bi\u1EBFn m\u1EA5t.`,
  `Tuy nhi\xEAn, v\xE0o nh\u1EEFng n\u0103m 1970, xu h\u01B0\u1EDBng b\u1EAFt \u0111\u1EA7u thay \u0111\u1ED5i.`,
  `M\u1EF9 lo ng\u1EA1i v\u1EC1 ngu\u1ED3n cung d\u1EA7u \u0111\xE3 kh\u01A1i l\u1EA1i s\u1EF1 quan t\xE2m \u0111\u1EBFn n\u0103ng l\u01B0\u1EE3ng m\u1EDBi.`,
  `V\xE0o nh\u1EEFng n\u0103m 1980,`,
  `c\xE1c nghi\xEAn c\u1EE9u li\xEAn h\u1EC7 kh\xED th\u1EA3i \xF4 t\xF4 v\u1EDBi s\u01B0\u01A1ng m\xF9 \u1EDF c\xE1c th\xE0nh ph\u1ED1 nh\u01B0 Los Angeles,`,
  `\u0111\xE3 khuy\u1EBFn kh\xEDch ch\xEDnh ph\u1EE7 v\xE0 c\xE1c t\u1ED5 ch\u1EE9c b\u1EA3o v\u1EC7 m\xF4i tr\u01B0\u1EDDng xem x\xE9t l\u1EA1i xe \u0111i\u1EC7n.`,
  `\u0110\u1EBFn l\xFAc n\xE0y, c\xE1c h\xE3ng xe \u0111\xE3 d\xE0nh h\xE0ng th\u1EADp k\u1EF7 \u0111\u1EC3 \u0111\u1EA7u t\u01B0 v\xE0o \u0111\u1ED9ng c\u01A1 \u0111\u1ED1t trong,`,
  `m\xE0 kh\xF4ng d\xE0nh b\u1EA5t k\u1EF3 ngu\u1ED3n l\u1EF1c n\xE0o \u0111\u1EC3 gi\u1EA3i quy\u1EBFt v\u1EA5n \u0111\u1EC1 pin k\xE9o d\xE0i c\u1EA3 th\u1EBF k\u1EF7.`,
  `Nh\u01B0ng c\xE1c c\xF4ng ty kh\xE1c \u0111ang ph\xE1t tri\u1EC3n c\xE1c lo\u1EA1i pin ng\xE0y c\xE0ng hi\u1EC7u qu\u1EA3,`,
  `\u0111\u1EC3 cung c\u1EA5p n\u0103ng l\u01B0\u1EE3ng cho c\xE1c thi\u1EBFt b\u1ECB \u0111i\u1EC7n t\u1EED c\u1EA7m tay s\u1EED d\u1EE5ng c\xE1c \u0111\u01B0\u1EDDng d\xE2y m\u1EDBi.`,
  `V\xE0o nh\u1EEFng n\u0103m 1990,`,
  `pin nikel-kim lo\u1EA1i hydrua m\u1EADt \u0111\u1ED9 n\u0103ng l\u01B0\u1EE3ng cao \u0111\xE3 xu\u1EA5t hi\u1EC7n tr\xEAn th\u1ECB tr\u01B0\u1EDDng,`,
  `v\xE0 pin lithium-ion c\u0169ng nhanh ch\xF3ng ra \u0111\u1EDDi.`,
  `C\xF9ng v\u1EDBi c\xE1c quy \u0111\u1ECBnh gi\u1EA3m s\u01B0\u01A1ng m\xF9 c\u1EE7a California,`,
  `nh\u1EEFng \u0111\u1ED5i m\u1EDBi n\xE0y \u0111\xE3 t\u1EA1o ra m\u1ED9t l\xE0n s\xF3ng xe \u0111i\u1EC7n m\u1EDBi,`,
  `bao g\u1ED3m c\u1EA3 xe hybrid.`,
  `Xe hybrid kh\xF4ng ph\u1EA3i l\xE0 xe \u0111i\u1EC7n th\u1EADt s\u1EF1,`,
  `Pin NiMH c\u1EE7a ch\xFAng ch\u1EC9 \u0111\u01B0\u1EE3c s\u1EED d\u1EE5ng \u0111\u1EC3 t\u1ED1i \u01B0u h\xF3a hi\u1EC7u su\u1EA5t c\u1EE7a \u0111\u1ED9ng c\u01A1 x\u0103ng.`,
  `Nh\u01B0ng v\xE0o n\u0103m 2008,`,
  `Tesla Motors \u0111\xE3 \u0111\u1ED5i m\u1EDBi h\u01A1n n\u1EEFa,`,
  `xe th\u1EC3 thao ch\u1EA1y b\u1EB1ng pin lithium-ion c\u1EE7a h\u1ECD \u0111\xE3 thu h\xFAt s\u1EF1 ch\xFA \xFD c\u1EE7a ng\u01B0\u1EDDi ti\xEAu d\xF9ng,`,
  `c\xE1c nh\xE0 s\u1EA3n xu\u1EA5t \xF4 t\xF4 v\xE0 c\u01A1 quan qu\u1EA3n l\xFD.`,
  `Lo\u1EA1i xe \u0111i\u1EC7n thu\u1EA7n t\xFAy n\xE0y,`,
  `c\xF3 th\u1EC3 \u0111i \u0111\u01B0\u1EE3c h\u01A1n 320 km ch\u1EC9 v\u1EDBi m\u1ED9t l\u1EA7n s\u1EA1c,`,
  `g\u1EA7n g\u1EA5p \u0111\xF4i k\u1EF7 l\u1EE5c tr\u01B0\u1EDBc \u0111\xE2y.`,
  `T\u1EEB \u0111\xF3 tr\u1EDF \u0111i, xe \u0111i\u1EC7n \u0111\xE3 c\u1EA3i thi\u1EC7n \u0111\xE1ng k\u1EC3 v\u1EC1 chi ph\xED,`,
  `hi\u1EC7u su\u1EA5t, hi\u1EC7u qu\u1EA3 v\xE0 kh\u1EA3 n\u0103ng ti\u1EBFp c\u1EADn,`,
  `ch\xFAng t\u0103ng t\u1ED1c nhanh h\u01A1n nhi\u1EC1u so v\u1EDBi xe th\u1EC3 thao ch\u1EA1y b\u1EB1ng x\u0103ng.`,
  `M\u1EB7c d\xF9 chi ph\xED ban \u0111\u1EA7u c\u1EE7a m\u1ED9t s\u1ED1 m\u1EABu xe v\u1EABn c\xF2n cao,`,
  `v\u1EC1 l\xE2u d\xE0i,`,
  `ch\xFAng th\u1EF1c s\u1EF1 \u0111\xE3 ti\u1EBFt ki\u1EC7m ti\u1EC1n cho ch\u1EE7 s\u1EDF h\u1EEFu.`,
  `Khi c\xE1c ch\xEDnh ph\u1EE7 tr\xEAn th\u1EBF gi\u1EDBi t\u1EADp trung v\xE0o vi\u1EC7c gi\u1EA3m thi\u1EC3u bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu,`,
  `\xD4 t\xF4 \u0111i\u1EC7n \u0111\u01B0\u1EE3c k\u1EF3 v\u1ECDng s\u1EBD thay th\u1EBF ho\xE0n to\xE0n xe ch\u1EA1y b\u1EB1ng x\u0103ng.`,
  `T\u1EA1i Na Uy, doanh s\u1ED1 b\xE1n \xF4 t\xF4 n\u0103m 2020,`,
  `xe \u0111i\u1EC7n chi\u1EBFm 75%.`,
  `C\xE1c s\u1EAFc l\u1EC7nh v\u1EC1 xe kh\xF4ng ph\xE1t th\u1EA3i \u1EDF California v\xE0 c\xE1c ch\xEDnh s\xE1ch gi\u1EA3m ph\xE1t th\u1EA3i t\xEDch c\u1EF1c \u1EDF Ch\xE2u \xC2u,`,
  `\u0111\xE3 l\xE0m ch\u1EADm \u0111\xE1ng k\u1EC3 \u0111\u1EA7u t\u01B0 to\xE0n c\u1EA7u v\xE0o xe ch\u1EA1y b\u1EB1ng x\u0103ng.`,
  `Ch\u1EB3ng bao l\xE2u n\u1EEFa, \xF4 t\xF4 \u0111i\u1EC7n s\u1EBD chi\u1EBFm \u01B0u th\u1EBF tr\u1EDF l\u1EA1i,`,
  `v\u01B0\u1EE3t xa xe ch\u1EA1y b\u1EB1ng x\u0103ng.`,
  `B\u1EA1n mu\u1ED1n t\xECm hi\u1EC3u th\xEAm v\u1EC1 c\xE1c nh\xE0 khoa h\u1ECDc,`,
  `c\xE1c nh\xE0 ho\u1EA1ch \u0111\u1ECBnh ch\xEDnh s\xE1ch v\xE0 nh\u1EEFng ng\u01B0\u1EDDi nh\u01B0 b\u1EA1n \u0111ang th\u1EF1c hi\u1EC7n nh\u1EEFng bi\u1EC7n ph\xE1p th\xFA v\u1ECB \u0111\u1EC3 \u0111\u1EA3m b\u1EA3o t\u01B0\u01A1ng lai c\u1EE7a Tr\xE1i \u0110\u1EA5t?`,
  `H\xE3y truy c\u1EADp idotide.com/earthgoo \u0111\u1EC3 th\u1ECFa m\xE3n tr\xED t\xF2 m\xF2 v\xE0 hy v\u1ECDng c\u1EE7a b\u1EA1n.`
];
