var TEDED_SMARTEST_AGE_IQJ9EPFRRKI_TRANSLATIONS = [
  `Ng\u01B0\u1EDDi \u1EDF \u0111\u1ED9 tu\u1ED5i n\xE0o l\xE0 th\xF4ng minh nh\u1EA5t?`,
  `C\xF3 l\u1EBD tham gia m\u1ED9t cu\u1ED9c thi \u0111\u1EA5u t\xECnh b\u1EA1n s\u1EBD cho t\xF4i c\xE2u tr\u1EA3 l\u1EDDi.`,
  `N\u0103m t\u1EDBi l\xE0 cu\u1ED9c thi Tranh \u0110o\u1EA1t Tr\xED Tu\u1EC7 th\u01B0\u1EDDng ni\xEAn,`,
  `10 \u0111\u1ED9i g\u1ED3m hai ng\u01B0\u1EDDi s\u1EBD c\u1EA1nh tranh trong m\u1ED9t cu\u1ED9c thi m\u01B0\u1EDDi m\xF4n ph\u1ED1i h\u1EE3p bao g\u1ED3m c\xE1c th\u1EED th\xE1ch tr\xED tu\u1EC7,`,
  `\u0111\u1ED1 vui ki\u1EBFn th\u1EE9c v\xE0 gi\u1EA3i \u0111\u1ED1.`,
  `T\xF4i \u0111\xE3 chu\u1EA9n b\u1ECB cho vi\u1EC7c n\xE0y m\u1ED9t n\u0103m,`,
  `c\u1EA7n ch\u1ECDn ng\u01B0\u1EDDi \u0111\u1ED3ng \u0111\u1ED9i th\xF4ng minh nh\u1EA5t,`,
  `c\xF3 n\u0103ng l\u1EF1c nh\u1EA5t,`,
  `v\xE0 l\u1EADp danh s\xE1ch m\u1ED9t s\u1ED1 \u1EE9ng c\u1EED vi\xEAn ti\u1EC1m n\u0103ng.`,
  `\u0110\u1EA7u ti\xEAn l\xE0 Gabriela, c\xF4 b\xE9 ch\u1EC9 m\u1EDBi 8 tu\u1ED5i, nh\u01B0ng \u0111\u1EEBng \u0111\xE1nh gi\xE1 th\u1EA5p c\xF4 b\xE9,`,
  `c\xF4 b\xE9 c\xF3 th\u1EC3 n\xF3i l\u01B0u lo\xE1t hai ng\xF4n ng\u1EEF,`,
  `v\xE0 c\u0169ng l\xE0 m\u1ED9t ng\u01B0\u1EDDi c\u1EF1c k\u1EF3 s\xE1ng t\u1EA1o.`,
  `Th\u1EE9 hai l\xE0 Emma, c\xF4 \u1EA5y c\xF3 th\u1EC3 \u0111\u1ECDc thu\u1ED9c 100 ch\u1EEF s\u1ED1 \u0111\u1EA7u ti\xEAn c\u1EE7a s\u1ED1 pi,`,
  `ki\u1EBFm s\u1ED1ng b\u1EB1ng vi\u1EC7c thi\u1EBFt k\u1EBF v\u1EC7 tinh,`,
  `v\xE0 gi\u1ECFi l\xE0m m\xF3n b\xE1nh souffl\xE9 ho\xE0n h\u1EA3o.`,
  `Ho\u1EB7c t\xF4i c\xF3 th\u1EC3 ch\u1ECDn \xF4ng Taylor,`,
  `ng\u01B0\u1EDDi ch\u01A1i c\u1EDD gi\u1ECFi nh\u1EA5t khu ph\u1ED1,`,
  `ch\u01B0a k\u1EC3 \xF4ng \u1EA5y \u0111\xE3 tham gia h\u01A1n 20 cu\u1ED9c thi Brain Brawl,`,
  `v\xE0 th\u1EAFng 5 l\u1EA7n.`,
  `T\xF4i kh\xF4ng ch\u1EAFc n\xEAn ch\u1ECDn ai,`,
  `ai l\xE0 ng\u01B0\u1EDDi th\xF4ng minh nh\u1EA5t?`,
  `T\xF4i n\xEAn ch\u1ECDn ai l\xE0m \u0111\u1ED3ng \u0111\u1ED9i cho tr\u1EADn \u0111\u1EA5u ng\xE0y mai?`,
  `V\xE0 t\u1EA1i sao l\u1EA1i l\xE0 ng\u01B0\u1EDDi \u0111\xF3?`,
  `Ch\xE0, \u0111i\u1EC1u \u0111\xF3 ph\u1EE5 thu\u1ED9c.`,
  `M\u1EB7c d\xF9 tr\xED th\xF4ng minh th\u01B0\u1EDDng g\u1EAFn li\u1EC1n v\u1EDBi c\xE1c b\xE0i ki\u1EC3m tra IQ,`,
  `nh\u01B0ng nh\u1EEFng b\xE0i ki\u1EC3m tra n\xE0y th\u01B0\u1EDDng b\u1ECF qua ph\u1EA1m vi v\xE0 chi\u1EC1u s\xE2u kh\u1EA3 n\u0103ng c\u1EE7a m\u1ED9t ng\u01B0\u1EDDi.`,
  `V\xEC v\u1EADy, ch\xFAng ta s\u1EBD chia kh\xE1i ni\u1EC7m v\u1EC1`,
  `v\xE0 kh\u1EA3 n\u0103ng h\u1ECDc h\u1ECFi, v.v.,`,
  `v\xE0 kh\xE1m ph\xE1 xem n\xE3o b\u1ED9 ho\u1EA1t \u0111\u1ED9ng t\u1ED1t nh\u1EA5t khi n\xE0o cho m\u1ED7i lo\u1EA1i.`,
  `H\xE3y b\u1EAFt \u0111\u1EA7u t\u1EEB \u0111\u1EA7u.`,
  `Trong nh\u1EEFng n\u0103m \u0111\u1EA7u \u0111\u1EDDi,`,
  `n\xE3o b\u1ED9 c\u1EE7a b\u1EA1n ph\xE1t tri\u1EC3n nhanh ch\xF3ng,`,
  `\u0111\u01B0\u1EE3c g\u1ECDi l\xE0 h\xECnh th\xE0nh kh\u1EDBp th\u1EA7n kinh,`,
  `t\u1EA1o ra h\u01A1n 1 tri\u1EC7u k\u1EBFt n\u1ED1i th\u1EA7n kinh m\u1EDBi m\u1ED7i gi\xE2y.`,
  `Khi n\xE3o b\u1ED9 ph\xE1t tri\u1EC3n, n\xF3 tr\u1EA3i qua qu\xE1 tr\xECnh tinh ch\u1EC9nh,`,
  `d\u1EF1a tr\xEAn tr\u1EA3i nghi\u1EC7m v\xE0 m\xF4i tr\u01B0\u1EDDng c\u1EE7a b\u1EA1n,`,
  `c\xE1c k\u1EBFt n\u1ED1i \u0111\u01B0\u1EE3c s\u1EED d\u1EE5ng s\u1EBD \u0111\u01B0\u1EE3c c\u1EE7ng c\u1ED1,`,
  `c\xE1c k\u1EBFt n\u1ED1i kh\xF4ng s\u1EED d\u1EE5ng s\u1EBD b\u1ECB lo\u1EA1i b\u1ECF.`,
  `C\xE1c \u0111\u01B0\u1EDDng d\u1EABn th\u1EA7n kinh \u0111\u01B0\u1EE3c s\u1EED d\u1EE5ng th\u01B0\u1EDDng xuy\xEAn c\xF3 myelin,`,
  `\u0111\u01B0\u1EE3c bao b\u1ECDc trong m\u1ED9t l\u1EDBp c\xE1ch \u0111i\u1EC7n,`,
  `l\xE0m cho th\xF4ng tin truy\u1EC1n \u0111i nhanh h\u01A1n,`,
  `\u0111i\u1EC1u n\xE0y t\u1EA1o ra m\u1ED9t b\u1ED9 n\xE3o hi\u1EC7u qu\u1EA3,`,
  `tinh vi h\u01A1n.`,
  `Nh\u01B0ng qu\xE1 tr\xECnh t\xE1i t\u1EA1o n\xE3o n\xE0y di\u1EC5n ra v\xE0o nh\u1EEFng th\u1EDDi \u0111i\u1EC3m kh\xE1c nhau,`,
  `b\xEAn trong v\xE0 gi\u1EEFa c\xE1c v\xF9ng n\xE3o,`,
  `ph\xE1t tri\u1EC3n \u1EDF nh\u1EEFng \u0111\u1ED9 tu\u1ED5i kh\xE1c nhau.`,
  `V\xED d\u1EE5, khi c\xF2n nh\u1ECF,`,
  `ph\u1EA7n n\xE3o b\u1ED9 li\xEAn quan \u0111\u1EBFn vi\u1EC7c h\u1ECDc ng\xF4n ng\u1EEF ph\xE1t tri\u1EC3n \u0111\u1EB7c bi\u1EC7t nhanh ch\xF3ng,`,
  `\u0111\xE2y c\u0169ng l\xE0 l\xFD do t\u1EA1i sao nhi\u1EC1u tr\u1EBB em c\xF3 th\u1EC3 h\u1ECDc v\xE0 th\xE0nh th\u1EA1o nhi\u1EC1u ng\xF4n ng\u1EEF.`,
  `Tuy nhi\xEAn, v\u1ECF n\xE3o tr\u01B0\u1EDBc tr\xE1n,`,
  `m\u1ED9t ph\u1EA7n n\xE3o b\u1ED9 ch\u1ECBu tr\xE1ch nhi\u1EC7m ki\u1EC3m so\xE1t nh\u1EADn th\u1EE9c v\xE0 \xFD ch\xED, l\u1EA1i ph\xE1t tri\u1EC3n ch\u1EADm.`,
  `Do \u0111\xF3, nhi\u1EC1u tr\u1EBB nh\u1ECF c\xF3 th\u1EC3 kh\xF4ng gi\u1ECFi c\xE1c tr\xF2 ch\u01A1i chi\u1EBFn l\u01B0\u1EE3c,`,
  `nh\u01B0 c\u1EDD vua ho\u1EB7c c\u1EDD caro,`,
  `nh\u1EEFng tr\xF2 \u0111\xF2i h\u1ECFi s\u1EF1 t\u1EADp trung li\xEAn t\u1EE5c,`,
  `l\u1EADp k\u1EBF ho\u1EA1ch v\xE0 t\u01B0 duy tr\u1EEBu t\u01B0\u1EE3ng.`,
  `\u0110\u1ED3ng th\u1EDDi, tr\u1EBB em c\xF3 xu h\u01B0\u1EDBng h\u1ECDc kh\xE1m ph\xE1 t\u1EF1 do,`,
  `ch\xFAng gi\u1EA3i quy\u1EBFt c\xE1c c\xE2u \u0111\u1ED1 b\u1EB1ng nh\u1EEFng ph\u01B0\u01A1ng ph\xE1p gi\xE0u tr\xED t\u01B0\u1EDFng t\u01B0\u1EE3ng h\u01A1n,`,
  `v\xE0 ph\u1EA7n l\u1EDBn \xEDt s\u1EE3 m\u1EAFc l\u1ED7i.`,
  `Nh\u01B0ng ng\u01B0\u1EDDi l\u1EDBn c\xF3 nh\u1EEFng kh\u1EA3 n\u0103ng \u0111\u1ED9c \u0111\xE1o c\u1EE7a ri\xEAng h\u1ECD.`,
  `Ng\u01B0\u1EDDi l\u1EDBn \u0111\u01B0\u1EE3c h\u01B0\u1EDFng l\u1EE3i t\u1EEB v\u1ECF n\xE3o tr\u01B0\u1EDBc tr\xE1n ph\xE1t tri\u1EC3n v\u01B0\u1EE3t tr\u1ED9i,`,
  `Gi\xFAp h\u1ECD th\u1EF1c hi\u1EC7n t\u1ED1t h\u01A1n c\xE1c k\u1EF9 n\u0103ng c\u1EA7n h\u1ECDc h\u1ECFi,`,
  `s\u1EF1 t\u1EADp trung v\xE0 ghi nh\u1EDB.`,
  `H\u1ECD c\xF3 th\u1EC3 gi\u1EA3i c\xE2u \u0111\u1ED1 ho\u1EB7c tr\xF2 ch\u01A1i \xF4 ch\u1EEF nhanh v\xE0 hi\u1EC7u qu\u1EA3 h\u01A1n.`,
  `\u1EDE tu\u1ED5i tr\u01B0\u1EDFng th\xE0nh, khi v\xF9ng hippocampus (trung t\xE2m tr\xED nh\u1EDB c\u1EE7a n\xE3o) b\u1ECB l\xE3o h\xF3a,`,
  `nh\u1EEFng k\u1EF9 n\u0103ng n\xE0y c\xF3 th\u1EC3 suy gi\u1EA3m.`,
  `Nh\u01B0ng c\xE2u n\xF3i g\u1EEBng c\xE0ng gi\xE0 c\xE0ng cay c\u0169ng c\xF3 c\u01A1 s\u1EDF khoa h\u1ECDc.`,
  `Nh\u1EDD h\u1ECDc h\u1ECFi su\u1ED1t \u0111\u1EDDi,`,
  `ng\u01B0\u1EDDi l\u1EDBn tu\u1ED5i c\xF3 nhi\u1EC1u ki\u1EBFn th\u1EE9c h\u01A1n \u0111\u1EC3 h\u1ED3i t\u01B0\u1EDFng v\xE0 s\u1EED d\u1EE5ng,`,
  `gi\xFAp h\u1ECD c\xF3 l\u1EE3i th\u1EBF h\u01A1n trong c\xE1c c\xE2u \u0111\u1ED1 ki\u1EBFn th\u1EE9c t\u1ED5ng qu\xE1t.`,
  `C\xE1c y\u1EBFu t\u1ED1 kh\xE1c c\u1EA7n xem x\xE9t, bao g\u1ED3m c\u1EA3 \u0111i\u1EC3m m\u1EA1nh c\u1EE7a ch\xEDnh ng\u01B0\u1EDDi \u0111\xF3.`,
  `\u1EDE tu\u1ED5i thi\u1EBFu ni\xEAn,`,
  `v\xF9ng v\u1ECF n\xE3o tr\u01B0\u1EDBc tr\xE1n ph\xE1t tri\u1EC3n h\u01A1n so v\u1EDBi th\u1EDDi th\u01A1 \u1EA5u,`,
  `\u0111i\u1EC1u n\xE0y gi\xFAp b\u1EA1n t\u01B0 duy logic h\u01A1n v\xE0 gi\u1ECFi gi\u1EA3i c\xE1c b\xE0i to\xE1n.`,
  `\u0110\u1ED3ng th\u1EDDi, s\xE2u b\xEAn trong n\xE3o c\u1EE7a b\u1EA1n,`,
  `v\xF9ng n\xE3o \u0111\xF3ng vai tr\xF2 quan tr\u1ECDng trong \u0111\u1ED9ng l\u1EF1c v\xE0 ph\u1EA7n th\u01B0\u1EDFng c\u0169ng ph\xE1t tri\u1EC3n nhanh ch\xF3ng,`,
  `th\xFAc \u0111\u1EA9y nh\u1EEFng thanh thi\u1EBFu ni\xEAn nh\u01B0 Emir tr\u1EDF th\xE0nh nh\u1EEFng ng\u01B0\u1EDDi ham h\u1ECDc h\u1ECFi,`,
  `c\xF3 tinh th\u1EA7n phi\xEAu l\u01B0u v\xE0 kh\xF4ng ng\u1EEBng h\u1ECDc h\u1ECFi.`,
  `Theo nhi\u1EC1u c\xE1ch,`,
  `b\u1EA1n c\xF3 th\u1EC3 coi thanh thi\u1EBFu ni\xEAn l\xE0 m\u1ED9t ng\u01B0\u1EDDi \u0111a n\u0103ng,`,
  `b\u1ED9 n\xE3o c\u1EE7a h\u1ECD d\xE1m t\xECm ki\u1EBFm nh\u1EEFng tr\u1EA3i nghi\u1EC7m m\u1EDBi v\xE0 h\u1ECDc h\u1ECFi nhanh ch\xF3ng.`,
  `B\u1EA1n \u0111ang \u1EDF trong m\u1ED9t giai \u0111o\u1EA1n n\u0103ng \u0111\u1ED9ng,`,
  `nh\u1EEFng l\u1EF1a ch\u1ECDn b\u1EA1n \u0111\u01B0a ra v\xE0 nh\u1EEFng k\u1EF9 n\u0103ng b\u1EA1n t\u1EADp trung v\xE0o,`,
  `th\u1EF1c s\u1EF1 c\xF3 th\u1EC3 \u0111\u1ECBnh h\u01B0\u1EDBng s\u1EF1 ph\xE1t tri\u1EC3n c\u1EE7a n\xE3o b\u1ED9 b\u1EA1n.`,
  `V\u1EADy \u0111\u1ED9 tu\u1ED5i n\xE0o l\xE0 th\xF4ng minh nh\u1EA5t?`,
  `Kh\xF4ng c\xF3 c\xE2u tr\u1EA3 l\u1EDDi duy nh\u1EA5t,`,
  `c\xF3 th\u1EC3 l\xE0 8 tu\u1ED5i,`,
  `16 tu\u1ED5i, 25 tu\u1ED5i,`,
  `65 tu\u1ED5i v\xE0 b\u1EA5t k\u1EF3 \u0111\u1ED9 tu\u1ED5i n\xE0o \u1EDF gi\u1EEFa.`,
  `B\u1ED9 n\xE3o c\u1EE7a ch\xFAng ta t\u1EADp trung ph\xE1t tri\u1EC3n c\xE1c k\u1EF9 n\u0103ng kh\xE1c nhau \u1EDF c\xE1c giai \u0111o\u1EA1n kh\xE1c nhau trong cu\u1ED9c \u0111\u1EDDi,`,
  `\u0111\u1EC3 \u0111\u1ED1i ph\xF3 v\u1EDBi nh\u1EEFng th\xE1ch th\u1EE9c v\xE0 nhu c\u1EA7u t\u01B0\u01A1ng \u1EE9ng trong cu\u1ED9c s\u1ED1ng.`,
  `V\xEC v\u1EADy, b\u1EA5t k\u1EC3 Emir ch\u1ECDn ai,`,
  `C\xF3 m\u1ED9t \u0111\u1ED9i ng\u0169 \u0111a th\u1EBF h\u1EC7 m\u1EDBi l\xE0 chi\u1EBFn l\u01B0\u1EE3c t\u1ED1t.`,
  `H\xE3y ti\u1EBFp t\u1EE5c h\u1ECDc h\u1ECFi qua nh\u1EEFng video n\xE0y,`,
  `V\xE0 \u0111\u1EEBng qu\xEAn \u0111\u0103ng k\xFD,`,
  `\u0110\u1EEBng b\u1ECF l\u1EE1 c\u01A1 h\u1ED9i h\u1ECDc h\u1ECFi nh\u1EEFng \u0111i\u1EC1u m\u1EDBi m\u1EBB.`
];
