var TEDED_SILK_ROAD_K_JJFZQNW_TRANSLATIONS = [
  `M\u1ED9t doanh nh\xE2n \u1EDF London g\u1EEDi th\xF4ng tin ch\u1EE9ng kho\xE1n m\u1EDBi nh\u1EA5t cho \u0111\u1ED3ng nghi\u1EC7p \u1EDF H\u1ED3ng K\xF4ng trong ch\u01B0a \u0111\u1EA7y m\u1ED9t gi\xE2y.`,
  `Kh\xE1ch h\xE0ng \u1EDF New York, M\u1EF9, \u0111\u1EB7t mua s\u1EA3n ph\u1EA9m \u0111i\u1EC7n t\u1EED s\u1EA3n xu\u1EA5t t\u1EA1i B\u1EAFc Kinh ch\u1EC9 b\u1EB1ng m\u1ED9t c\xFA nh\u1EA5p chu\u1ED9t.`,
  `Trong v\xF2ng v\xE0i ng\xE0y, h\xE0ng h\xF3a \u0111\xE3 \u0111\u01B0\u1EE3c v\u1EADn chuy\u1EC3n t\u1EEB \u0111\u1EA7u n\xE0y sang \u0111\u1EA7u kia c\u1EE7a \u0111\u1EA1i d\u01B0\u01A1ng b\u1EB1ng m\xE1y bay v\u1EADn t\u1EA3i ho\u1EB7c container \u0111\u01B0\u1EDDng bi\u1EC3n.`,
  `Ng\xE0y nay, t\u1ED1c \u0111\u1ED9 v\xE0 t\u1ED5ng l\u01B0\u1EE3ng h\xE0ng h\xF3a v\xE0 th\xF4ng tin l\u01B0u chuy\u1EC3n to\xE0n c\u1EA7u l\xE0 ch\u01B0a t\u1EEBng c\xF3.`,
  `Nh\u01B0ng l\u1ECBch s\u1EED giao th\u01B0\u01A1ng to\xE0n c\u1EA7u c\u1ED5 x\u01B0a h\u01A1n nhi\u1EC1u so v\u1EDBi ch\xFAng ta t\u01B0\u1EDFng.`,
  `2000 n\u0103m tr\u01B0\u1EDBc, d\u1ECDc theo con \u0111\u01B0\u1EDDng d\xE0i 5000 d\u1EB7m,`,
  `t\u1EE9c l\xE0 con \u0111\u01B0\u1EDDng t\u01A1 l\u1EE5a n\u1ED5i ti\u1EBFng, ho\u1EA1t \u0111\u1ED9ng n\xE0y \u0111\xE3 b\u1EAFt \u0111\u1EA7u.`,
  `Con \u0111\u01B0\u1EDDng t\u01A1 l\u1EE5a kh\xF4ng ch\u1EC9 l\xE0 m\u1ED9t con \u0111\u01B0\u1EDDng,`,
  `m\xE0 l\xE0 nhi\u1EC1u tuy\u1EBFn \u0111\u01B0\u1EDDng \u0111an xen, d\u1EA7n h\xECnh th\xE0nh qua nhi\u1EC1u th\u1EBF k\u1EF7.`,
  `T\u1EEBng tuy\u1EBFn \u0111\u01B0\u1EDDng d\u1EABn \u0111\u1EBFn nh\u1EEFng n\u01A1i \u1EDF kh\xE1c nhau,`,
  `v\xE0 c\u0169ng k\u1EBFt n\u1ED1i ch\xFAng l\u1EA1i v\u1EDBi nhau.`,
  `N\u1EC1n v\u0103n minh n\xF4ng nghi\u1EC7p nguy\xEAn th\u1EE7y xu\u1EA5t hi\u1EC7n \u1EDF c\xE1c thung l\u0169ng s\xF4ng m\xE0u m\u1EE1 xa x\xF4i,`,
  `\u0111\u1ECBa h\xECnh b\u1EA5t ti\u1EC7n xung quanh v\xE0 n\u1ED7i s\u1EE3 h\xE3i nh\u1EEFng \u0111i\u1EC1u ch\u01B0a bi\u1EBFt \u0111\xE3 c\u1EA3n tr\u1EDF s\u1EF1 giao l\u01B0u c\u1EE7a ng\u01B0\u1EDDi d\xE2n \u0111\u1ECBa ph\u01B0\u01A1ng.`,
  `Sau khi ng\u01B0\u1EDDi d\xE2n \u0111\u1ECBa ph\u01B0\u01A1ng sinh s\u1ED1ng \u1EDF \u0111\xE2y m\u1ED9t th\u1EDDi gian,`,
  `h\u1ECD ph\xE1t hi\u1EC7n ra r\u1EB1ng nh\u1EEFng g\xEC h\u1ECD \u0111ang s\u1ED1ng trong sa m\u1EA1c kh\xF4 c\u1EB1n v\xE0 xung quanh bi\xEAn gi\u1EDBi kh\xF4ng ph\u1EA3i l\xE0 ma qu\u1EF7 trong truy\u1EC1n thuy\u1EBFt d\xE2n gian,`,
  `m\xE0 l\xE0 c\xE1c b\u1ED9 l\u1EA1c du m\u1EE5c tr\xEAn l\u01B0ng ng\u1EF1a.`,
  `Ng\u01B0\u1EDDi Scythia tr\xEAn kh\u1EAFp M\xF4ng C\u1ED5 \u0111\u1EBFn Hungary,`,
  `\u0111\xE3 s\u1EDBm ti\u1EBFp x\xFAc v\u1EDBi Hy L\u1EA1p,`,
  `Ai C\u1EADp, \u1EA4n \u0110\u1ED9 v\xE0 Trung Qu\u1ED1c,`,
  `nh\u1EEFng cu\u1ED9c ti\u1EBFp x\xFAc n\xE0y th\u01B0\u1EDDng kh\xF4ng m\u1EA5y h\xF2a b\xECnh.`,
  `Nh\u01B0ng ngay c\u1EA3 th\xF4ng qua c\xE1c cu\u1ED9c t\u1EA5n c\xF4ng v\xE0 chi\u1EBFn tranh,`,
  `c\u0169ng nh\u01B0 th\u01B0\u01A1ng m\u1EA1i v\xE0 b\u1EA3o v\u1EC7 c\xE1c th\u01B0\u01A1ng nh\xE2n \u0111i l\u1EA1i \u0111\u1EC3 \u0111\u1ED5i l\u1EA5y thu\u1EBF quan,`,
  `c\xE1c d\xE2n t\u1ED9c du m\u1EE5c c\u0169ng b\u1EAFt \u0111\u1EA7u truy\u1EC1n b\xE1 h\xE0ng h\xF3a,`,
  `\xFD t\u01B0\u1EDFng v\xE0 c\xF4ng ngh\u1EC7 gi\u1EEFa c\xE1c n\u1EC1n v\u0103n h\xF3a kh\xF4ng c\xF3 ti\u1EBFp x\xFAc tr\u1EF1c ti\u1EBFp.`,
  `Trong m\u1EA1ng l\u01B0\u1EDBi ng\xE0y c\xE0ng m\u1EDF r\u1ED9ng n\xE0y,`,
  `m\u1ED9t trong nh\u1EEFng tuy\u1EBFn \u0111\u01B0\u1EDDng quan tr\u1ECDng nh\u1EA5t l\xE0 con \u0111\u01B0\u1EDDng ho\xE0ng gia Ba T\u01B0.`,
  `Con \u0111\u01B0\u1EDDng n\xE0y \u0111\u01B0\u1EE3c Darius I ho\xE0n th\xE0nh v\xE0o th\u1EBF k\u1EF7 th\u1EE9 5 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn,`,
  `n\xF3 tr\u1EA3i d\xE0i t\u1EEB s\xF4ng Tigris \u0111\u1EBFn bi\u1EC3n Aegean,`,
  `d\xE0i kho\u1EA3ng 2000 d\u1EB7m, h\xE0ng h\xF3a v\xE0 th\xF4ng tin trong \u0111\xF3 ch\u1EC9 m\u1EA5t m\u1ED9t ph\u1EA7n m\u01B0\u1EDDi th\u1EDDi gian so v\u1EDBi m\u1ED9t l\u1EEF kh\xE1ch c\xE1 nh\xE2n.`,
  `Sau \u0111\xF3, Alexander \u0110\u1EA1i \u0111\u1EBF chinh ph\u1EE5c Ba T\u01B0,`,
  `B\u1EB1ng c\xE1ch chi\u1EBFm \u0111\xF3ng c\xE1c th\xE0nh ph\u1ED1 nh\u01B0 Samarkand,`,
  `l\xE3nh th\u1ED5 c\u1EE7a \xF4ng \u0111\xE3 m\u1EDF r\u1ED9ng \u0111\u1EBFn t\u1EADn Trung \xC1.`,
  `Ngo\xE0i ra, \xF4ng c\xF2n th\xE0nh l\u1EADp c\xE1c th\xE0nh ph\u1ED1 m\u1EDBi nh\u01B0 Khujand.`,
  `Nh\u1EEFng n\u1EC1n v\u0103n minh v\xE0 m\u1EA1ng l\u01B0\u1EDBi th\u01B0\u01A1ng m\u1EA1i c\u1EE7a Hy L\u1EA1p, Ai C\u1EADp, Ba T\u01B0 v\xE0 \u1EA4n \u0110\u1ED9 \u0111\xE3 m\u1EDF r\u1ED9ng v\u1EC1 ph\xEDa \u0111\xF4ng t\u1EDBi m\u1EE9c l\u1EDBn nh\u1EA5t trong l\u1ECBch s\u1EED,`,
  `t\u1EA1o n\u1EC1n t\u1EA3ng cho c\u1EA7u n\u1ED1i giao ti\u1EBFp gi\u1EEFa Trung Qu\u1ED1c v\xE0 ph\u01B0\u01A1ng T\xE2y.`,
  `M\xE3i \u0111\u1EBFn th\u1EBF k\u1EF7 th\u1EE9 2 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn,`,
  `m\u1ED9t s\u1EE9 gi\u1EA3 t\xEAn l\xE0 Tr\u01B0\u01A1ng Khi\xEAn \u0111\u01B0\u1EE3c ph\xE1i \u0111i \u0111\xE0m ph\xE1n v\u1EDBi c\xE1c b\u1ED9 l\u1EA1c du m\u1EE5c ph\xEDa t\xE2y.`,
  `Sau khi tr\u1EDF v\u1EC1 Trung Qu\u1ED1c, v\u1ECB s\u1EE9 gi\u1EA3 n\xE0y \u0111\xE3 k\u1EC3 cho H\xE1n V\u0169 \u0110\u1EBF nghe nhi\u1EC1u c\xE2u chuy\u1EC7n v\u1EC1 c\xE1c n\u1EC1n v\u0103n minh c\u1ED5 \u0111\u1EA1i,`,
  `th\u01B0\u01A1ng m\u1EA1i th\u1ECBnh v\u01B0\u1EE3ng v\xE0 h\xE0ng h\xF3a k\u1EF3 l\u1EA1 \u1EDF c\xE1c v\xF9ng l\xE3nh th\u1ED5 ph\xEDa t\xE2y bi\xEAn gi\u1EDBi c\u1EE7a \xF4ng.`,
  `Sau \u0111\xF3, nhi\u1EC1u s\u1EE9 gi\u1EA3`,
  `v\xE0 th\u01B0\u01A1ng nh\xE2n li\xEAn t\u1EE5c \u0111\u01B0\u1EE3c ph\xE1i \u0111\u1EBFn Ba T\u01B0 v\xE0 \u1EA4n \u0110\u1ED9,`,
  `trao \u0111\u1ED5i l\u1EE5a v\xE0 ng\u1ECDc \u0111\u1EC3 l\u1EA5y ng\u1EF1a v\xE0 b\xF4ng c\u1EE7a h\u1ECD.`,
  `Qu\xE2n \u0111\u1ED9i c\u0169ng \u0111i theo \u0111\u1EC3 \u0111\u1EA3m b\u1EA3o an to\xE0n cho h\xE0nh tr\xECnh c\u1EE7a h\u1ECD.`,
  `Con \u0111\u01B0\u1EDDng gi\u1EEFa ph\u01B0\u01A1ng \u0110\xF4ng v\xE0 ph\u01B0\u01A1ng T\xE2y d\u1EA7n h\xECnh th\xE0nh m\u1ED9t m\u1EA1ng l\u01B0\u1EDBi xuy\xEAn \xC2u-\xC1,`,
  `m\u1EA1ng l\u01B0\u1EDBi n\xE0y gi\xFAp cho giao l\u01B0u v\u0103n h\xF3a v\xE0 th\u01B0\u01A1ng m\u1EA1i gi\u1EEFa \xC2u-\xC1 \u0111\u1EA1t m\u1EE9c cao nh\u1EA5t trong l\u1ECBch s\u1EED l\xFAc b\u1EA5y gi\u1EDD.`,
  `H\xE0ng h\xF3a Trung Qu\u1ED1c du nh\u1EADp v\xE0o La M\xE3,`,
  `g\xE2y ra t\xECnh tr\u1EA1ng ch\u1EA3y m\xE1u v\xE0ng nghi\xEAm tr\u1ECDng,`,
  `do \u0111\xF3 La M\xE3 \u0111\xE3 c\u1EA5m giao d\u1ECBch t\u01A1 l\u1EE5a.`,
  `\u0110\u1ED3 th\u1EE7y tinh La M\xE3 c\u0169ng r\u1EA5t \u0111\u01B0\u1EE3c \u01B0a chu\u1ED9ng \u1EDF Trung Qu\u1ED1c.`,
  `Qu\xE2n vi\u1EC5n chinh Trung \xC1 \u0111\xE3 ch\u1EE9ng ki\u1EBFn cu\u1ED9c g\u1EB7p g\u1EE1 gi\u1EEFa qu\xE2n \u0111\u1ED9i Trung Qu\u1ED1c v\xE0 La M\xE3,`,
  `th\u1EADm ch\xED c\xF3 th\u1EC3 \u0111\xE3 truy\u1EC1n b\xE1 k\u1EF9 thu\u1EADt n\u1ECF sang ph\u01B0\u01A1ng T\xE2y.`,
  `Nhu c\u1EA7u v\u1EC1 h\xE0ng h\xF3a ngo\u1EA1i qu\u1ED1c,`,
  `l\u1EE3i \xEDch t\u1EEB th\u01B0\u01A1ng m\u1EA1i \u0111\xE3 gi\u1EEF cho Con \u0111\u01B0\u1EDDng T\u01A1 l\u1EE5a n\xE0y lu\xF4n \u0111\u01B0\u1EE3c b\u1EA3o t\u1ED3n.`,
  `M\u1EB7c d\xF9 \u0110\u1EBF ch\u1EBF La M\xE3 s\u1EE5p \u0111\u1ED5, c\xE1c tri\u1EC1u \u0111\u1EA1i Trung Qu\u1ED1c h\u01B0ng th\u1ECBnh r\u1ED3i suy t\xE0n,`,
  `ngay c\u1EA3 nh\u1EEFng th\u01B0\u01A1ng nh\xE2n M\xF4ng C\u1ED5 n\u1ED5i ti\u1EBFng v\u1EDBi vi\u1EC7c c\u01B0\u1EDB b\xF3c v\xE0 t\xEDch tr\u1EEF c\u1EE7a c\u1EA3i c\u0169ng t\xEDch c\u1EF1c b\u1EA3o v\u1EC7 c\xE1c tuy\u1EBFn \u0111\u01B0\u1EDDng th\u01B0\u01A1ng m\u1EA1i n\xE0y,`,
  `ch\u1EE9 kh\xF4ng ph\u1EA3i ph\xE1 h\u1EE7y ch\xFAng.`,
  `V\u1EDBi s\u1EF1 ph\xE1t tri\u1EC3n c\u1EE7a n\u1EC1n kinh t\u1EBF h\xE0ng h\xF3a, con \u0111\u01B0\u1EDDng n\xE0y \u0111\u1ED3ng th\u1EDDi gi\xFAp v\u0103n h\xF3a,`,
  `c\xF4ng ngh\u1EC7 ti\xEAn ti\u1EBFn, t\u01B0 t\u01B0\u1EDFng v\xE0 ng\xF4n ng\u1EEF \u0111\u01B0\u1EE3c l\u01B0u th\xF4ng.`,
  `Kh\u1EDFi ngu\u1ED3n t\u1EEB \u1EA4n \u0110\u1ED9,`,
  `Ph\u1EADt gi\xE1o \u0111\xE3 truy\u1EC1n b\xE1 \u0111\u1EBFn Trung Qu\u1ED1c v\xE0 Nh\u1EADt B\u1EA3n,`,
  `tr\u1EDF th\xE0nh t\xF4n gi\xE1o ph\u1ED5 bi\u1EBFn nh\u1EA5t \u1EDF ch\xE2u \xC1.`,
  `H\u1ED3i gi\xE1o t\u1EEB b\xE1n \u0111\u1EA3o \u1EA2 R\u1EADp truy\u1EC1n \u0111\u1EBFn Nam \xC1,`,
  `v\xE0 k\u1EBFt h\u1EE3p v\u1EDBi t\xEDn ng\u01B0\u1EE1ng \u0111\u1ECBa ph\u01B0\u01A1ng h\xECnh th\xE0nh c\xE1c t\xF4n gi\xE1o m\u1EDBi,`,
  `nh\u01B0 \u0111\u1EA1o Sikh.`,
  `Thu\u1ED1c s\xFAng t\u1EEB Trung Qu\u1ED1c truy\u1EC1n \u0111\u1EBFn Trung \u0110\xF4ng,`,
  `\u0111\u1ECBnh h\xECnh t\u01B0\u01A1ng lai c\u1EE7a \u0110\u1EBF qu\u1ED1c Ottoman,`,
  `\u0110\u1EBF qu\u1ED1c Safavid v\xE0 \u0110\u1EBF qu\u1ED1c Maratha.`,
  `\u1EDE m\u1ED9t m\u1EE9c \u0111\u1ED9 n\xE0o \u0111\xF3,`,
  `Con \u0111\u01B0\u1EDDng T\u01A1 l\u1EE5a \u0111\xE3 t\u1EF1 k\u1EBFt th\xFAc vai tr\xF2 c\u1EE7a m\xECnh.`,
  `K\u0129 thu\u1EADt h\xE0ng h\u1EA3i m\u1EDBi nh\u01B0 la b\xE0n truy\u1EC1n \u0111\u1EBFn ch\xE2u \xC2u,`,
  `khi\u1EBFn c\xE1c tuy\u1EBFn \u0111\u01B0\u1EDDng b\u1ED9 d\xE0i tr\xEAn \u0111\u1EA5t li\u1EC1n b\u1ECB lo\u1EA1i b\u1ECF.`,
  `\u0110\u1ED3ng th\u1EDDi, sau khi nh\xE0 Nguy\xEAn s\u1EE5p \u0111\u1ED5, Trung Qu\u1ED1c bi\u1EBFn m\u1EA5t kh\u1ECFi b\u1EA3n \u0111\u1ED3 th\u01B0\u01A1ng m\u1EA1i qu\u1ED1c t\u1EBF.`,
  `M\u1EB7c d\xF9 c\xE1c tuy\u1EBFn \u0111\u01B0\u1EDDng v\xE0 m\u1EA1ng l\u01B0\u1EDBi th\u01B0\u01A1ng m\u1EA1i c\u0169 kh\xF4ng t\u1ED3n t\u1EA1i l\xE2u d\xE0i,`,
  `ch\xFAng \u0111\xE3 v\u0129nh vi\u1EC5n thay \u0111\u1ED5i th\u1EBF gi\u1EDBi,`,
  `kh\xF4ng c\xF2n kh\u1EA3 n\u0103ng quay ng\u01B0\u1EE3c tr\u1EDF l\u1EA1i.`,
  `Ng\u01B0\u1EDDi ch\xE2u \xC2u t\xECm ki\u1EBFm nh\u1EEFng tuy\u1EBFn \u0111\u01B0\u1EDDng bi\u1EC3n m\u1EDBi,`,
  `mong mu\u1ED1n t\xECm ki\u1EBFm s\u1EF1 gi\xE0u c\xF3 \u1EDF \u0110\xF4ng \xC1,`,
  `d\u1EABn \u0111\u1EBFn vi\u1EC7c h\u1ECD th\xE1m hi\u1EC3m v\xE0 m\u1EDF r\u1ED9ng \u1EDF ch\xE2u Phi v\xE0 ch\xE2u M\u1EF9.`,
  `Ng\xE0y nay, s\u1EF1 k\u1EBFt n\u1ED1i kh\xF4ng ng\u1EEBng gi\u1EEFa c\xE1c qu\u1ED1c gia tr\xEAn to\xE0n c\u1EA7u \u0111ang \u1EA3nh h\u01B0\u1EDFng \u0111\u1EBFn cu\u1ED9c s\u1ED1ng c\u1EE7a ch\xFAng ta.`,
  `Ng\u01B0\u1EDDi ti\xEAu d\xF9ng Canada mua \xE1o ph\xF4ng s\u1EA3n xu\u1EA5t t\u1EA1i Bangladesh,`,
  `kh\xE1n gi\u1EA3 Nh\u1EADt B\u1EA3n xem c\xE1c ch\u01B0\u01A1ng tr\xECnh truy\u1EC1n h\xECnh c\u1EE7a Anh,`,
  `v\xE0 ng\u01B0\u1EDDi Tunisia s\u1EED d\u1EE5ng ph\u1EA7n m\u1EC1m c\u1EE7a M\u1EF9 \u0111\u1EC3 t\u1ED5 ch\u1EE9c c\xE1ch m\u1EA1ng.`,
  `\u1EA2nh h\u01B0\u1EDFng v\u0103n h\xF3a v\xE0 kinh t\u1EBF c\u1EE7a to\xE0n c\u1EA7u h\xF3a l\xE0 kh\xF4ng th\u1EC3 ph\u1EE7 nh\u1EADn,`,
  `nh\u01B0ng nh\u1EEFng l\u1EE3i \xEDch v\xE0 h\u1EA1n ch\u1EBF \u0111i k\xE8m c\u0169ng kh\xF4ng c\xF2n l\xE0 \u0111i\u1EC1u m\u1EDBi m\u1EBB.`,
  `M\u1EB7c d\xF9 nh\u1EEFng d\xE3y n\xFAi,`,
  `sa m\u1EA1c v\xE0 \u0111\u1EA1i d\u01B0\u01A1ng t\u1EEBng ng\u0103n c\xE1ch ch\xFAng ta hi\u1EC7n \u0111\xE3 \u0111\u01B0\u1EE3c v\u01B0\u1EE3t qua b\u1EB1ng m\xE1y bay si\xEAu thanh,`,
  `c\xE1p li\xEAn l\u1EA1c xuy\xEAn l\u1EE5c \u0111\u1ECBa v\xE0 t\xEDn hi\u1EC7u truy\u1EC1n qua kh\xF4ng gian,`,
  `kh\xF4ng c\xF2n c\u1EA7n \u0111\u1EBFn nh\u1EEFng \u0111o\xE0n l\u1EEF h\xE0nh m\u1EA5t h\xE0ng th\xE1ng tr\u1EDDi, nh\u01B0ng t\u1EA5t c\u1EA3 nh\u1EEFng \u0111i\u1EC1u n\xE0y s\u1EBD kh\xF4ng th\u1EC3 th\u1EF1c hi\u1EC7n \u0111\u01B0\u1EE3c n\u1EBFu kh\xF4ng c\xF3 m\u1ED9t n\u1EC1n v\u0103n h\xF3a ti\xEAn phong.`,
  `\u0110i\u1EC1u n\xE0y kh\xF4ng th\u1EC3 th\u1EF1c hi\u1EC7n \u0111\u01B0\u1EE3c.`,
  `N\u1EC1n v\u0103n h\xF3a ti\xEAn ti\u1EBFn nh\u01B0 v\u1EADy \u0111\xE3 t\u1EA1o ra Con \u0111\u01B0\u1EDDng t\u01A1 l\u1EE5a,`,
  `M\u1EA1ng internet \u0111\u1EA7u ti\xEAn tr\xEAn th\u1EBF gi\u1EDBi k\u1EBFt n\u1ED1i v\u1EA1n v\u1EADt.`,
  `N\u1EBFu b\u1EA1n y\xEAu th\xEDch vi\u1EC7c h\u1ECDc h\u1ECFi,`,
  `h\xE3y \u0111\u0103ng k\xFD k\xEAnh ch\xFAng t\xF4i.`,
  `Ch\xFAng t\xF4i \u0111\u0103ng t\u1EA3i nhi\u1EC1u n\u1ED9i dung video m\u1EDBi m\u1EBB v\xE0 \u0111a d\u1EA1ng,`,
  `t\u1EEB vi\u1EC7c nh\xECn nh\u1EADn l\u1ECBch s\u1EED th\u1EBF gi\u1EDBi qua \u0111\xF4i m\u1EAFt lo\xE0i m\xE8o,`,
  `\u0111\u1EBFn nh\u1EEFng k\u1EF9 n\u0103ng c\u1EA7n thi\u1EBFt \u0111\u1EC3 sinh t\u1ED3n tr\xEAn m\u1EB7t tr\u0103ng,`,
  `v\xE0 nhi\u1EC1u h\u01A1n th\u1EBF n\u1EEFa. H\xE3y ti\u1EBFp t\u1EE5c theo d\xF5i,`,
  `v\xE0 gi\u1EEF v\u1EEFng tinh th\u1EA7n kh\xE1m ph\xE1!`
];
