var TEDED_TEA_HISTORY_ELXU9VLZLSQ_TRANSLATIONS = [
  `Su\u1ED1t m\u1ED9t ng\xE0y \u0111i lang thang trong r\u1EEBng,`,
  `Th\u1EA7n N\xF4ng t\xECm ki\u1EBFm ng\u0169 c\u1ED1c v\xE0 th\u1EA3o m\u1ED9c \u0103n \u0111\u01B0\u1EE3c.`,
  `Th\u1EA7n N\xF4ng m\u1EC7t m\u1ECFi \u0111\xE3 tr\xFAng \u0111\u1ED9c 72 l\u1EA7n,`,
  `Nh\u01B0ng ngay tr\u01B0\u1EDBc khi \xF4ng qua \u0111\u1EDDi v\xEC tr\xFAng \u0111\u1ED9c,`,
  `m\u1ED9t chi\u1EBFc l\xE1 bay v\xE0o mi\u1EC7ng \xF4ng.`,
  `\xD4ng nhai chi\u1EBFc l\xE1,`,
  `v\xE0 h\u1ED3i ph\u1EE5c s\u1EE9c l\u1EF1c.`,
  `\u0110\xE2y ch\xEDnh l\xE0 qu\xE1 tr\xECnh ph\xE1t hi\u1EC7n ra tr\xE0.`,
  `\xCDt nh\u1EA5t th\xEC th\u1EA7n tho\u1EA1i c\u1ED5 x\u01B0a k\u1EC3 l\u1EA1i nh\u01B0 v\u1EADy:`,
  `Tr\xE0 th\u1EF1c ra kh\xF4ng gi\u1EA3i \u0111\u1ED9c \u0111\u01B0\u1EE3c,`,
  `nh\u01B0ng Th\u1EA7n N\xF4ng, v\u1EDBi t\u01B0 c\xE1ch l\xE0 ng\u01B0\u1EDDi ph\xE1t minh ra n\xF4ng nghi\u1EC7p Trung Qu\u1ED1c,`,
  `\u0111\xE3 l\xE0m n\u1ED5i b\u1EADt t\u1EA7m quan tr\u1ECDng c\u1EE7a tr\xE0 \u1EDF Trung Qu\u1ED1c c\u1ED5 \u0111\u1EA1i.`,
  `B\u1EB1ng ch\u1EE9ng kh\u1EA3o c\u1ED5 cho th\u1EA5y tr\xE0 \u0111\u01B0\u1EE3c tr\u1ED3ng s\u1EDBm nh\u1EA5t \u1EDF Trung Qu\u1ED1c,`,
  `c\xE1ch \u0111\xE2y kho\u1EA3ng 6000 n\u0103m;`,
  `S\u1EDBm h\u01A1n 1500 n\u0103m so v\u1EDBi th\u1EDDi c\xE1c Pharaoh x\xE2y d\u1EF1ng kim t\u1EF1 th\xE1p.`,
  `C\xE2y ch\xE8 \u0111\u1EA7u ti\xEAn c\u1EE7a Trung Qu\u1ED1c gi\u1ED1ng v\u1EDBi c\xE2y ch\xE8 hi\u1EC7n nay tr\xEAn to\xE0n c\u1EA7u,`,
  `nh\u01B0ng c\xE1ch d\xF9ng l\u1EA1i r\u1EA5t kh\xE1c so v\u1EDBi b\xE2y gi\u1EDD.`,
  `Ban \u0111\u1EA7u, n\xF3 \u0111\u01B0\u1EE3c d\xF9ng l\xE0m rau ho\u1EB7c \u0111\u1EC3 n\u1EA5u ch\xE1o.`,
  `N\xF3 tr\u1EDF th\xE0nh th\u1EE9c u\u1ED1ng t\u1EEB th\u1EF1c ph\u1EA9m,`,
  `c\xE1ch \u0111\xE2y 1500 n\u0103m,`,
  `khi con ng\u01B0\u1EDDi nh\u1EADn ra vi\u1EC7c \u0111un n\xF3ng v\xE0 h\u01A1i n\u01B0\u1EDBc c\xF3 th\u1EC3 t\u1EA1o ra h\u01B0\u01A1ng v\u1ECB ph\u1EE9c t\u1EA1p v\xE0 \u0111a d\u1EA1ng t\u1EEB l\xE1 ch\xE8.`,
  `Ph\u01B0\u01A1ng ph\xE1p pha tr\xE0 \u0111\xE3 ph\xE1t tri\u1EC3n qua h\xE0ng tr\u0103m n\u0103m,`,
  `t\u1EA1o n\xEAn quy tr\xECnh chu\u1EA9n hi\u1EC7n nay,`,
  `bao g\u1ED3m vi\u1EC7c l\xE0m n\xF3ng l\xE1 tr\xE0,`,
  `\xE9p th\xE0nh b\xE1nh tr\xE0 ti\u1EC7n l\u1EE3i \u0111\u1EC3 mang theo,`,
  `nghi\u1EC1n th\xE0nh b\u1ED9t, pha v\u1EDBi n\u01B0\u1EDBc n\xF3ng,`,
  `t\u1EEB \u0111\xF3 t\u1EA1o ra`,
  `Tr\xE0 M\u1EB7c th\u1ECBnh h\xE0nh m\u1ED9t th\u1EDDi,`,
  `v\xE0 n\u1EC1n v\u0103n h\xF3a tr\xE0 \u0111\u1ED9c \u0111\xE1o c\u1EE7a Trung Qu\u1ED1c c\u0169ng t\u1EEB \u0111\xF3 m\xE0 h\xECnh th\xE0nh.`,
  `Tr\xE0 tr\u1EDF th\xE0nh ch\u1EE7 \u0111\u1EC1 trong th\u01A1 ca v\xE0 s\xE1ch v\u1EDF,`,
  `tr\u1EDF th\xE0nh th\u1EE9c u\u1ED1ng \u0111\u01B0\u1EE3c ho\xE0ng \u0111\u1EBF y\xEAu th\xEDch nh\u1EA5t,`,
  `c\u0169ng l\xE0 c\xF4ng c\u1EE5 s\xE1ng t\u1EA1o c\u1EE7a c\xE1c ngh\u1EC7 s\u0129.`,
  `H\u1ECD c\xF3 th\u1EC3 v\u1EBD trong b\u1ECDt tr\xE0,`,
  `r\u1EA5t gi\u1ED1ng v\u1EDBi c\xE1ch c\xE1c qu\xE1n c\xE0 ph\xEA ng\xE0y nay v\u1EBD tr\xEAn c\xE0 ph\xEA espresso.`,
  `V\xE0o th\u1EBF k\u1EF7 th\u1EE9 9, th\u1EDDi nh\xE0 \u0110\u01B0\u1EDDng,`,
  `m\u1ED9t nh\xE0 s\u01B0 Nh\u1EADt B\u1EA3n \u0111\xE3 mang c\xE2y tr\xE0 \u0111\u1EA7u ti\xEAn \u0111\u1EBFn Nh\u1EADt B\u1EA3n.`,
  `Ng\u01B0\u1EDDi Nh\u1EADt cu\u1ED1i c\xF9ng \u0111\xE3 h\xECnh th\xE0nh th\xF3i quen u\u1ED1ng tr\xE0 \u0111\u1ED9c \u0111\xE1o c\u1EE7a ri\xEAng m\xECnh,`,
  `t\u1EA1o ra "tr\xE0 \u0111\u1EA1o".`,
  `V\xE0o th\u1EBF k\u1EF7 14, th\u1EDDi nh\xE0 Minh,`,
  `ho\xE0ng \u0111\u1EBF Trung Qu\u1ED1c \u0111\xE3 thay \u0111\u1ED5i ti\xEAu chu\u1EA9n s\u1EA3n xu\u1EA5t tr\xE0 t\u1EEB vi\u1EC7c \xE9p l\xE1 tr\xE0 th\xE0nh b\xE1nh,`,
  `sang tr\xE0 l\xE1 r\u1EDDi.`,
  `Khi \u0111\xF3, Trung Qu\u1ED1c v\u1EABn g\u1EA7n nh\u01B0 \u0111\u1ED9c quy\u1EC1n c\xE2y tr\xE0 tr\xEAn th\u1EBF gi\u1EDBi,`,
  `khi\u1EBFn tr\xE0 tr\u1EDF th\xE0nh m\u1ED9t trong ba m\u1EB7t h\xE0ng xu\u1EA5t kh\u1EA9u c\u01A1 b\u1EA3n ch\xEDnh c\u1EE7a Trung Qu\u1ED1c, c\xF9ng v\u1EDBi \u0111\u1ED3 s\u1EE9 v\xE0 l\u1EE5a.`,
  `\u0110i\u1EC1u n\xE0y mang l\u1EA1i cho Trung Qu\u1ED1c quy\u1EC1n l\u1EF1c v\xE0 \u1EA3nh h\u01B0\u1EDFng kinh t\u1EBF l\u1EDBn,`,
  `v\xEC v\xE0o th\u1EDDi \u0111i\u1EC3m n\xE0y, th\xF3i quen u\u1ED1ng tr\xE0 \u0111\xE3 ph\u1ED5 bi\u1EBFn kh\u1EAFp th\u1EBF gi\u1EDBi.`,
  `Xu h\u01B0\u1EDBng n\xE0y \u0111\u1EA1t \u0111\u1EBFn \u0111\u1EC9nh \u0111i\u1EC3m v\xE0o \u0111\u1EA7u th\u1EBF k\u1EF7 17,`,
  `Trong th\u1EDDi gian n\xE0y, c\xE1c th\u01B0\u01A1ng nh\xE2n H\xE0 Lan \u0111\xE3 mang m\u1ED9t l\u01B0\u1EE3ng l\u1EDBn tr\xE0 \u0111\u1EBFn ch\xE2u \xC2u.`,
  `Nhi\u1EC1u ng\u01B0\u1EDDi tin r\u1EB1ng,`,
  `N\u1EEF ho\xE0ng Catherine t\xF4n qu\xFD c\u1EE7a B\u1ED3 \u0110\xE0o Nha \u0111\xE3 k\u1EBFt h\xF4n v\u1EDBi Vua Charles II c\u1EE7a Anh v\xE0o n\u0103m 1661,`,
  `nh\u1EDD \u0111\xF3 gi\u1EDBi qu\xFD t\u1ED9c Anh \u0111\xE3 y\xEAu th\xEDch tr\xE0.`,
  `V\xE0o th\u1EDDi \u0111i\u1EC3m \u0111\xF3, Anh \u0111ang m\u1EDF r\u1ED9ng thu\u1ED9c \u0111\u1ECBa,`,
  `v\xE0 d\u1EA7n tr\u1EDF th\xE0nh c\u01B0\u1EDDng qu\u1ED1c h\xE0ng \u0111\u1EA7u th\u1EBF gi\u1EDBi.`,
  `C\xF9ng v\u1EDBi s\u1EF1 l\u1EDBn m\u1EA1nh c\u1EE7a Anh,`,
  `s\u1EDF th\xEDch u\u1ED1ng tr\xE0 \u0111\xE3 lan r\u1ED9ng kh\u1EAFp th\u1EBF gi\u1EDBi.`,
  `V\xE0o n\u0103m 1700 tr\xEAn th\u1ECB tr\u01B0\u1EDDng ch\xE2u \xC2u,`,
  `gi\xE1 tr\xE0 \u0111\xE3 \u0111\u1EA1t g\u1EA5p 10 l\u1EA7n c\xE0 ph\xEA,`,
  `nh\u01B0ng v\xE0o th\u1EDDi \u0111i\u1EC3m n\xE0y, c\xE2y tr\xE0 v\u1EABn ch\u1EC9 m\u1ECDc \u1EDF Trung Qu\u1ED1c.`,
  `Th\u01B0\u01A1ng m\u1EA1i tr\xE0 tr\xF4ng th\u1EADt h\u1EA5p d\u1EABn,`,
  `nh\xE0 thuy\u1EC1n bu\u1ED3m nhanh nh\u1EA5t th\u1EBF gi\u1EDBi ra \u0111\u1EDDi do s\u1EF1 c\u1EA1nh tranh kh\u1ED1c li\u1EC7t gi\u1EEFa c\xE1c c\xF4ng ty th\u01B0\u01A1ng m\u1EA1i ph\u01B0\u01A1ng T\xE2y.`,
  `Nh\u1EEFng con t\xE0u n\xE0y nhanh ch\xF3ng \u0111\u01B0a tr\xE0 v\u1EC1 ch\xE2u \xC2u,`,
  `nh\u1EB1m t\u1ED1i \u0111a h\xF3a l\u1EE3i nhu\u1EADn c\xF4ng ty.`,
  `Ban \u0111\u1EA7u, ng\u01B0\u1EDDi Anh d\xF9ng ti\u1EC1n b\u1EA1c \u0111\u1EC3 tr\u1EA3 ti\u1EC1n tr\xE0.`,
  `Khi \u0111i\u1EC1u n\xE0y tr\u1EDF n\xEAn qu\xE1 t\u1ED1n k\xE9m,`,
  `h\u1ECD \u0111\u1EC1 xu\u1EA5t \u0111\u1ED5i b\u1EB1ng thu\u1ED1c phi\u1EC7n.`,
  `\u0110i\u1EC1u n\xE0y g\xE2y ra v\u1EA5n \u0111\u1EC1 s\u1EE9c kh\u1ECFe c\u1ED9ng \u0111\u1ED3ng \u1EDF Trung Qu\u1ED1c,`,
  `v\xEC ng\u01B0\u1EDDi d\xE2n s\u1EBD nghi\u1EC7n thu\u1ED1c phi\u1EC7n.`,
  `\u0110\u1EBFn n\u0103m 1839,`,
  `m\u1ED9t quan ch\u1EE9c Trung Qu\u1ED1c \u0111\xE3 ra l\u1EC7nh ti\xEAu h\u1EE7y m\u1ED9t l\u01B0\u1EE3ng l\u1EDBn thu\u1ED1c phi\u1EC7n do Anh v\u1EADn chuy\u1EC3n,`,
  `\u0111i\u1EC1u n\xE0y \u0111\u01B0\u1EE3c coi l\xE0 ch\u1ED1ng l\u1EA1i \u1EA3nh h\u01B0\u1EDFng c\u1EE7a Anh \u0111\u1ED1i v\u1EDBi Trung Qu\u1ED1c.`,
  `H\xE0nh \u0111\u1ED9ng n\xE0y \u0111\xE3 ch\xE2m ng\xF2i cho Chi\u1EBFn tranh Nha phi\u1EBFn l\u1EA7n th\u1EE9 nh\u1EA5t gi\u1EEFa hai n\u01B0\u1EDBc.`,
  `C\xE1c cu\u1ED9c giao tranh di\u1EC5n ra d\u1ECDc b\u1EDD bi\u1EC3n Trung Qu\u1ED1c,`,
  `cho \u0111\u1EBFn khi nh\xE0 Thanh th\u1EA5t b\u1EA1i v\xE0o n\u0103m 1842,`,
  `nh\u01B0\u1EE3ng \u0111\u1EA3o H\u1ED3ng K\xF4ng cho Anh,`,
  `v\xE0 ch\u1EA5p nh\u1EADn c\xE1c \u0111i\u1EC1u kho\u1EA3n th\u01B0\u01A1ng m\u1EA1i b\u1EA5t b\xECnh \u0111\u1EB3ng.`,
  `Cu\u1ED9c chi\u1EBFn n\xE0y \u0111\xE3 l\xE0m suy y\u1EBFu v\u1ECB th\u1EBF to\xE0n c\u1EA7u c\u1EE7a Trung Qu\u1ED1c trong m\u1ED9t th\u1EBF k\u1EF7.`,
  `C\xF4ng ty \u0110\xF4ng \u1EA4n c\u1EE7a Anh c\u0169ng mu\u1ED1n tr\u1ED3ng ch\xE8,`,
  `v\xE0 ki\u1EC3m so\xE1t s\xE2u h\u01A1n th\u1ECB tr\u01B0\u1EDDng ch\xE8.`,
  `V\xEC v\u1EADy, h\u1ECD \u0111\xE3 c\u1EED nh\xE0 th\u1EF1c v\u1EADt h\u1ECDc Robert Fortune b\xED m\u1EADt \u0111\u1EBFn Trung Qu\u1ED1c \u0111\u1EC3 l\u1EA5y tr\u1ED9m ch\xE8.`,
  `\xD4ng ta c\u1EA3i trang v\xE0 b\u1EAFt \u0111\u1EA7u cu\u1ED9c h\xE0nh tr\xECnh \u0111\u1EA7y nguy hi\u1EC3m \u0111\xF3.`,
  `\xD4ng ta \u0111i qua nh\u1EEFng v\xF9ng n\xFAi tr\u1ED3ng ch\xE8 c\u1EE7a Trung Qu\u1ED1c, bu\xF4n l\u1EADu c\xE2y ch\xE8 v\xE0 nh\u1EEFng c\xF4ng nh\xE2n pha ch\u1EBF ch\xE8 c\xF3 kinh nghi\u1EC7m,`,
  `\u0111\u01B0a h\u1ECD \u0111\u1EBFn Darjeeling c\u1EE7a \u1EA4n \u0110\u1ED9.`,
  `T\u1EEB \u0111\xF3, c\xE2y ch\xE8 \u0111\u01B0\u1EE3c tr\u1ED3ng r\u1ED9ng r\xE3i,`,
  `th\xFAc \u0111\u1EA9y tr\xE0 nhanh ch\xF3ng tr\u1EDF th\xE0nh \u0111\u1ED3 u\u1ED1ng ph\u1ED5 bi\u1EBFn h\xE0ng ng\xE0y.`,
  `Hi\u1EC7n nay, l\u01B0\u1EE3ng ti\xEAu th\u1EE5 tr\xE0 ch\u1EC9 \u0111\u1EE9ng sau n\u01B0\u1EDBc l\u1ECDc,`,
  `\u0111\u1EE9ng th\u1EE9 hai tr\xEAn th\u1EBF gi\u1EDBi.`,
  `T\u1EEB tr\xE0 \u0111en Th\u1ED5 Nh\u0129 K\u1EF3 ng\u1ECDt ng\xE0o \u0111\u1EBFn tr\xE0 b\u01A1 m\u1EB7n c\u1EE7a T\xE2y T\u1EA1ng,`,
  `c\xE1ch pha ch\u1EBF tr\xE0 r\u1EA5t \u0111a d\u1EA1ng,`,
  `gi\u1ED1ng nh\u01B0 v\xF4 s\u1ED1 n\u1EC1n v\u0103n h\xF3a kh\xE1c nhau tr\xEAn th\u1EBF gi\u1EDBi,`,
  `kh\xF4ng th\u1EC3 \u0111\u1EBFm xu\u1EC3. Th\xF4ng qua video n\xE0y,`,
  `h\xE3y ti\u1EBFp t\u1EE5c kh\xE1m ph\xE1 l\u1ECBch s\u1EED \u0111\u1EA7y h\u1EA5p d\u1EABn c\u1EE7a Trung Qu\u1ED1c,`,
  `khai qu\u1EADt l\u0103ng m\u1ED9 ho\xE0ng \u0111\u1EBF 2000 n\u0103m tu\u1ED5i,`,
  `v\xE0 nh\u1EEFng ph\xE1t hi\u1EC7n \u0111\xE1ng kinh ng\u1EA1c b\xEAn trong.`
];
