var JOVANE_MACAU_VLOG_OZ9CEIUFZX0_TRANSLATIONS = [
  `Ch\xFAng ta s\u1EBD kh\u1EDFi h\xE0nh \u0111i Ma Cao,`,
  `H\u1EB9n g\u1EB7p l\u1EA1i \u1EDF Ma Cao!`,
  `V\u1EEBa \u0111\u1EBFn s\xE2n bay \u0111\xE3 c\xF3 xe \u0111\u01B0a ch\xFAng t\xF4i v\u1EC1 kh\xE1ch s\u1EA1n,`,
  `H\u01A1n n\u1EEFa, chi\u1EBFc xe n\xE0y si\xEAu tho\u1EA3i m\xE1i,`,
  `B\u1EA1n th\u1EA5y kh\xF4ng, gh\u1EBF ng\u1ED3i c\xF2n c\xF3 n\xFAt b\u1EA5m n\u1EEFa.`,
  `C\u1EE9 nh\u01B0 v\u1EADy l\xE0 \u0111\u01B0\u1EE3c.`,
  `Tada, t\xF4i \u0111\xE3 c\xF3 Makau Pass r\u1ED3i. G\xF3i du l\u1ECBch l\u1EA7n n\xE0y c\u1EE7a ch\xFAng t\xF4i c\u0169ng bao g\u1ED3m Makau Pass n\xE0y.`,
  `\u0110\u1EBFn Ma Cao nh\u1EA5t \u0111\u1ECBnh ph\u1EA3i c\xF3 Makau Pass, v\xEC Makau Pass n\xE0y c\xF3 th\u1EC3 d\xF9ng \u0111\u1EC3 \u0111i xe bu\xFDt,`,
  `V\xE0 mua s\u1EAFm. B\xE2y gi\u1EDD ch\xFAng t\xF4i s\u1EBD \u0111i nh\u1EADn ph\xF2ng,`,
  `Ch\xFAng t\xF4i \u0111\xE3 nh\u1EADn ph\xF2ng kh\xE1ch s\u1EA1n r\u1ED3i, b\xE2y gi\u1EDD s\u1EBD d\u1EABn m\u1ECDi ng\u01B0\u1EDDi \u0111i tham quan ph\xF2ng nhanh.`,
  `T\xF4i \u0111\xE3 t\u1EAFm r\u1EEDa xong, t\xF4i mu\u1ED1n chia s\u1EBB v\u1EDBi m\u1ECDi ng\u01B0\u1EDDi r\u1EB1ng chuy\u1EBFn \u0111i Ma Cao l\u1EA7n n\xE0y c\u1EE7a t\xF4i th\u1EF1c ra l\xE0 m\u1ED9t g\xF3i du l\u1ECBch \u0111\u01B0\u1EE3c \u0111\u1EB7t tr\xEAn Touch 'n Go eWallet,`,
  `T\xEAn c\u1EE7a g\xF3i du l\u1ECBch n\xE0y l\xE0 Voyage,`,
  `N\xF3 bao g\u1ED3m v\xE9 m\xE1y bay, ch\u1ED7 \u1EDF,`,
  `D\u1ECBch v\u1EE5 \u0111\u01B0a \u0111\xF3n s\xE2n bay, v\xE0 m\u1ED9t s\u1ED1 Voucher, v.v.`,
  `Ngo\xE0i vi\u1EC7c r\u1EA5t ti\u1EC7n l\u1EE3i, t\xF4i ngh\u0129 gi\xE1 c\u1EE7a n\xF3 c\u0169ng kh\xE1 ph\u1EA3i ch\u0103ng.`,
  `Trong v\xE0i ng\xE0y t\u1EDBi, t\xF4i s\u1EBD c\xF9ng c\xE1c b\u1EA1n tr\u1EA3i nghi\u1EC7m g\xF3i du l\u1ECBch n\xE0y,`,
  `\u0110\u01B0a c\xE1c b\u1EA1n \u0111i \u0103n u\u1ED1ng \u1EDF Macao.`,
  `B\xE2y gi\u1EDD ch\xFAng ta s\u1EBD ra ngo\xE0i,`,
  `V\u1EEBa nhanh ch\xF3ng chia s\u1EBB l\xE0 \u1EDF Galaxy Macau Pass n\xE0y c\u0169ng c\xF3 th\u1EC3 mua Makau Pass,`,
  `Makau Pass \u1EDF \u0111\xE2y l\xE0 phi\xEAn b\u1EA3n \u0111\u1EB7c bi\u1EC7t, c\xE1c b\u1EA1n c\xF2n c\xF3 th\u1EC3 tr\u1EF1c ti\u1EBFp n\u1EA1p ti\u1EC1n \u1EDF \u0111\xE2y.`,
  `\u0110\u1EBFn Macao nh\u1EA5t \u0111\u1ECBnh ph\u1EA3i \u0103n m\xF3n rau \u0111\u1EAFng ch\xEDnh hi\u1EC7u.`,
  `\u0110\xE3 g\u1ECDi m\u1ED9t su\u1EA5t c\u01A1m h\u1EA7m h\u1EA3i s\u1EA3n \u0111\u1EAFng,`,
  `V\xE0 g\xE0 n\u01B0\u1EDBng \u0111\u1EB7c bi\u1EC7t.`,
  `C\u01A1m \u1EDF \u0111\xE2y ngon qu\xE1,`,
  `H\u1EA3i s\u1EA3n r\u1EA5t t\u01B0\u01A1i.`,
  `Th\u1EADt s\u1EF1 r\u1EA5t ti\u1EC7n l\u1EE3i.`,
  `B\xE2y gi\u1EDD t\xF4i s\u1EBD l\u1EA5y v\xE9,`,
  `\u0110\u1EC3 \u0111i xem th\xE1p Macao.`,
  `Anh \u1EA5y \u0111\u01B0a cho ch\xFAng t\xF4i.`,
  `H\u1EA3i s\u1EA3n t\u1EF1 ch\u1ECDn c\u1EE7a t\xF4i,`,
  `C\u1EA3 con h\xE0u n\xE0y n\u1EEFa. \u1EEAm,`,
  `Wow, n\xF3 th\u1EF1c s\u1EF1 r\u1EA5t t\u01B0\u01A1i.`,
  `C\u1EE9 nh\u01B0 th\u1EC3 t\xF4i \u0111ang b\u01B0\u1EDBc v\xE0o m\u1ED9t l\xE2u \u0111\xE0i, m\u1ED9t th\u1EBF gi\u1EDBi c\u1ED5 t\xEDch v\u1EADy.`,
  `N\u01A1i n\xE0y th\u1EF1c s\u1EF1 r\u1EA5t \u0111\u1EB9p.`,
  `Trung t\xE2m th\u01B0\u01A1ng m\u1EA1i n\xE0y c\xF3 r\u1EA5t nhi\u1EC1u ti\u1EC7m b\xE1nh.`,
  `Nh\u1EEFng ti\u1EC7m b\xE1nh n\xE0y \u0111\u1EC1u b\xE1n nh\u1EEFng lo\u1EA1i b\xE1nh quy \u0111\u1ECBa ph\u01B0\u01A1ng \u0111\u1EB7c tr\u01B0ng.`,
  `B\xE2y gi\u1EDD t\xF4i s\u1EBD \u0111i mua v\xE0i m\xF3n qu\xE0 l\u01B0u ni\u1EC7m v\u1EC1 cho gia \u0111\xECnh.`,
  `B\xE1nh g\xE0, c\xF2n c\xF3 ch\u1EEF 'c\u1EE5c c\u1EE5c c\u1EE5c c\u1EE5c c\u1EE5c'.`,
  `Ng\xE0y cu\u1ED1i c\xF9ng r\u1ED3i, cu\u1ED1i c\xF9ng c\u0169ng mua \u0111\u01B0\u1EE3c b\xE1nh tart tr\u1EE9ng m\xE0 t\xF4i h\u1EB1ng mong \u01B0\u1EDBc.`,
  `\u0110\xE2y l\xE0 b\xE1nh tart tr\u1EE9ng ngon nh\u1EA5t Ma Cao.`,
  `\u01AFm, n\xF3 th\u1EF1c s\u1EF1 r\u1EA5t th\u01A1m.`,
  `Ch\u1EC9 c\u1EA7n mua tr\xEAn \u1EE9ng d\u1EE5ng Touch 'n Go eWallet, \u1EDF \u0111\xE2y c\xF3 nhi\u1EC1u g\xF3i kh\xE1c nhau \u0111\u1EC3 m\u1ECDi ng\u01B0\u1EDDi l\u1EF1a ch\u1ECDn \u0111\xF3.`,
  `\u0110\u01A1n gi\u1EA3n l\xE0 v\u1EADy \u0111\xF3.`,
  `T\u1EA1m bi\u1EC7t!`
];
