var TEDED_WILDLIFE_CLIMATE_GYWPFSJ_MBA_TRANSLATIONS = [
  `Nhi\u1EC7t \u0111\u1ED9 v\xE0 m\u1EF1c n\u01B0\u1EDBc bi\u1EC3n ng\xE0y c\xE0ng t\u0103ng cao,`,
  `h\u1EA1n h\xE1n nghi\xEAm tr\u1ECDng,`,
  `\u0111\u1ECBa h\xECnh thay \u0111\u1ED5i,`,
  `t\u1EA5t c\u1EA3 nh\u1EEFng \u0111i\u1EC1u n\xE0y khi\u1EBFn kh\u1EA3 n\u0103ng th\xEDch \u1EE9ng th\xE0nh c\xF4ng v\u1EDBi bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu tr\u1EDF n\xEAn quan tr\u1ECDng h\u01A1n bao gi\u1EDD h\u1EBFt.`,
  `\u0110\u1ED1i v\u1EDBi con ng\u01B0\u1EDDi ch\xFAng ta, \u0111\xF3 l\xE0 vi\u1EC7c s\u1EED d\u1EE5ng c\xF4ng ngh\u1EC7 ti\xEAn ti\u1EBFn \u0111\u1EC3 t\xECm ki\u1EBFm c\xE1c gi\u1EA3i ph\xE1p,`,
  `ch\u1EB3ng h\u1EA1n nh\u01B0 c\xE1c th\xE0nh ph\u1ED1 th\xF4ng minh h\u01A1n v\xE0 qu\u1EA3n l\xFD t\xE0i nguy\xEAn n\u01B0\u1EDBc t\u1ED1t h\u01A1n.`,
  `Nh\u01B0ng \u0111\u1ED1i v\u1EDBi \u0111\u1ED9ng v\u1EADt v\xE0 th\u1EF1c v\u1EADt,`,
  `\u0111\u1EC3 th\xEDch nghi v\u1EDBi nh\u1EEFng thay \u0111\u1ED5i n\xE0y c\u1EA7n c\xF3 c\xE1ch th\u1EE9c c\u1ED5 x\u01B0a nh\u1EA5t,`,
  `\u0111\xF3 l\xE0 s\u1EF1 ti\u1EBFn h\xF3a.`,
  `Ti\u1EBFn h\xF3a th\u01B0\u1EDDng m\u1EA5t h\xE0ng tr\u0103m tri\u1EC7u, th\u1EADm ch\xED h\xE0ng t\u1EF7 n\u0103m,`,
  `nh\u01B0ng trong nh\u1EEFng m\xF4i tr\u01B0\u1EDDng lo\u1EA1i b\u1ECF c\u1EF1c k\u1EF3 kh\u1EAFc nghi\u1EC7t nh\u01B0 bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu nhanh ch\xF3ng,`,
  `c\xE1c lo\xE0i \u0111ang ti\u1EBFn h\xF3a nhanh ch\xF3ng.`,
  `Trong v\xE0i th\u1EADp k\u1EF7 g\u1EA7n \u0111\xE2y, ch\xFAng ta \u0111\xE3 ch\u1EE9ng ki\u1EBFn nhi\u1EC1u lo\xE0i th\u1EF1c v\u1EADt,`,
  `\u0111\u1ED9ng v\u1EADt, c\xF4n tr\xF9ng di c\u01B0.`,
  `Ch\xFAng \u0111\xE3 tr\u1EA3i qua nh\u1EEFng thay \u0111\u1ED5i v\u1EC1 k\xEDch th\u01B0\u1EDBc c\u01A1 th\u1EC3,`,
  `v\xE0 s\u1EF1 thay \u0111\u1ED5i th\u1EDDi gian ra hoa, sinh s\u1EA3n.`,
  `Tuy nhi\xEAn, \u0111\u1ED1i v\u1EDBi c\xE1c \u0111\u1EB7c \u0111i\u1EC3m sinh l\xFD c\xE1 th\u1EC3,`,
  `nhi\u1EC1u thay \u0111\u1ED5i c\xF3 t\xEDnh ch\u1EA5t m\u1EC1m d\u1EBBo,`,
  `ngh\u0129a l\xE0 nh\u1EEFng thay \u0111\u1ED5i kh\xF4ng th\u1EC3 di truy\u1EC1n.`,
  `H\u01A1n n\u1EEFa, kh\u1EA3 n\u0103ng c\u1EE7a m\u1ED9t sinh v\u1EADt \u0111\u1EC3 thay \u0111\u1ED5i ch\u1EE9c n\u0103ng sinh l\xFD c\u1EE7a m\xECnh nh\u1EB1m th\xEDch nghi v\u1EDBi y\xEAu c\u1EA7u m\xF4i tr\u01B0\u1EDDng l\xE0 c\xF3 h\u1EA1n.`,
  `kh\u1EA3 n\u0103ng thay \u0111\u1ED5i ch\u1EE9c n\u0103ng sinh l\xFD c\u1EE7a m\u1ED9t sinh v\u1EADt \u0111\u1EC3 th\xEDch nghi v\u1EDBi y\xEAu c\u1EA7u m\xF4i tr\u01B0\u1EDDng l\xE0 c\xF3 h\u1EA1n.`,
  `\u0110\xE2y l\xE0 l\xFD do t\u1EA1i sao c\xE1c nh\xE0 khoa h\u1ECDc \u0111ang t\xECm ki\u1EBFm c\xE1c v\xED d\u1EE5 v\u1EC1 qu\xE1 tr\xECnh ti\u1EBFn h\xF3a trong DNA c\u1EE7a lo\xE0i.`,
  `Nh\u1EEFng thay \u0111\u1ED5i ti\u1EBFn h\xF3a n\xE0y c\xF3 t\xEDnh di truy\u1EC1n,`,
  `l\xE0 b\u1EC1n v\u1EEFng v\xE0 c\xF3 \xFD ngh\u0129a l\u1EDBn \u0111\u1ED1i v\u1EDBi t\u01B0\u01A1ng lai c\u1EE7a lo\xE0i.`,
  `L\u1EA5y c\xFA x\xE1m l\xE0m v\xED d\u1EE5,`,
  `N\u1EBFu ba m\u01B0\u01A1i n\u0103m tr\u01B0\u1EDBc b\u1EA1n \u0111i b\u1ED9 trong khu r\u1EEBng l\u1EA1nh gi\xE1 \u1EDF B\u1EAFc \xC2u,`,
  `B\u1EA1n c\xF3 th\u1EC3 kh\xF4ng nh\xECn th\u1EA5y lo\xE0i chim kh\xF3 t\xECm n\xE0y,`,
  `M\xE0 c\xF3 th\u1EC3 ch\u1EC9 nghe th\u1EA5y \xE2m thanh c\u1EE7a ch\xFAng.`,
  `Tr\xEAn n\u1EC1n tuy\u1EBFt tr\u1EAFng,`,
  `L\xF4ng c\u1EE7a ch\xFAng kh\xF3 b\u1ECB ph\xE1t hi\u1EC7n.`,
  `T\xECnh h\xECnh ng\xE0y nay \u0111\xE3 r\u1EA5t kh\xE1c.`,
  `T\u1EEB khi bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu v\xE0o nh\u1EEFng n\u0103m 1980 khi\u1EBFn l\u01B0\u1EE3ng tuy\u1EBFt r\u01A1i gi\u1EA3m m\u1EA1nh,`,
  `nh\u01B0ng b\u1EA1n v\u1EABn kh\xF3 t\xECm th\u1EA5y c\xFA tro, v\xEC gi\u1EDD \u0111\xE2y ch\xFAng chuy\u1EC3n sang m\xE0u n\xE2u.`,
  `Bi\u1EBFn th\u1EC3 m\xE0u n\xE2u n\xE0y l\xE0 \u0111\u1EB7c \u0111i\u1EC3m tr\u1ED9i c\u1EE7a lo\xE0i,`,
  `nh\u01B0ng trong l\u1ECBch s\u1EED, \u0111\u1EB7c \u0111i\u1EC3m l\u1EB7n m\xE0u x\xE1m nh\u1EA1t l\u1EA1i chi\u1EBFm \u01B0u th\u1EBF.`,
  `Nh\u1EDD nh\u1EEFng l\u1EE3i th\u1EBF ch\u1ECDn l\u1ECDc \u0111\u1EB7c bi\u1EC7t n\xE0y,`,
  `nh\u1EEFng k\u1EBB s\u0103n m\u1ED3i n\xE0y c\xF3 th\u1EC3 h\xF2a nh\u1EADp v\xE0o m\xF4i tr\u01B0\u1EDDng.`,
  `Nh\u01B0ng l\u01B0\u1EE3ng tuy\u1EBFt r\u01A1i gi\u1EA3m \u0111\xE3 l\xE0m gi\u1EA3m hi\u1EC7u qu\u1EA3 ng\u1EE5y trang c\u1EE7a ch\xFAng,`,
  `n\xEAn trong ch\u1ECDn l\u1ECDc t\u1EF1 nhi\xEAn g\u1EA7n \u0111\xE2y, bi\u1EBFn th\u1EC3 m\xE0u x\xE1m thua k\xE9m h\u01A1n.`,
  `Tuy nhi\xEAn, nh\u1EEFng c\xE1 th\u1EC3 mang bi\u1EBFn th\u1EC3 m\xE0u n\xE2u l\u1EA1i c\xF3 l\u1EE3i th\u1EBF trong c\xE1c khu r\u1EEBng l\u1ED9 thi\xEAn,`,
  `v\xE0 c\xFA tro m\xE0u n\xE2u ng\xE0y c\xE0ng nhi\u1EC1u.`,
  `M\u1ED9t s\u1ED1 lo\xE0i kh\xE1c c\u0169ng tr\u1EA3i qua nh\u1EEFng bi\u1EBFn \u0111\u1ED5i t\u01B0\u01A1ng t\u1EF1 \u0111\u1EC3 th\xEDch nghi v\u1EDBi bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu trong nh\u1EEFng th\u1EADp k\u1EF7 g\u1EA7n \u0111\xE2y.`,
  `Mu\u1ED7i \u0103n th\u1ECBt \u0111\xE3 ti\u1EBFn h\xF3a nhanh ch\xF3ng,`,
  `ch\xFAng b\u1EAFt \u0111\u1EA7u ng\u1EE7 \u0111\xF4ng mu\u1ED9n h\u01A1n,`,
  `\u0111\u1EC3 t\u1EADn d\u1EE5ng th\u1EDDi ti\u1EBFt \u1EA5m \xE1p h\u01A1n.`,
  `Tr\u01B0\u1EDBc \u0111\xE2y c\xF3 s\u1ED1 l\u01B0\u1EE3ng b\u1ECD r\xF9a hai ch\u1EA5m lo\u1EA1i \u0111en v\xE0 kh\xF4ng \u0111en t\u01B0\u01A1ng \u0111\u01B0\u01A1ng nhau,`,
  `gi\u1EDD \u0111\xE2y ch\xFAng \u0111\xE3 ho\xE0n to\xE0n bi\u1EBFn th\xE0nh lo\u1EA1i kh\xF4ng \u0111en.`,
  `C\xE1c nh\xE0 khoa h\u1ECDc cho r\u1EB1ng \u0111i\u1EC1u n\xE0y gi\xFAp ch\xFAng kh\xF4ng b\u1ECB qu\xE1 nhi\u1EC7t.`,
  `\u0110\u1ED3ng th\u1EDDi, c\xE1 h\u1ED3i Coho, b\u1EB1ng c\xE1ch \u0111\u1EBB tr\u1EE9ng s\u1EDBm h\u01A1n \u0111\u1EC3 b\u1EA3o v\u1EC7 nh\u1EEFng qu\u1EA3 tr\u1EE9ng m\u1ECFng manh c\u1EE7a m\xECnh,`,
  `\u0111\xE3 th\xEDch nghi v\u1EDBi v\xF9ng n\u01B0\u1EDBc \u1EA5m h\u01A1n.`,
  `C\u1ECF x\u1EA1 h\u01B0\u01A1ng hoang d\xE3 \u1EDF ch\xE2u \xC2u ti\u1EBFt ra nhi\u1EC1u d\u1EA7u b\u1EA3o v\u1EC7 h\u01A1n \u0111\u1EC3 ch\u1ED1ng l\u1EA1i s\u1EF1 gia t\u0103ng c\u1EE7a \u0111\u1ED9ng v\u1EADt \u0103n c\u1ECF do th\u1EDDi ti\u1EBFt \u1EA5m \xE1p.`,
  `Nh\u1EEFng lo\xE0i n\xE0y thu\u1ED9c m\u1ED9t qu\u1EA7n th\u1EC3 v\u1EDBi hai m\u01B0\u01A1i lo\xE0i \u0111\u01B0\u1EE3c x\xE1c \u0111\u1ECBnh.`,
  `Nh\u1EEFng lo\xE0i n\xE0y bao g\u1ED3m r\u1EAFn,`,
  `C\xE1c lo\xE0i ti\u1EBFn h\xF3a \u0111\u1EC3 th\xEDch nghi v\u1EDBi bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu, bao g\u1ED3m r\xF9a c\xE1 s\u1EA5u,`,
  `nh\u01B0 \u1EBFch g\u1ED7, c\xE2y h\u1ECD c\xFAc v\xE0 b\u01B0\u1EDBm b\u1EA1c \u0111\u1ED1m.`,
  `Tuy nhi\xEAn, c\xE1c nh\xE0 khoa h\u1ECDc hy v\u1ECDng trong s\u1ED1 87 tri\u1EC7u lo\xE0i tr\xEAn Tr\xE1i \u0110\u1EA5t,`,
  `s\u1EBD t\xECm th\u1EA5y nhi\u1EC1u lo\xE0i h\u01A1n \u0111\xE3 ti\u1EBFn h\xF3a \u0111\u1EC3 th\xEDch nghi v\u1EDBi bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu.`,
  `B\u1EDFi v\xEC \u0111\u1ED1i v\u1EDBi s\u1EF1 \u0111a d\u1EA1ng sinh h\u1ECDc qu\xFD gi\xE1 v\xE0 \u0111\xE1ng kinh ng\u1EA1c tr\xEAn h\xE0nh tinh c\u1EE7a ch\xFAng ta,`,
  `ti\u1EBFn h\xF3a kh\xF4ng ph\u1EA3i l\xE0 c\xE2u tr\u1EA3 l\u1EDDi cu\u1ED1i c\xF9ng.`,
  `Ng\u01B0\u1EE3c l\u1EA1i, nhi\u1EC1u lo\xE0i c\u1EA7n ch\xFAng ta gi\xFAp \u0111\u1EE1 \u0111\u1EC3 t\u1ED3n t\u1EA1i trong m\u1ED9t th\u1EBF gi\u1EDBi \u0111ang thay \u0111\u1ED5i,`,
  `N\u1EBFu kh\xF4ng, ch\xFAng s\u1EBD di\u1EC7t vong.`,
  `Tin t\u1ED1t l\xE0 ch\xFAng ta \u0111\xE3 c\xF3 m\u1ED9t s\u1ED1 c\xF4ng c\u1EE5,`,
  `tr\xEAn to\xE0n c\u1EA7u, ch\xFAng ta \u0111\xE3 \u0111\u01B0a ra m\u1ED9t s\u1ED1 quy\u1EBFt \u0111\u1ECBnh th\u1EF1c s\u1EF1.`,
  `Nh\u1EEFng quy\u1EBFt \u0111\u1ECBnh \u0111\xF3 s\u1EBD gi\xFAp to\xE0n b\u1ED9 h\u1EC7 sinh th\xE1i th\xEDch nghi v\u1EDBi nh\u1EEFng ng\u01B0\u1EDDi t\u1ECB n\u1EA1n do bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu \u0111ang \u0111\u01B0\u1EE3c x\xE1c \u0111\u1ECBnh v\xE0 b\u1EA3o v\u1EC7.`,
  `C\xE1c k\u1EBF ho\u1EA1ch gi\xFAp c\xE1c lo\xE0i di c\u01B0 \u0111ang \u0111\u01B0\u1EE3c ti\u1EBFn h\xE0nh,`,
  `ch\xFAng c\xF3 th\u1EC3 di chuy\u1EC3n \u0111\u1EBFn m\xF4i tr\u01B0\u1EDDng kh\xED h\u1EADu ph\xF9 h\u1EE3p h\u01A1n.`,
  `C\xE1c c\xF4ng vi\xEAn v\xE0 khu b\u1EA3o t\u1ED3n hi\u1EC7n c\xF3 \u0111ang ti\u1EBFn h\xE0nh \u0111i\u1EC1u tra bi\u1EBFn \u0111\u1ED5i kh\xED h\u1EADu \u0111\u1EC3 gi\xFAp \u0111\u1ED9ng v\u1EADt hoang d\xE3 th\xEDch nghi.`,
  `May m\u1EAFn thay, t\u1EA5t c\u1EA3 nh\u1EEFng \u0111i\u1EC1u n\xE0y v\u1EABn n\u1EB1m trong t\u1EA7m ki\u1EC3m so\xE1t c\u1EE7a ch\xFAng ta.`,
  `Ch\xFAng ta v\u1EABn c\xF3 th\u1EC3 b\u1EA3o v\u1EC7 s\u1EF1 \u0111a d\u1EA1ng sinh h\u1ECDc k\u1EF3 l\u1EA1 tr\xEAn h\xE0nh tinh n\xE0y,`,
  `sau c\xF9ng, ch\xFAng \u0111ang h\u1ED7 tr\u1EE3 s\u1EF1 s\u1ED1ng c\xF2n c\u1EE7a lo\xE0i ng\u01B0\u1EDDi ch\xFAng ta b\u1EB1ng nhi\u1EC1u c\xE1ch kh\xE1c nhau.`,
  `B\u1EA3o v\u1EC7 v\xE0 b\u1EA3o t\u1ED3n thi\xEAn nhi\xEAn c\u1EE7a ch\xFAng ta c\u1EA7n tr\u1EDF th\xE0nh \u01B0u ti\xEAn h\xE0ng \u0111\u1EA7u c\u1EE7a m\u1ECDi qu\u1ED1c gia,`,
  `c\xF4ng ty v\xE0 c\u1ED9ng \u0111\u1ED3ng tr\xEAn th\u1EBF gi\u1EDBi.`,
  `N\u1EBFu b\u1EA1n mu\u1ED1n bi\u1EBFt b\u1EA1n c\xF3 th\u1EC3 th\u1EF1c hi\u1EC7n nh\u1EEFng bi\u1EC7n ph\xE1p c\u1EE5 th\u1EC3 n\xE0o ngay b\xE2y gi\u1EDD \u0111\u1EC3 gi\xFAp \u0111\u1EA1t \u0111\u01B0\u1EE3c m\u1EE5c ti\xEAu n\xE0y,`,
  `vui l\xF2ng truy c\u1EADp eddoted.com/earthgoal.`
];
