var TEDED_TOILET_HISTORY_UPY3BQ8TZOQ_TRANSLATIONS = [
  `V\xE0o nh\u1EEFng ng\xE0y n\u1EAFng r\xE1o, c\xE1c c\xF4ng d\xE2n La M\xE3 c\u1ED5 \u0111\u1EA1i c\u1EE7a Ostia s\u1EBD t\u1EADp trung t\u1EA1i m\u1ED9t b\u0103ng gh\u1EBF d\xE0i b\u1EB1ng \u0111\xE1 ch\u1EA1y d\u1ECDc theo n\u01A1i h\u1ED9i h\u1ECDp c\xF4ng c\u1ED9ng.`,
  `Trong l\xFAc b\u1EA1n b\xE8 v\xE0 h\xE0ng x\xF3m trao \u0111\u1ED5i tin t\u1EE9c v\xE0 chuy\u1EC7n phi\u1EBFm,`,
  `h\u1ECD c\u0169ng tham gia v\xE0o m\u1ED9t vi\u1EC7c c\u1EA5p b\xE1ch h\u01A1n nhi\u1EC1u.`,
  `Nh\u1EEFng nh\xE0 v\u1EC7 sinh c\xF4ng c\u1ED9ng n\xE0y c\xF3 th\u1EC3 ch\u1EE9a t\u1EDBi 20 c\xF4ng d\xE2n La M\xE3 m\u1ED9t l\xFAc,`,
  `v\xE0 s\u1EED d\u1EE5ng n\u01B0\u1EDBc ch\u1EA3y b\xEAn d\u01B0\u1EDBi \u0111\u1EC3 lo\u1EA1i b\u1ECF ch\u1EA5t th\u1EA3i.`,
  `Ng\xE0y nay, h\u1EA7u h\u1EBFt c\xE1c n\u1EC1n v\u0103n h\xF3a coi vi\u1EC7c \u0111i v\u1EC7 sinh l\xE0 m\u1ED9t chuy\u1EC7n ri\xEAng t\u01B0 h\u01A1n.`,
  `Th\u1EBF nh\u01B0ng ngay c\u1EA3 khi \u0111i v\u1EC7 sinh m\u1ED9t m\xECnh,`,
  `c\u01A1 s\u1EDF h\u1EA1 t\u1EA7ng n\u01B0\u1EDBc th\u1EA3i c\xF4ng c\u1ED9ng v\u1EABn l\xE0 m\u1ED9t trong nh\u1EEFng ph\xE1t minh quan tr\u1ECDng nh\u1EA5t trong l\u1ECBch s\u1EED nh\xE2n lo\u1EA1i.`,
  `Nhi\u1EC1u v\u0103n b\u1EA3n t\xF4n gi\xE1o c\u1ED5 \u0111\u1EA1i m\xF4 t\u1EA3 c\xE1c ph\u01B0\u01A1ng ph\xE1p t\xE1ch n\u01B0\u1EDBc th\u1EA3i kh\u1ECFi n\u01B0\u1EDBc u\u1ED1ng v\xE0 khu c\u1EAFm tr\u1EA1i.`,
  `Vi\u1EC7c qu\u1EA3n l\xFD n\u01B0\u1EDBc th\u1EA3i t\u01B0\u01A1ng t\u1EF1 nh\u01B0 hi\u1EC7n \u0111\u1EA1i \u0111\xE3 c\xF3 t\u1EEB n\u0103m 3000 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn.`,
  `C\xE1c khu \u0111\u1ECBnh c\u01B0 c\u1ED5 \u0111\u1EA1i c\u1EE7a L\u01B0\u1EE1ng H\xE0 c\xF3 m\u1ED9t c\u1EA5u tr\xFAc b\u1EB1ng \u0111\u1EA5t s\xE9t \u1EDF v\u1ECB tr\xED ri\xEAng t\u01B0 nh\u1EA5t trong nh\xE0,`,
  `th\u01B0\u1EDDng \u0111\u01B0\u1EE3c d\xF9ng \u0111\u1EC3 ng\u1ED3i x\u1ED5m.`,
  `Ch\xFAng \u0111\u01B0\u1EE3c n\u1ED1i v\u1EDBi c\xE1c \u0111\u01B0\u1EDDng \u1ED1ng d\u1EABn n\u01B0\u1EDBc th\u1EA3i ra r\xE3nh v\xE0 h\u1ED1 ga tr\xEAn \u0111\u01B0\u1EDDng ph\u1ED1.`,
  `V\xED d\u1EE5 tr\xEAn ph\xE1t tri\u1EC3n m\u1EA1nh m\u1EBD v\xE0o th\u1EDDi k\u1EF3 \u0111\u1ED3 \u0111\u1ED3ng,`,
  `cho ph\xE9p c\xE1c gia \u0111\xECnh kh\xF4ng ch\u1EC9 x\u1EED l\xFD ch\u1EA5t th\u1EA3i c\u1EE7a con ng\u01B0\u1EDDi m\xE0 c\xF2n t\u1EAFm r\u1EEDa v\xE0 gi\u1EB7t gi\u0169.`,
  `c\u0169ng nh\u01B0 \u1EDF m\u1ED9t s\u1ED1 khu v\u1EF1c thu\u1ED9c l\u01B0u v\u1EF1c s\xF4ng \u1EA4n,`,
  `h\u1EA7u h\u1EBFt m\u1ECDi nh\xE0 v\u1EC7 sinh \u0111\u1EC1u \u0111\u01B0\u1EE3c k\u1EBFt n\u1ED1i v\u1EDBi h\u1EC7 th\u1ED1ng tho\xE1t n\u01B0\u1EDBc th\xE0nh ph\u1ED1.`,
  `Nh\xE0 v\u1EC7 sinh trong c\xE1c cung \u0111i\u1EC7n c\u1ED5 \u1EDF Crete th\u1EADm ch\xED c\xF2n c\xF3 th\u1EC3 x\u1EA3 n\u01B0\u1EDBc th\u1EE7 c\xF4ng.`,
  `C\xE1c nh\xE0 nghi\xEAn c\u1EE9u kh\xF4ng ch\u1EAFc ch\u1EAFn v\u1EC1 c\xE1ch nh\u1EEFng h\u1EC7 th\u1ED1ng tho\xE1t n\u01B0\u1EDBc ban \u0111\u1EA7u n\xE0y \u0111\u01B0\u1EE3c ph\xE1t minh,`,
  `nh\u01B0ng c\xF3 th\u1EC3 kh\u1EB3ng \u0111\u1ECBnh r\u1EB1ng vi\u1EC7c qu\u1EA3n l\xFD n\u01B0\u1EDBc th\u1EA3i l\xE0 y\u1EBFu t\u1ED1 then ch\u1ED1t \u0111\u1ED1i v\u1EDBi s\u1EE9c kh\u1ECFe c\u1ED9ng \u0111\u1ED3ng.`,
  `N\u01B0\u1EDBc th\u1EA3i ch\u01B0a \u0111\u01B0\u1EE3c x\u1EED l\xFD c\xF3 th\u1EC3 nu\xF4i d\u01B0\u1EE1ng vi sinh v\u1EADt c\xF3 h\u1EA1i,`,
  `g\xE2y ra c\xE1c b\u1EC7nh nh\u01B0 t\u1EA3,`,
  `ki\u1EBFt l\u1EF5 v\xE0 s\u1ED1t th\u01B0\u01A1ng h\xE0n.`,
  `Tuy nhi\xEAn, ph\u1EA3i m\u1EA5t h\xE0ng ngh\xECn n\u0103m sau c\xE1c nh\xE0 khoa h\u1ECDc m\u1EDBi c\xF3 th\u1EC3 hi\u1EC3u r\xF5 m\u1ED1i quan h\u1EC7 gi\u1EEFa n\u01B0\u1EDBc th\u1EA3i v\xE0 b\u1EC7nh t\u1EADt.`,
  `D\xF9 v\u1EADy, m\u1ED1i li\xEAn h\u1EC7 gi\u1EEFa m\xF9i n\u01B0\u1EDBc th\u1EA3i h\xF4i th\u1ED1i v\xE0 b\u1EC7nh t\u1EADt \u0111\xE3 \u0111\u01B0\u1EE3c ghi nh\u1EADn t\u1EEB n\u0103m 100 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn.`,
  `\u0110\u1EBFn n\u0103m 100 sau C\xF4ng nguy\xEAn, c\xE1c gi\u1EA3i ph\xE1p v\u1EC7 sinh ph\u1EE9c t\u1EA1p h\u01A1n \u0111\xE3 xu\u1EA5t hi\u1EC7n.`,
  `\u0110\u1EBF ch\u1EBF La M\xE3 s\u1EED d\u1EE5ng h\u1EC7 th\u1ED1ng d\u1EABn n\u01B0\u1EDBc ch\u1EA3y li\xEAn t\u1EE5c,`,
  `\u0111\u01B0a n\u01B0\u1EDBc th\u1EA3i ra ngo\u1EA1i \xF4 th\xE0nh ph\u1ED1.`,
  `C\xF9ng th\u1EDDi k\u1EF3, Trung Qu\u1ED1c c\u0169ng c\xF3 nh\xE0 v\u1EC7 sinh ri\xEAng v\xE0 c\xF4ng c\u1ED9ng.`,
  `Tuy nhi\xEAn, \u1EDF Trung Qu\u1ED1c, ch\u1EA5t th\u1EA3i n\xE0y \u0111\u01B0\u1EE3c t\xE1i s\u1EED d\u1EE5ng ngay l\u1EADp t\u1EE9c,`,
  `Ph\xE2n ng\u01B0\u1EDDi t\u1EEB nh\xE0 v\u1EC7 sinh gia \u0111\xECnh ch\u1EE7 y\u1EBFu \u0111\u01B0\u1EE3c d\xF9ng \u0111\u1EC3 nu\xF4i l\u1EE3n,`,
  `c\xF2n ch\u1EA5t th\u1EA3i t\u1EEB nh\xE0 v\u1EC7 sinh c\xF4ng c\u1ED9ng s\u1EBD \u0111\u01B0\u1EE3c ng\u01B0\u1EDDi chuy\xEAn tr\xE1ch thu gom,`,
  `sau \u0111\xF3 ch\u1EBF bi\u1EBFn th\xE0nh ph\xE2n b\xF3n \u0111\u1EC3 b\xE1n.`,
  `Ph\u01B0\u01A1ng ph\xE1p x\u1EED l\xFD ch\u1EA5t th\u1EA3i truy\u1EC1n th\u1ED1ng c\u1EE7a Trung Qu\u1ED1c \u0111\xE3 duy tr\xEC trong nhi\u1EC1u th\u1EBF k\u1EF7.`,
  `Nh\u01B0ng \u1EDF ch\xE2u \xC2u,`,
  `s\u1EF1 suy t\xE0n c\u1EE7a \u0110\u1EBF ch\u1EBF La M\xE3 \u0111\xE3 \u0111\u1EA9y v\u1EC7 sinh c\xF4ng c\u1ED9ng v\xE0o th\u1EDDi k\u1EF3 t\u0103m t\u1ED1i.`,
  `H\u1ED1 x\xED, c\xF2n \u0111\u01B0\u1EE3c g\u1ECDi l\xE0 "gong", r\u1EA5t ph\u1ED5 bi\u1EBFn.`,
  `B\xF4 th\u01B0\u1EDDng xuy\xEAn \u0111\u01B0\u1EE3c \u0111\u1ED5 th\u1EB3ng ra \u0111\u01B0\u1EDDng,`,
  `c\xF2n c\xE1c c\u1EEDa s\u1ED5 cao c\u1EE7a l\xE2u \u0111\xE0i th\xEC x\u1EA3 ch\u1EA5t th\u1EA3i xu\u1ED1ng h\u1ED1 ph\xE2n c\xF4ng c\u1ED9ng b\xEAn ngo\xE0i.`,
  `\u0110\u1EBFn \u0111\xEAm, nh\u1EEFng ng\u01B0\u1EDDi h\xF3t ph\xE2n s\u1EBD ch\u1EA5t \u0111\u1EA7y xe c\xFAt k\xEDt ch\u1EA5t th\u1EA3i,`,
  `ch\u1EDF ch\xFAng ra ngo\xE0i th\xE0nh ph\u1ED1 v\xE0 v\u1EE9t b\u1ECF.`,
  `Trong nhi\u1EC1u th\u1EBF k\u1EF7, ch\xE2u \xC2u kh\xF4ng x\u1EED l\xFD v\u1EC7 sinh ch\u1EA5t th\u1EA3i,`,
  `nh\u01B0ng b\u1EA3n th\xE2n nh\xE0 v\u1EC7 sinh \u0111\xE3 tr\u1EA3i qua m\u1ED9t s\u1ED1 thay \u0111\u1ED5i l\u1EDBn.`,
  `\u0110\u1EBFn cu\u1ED1i th\u1EDDi Trung c\u1ED5,`,
  `h\u1EA7u h\u1EBFt c\xE1c gia \u0111\xECnh gi\xE0u c\xF3 \u0111\u1EC1u \u0111\u01B0\u1EE3c trang b\u1ECB b\u1ED3n c\u1EA7u,`,
  `H\xF2m g\u1ED7 c\xF3 n\u1EAFp v\xE0 gh\u1EBF ng\u1ED3i.`,
  `Trong c\xE1c tri\u1EC1u \u0111\xECnh ho\xE0ng gia \u1EDF Anh,`,
  `nh\u1EEFng chi\u1EBFc b\xF4 n\xE0y \u0111\u01B0\u1EE3c c\xE1c th\u1ECB th\u1EA7n chuy\xEAn qu\u1EA3n l\xFD ch\u1EA5t th\u1EA3i ph\u1EE5 tr\xE1ch.`,
  `Ngo\xE0i ra, \u0111\u1EC3 theo d\xF5i s\u1EE9c kh\u1ECFe \u0111\u01B0\u1EDDng ru\u1ED9t c\u1EE7a nh\xE0 vua,`,
  `m\u1ED1i quan h\u1EC7 v\xF4 c\xF9ng th\xE2n thi\u1EBFt gi\u1EEFa v\u1ECB th\u1ECB th\u1EA7n n\xE0y v\xE0 nh\xE0 vua,`,
  `\u0111\xE3 khi\u1EBFn ch\u1EE9c danh n\xE0y tr\u1EDF n\xEAn c\u1EF1c k\u1EF3 c\xF3 \u1EA3nh h\u01B0\u1EDFng.`,
  `B\u01B0\u1EDBc nh\u1EA3y v\u1ECDt l\u1EDBn ti\u1EBFp theo trong l\u1ECBch s\u1EED ph\xE1t tri\u1EC3n c\xF4ng ngh\u1EC7 nh\xE0 v\u1EC7 sinh xu\u1EA5t hi\u1EC7n v\xE0o n\u0103m 1596.`,
  `Ng\xE0i John Harington \u0111\xE3 thi\u1EBFt k\u1EBF chi\u1EBFc b\u1ED3n c\u1EA7u x\u1EA3 n\u01B0\u1EDBc hi\u1EC7n \u0111\u1EA1i \u0111\u1EA7u ti\xEAn cho N\u1EEF ho\xE0ng Elizabeth.`,
  `\xD4ng s\u1EED d\u1EE5ng c\u1EA7n g\u1EA1t \u0111\u1EC3 x\u1EA3 n\u01B0\u1EDBc v\xE0 van \u0111\u1EC3 h\xFAt n\u01B0\u1EDBc t\u1EEB th\xF9ng,`,
  `t\u1EA1o ti\u1EC1n \u0111\u1EC1 cho thi\u1EBFt k\u1EBF b\u1ED3n c\u1EA7u hi\u1EC7n \u0111\u1EA1i.`,
  `Tuy nhi\xEAn, ph\xE1t minh c\u1EE7a Harington kh\xF4ng gi\u1EA3i quy\u1EBFt \u0111\u01B0\u1EE3c v\u1EA5n \u0111\u1EC1 ng\u0103n k\xE9o ch\u1EA5t th\u1EA3i.`,
  `May m\u1EAFn thay, \u0111\u1EBFn n\u0103m 1775,`,
  `nh\xE0 ph\xE1t minh ng\u01B0\u1EDDi Scotland Alexander Cumming \u0111\xE3 th\xEAm m\u1ED9t thi\u1EBFt k\u1EBF u\u1ED1n cong v\xE0o \u0111\u01B0\u1EDDng \u1ED1ng tho\xE1t n\u01B0\u1EDBc \u0111\u1EC3 gi\u1EEF n\u01B0\u1EDBc v\xE0 ng\u0103n m\xF9i h\xF4i.`,
  `Thi\u1EBFt k\u1EBF h\xECnh ch\u1EEF S n\xE0y,`,
  `\u0111\xE3 \u0111\u01B0\u1EE3c Thomas Crapper c\u1EA3i ti\u1EBFn th\xE0nh thi\u1EBFt k\u1EBF h\xECnh ch\u1EEF U hi\u1EC7n \u0111\u1EA1i.`,
  `M\u1EB7c d\xF9 thu\u1EADt ng\u1EEF`,
  `\u0110\u1EBFn cu\u1ED1i th\u1EBF k\u1EF7 19,`,
  `nhi\u1EC1u th\xE0nh ph\u1ED1 \u0111\xE3 c\xF3 c\u01A1 s\u1EDF h\u1EA1 t\u1EA7ng tho\xE1t n\u01B0\u1EDBc hi\u1EC7n \u0111\u1EA1i v\xE0 nh\xE0 m\xE1y x\u1EED l\xFD n\u01B0\u1EDBc th\u1EA3i.`,
  `Ng\xE0y nay, nh\xE0 v\u1EC7 sinh c\u0169ng \u0111\xE3 ph\xE1t tri\u1EC3n nhi\u1EC1u t\xEDnh n\u0103ng \u0111a d\u1EA1ng,`,
  `t\u1EEB sang tr\u1ECDng \u0111\u1EBFn b\u1EC1n v\u1EEFng.`,
  `Tuy nhi\xEAn, v\u1EABn c\xF2n kho\u1EA3ng 2 t\u1EF7 ng\u01B0\u1EDDi kh\xF4ng c\xF3 nh\xE0 v\u1EC7 sinh ri\xEAng t\u1EA1i nh\xE0,`,
  `v\xE0 2,2 t\u1EF7 ng\u01B0\u1EDDi kh\xE1c kh\xF4ng c\xF3 c\u01A1 s\u1EDF x\u1EED l\xFD n\u01B0\u1EDBc th\u1EA3i ph\xF9 h\u1EE3p,`,
  `khi\u1EBFn h\u1ECD ti\u1EBFp x\xFAc v\u1EDBi v\xF4 s\u1ED1 b\u1EC7nh t\u1EADt.`,
  `\u0110\u1EC3 gi\u1EA3i quy\u1EBFt v\u1EA5n \u0111\u1EC1 n\xE0y,`,
  `ch\xFAng ta c\u1EA7n ph\xE1t minh ra c\xE1c c\xF4ng ngh\u1EC7 v\u1EC7 sinh m\u1EDBi,`,
  `v\xE0 th\xF4ng qua c\xE1c y\u1EBFu t\u1ED1 h\xE0nh vi,`,
  `kinh t\u1EBF v\xE0 ch\xEDnh tr\u1ECB \u0111\u1EC3 gi\u1EA3i quy\u1EBFt s\u1EF1 b\u1EA5t b\xECnh \u0111\u1EB3ng trong h\u1EC7 th\u1ED1ng \u0111\u01B0\u1EDDng \u1ED1ng v\u1EC7 sinh.`,
  `\u0110\u1EC3 t\xECm hi\u1EC3u l\u1ECBch s\u1EED h\u1EA5p d\u1EABn, tri\u1EBFt l\xFD kh\xF3 hi\u1EC3u v\u1EC1 cu\u1ED9c phi\xEAu l\u01B0u ngo\xE0i kh\xF4ng gian,`,
  `c\xE2u tr\u1EA3 l\u1EDDi cho nh\u1EEFng c\xE2u h\u1ECFi ng\u1EABu nhi\xEAn nh\u1EA5t v\u1EC1 c\u01A1 th\u1EC3 b\u1EA1n, v.v.`,
  `H\xE3y \u0111\u0103ng k\xFD k\xEAnh n\xE0y,`,
  `H\xE3y ti\u1EBFp t\u1EE5c theo d\xF5i,`,
  `v\xE0 gi\u1EEF s\u1EF1 t\xF2 m\xF2.`
];
