var TEDED_ABSURD_QUESTIONS_9DNOI_RCVCO_TRANSLATIONS = [
  `Albert Camus l\u1EDBn l\xEAn trong b\u1ED1i c\u1EA3nh b\u1EA1o l\u1EF1c.`,
  `Qu\xEA h\u01B0\u01A1ng \xF4ng, Algeria,`,
  `ch\xECm trong xung \u0111\u1ED9t gi\u1EEFa ng\u01B0\u1EDDi d\xE2n Algeria b\u1EA3n \u0111\u1ECBa v\xE0 th\u1EF1c d\xE2n Ph\xE1p g\u1ED1c \xC2u.`,
  `\xD4ng m\u1EA5t cha trong Th\u1EBF chi\u1EBFn th\u1EE9 nh\u1EA5t,`,
  `v\xE0 b\u1ECB tuy\xEAn b\u1ED1 kh\xF4ng \u0111\u1EE7 s\u1EE9c kh\u1ECFe \u0111\u1EC3 chi\u1EBFn \u0111\u1EA5u trong Th\u1EBF chi\u1EBFn th\u1EE9 hai.`,
  `\u1EDE Ph\xE1p, \xF4ng \u0111\xE3 ch\u1EE9ng ki\u1EBFn v\xE0 chi\u1EBFn \u0111\u1EA5u v\u1EDBi t\u01B0 c\xE1ch l\xE0 m\u1ED9t ph\xF3ng vi\xEAn c\u1EE7a t\u1ED5 ch\u1EE9c kh\xE1ng chi\u1EBFn \u0111\u1EC3 tr\u1EF1c ti\u1EBFp \u0111\u1ED1i m\u1EB7t v\u1EDBi s\u1EF1 t\xE0n ph\xE1 c\u1EE7a chi\u1EBFn tranh.`,
  `Nh\u1EEFng tr\u1EA3i nghi\u1EC7m n\xE0y khi\u1EBFn Camus suy s\u1EE5p,`,
  `\xF4ng kh\xF4ng th\u1EC3 t\xECm th\u1EA5y b\u1EA5t k\u1EF3 \xFD ngh\u0129a n\xE0o \u0111\u1EB1ng sau nh\u1EEFng cu\u1ED9c t\xE0n s\xE1t v\xE0 \u0111au kh\u1ED5 kh\xF4ng ng\u1EEBng n\xE0y.`,
  `\xD4ng h\u1ECFi: "N\u1EBFu th\u1EBF gi\u1EDBi n\xE0y v\xF4 ngh\u0129a,`,
  `th\xEC cu\u1ED9c s\u1ED1ng c\xE1 nh\xE2n c\u1EE7a ch\xFAng ta c\xF3 gi\xE1 tr\u1ECB g\xEC kh\xF4ng?`,
  `Nhi\u1EC1u ng\u01B0\u1EDDi c\xF9ng th\u1EDDi v\u1EDBi Camus c\u0169ng kh\xE1m ph\xE1 nh\u1EEFng c\xE2u h\u1ECFi t\u01B0\u01A1ng t\u1EF1 d\u01B0\u1EDBi ng\u1ECDn c\u1EDD c\u1EE7a m\u1ED9t l\u0129nh v\u1EF1c tri\u1EBFt h\u1ECDc m\u1EDBi: ch\u1EE7 ngh\u0129a hi\u1EC7n sinh.`,
  `Nh\u1EEFng ng\u01B0\u1EDDi theo ch\u1EE7 ngh\u0129a hi\u1EC7n sinh tin r\u1EB1ng cu\u1ED9c s\u1ED1ng b\u1EAFt \u0111\u1EA7u nh\u01B0 m\u1ED9t b\u1EA3ng tr\u1EAFng,`,
  `trong th\u1EBF gi\u1EDBi h\u1ED7n lo\u1EA1n n\xE0y, m\u1ED7i ng\u01B0\u1EDDi \u0111\u1EC1u c\xF3 tr\xE1ch nhi\u1EC7m t\u1EA1o ra \xFD ngh\u0129a cho cu\u1ED9c \u0111\u1EDDi m\xECnh.`,
  `Nh\u01B0ng Camus kh\xF4ng \u0111\u1ED3ng t\xECnh v\u1EDBi tr\u01B0\u1EDDng ph\xE1i t\u01B0 t\u01B0\u1EDFng n\xE0y,`,
  `\xF4ng tin r\u1EB1ng t\u1EA5t c\u1EA3 m\u1ECDi ng\u01B0\u1EDDi \u0111\u1EC1u c\xF3 m\u1ED9t b\u1EA3n ch\u1EA5t con ng\u01B0\u1EDDi chung b\u1EA9m sinh,`,
  `B\u1EA3n ch\u1EA5t n\xE0y \u0111o\xE0n k\u1EBFt m\u1ECDi ng\u01B0\u1EDDi h\u01B0\u1EDBng t\u1EDBi nh\u1EEFng m\u1EE5c ti\xEAu chung.`,
  `M\u1ED9t trong nh\u1EEFng m\u1EE5c ti\xEAu \u0111\xF3 l\xE0, ngay c\u1EA3 khi th\u1EBF gi\u1EDBi kh\u1EAFc nghi\u1EC7t v\xE0 v\xF4 th\u01B0\u1EDDng,`,
  `ch\xFAng ta v\u1EABn ph\u1EA3i t\xECm ki\u1EBFm \xFD ngh\u0129a.`,
  `Theo Camus,`,
  `kh\xE1t v\u1ECDng \xFD ngh\u0129a c\u1EE7a con ng\u01B0\u1EDDi v\xE0 s\u1EF1 th\u1EDD \u01A1 l\u1EA1nh l\xF9ng, im l\u1EB7ng c\u1EE7a v\u0169 tr\u1EE5 gi\u1ED1ng nh\u01B0 hai m\u1EA3nh gh\xE9p kh\xF4ng t\u01B0\u01A1ng th\xEDch trong m\u1ED9t b\u1EE9c tranh gh\xE9p h\xECnh,`,
  `v\xE0 \xF4ng cho r\u1EB1ng m\u1ECDi n\u1ED7 l\u1EF1c gh\xE9p ch\xFAng l\u1EA1i v\u1EDBi nhau v\u1EC1 c\u01A1 b\u1EA3n l\xE0 phi l\xFD.`,
  `T\xECnh tr\u1EA1ng c\u0103ng th\u1EB3ng n\xE0y tr\u1EDF th\xE0nh c\u1ED1t l\xF5i tri\u1EBFt l\xFD phi l\xFD c\u1EE7a Camus,`,
  `\xF4ng cho r\u1EB1ng cu\u1ED9c s\u1ED1ng v\u1ED1n d\u0129 l\xE0 v\xF4 \xEDch.`,
  `Kh\xE1m ph\xE1 c\xE1ch s\u1ED1ng v\xF4 ngh\u0129a l\xE0 c\xE2u h\u1ECFi \u0111\u1ECBnh h\u01B0\u1EDBng trong c\xE1c t\xE1c ph\u1EA9m \u0111\u1EA7u ti\xEAn c\u1EE7a Camus,`,
  `m\xE0 \xF4ng g\u1ECDi l\xE0 lo\u1EA1t t\xE1c ph\u1EA9m v\u1EC1 s\u1EF1 phi l\xFD.`,
  `Ng\xF4i sao trong lo\u1EA1t t\xE1c ph\u1EA9m n\xE0y c\u0169ng l\xE0 cu\u1ED1n ti\u1EC3u thuy\u1EBFt \u0111\u1EA7u ti\xEAn Camus xu\u1EA5t b\u1EA3n,`,
  `\u0111\u01B0a ra m\u1ED9t c\xE2u tr\u1EA3 l\u1EDDi r\u1EA5t \u1EA3m \u0111\u1EA1m.`,
  `Ng\u01B0\u1EDDi xa l\u1EA1 xoay quanh Meursault,`,
  `m\u1ED9t thanh ni\xEAn xa c\xE1ch v\u1EC1 m\u1EB7t c\u1EA3m x\xFAc,`,
  `kh\xF4ng g\xE1n cho b\u1EA5t c\u1EE9 \u0111i\u1EC1u g\xEC qu\xE1 nhi\u1EC1u \xFD ngh\u0129a.`,
  `Anh ta kh\xF4ng h\u1EC1 kh\xF3c trong \u0111\xE1m tang m\u1EB9,`,
  `\u1EE7ng h\u1ED9 h\xE0ng x\xF3m l\xE0m b\u1EBD m\u1EB7t m\u1ED9t ng\u01B0\u1EDDi ph\u1EE5 n\u1EEF,`,
  `th\u1EADm ch\xED g\xE2y ra m\u1ED9t t\u1ED9i \xE1c b\u1EA1o l\u1EF1c.`,
  `Nh\u01B0ng Meursault kh\xF4ng h\u1EC1 h\u1ED1i h\u1EADn,`,
  `\u0111\u1ED1i v\u1EDBi anh ta, th\u1EBF gi\u1EDBi n\xE0y v\xF4 ngh\u0129a,`,
  `v\xE0 nh\u1EEFng ph\xE1n x\xE9t \u0111\u1EA1o \u0111\u1EE9c kh\xF4ng c\xF3 ch\u1ED7 \u0111\u1EE9ng.`,
  `Th\xE1i \u0111\u1ED9 n\xE0y \u0111\xE3 t\u1EA1o ra s\u1EF1 \u0111\u1ED1i kh\xE1ng gi\u1EEFa Meursault v\xE0 x\xE3 h\u1ED9i c\xF3 tr\u1EADt t\u1EF1 m\xE0 anh ta \u0111ang s\u1ED1ng,`,
  `khi\u1EBFn anh ta ng\xE0y c\xE0ng xa l\xE1nh x\xE3 h\u1ED9i,`,
  `cho \u0111\u1EBFn khi cu\u1ED1n ti\u1EC3u thuy\u1EBFt \u0111i \u0111\u1EBFn cao tr\xE0o b\xF9ng n\u1ED5.`,
  `Kh\xF4ng gi\u1ED1ng nh\u01B0 nh\xE2n v\u1EADt ch\xEDnh b\u1ECB ru\u1ED3ng b\u1ECF trong t\xE1c ph\u1EA9m c\u1EE7a m\xECnh,`,
  `Camus \u0111\u01B0\u1EE3c ca ng\u1EE3i v\xEC tri\u1EBFt l\xFD ch\xE2n th\xE0nh c\u1EE7a \xF4ng.`,
  `Ng\u01B0\u1EDDi xa l\u1EA1 \u0111\xE3 gi\xFAp Camus n\u1ED5i ti\u1EBFng ch\u1EC9 sau m\u1ED9t \u0111\xEAm,`,
  `\xF4ng ti\u1EBFp t\u1EE5c s\xE1ng t\xE1c,`,
  `c\xE1c t\xE1c ph\u1EA9m c\u1EE7a \xF4ng kh\xE1m ph\xE1 gi\xE1 tr\u1ECB c\u1EE7a cu\u1ED9c s\u1ED1ng trong s\u1EF1 phi l\xFD,`,
  `trong \u0111\xF3 nhi\u1EC1u t\xE1c ph\u1EA9m xoay quanh c\xF9ng m\u1ED9t v\u1EA5n \u0111\u1EC1 tri\u1EBFt h\u1ECDc:`,
  `N\u1EBFu cu\u1ED9c s\u1ED1ng th\u1EADt s\u1EF1 v\xF4 ngh\u0129a,`,
  `v\u1EADy t\u1EF1 s\xE1t c\xF3 ph\u1EA3i l\xE0 ph\u1EA3n \u1EE9ng h\u1EE3p l\xFD duy nh\u1EA5t kh\xF4ng?`,
  `C\xE2u tr\u1EA3 l\u1EDDi c\u1EE7a Camus l\xE0 m\u1ED9t`,
  `\u0110\u1ED1i v\u1EDBi th\u1EBF gi\u1EDBi b\u1EA5t c\xF4ng c\u1EE7a ch\xFAng ta,`,
  `c\xF3 th\u1EC3 kh\xF4ng c\xF3 b\u1EA5t k\u1EF3 l\u1EDDi gi\u1EA3i th\xEDch n\xE0o, nh\u01B0ng d\xF9 sao \u0111i n\u1EEFa,`,
  `vi\u1EC7c ch\u1ECDn s\u1ED1ng v\u1EABn l\xE0 bi\u1EC3u hi\u1EC7n s\xE2u s\u1EAFc nh\u1EA5t c\u1EE7a t\u1EF1 do ch\xE2n ch\xEDnh.`,
  `Camus \u0111\xE3 gi\u1EA3i th\xEDch \u0111i\u1EC1u n\xE0y trong m\u1ED9t truy\u1EC7n ng\u1EAFn n\u1ED5i ti\u1EBFng nh\u1EA5t c\u1EE7a \xF4ng,`,
  `xoay quanh th\u1EA7n tho\u1EA1i Hy L\u1EA1p v\u1EC1 Sisyphus.`,
  `Sisyphus l\xE0 m\u1ED9t v\u1ECB vua,`,
  `\xF4ng \u0111\xE3 l\u1EEBa d\u1ED1i c\xE1c v\u1ECB th\u1EA7n,`,
  `v\xEC v\u1EADy b\u1ECB k\u1EBFt \xE1n ph\u1EA3i l\u0103n m\xE3i m\u1ED9t t\u1EA3ng \u0111\xE1 l\u1EDBn l\xEAn \u0111\u1EC9nh n\xFAi.`,
  `S\u1EF1 t\xE0n kh\u1ED1c c\u1EE7a h\xECnh ph\u1EA1t n\u1EB1m \u1EDF ch\u1ED7 m\u1ECDi vi\u1EC7c l\xE0m \u0111\u1EC1u v\xF4 \xEDch,`,
  `nh\u01B0ng Camus cho r\u1EB1ng to\xE0n b\u1ED9 nh\xE2n lo\u1EA1i \u0111\u1EC1u \u1EDF trong ho\xE0n c\u1EA3nh t\u01B0\u01A1ng t\u1EF1,`,
  `ch\u1EC9 khi ch\xFAng ta ch\u1EA5p nh\u1EADn s\u1EF1 v\xF4 ngh\u0129a c\u1EE7a cu\u1ED9c s\u1ED1ng,`,
  `ch\xFAng ta m\u1EDBi c\xF3 th\u1EC3 ng\u1EA9ng cao \u0111\u1EA7u \u0111\u1ED1i m\u1EB7t v\u1EDBi s\u1EF1 phi l\xFD.`,
  `Nh\u01B0 Camus \u0111\xE3 n\xF3i,`,
  `Khi Syphus ch\u1ECDn b\u1EAFt \u0111\u1EA7u l\u1EA1i nhi\u1EC7m v\u1EE5 b\u1EA5t t\u1EADn c\u1EE7a m\xECnh,`,
  `ng\u01B0\u1EDDi ta ph\u1EA3i h\xECnh dung Syphus h\u1EA1nh ph\xFAc.`,
  `Nh\u1EEFng ng\u01B0\u1EDDi c\xF9ng th\u1EDDi v\u1EDBi Camus kh\xF4ng ch\u1EA5p nh\u1EADn s\u1ED1 ph\u1EADn v\xF4 \xEDch n\xE0y m\u1ED9t c\xE1ch d\u1EC5 d\xE0ng nh\u01B0 v\u1EADy,`,
  `nhi\u1EC1u nh\xE0 hi\u1EC7n sinh \u0111\xE3 ch\u1EE7 tr\u01B0\u01A1ng c\xE1ch m\u1EA1ng b\u1EA1o l\u1EF1c \u0111\u1EC3 l\u1EADt \u0111\u1ED5 c\xE1c th\u1EC3 ch\u1EBF hi\u1EC7n c\xF3,`,
  `m\xE0 h\u1ECD cho l\xE0 t\u01B0\u1EDBc b\u1ECF quy\u1EC1n t\u1EF1 quy\u1EBFt v\xE0 m\u1EE5c \u0111\xEDch c\u1EE7a ng\u01B0\u1EDDi d\xE2n.`,
  `Camus \u0111\xE3 \u0111\xE1p l\u1EA1i \u0111i\u1EC1u n\xE0y b\u1EB1ng lo\u1EA1t t\xE1c ph\u1EA9m th\u1EE9 hai c\u1EE7a m\xECnh:`,
  `Lo\u1EA1t t\xE1c ph\u1EA9m v\u1EC1 s\u1EF1 n\u1ED5i lo\u1EA1n. Trong Ng\u01B0\u1EDDi n\u1ED5i lo\u1EA1n,`,
  `\xF4ng \u0111\xE3 kh\xE1m ph\xE1 s\u1EF1 n\u1ED5i lo\u1EA1n nh\u01B0 m\u1ED9t h\xE0nh \u0111\u1ED9ng s\xE1ng t\u1EA1o ch\u1EE9 kh\xF4ng ph\u1EA3i h\u1EE7y di\u1EC7t.`,
  `Camus tin ch\u1EAFc r\u1EB1ng \u0111\u1ED9ng l\u1EF1c c\u1ED1 h\u1EEFu c\u1EE7a vi\u1EC7c l\u1EADt \u0111\u1ED5 quy\u1EC1n l\u1EF1c s\u1EBD ch\u1EC9 d\u1EABn \u0111\u1EBFn m\u1ED9t v\xF2ng lu\u1EA9n qu\u1EA9n b\u1EA1o l\u1EF1c kh\xF4ng ng\u1EEBng.`,
  `Thay v\xE0o \u0111\xF3, \u0111\u1EC3 tr\xE1nh nh\u1EEFng cu\u1ED9c t\xE0n s\xE1t v\xF4 ngh\u0129a,`,
  `\u0111i\u1EC1u c\u1EA7n l\xE0m l\xE0 khi\u1EBFn c\xF4ng ch\xFAng hi\u1EC3u \u0111\u01B0\u1EE3c b\u1EA3n ch\u1EA5t con ng\u01B0\u1EDDi chung c\u1EE7a ch\xFAng ta.`,
  `Tr\u1EDB tr\xEAu thay, ch\xEDnh lo\u1EA1t t\u01B0 t\u01B0\u1EDFng t\u01B0\u01A1ng \u0111\u1ED1i \xF4n h\xF2a n\xE0y \u0111\xE3 g\xE2y ra r\u1EA1n n\u1EE9t gi\u1EEFa \xF4ng v\u1EDBi m\u1ED9t s\u1ED1 nh\xE0 v\u0103n v\xE0 tri\u1EBFt gia \u0111\u1ED3ng nghi\u1EC7p.`,
  `B\u1EA5t ch\u1EA5p nh\u1EEFng tranh c\xE3i,`,
  `Camus v\u1EABn b\u1EAFt \u0111\u1EA7u s\xE1ng t\xE1c t\xE1c ph\u1EA9m d\xE0i nh\u1EA5t c\u1EE7a m\xECnh cho \u0111\u1EBFn nay,`,
  `cu\u1ED1n ti\u1EC3u thuy\u1EBFt ri\xEAng t\u01B0 nh\u1EA5t,`,
  `t\u1EF1 truy\u1EC7n c\u1EE7a \xF4ng c\xF3 t\u1EF1a \u0111\u1EC1`,
  `Cu\u1ED1n ti\u1EC3u thuy\u1EBFt n\xE0y ban \u0111\u1EA7u d\xF9ng \u0111\u1EC3 m\u1EDF ra m\u1ED9t h\u01B0\u1EDBng \u0111i m\u1EDBi \u0111\u1EA7y hy v\u1ECDng \u2013 m\u1ED9t lo\u1EA1t truy\u1EC7n t\xECnh l\xE3ng m\u1EA1n,`,
  `nh\u01B0ng v\xE0o n\u0103m 1960,`,
  `Camus \u0111\u1ED9t ng\u1ED9t qua \u0111\u1EDDi trong m\u1ED9t v\u1EE5 tai n\u1EA1n \xF4 t\xF4.`,
  `S\u1EF1 ki\u1EC7n n\xE0y ch\u1EC9 c\xF3 th\u1EC3 \u0111\u01B0\u1EE3c m\xF4 t\u1EA3 l\xE0 v\xF4 ngh\u0129a,`,
  `phi l\xFD. D\xF9 th\u1EBF gi\u1EDBi s\u1EBD kh\xF4ng bao gi\u1EDD \u0111\u01B0\u1EE3c th\u1EA5y lo\u1EA1t truy\u1EC7n t\xECnh l\xE3ng m\u1EA1n c\u1EE7a \xF4ng,`,
  `nh\u01B0ng c\xE1c t\xE1c ph\u1EA9m v\u1EC1 n\u1ED5i lo\u1EA1n v\xE0 phi l\xFD c\u1EE7a \xF4ng v\u1EABn c\xF2n g\xE2y \u0111\u01B0\u1EE3c ti\u1EBFng vang trong l\xF2ng \u0111\u1ED9c gi\u1EA3 cho \u0111\u1EBFn t\u1EADn ng\xE0y nay.`,
  `Kh\xE1i ni\u1EC7m v\u1EC1 s\u1EF1 phi l\xFD c\u1EE7a \xF4ng \u0111\xE3 tr\u1EDF th\xE0nh m\u1ED9t ph\u1EA7n c\u1EE7a v\u0103n h\u1ECDc th\u1EBF gi\u1EDBi,`,
  `tri\u1EBFt h\u1ECDc th\u1EBF k\u1EF7 20,`,
  `v\xE0 th\u1EADm ch\xED c\u1EA3 v\u0103n h\xF3a \u0111\u1EA1i ch\xFAng.`,
  `Ng\xE0y nay, trong nh\u1EEFng th\u1EDDi kh\u1EAFc \u0111\u1EA7y b\u1EA5t \u0111\u1ECBnh,`,
  `Camus v\u1EABn l\xE0 m\u1ED9t ng\u01B0\u1EDDi d\u1EABn \u0111\u01B0\u1EDDng \u0111\xE1ng tin c\u1EADy,`,
  `t\u01B0 t\u01B0\u1EDFng c\u1EE7a \xF4ng \u0111\xE3 truy\u1EC1n c\u1EA3m h\u1EE9ng v\xE0o th\u1EBF gi\u1EDBi v\xF4 ngh\u0129a n\xE0y b\u1EB1ng m\u1ED9t tinh th\u1EA7n ph\u1EA3n kh\xE1ng ch\u1EE9 kh\xF4ng ph\u1EA3i s\u1EF1 th\u1EA5t b\u1EA1i.`,
  `Cung c\u1EA5p n\u1ED9i dung gi\xE1o d\u1EE5c ch\u1EA5t l\u01B0\u1EE3ng cao mi\u1EC5n ph\xED cho c\xE0ng nhi\u1EC1u ng\u01B0\u1EDDi c\xE0ng t\u1ED1t.`,
  `c\xE0ng nhi\u1EC1u ng\xF4n ng\u1EEF c\xE0ng t\u1ED1t,`,
  `h\u1ED7 tr\u1EE3 s\u1EE9 m\u1EC7nh phi l\u1EE3i nhu\u1EADn c\u1EE7a ch\xFAng t\xF4i b\u1EB1ng c\xE1ch quy\xEAn g\xF3p qua Patreon,`,
  `v\xE0 \u0111\u1EEBng qu\xEAn \u0111\u0103ng k\xFD k\xEAnh n\xE0y.`
];
