var TEDED_FOOD_EXPIRATION_EER4H6CYKC_TRANSLATIONS = [
  `B\u1EA1n \u0111\xE3 v\u1EE9t b\u1ECF bao nhi\xEAu th\u1EF1c ph\u1EA9m trong t\u1EE7 l\u1EA1nh tr\u01B0\u1EDBc khi ch\xFAng \u0111\u01B0\u1EE3c s\u1EED d\u1EE5ng?`,
  `B\xE1nh m\xEC k\u1EB9p th\u1ECBt c\xF2n s\xF3t l\u1EA1i t\u1EEB bu\u1ED5i d\xE3 ngo\u1EA1i h\xE8 n\u0103m ngo\xE1i,`,
  `S\u1EEFa \u0111\xE3 h\u1EBFt h\u1EA1n s\u1EED d\u1EE5ng,`,
  `C\xE0 r\u1ED1t b\u1ECB m\u1EC1m?`,
  `C\xE1c qu\u1ED1c gia tr\xEAn th\u1EBF gi\u1EDBi l\xE3ng ph\xED m\u1ED9t l\u01B0\u1EE3ng l\u1EDBn th\u1EF1c ph\u1EA9m m\u1ED7i n\u0103m,`,
  `v\xE0 Hoa K\u1EF3 l\xE0 m\u1ED9t trong nh\u1EEFng khu v\u1EF1c l\xE3ng ph\xED nhi\u1EC1u nh\u1EA5t.`,
  `37% l\u01B0\u1EE3ng th\u1EF1c ph\u1EA9m l\xE3ng ph\xED \u1EDF M\u1EF9 \u0111\u1EBFn t\u1EEB c\xE1c h\u1ED9 gia \u0111\xECnh \u0111\u01A1n l\u1EBB,`,
  `trong \u0111\xF3 kho\u1EA3ng 20% th\u1EF1c ph\u1EA9m b\u1ECB v\u1EE9t b\u1ECF v\xEC ng\u01B0\u1EDDi ti\xEAu d\xF9ng kh\xF4ng ch\u1EAFc ch\u1EAFn v\u1EC1 c\xE1ch hi\u1EC3u ng\xE0y tr\xEAn nh\xE3n,`,
  `nh\u01B0ng h\u1EA7u h\u1EBFt th\u1EF1c ph\u1EA9m v\u1EABn an to\xE0n \u0111\u1EC3 \u0103n.`,
  `N\u1EBFu ng\xE0y th\xE1ng tr\xEAn th\u1EF1c ph\u1EA9m kh\xF4ng c\xF3 ngh\u0129a l\xE0 c\xF3 th\u1EE9 g\xEC \u0111\xF3 b\u1ECB h\u1ECFng,`,
  `v\u1EADy n\xF3 c\xF3 ngh\u0129a l\xE0 g\xEC?`,
  `Tr\u01B0\u1EDBc th\u1EBF k\u1EF7 20,`,
  `n\u01A1i s\u1EA3n xu\u1EA5t th\u1EF1c ph\u1EA9m v\xE0 n\u01A1i ti\xEAu th\u1EE5 c\xF3 m\u1ED1i li\xEAn h\u1EC7 tr\u1EF1c ti\u1EBFp h\u01A1n.`,
  `Nhi\u1EC1u ng\u01B0\u1EDDi bi\u1EBFt c\xE1ch \u0111\xE1nh gi\xE1 \u0111\u1ED9 t\u01B0\u01A1i b\u1EB1ng m\u1EAFt th\u01B0\u1EDDng,`,
  `m\u0169i v\xE0 tay,`,
  `Nh\u01B0ng khi si\xEAu th\u1ECB b\u1EAFt \u0111\u1EA7u nh\u1EADp th\u1EF1c ph\u1EA9m ch\u1EBF bi\u1EBFn,`,
  `th\u1EDDi gian l\u01B0u tr\u1EEF s\u1EA3n ph\u1EA9m s\u1EBD kh\xF3 x\xE1c \u0111\u1ECBnh h\u01A1n.`,
  `\u1EDE M\u1EF9, nh\xE2n vi\xEAn si\xEAu th\u1ECB theo d\xF5i th\u1EDDi gian th\u1EF1c ph\u1EA9m tr\xEAn k\u1EC7 d\u1EF1a tr\xEAn m\xE3 bao b\xEC.`,
  `V\xE0o nh\u1EEFng n\u0103m 1970, ng\u01B0\u1EDDi ti\xEAu d\xF9ng r\u1EA5t ph\u1EE5 thu\u1ED9c v\xE0o lo\u1EA1i th\xF4ng tin n\xE0y.`,
  `Ng\xE0y nay, nhi\u1EC1u si\xEAu th\u1ECB \xE1p d\u1EE5ng quy t\u1EAFc g\u1ECDi l\xE0 th\u1EDDi h\u1EA1n t\u01B0\u01A1i ngon,`,
  `nh\xE0 s\u1EA3n xu\u1EA5t ho\u1EB7c nh\xE0 b\xE1n l\u1EBB s\u1EBD ghi ng\xE0y t\u01B0\u01A1i ngon nh\u1EA5t l\xEAn s\u1EA3n ph\u1EA9m.`,
  `Ti\xEAu chu\u1EA9n m\u01A1 h\u1ED3 n\xE0y kh\xF4ng li\xEAn quan g\xEC \u0111\u1EBFn ng\xE0y h\u1EBFt h\u1EA1n hay an to\xE0n th\u1EF1c ph\u1EA9m,`,
  `th\u1EF1c ra n\xF3 \u0111\u01B0\u1EE3c thi\u1EBFt l\u1EADp m\xE0 g\u1EA7n nh\u01B0 kh\xF4ng c\xF3 c\u01A1 s\u1EDF khoa h\u1ECDc n\xE0o,`,
  `c\u0169ng kh\xF4ng c\xF3 quy \u0111\u1ECBnh n\xE0o v\u1EC1 vi\u1EC7c ghi nh\u1EEFng ng\xE0y n\xE0o.`,
  `Nhi\u1EC1u nh\xE0 s\u1EA3n xu\u1EA5t v\xE0 nh\xE0 b\xE1n l\u1EBB c\xF3 xu h\u01B0\u1EDBng ghi ng\xE0y n\xE0y s\u1EDBm h\u01A1n,`,
  `\u0111\u1EC3 \u0111\u1EA3m b\u1EA3o ng\u01B0\u1EDDi ti\xEAu d\xF9ng th\u01B0\u1EDFng th\u1EE9c th\u1EF1c ph\u1EA9m t\u01B0\u01A1i ngon v\xE0 quay l\u1EA1i mua h\xE0ng th\u01B0\u1EDDng xuy\xEAn.`,
  `\u0110i\u1EC1u n\xE0y c\xF3 ngh\u0129a l\xE0 nhi\u1EC1u th\u1EF1c ph\u1EA9m v\u1EABn an to\xE0n \u0111\u1EC3 \u0103n sau ng\xE0y ghi tr\xEAn bao b\xEC.`,
  `B\xE1nh quy \u0111\u1EC3 l\xE2u,`,
  `m\xEC \u1ED1ng v\xE0 c\xE1c th\u1EF1c ph\u1EA9m kh\xF4 kh\xE1c c\xF3 th\u1EC3 kh\xF4ng c\xF2n t\u01B0\u01A1i ngon,`,
  `nh\u01B0ng ch\xFAng kh\xF4ng g\xE2y ra r\u1EE7i ro s\u1EE9c kh\u1ECFe.`,
  `Th\u1EF1c ph\u1EA9m \u0111\xF3ng h\u1ED9p c\xF3 th\u1EC3 \u0111\u1EC3 \u0111\u01B0\u1EE3c v\xE0i n\u0103m,`,
  `mi\u1EC5n l\xE0 kh\xF4ng c\xF3 d\u1EA5u hi\u1EC7u ph\u1ED3ng h\u1ED9p ho\u1EB7c g\u1EC9 s\xE9t.`,
  `Nhi\u1EC7t \u0111\u1ED9 th\u1EA5p trong t\u1EE7 l\u1EA1nh c\xF3 th\u1EC3 \u1EE9c ch\u1EBF vi khu\u1EA9n g\xE2y ng\u1ED9 \u0111\u1ED9c th\u1EF1c ph\u1EA9m,`,
  `b\u1EA3o qu\u1EA3n th\u1EF1c ph\u1EA9m \u0111\xF4ng l\u1EA1nh \u0111\xFAng c\xE1ch v\xF4 th\u1EDDi h\u1EA1n.`,
  `Tr\u1EE9ng \u0111\u1EC3 t\u1EE7 l\u1EA1nh c\xF3 th\u1EC3 b\u1EA3o qu\u1EA3n t\u1EDBi 5 tu\u1EA7n,`,
  `n\u1EBFu h\u1ECFng, b\u1EA1n s\u1EBD ng\u1EEDi th\u1EA5y m\xF9i.`,
  `B\u1EA1n c\u0169ng c\xF3 th\u1EC3 ph\xE1t hi\u1EC7n th\u1EF1c ph\u1EA9m h\u01B0 h\u1ECFng qua m\xF9i l\u1EA1, b\u1EC1 m\u1EB7t d\xEDnh nh\u1EDBt v\xE0 n\u1EA5m m\u1ED1c.`,
  `B\u1EA1n c\u0169ng c\xF3 th\u1EC3 ph\xE1t hi\u1EC7n th\u1EF1c ph\u1EA9m h\u01B0 h\u1ECFng qua m\xF9i l\u1EA1, b\u1EC1 m\u1EB7t d\xEDnh nh\u1EDBt v\xE0 n\u1EA5m m\u1ED1c.`,
  `T\u1EA5t nhi\xEAn, c\xF3 nh\u1EEFng tr\u01B0\u1EDDng h\u1EE3p t\u1ED1t h\u01A1n l\xE0 n\xEAn th\u1EADn tr\u1ECDng.`,
  `B\u1ED9 N\xF4ng nghi\u1EC7p Hoa K\u1EF3 (USDA) khuy\u1EBFn ngh\u1ECB n\xEAn \u0103n ho\u1EB7c \u0111\xF4ng l\u1EA1nh th\u1ECBt \u0111\xE3 mua trong v\xF2ng v\xE0i ng\xE0y.`,
  `Qu\xE1 th\u1EDDi h\u1EA1n ghi tr\xEAn nh\xE3n,`,
  `salad \u0103n li\u1EC1n, th\u1ECBt ngu\u1ED9i v\xE0 ph\xF4 mai ch\u01B0a ti\u1EC7t tr\xF9ng c\xF3 kh\u1EA3 n\u0103ng ch\u1EE9a vi khu\u1EA9n g\xE2y b\u1EC7nh,`,
  `kh\xF4ng th\u1EC3 ph\xE1t hi\u1EC7n ch\u1EC9 b\u1EB1ng m\xF9i ho\u1EB7c v\u1ECB.`,
  `Ng\xE0y ghi tr\xEAn h\u1ED9p s\u1EEFa c\xF4ng th\u1EE9c d\xE0nh cho tr\u1EBB s\u01A1 sinh \u0111\u01B0\u1EE3c qu\u1EA3n l\xFD v\xEC l\xFD do an to\xE0n,`,
  `m\u1EB7c d\xF9 m\u1ED9t s\u1ED1 nh\xE3n m\xE1c c\xF3 hi\u1EC7u qu\u1EA3,`,
  `H\u1EA7u h\u1EBFt c\xE1c nh\xE3n m\xE1c th\xEC kh\xF4ng.`,
  `Trong m\u1ED9t cu\u1ED9c kh\u1EA3o s\xE1t h\u01A1n 1.000 ng\u01B0\u1EDDi M\u1EF9 v\xE0o n\u0103m 2019,`,
  `h\u01A1n 70% n\xF3i r\u1EB1ng h\u1ECD s\u1EED d\u1EE5ng ng\xE0y th\xE1ng \u0111\u1EC3 x\xE1c \u0111\u1ECBnh xem th\u1EF1c ph\u1EA9m c\xF3 c\xF2n \u0103n \u0111\u01B0\u1EE3c kh\xF4ng,`,
  `v\xE0 g\u1EA7n 60% ch\u1EC9 ra r\u1EB1ng h\u1ECD s\u1EBD v\u1EE9t b\u1ECF b\u1EA5t c\u1EE9 th\u1EE9 g\xEC`,
  `ch\u1EC9 c\u1EA7n qu\xE1 h\u1EA1n s\u1EED d\u1EE5ng.`,
  `C\xE1c nh\xE0 h\xE0ng v\xE0 si\xEAu th\u1ECB c\u0169ng th\u01B0\u1EDDng l\xE0m nh\u01B0 v\u1EADy.`,
  `\u0110\u1EC3 tr\xE1nh l\xE3ng ph\xED nh\u01B0 v\u1EADy,`,
  `nhi\u1EC1u chuy\xEAn gia k\xEAu g\u1ECDi ban h\xE0nh lu\u1EADt,`,
  `y\xEAu c\u1EA7u s\u1EED d\u1EE5ng hai lo\u1EA1i nh\xE3n ng\xE0y th\xE1ng sau:`,
  `Ng\xE0y \u201Cs\u1EED d\u1EE5ng t\u1ED1t nh\u1EA5t\u201D cho \u0111\u1ED9 t\u01B0\u01A1i ngon,`,
  `v\xE0 ng\xE0y \u201Ch\u1EA1n s\u1EED d\u1EE5ng\u201D cho \u0111\u1ED9 an to\xE0n.`,
  `Gi\u1EA3i ph\xE1p n\xE0y kh\xF4ng ho\xE0n h\u1EA3o, nh\u01B0ng m\u1ED9t s\u1ED1 nh\xE0 nghi\xEAn c\u1EE9u M\u1EF9 \u01B0\u1EDBc t\xEDnh r\u1EB1ng vi\u1EC7c \xE1p d\u1EE5ng c\xE1c quy \u0111\u1ECBnh n\xE0y \u1EDF c\u1EA5p qu\u1ED1c gia`,
  `c\xF3 th\u1EC3 tr\xE1nh \u0111\u01B0\u1EE3c kho\u1EA3ng 398.000 t\u1EA5n th\u1EF1c ph\u1EA9m b\u1ECB l\xE3ng ph\xED m\u1ED7i n\u0103m.`,
  `C\xE1c si\xEAu th\u1ECB c\u0169ng c\xF3 th\u1EC3 lo\u1EA1i b\u1ECF nh\xE3n ng\xE0y th\xE1ng tr\xEAn s\u1EA3n ph\u1EA9m,`,
  `nh\u01B0 m\u1ED9t s\u1ED1 chu\u1ED7i si\xEAu th\u1ECB c\u1EE7a Anh \u0111\xE3 l\xE0m,`,
  `khuy\u1EBFn kh\xEDch ng\u01B0\u1EDDi ti\xEAu d\xF9ng t\u1EF1 m\xECnh \u0111\xE1nh gi\xE1.`,
  `Nhi\u1EC1u chuy\xEAn gia k\xEAu g\u1ECDi ban h\xE0nh ch\xEDnh s\xE1ch,`,
  `khuy\u1EBFn kh\xEDch c\xE1c si\xEAu th\u1ECB v\xE0 nh\xE0 h\xE0ng t\u1EB7ng th\u1EF1c ph\u1EA9m ch\u01B0a b\xE1n h\u1EBFt.`,
  `Ng\xE0y nay, s\u1EF1 hi\u1EC3u l\u1EA7m v\u1EC1 ng\xE0y h\u1EBFt h\u1EA1n \u0111\xE3 khi\u1EBFn \xEDt nh\u1EA5t 20 bang \u1EDF M\u1EF9 h\u1EA1n ch\u1EBF vi\u1EC7c t\u1EB7ng th\u1EF1c ph\u1EA9m qu\xE1 h\u1EA1n ghi tr\xEAn nh\xE3n.`,
  `M\u1EB7c d\xF9 ch\xEDnh ph\u1EE7 li\xEAn bang th\u1EF1c s\u1EF1 khuy\u1EBFn kh\xEDch vi\u1EC7c t\u1EB7ng th\u1EF1c ph\u1EA9m nh\u01B0 v\u1EADy,`,
  `nh\u1EEFng qu\u1ED1c gia nh\u01B0 Ph\xE1p c\xF2n \u0111i xa h\u01A1n,`,
  `y\xEAu c\u1EA7u nhi\u1EC1u si\xEAu th\u1ECB ph\u1EA3i t\u1EB7ng th\u1EF1c ph\u1EA9m ch\u01B0a b\xE1n h\u1EBFt.`,
  `Cho d\xF9 ch\xEDnh ph\u1EE7 c\u1EE7a b\u1EA1n ch\u1ECDn c\xE1ch n\xE0o \u0111i n\u1EEFa,`,
  `c\xE1ch t\u1ED1t nh\u1EA5t \u0111\u1EC3 tr\xE1nh l\xE3ng ph\xED th\u1EF1c ph\u1EA9m l\xE0 mua bao nhi\xEAu \u0103n b\u1EA5y nhi\xEAu.`,
  `\u0110\u1EEBng qu\xEAn, m\u1EAFt c\u1EE7a b\u1EA1n,`,
  `m\u0169i v\xE0 l\u01B0\u1EE1i th\u01B0\u1EDDng \u0111\u1EE7 \u0111\u1EC3 \u0111\xE1nh gi\xE1 xem th\u1EF1c ph\u1EA9m \u0111\xF3 n\xEAn v\xE0o b\u1EE5ng b\u1EA1n hay v\xE0o th\xF9ng r\xE1c.`,
  `Ch\xFAng ta c\xF3 c\xF4ng c\u1EE5 v\xE0 ki\u1EBFn th\u1EE9c \u0111\u1EC3 c\u1EE9u th\u1EBF gi\u1EDBi,`,
  `nh\u01B0ng b\u01B0\u1EDBc ti\u1EBFp theo l\xE0 g\xEC?`,
  `H\xE3y truy c\u1EADp edted.com/earthgoo \u0111\u1EC3 t\xECm hi\u1EC3u l\u1ED9 tr\xECnh b\u1EA1n c\xF3 th\u1EC3 theo d\xF5i,`,
  `v\xE0 nh\u1EEFng h\xE0nh \u0111\u1ED9ng c\u1EE5 th\u1EC3 b\u1EA1n c\xF3 th\u1EC3 th\u1EF1c hi\u1EC7n,`,
  `\u0111\u1EC3 t\u1EA1o ra s\u1EF1 thay \u0111\u1ED5i.`
];
