var TEDED_NOSTALGIA_KXK9MMPYTGU_TRANSLATIONS = [
  `V\xE0o cu\u1ED1i th\u1EBF k\u1EF7 17, m\u1ED9t sinh vi\xEAn y khoa t\xEAn Johannes Hofer \u0111\xE3 nh\u1EADn th\u1EA5y m\u1ED9t c\u0103n b\u1EC7nh l\u1EA1,`,
  `\u1EA3nh h\u01B0\u1EDFng \u0111\u1EBFn nh\u1EEFng l\xEDnh \u0111\xE1nh thu\xEA Th\u1EE5y S\u0129 \u0111ang l\xE0m vi\u1EC7c \u1EDF n\u01B0\u1EDBc ngo\xE0i.`,
  `Tri\u1EC7u ch\u1EE9ng c\u1EE7a b\u1EC7nh bao g\u1ED3m m\u1EC7t m\u1ECFi,`,
  `m\u1EA5t ng\u1EE7, nh\u1ECBp tim kh\xF4ng \u0111\u1EC1u,`,
  `kh\xF3 ti\xEAu v\xE0 s\u1ED1t cao,`,
  `nh\u1EEFng ng\u01B0\u1EDDi l\xEDnh n\xE0y th\u01B0\u1EDDng ph\u1EA3i gi\u1EA3i ng\u0169.`,
  `Hofer ph\xE1t hi\u1EC7n ra r\u1EB1ng nguy\xEAn nh\xE2n b\u1EC7nh c\u1EE7a h\u1ECD kh\xF4ng ph\u1EA3i l\xE0 b\u1EC7nh t\u1EADt th\u1EC3 ch\u1EA5t,`,
  `m\xE0 l\xE0 n\u1ED7i nh\u1EDB nh\xE0 m\xE3nh li\u1EC7t.`,
  `\xD4ng \u0111\u1EB7t t\xEAn cho t\xECnh tr\u1EA1ng n\xE0y l\xE0 'nostalgia', t\u1EEB 'nostos' trong ti\u1EBFng Hy L\u1EA1p c\xF3 ngh\u0129a l\xE0 'tr\u1EDF v\u1EC1 nh\xE0',`,
  `v\xE0 'algia' c\xF3 ngh\u0129a l\xE0 \u0111au \u0111\u1EDBn v\xE0 khao kh\xE1t.`,
  `Ban \u0111\u1EA7u, nostalgia \u0111\u01B0\u1EE3c cho l\xE0 m\u1ED9t c\u0103n b\u1EC7nh ch\u1EC9 x\u1EA3y ra \u1EDF Th\u1EE5y S\u0129,`,
  `m\u1ED9t s\u1ED1 b\xE1c s\u0129 cho r\u1EB1ng ti\u1EBFng chu\xF4ng b\xF2 li\xEAn t\u1EE5c \u1EDF d\xE3y Alps \u0111\xE3 g\xE2y ra ch\u1EA5n th\u01B0\u01A1ng m\xE0ng x\u01B0\u01A1ng v\xE0 n\xE3o.`,
  `C\xE1c ch\u1EC9 huy th\u1EADm ch\xED c\xF2n c\u1EA5m binh l\xEDnh c\u1EE7a h\u1ECD h\xE1t c\xE1c b\xE0i h\xE1t truy\u1EC1n th\u1ED1ng c\u1EE7a Th\u1EE5y S\u0129,`,
  `\u0111\u1EC3 ng\u0103n h\u1ECD t\u1EF1 \xFD r\u1EDDi qu\xE2n ho\u1EB7c t\u1EF1 s\xE1t.`,
  `Tuy nhi\xEAn, v\u1EDBi s\u1EF1 to\xE0n c\u1EA7u h\xF3a c\u1EE7a di c\u01B0, ng\u01B0\u1EDDi ta nh\u1EADn th\u1EA5y nostalgia xu\u1EA5t hi\u1EC7n \u1EDF nhi\u1EC1u nh\xF3m ng\u01B0\u1EDDi kh\xE1c nhau,`,
  `Th\xEC ra b\u1EA5t c\u1EE9 ai xa qu\xEA h\u01B0\u01A1ng l\xE2u ng\xE0y \u0111\u1EC1u d\u1EC5 m\u1EAFc ch\u1EE9ng t\u01B0\u01A1ng t\u01B0.`,
  `Nh\u01B0ng \u0111\u1EBFn \u0111\u1EA7u th\u1EBF k\u1EF7 20,`,
  `c\xE1c chuy\xEAn gia kh\xF4ng c\xF2n coi \u0111\xF3 l\xE0 m\u1ED9t b\u1EC7nh th\u1EA7n kinh n\u1EEFa,`,
  `m\xE0 coi \u0111\xF3 l\xE0 m\u1ED9t b\u1EC7nh t\xE2m l\xFD t\u01B0\u01A1ng t\u1EF1 nh\u01B0 tr\u1EA7m c\u1EA3m.`,
  `C\xE1c nh\xE0 t\xE2m l\xFD h\u1ECDc th\u1EDDi \u0111\xF3 suy \u0111o\xE1n r\u1EB1ng,`,
  `n\xF3 ph\u1EA3n \xE1nh s\u1EF1 kh\xF3 kh\u0103n khi qu\xEAn \u0111i th\u1EDDi th\u01A1 \u1EA5u,`,
  `hay th\u1EADm ch\xED l\xE0 khao kh\xE1t \u0111\u01B0\u1EE3c tr\u1EDF v\u1EC1 tu\u1ED5i th\u01A1 \u1EA5u c\u1EE7a m\u1ED9t ng\u01B0\u1EDDi.`,
  `Nh\u01B0ng trong v\xE0i th\u1EADp k\u1EF7 ti\u1EBFp theo,`,
  `nh\u1EADn th\u1EE9c v\u1EC1 n\u1ED7i nh\u1EDB \u0111\xE3 thay \u0111\u1ED5i \u1EDF hai kh\xEDa c\u1EA1nh quan tr\u1ECDng,`,
  `\xFD ngh\u0129a c\u1EE7a n\xF3 \u0111\xE3 m\u1EDF r\u1ED9ng t\u1EEB vi\u1EC7c ch\u1EC9 t\xECnh c\u1EA3m nh\u1EDB nh\xE0 sang m\u1ED9t n\u1ED7i khao kh\xE1t chung v\u1EC1 qu\xE1 kh\u1EE9.`,
  `H\u01A1n n\u1EEFa, kh\xF4ng ph\u1EA3i l\xE0 m\u1ED9t c\u0103n b\u1EC7nh \u0111\xE1ng gh\xE9t,`,
  `n\xF3 b\u1EAFt \u0111\u1EA7u \u0111\u01B0\u1EE3c coi l\xE0 m\u1ED9t tr\u1EA3i nghi\u1EC7m v\u1EEBa cay \u0111\u1EAFng v\u1EEBa th\xFA v\u1ECB.`,
  `C\xF3 l\u1EBD v\xED d\u1EE5 n\u1ED5i ti\u1EBFng li\xEAn quan \u0111\u1EBFn \u0111i\u1EC1u n\xE0y,`,
  `ch\xEDnh l\xE0 nh\xE0 v\u0103n ng\u01B0\u1EDDi Ph\xE1p Marcel Proust.`,
  `\xD4ng \u0111\xE3 mi\xEAu t\u1EA3 vi\u1EC7c n\u1EBFm th\u1EED m\u1ED9t chi\u1EBFc b\xE1nh Madeleine m\xE0 t\u1EEB nh\u1ECF \xF4ng ch\u01B0a t\u1EEBng \u0103n l\u1EA1i,`,
  `l\xE0 nh\u1EEFng g\xEC \u0111\xE3 k\xEDch ho\u1EA1t c\xE1c li\xEAn t\u01B0\u1EDFng c\u1EA3m gi\xE1c \u1EA5m \xE1p v\xE0 m\u1EA1nh m\u1EBD c\u1EE7a anh \u1EA5y.`,
  `V\u1EADy \u0111i\u1EC1u g\xEC \u0111\xE3 g\xE2y ra s\u1EF1 thay \u0111\u1ED5i l\u1EDBn trong c\xE1ch ch\xFAng ta nh\xECn nh\u1EADn hi\u1EC7n t\u01B0\u1EE3ng ho\xE0i ni\u1EC7m?`,
  `C\xF4ng ngh\u1EC7 ch\u1EAFc ch\u1EAFn c\xF3 li\xEAn quan \u0111\u1EBFn \u0111i\u1EC1u n\xE0y,`,
  `v\xE0 t\xE2m l\xFD h\u1ECDc \u0111\xE3 thay \u0111\u1ED5i t\u1EEB l\xFD thuy\u1EBFt thu\u1EA7n t\xFAy sang th\u1EF1c h\xE0nh quan s\xE1t c\xF3 h\u1EC7 th\u1ED1ng v\xE0 th\u1EADn tr\u1ECDng h\u01A1n.`,
  `V\xEC v\u1EADy, c\xE1c chuy\xEAn gia ph\xE1t hi\u1EC7n ra r\u1EB1ng nhi\u1EC1u tri\u1EC7u ch\u1EE9ng ti\xEAu c\u1EF1c c\xF3 th\u1EC3 ch\u1EC9 li\xEAn quan \u0111\u1EBFn n\u1ED7i nh\u1EDB nh\xE0,`,
  `c\xF3 th\u1EC3 ch\u1EC9 li\xEAn quan \u0111\u1EBFn ho\xE0i ni\u1EC7m,`,
  `ch\u1EE9 kh\xF4ng ph\u1EA3i do n\xF3 g\xE2y ra.`,
  `Tr\xEAn th\u1EF1c t\u1EBF, ngo\u1EA1i tr\u1EEB khi \u1EDF trong tr\u1EA1ng th\xE1i c\u1EA3m x\xFAc ph\u1EE9c t\u1EA1p,`,
  `M\u1ED9t tr\u1EA1ng th\xE1i ch\u1EE9a \u0111\u1EF1ng s\u1EF1 m\u1EA5t m\xE1t v\xE0 \u0111au bu\u1ED3n,`,
  `Ho\xE0i ni\u1EC7m kh\xF4ng ph\u1EA3i l\xFAc n\xE0o c\u0169ng khi\u1EBFn ng\u01B0\u1EDDi ta ch\xECm \u0111\u1EAFm trong nh\u1EEFng c\u1EA3m x\xFAc ti\xEAu c\u1EF1c.`,
  `Ng\u01B0\u1EE3c l\u1EA1i, n\u1EBFu cho ph\xE9p m\u1ED7i c\xE1 nh\xE2n ghi l\u1EA1i \u0111\u1ED1i v\u1EDBi ri\xEAng h\u1ECD,`,
  `Nh\u1EEFng tr\u1EA3i nghi\u1EC7m \xFD ngh\u0129a v\xE0 \u0111\u1EB7c bi\u1EC7t v\u1EDBi ng\u01B0\u1EDDi kh\xE1c,`,
  `V\u1EADy th\xEC c\u1EA3m gi\xE1c ho\xE0i ni\u1EC7m c\xF3 l\u1EE3i cho s\u1EE9c kh\u1ECFe tinh th\u1EA7n.`,
  `Nghi\xEAn c\u1EE9u cho th\u1EA5y g\u1EE3i l\xEAn c\u1EA3m gi\xE1c ho\xE0i ni\u1EC7m gi\xFAp n\xE2ng cao l\xF2ng t\u1EF1 tr\u1ECDng v\xE0 c\u1EA3m gi\xE1c th\xE2n thu\u1ED9c c\u1EE7a con ng\u01B0\u1EDDi,`,
  `th\xFAc \u0111\u1EA9y tr\u01B0\u1EDFng th\xE0nh v\u1EC1 t\xE2m l\xFD,`,
  `th\u1EADm ch\xED khi\u1EBFn h\u1ECD tr\u1EDF n\xEAn nh\xE2n \xE1i h\u01A1n.`,
  `Do \u0111\xF3, h\u1ED3i t\u01B0\u1EDFng kh\xF4ng ph\u1EA3i l\xE0 nguy\xEAn nh\xE2n g\xE2y ra \u0111au kh\u1ED5 v\u1EC1 m\u1EB7t t\xE2m l\xFD,`,
  `m\xE0 c\xF3 th\u1EC3 l\xE0 m\u1ED9t c\u01A1 ch\u1EBF \u0111\u1ED1i ph\xF3 gi\xFAp ph\u1EE5c h\u1ED3i.`,
  `Ch\u1EB3ng h\u1EA1n, khi con ng\u01B0\u1EDDi r\u01A1i v\xE0o tr\u1EA1ng th\xE1i c\u1EA3m x\xFAc ti\xEAu c\u1EF1c,`,
  `h\u1ECD c\xF3 xu h\u01B0\u1EDBng t\u1EF1 nhi\xEAn nh\u1EDB v\u1EC1 qu\xE1 kh\u1EE9,`,
  `nh\u1EDD \u0111\xF3 gi\u1EA3m b\u1EDBt \u0111au kh\u1ED5 v\xE0 ph\u1EE5c h\u1ED3i s\u1EE9c kh\u1ECFe.`,
  `Ng\xE0y nay, ho\xE0i ni\u1EC7m d\u01B0\u1EDDng nh\u01B0 hi\u1EC7n di\u1EC7n \u1EDF kh\u1EAFp m\u1ECDi n\u01A1i,`,
  `m\u1ED9t ph\u1EA7n v\xEC c\xE1c nh\xE0 qu\u1EA3ng c\xE1o \u0111\xE3 kh\xE1m ph\xE1 ra s\u1EE9c \u1EA3nh h\u01B0\u1EDFng to l\u1EDBn c\u1EE7a n\xF3.`,
  `Khi n\xF3 \u0111\u01B0\u1EE3c d\xF9ng nh\u01B0 m\u1ED9t c\xF4ng c\u1EE5 ti\u1EBFp th\u1ECB,`,
  `ng\u01B0\u1EDDi ta d\u1EC5 d\xE0ng coi ho\xE0i ni\u1EC7m l\xE0 d\u1EA5u hi\u1EC7u cho th\u1EA5y ch\xFAng ta \u0111ang ch\xECm \u0111\u1EAFm trong qu\xE1 kh\u1EE9,`,
  `nh\u01B0ng \u0111\xF3 kh\xF4ng th\u1EF1c s\u1EF1 l\xE0 m\u1EE5c \u0111\xEDch c\u1EE7a n\xF3.`,
  `Thay v\xE0o \u0111\xF3,`,
  `ho\xE0i ni\u1EC7m gi\xFAp ch\xFAng ta ghi nh\u1EDB r\u1EB1ng,`,
  `cu\u1ED9c s\u1ED1ng c\u1EE7a ch\xFAng ta c\xF3 th\u1EC3 c\xF3 \xFD ngh\u0129a v\xE0 gi\xE1 tr\u1ECB,`,
  `gi\xFAp ch\xFAng ta t\xECm th\u1EA5y ni\u1EC1m tin,`,
  `T\xECm \u0111\u01B0\u1EE3c \u0111\u1ED9ng l\u1EF1c \u0111\u1EC3 \u0111\u1ED1i m\u1EB7t v\u1EDBi th\u1EED th\xE1ch trong t\u01B0\u01A1ng lai.`,
  `H\xE3y \u0111\u1EA3m b\u1EA3o b\u1EA1n \u0111\xE3 \u0111\u0103ng k\xFD k\xEAnh n\xE0y,`,
  `\u0110\u1EC3 kh\xF4ng b\u1ECF l\u1EE1 c\u01A1 h\u1ED9i ti\u1EBFp thu nh\u1EEFng \u0111i\u1EC1u m\u1EDBi m\u1EBB.`
];
