var TEDED_LIANGZHU_LEGEND_YNTEL_JSFDY_TRANSLATIONS = [
  `Ch\xFAc Anh \u0110\xE0i thay trang ph\u1EE5c,`,
  `chu\u1EA9n b\u1ECB t\u1EEB bi\u1EC7t cha m\u1EB9.`,
  `\u1EDE nh\xE0, n\xE0ng lu\xF4n l\xE0 m\u1ED9t ng\u01B0\u1EDDi con g\xE1i ngoan ngo\xE3n,`,
  `n\xE0ng tinh th\xF4ng th\xEAu th\xF9a,`,
  `khi\u1EBFn cha m\u1EB9 t\u1EF1 h\xE0o v\u1EC1 t\xE0i n\u0103ng c\u1EE7a n\xE0ng.`,
  `M\u1EB7c d\xF9 v\u1EADy, \u0111i\u1EC1u Anh \u0110\xE0i th\u1EF1c s\u1EF1 mu\u1ED1n l\xE0m l\xE0 \u0111\u01B0\u1EE3c \u0111i h\u1ECDc.`,
  `D\xF9 h\u1ECDc vi\u1EC7n Kh\u1ED5ng T\u1EED \u1EDF H\xE0ng Ch\xE2u ch\u1EC9 nh\u1EADn nam sinh,`,
  `n\xE0ng \u0111\xE3 c\u1EA7u xin cha m\u1EB9 cho ph\xE9p m\xECnh gi\u1EA3 trai \u0111i h\u1ECDc.`,
  `Cha m\u1EB9 th\u1EA5y n\xE0ng \xFD ch\xED ki\xEAn quy\u1EBFt,`,
  `l\u1EA1i th\u1EA5y gi\u1EA3 trang kh\xF4ng l\u1ED9 s\u01A1 h\u1EDF,`,
  `cu\u1ED1i c\xF9ng \u0111\xE0nh \u0111\u1ED3ng \xFD.`,
  `Tuy nhi\xEAn, cha m\u1EB9 y\xEAu c\u1EA7u Anh \u0110\xE0i ph\u1EA3i \u0111\u1EA3m b\u1EA3o gi\u1EA5u th\xE2n ph\u1EADn,`,
  `v\xE0 sau khi h\u1ECDc xong ph\u1EA3i v\u1EC1 nh\xE0,`,
  `theo s\u1EF1 s\u1EAFp \u0111\u1EB7t c\u1EE7a h\u1ECD m\xE0 tr\u1EDF l\u1EA1i cu\u1ED9c s\u1ED1ng truy\u1EC1n th\u1ED1ng c\u1EE7a ng\u01B0\u1EDDi ph\u1EE5 n\u1EEF.`,
  `Anh \u0110\xE0i t\u1EEB \u0111\xF3 vui v\u1EBB b\u1EAFt \u0111\u1EA7u chuy\u1EBFn \u0111i H\xE0ng Ch\xE2u c\u1EE7a m\xECnh.`,
  `Tr\xEAn \u0111\u01B0\u1EDDng \u0111i, n\xE0ng l\u1EA1c \u1EDF m\u1ED9t ng\xE3 t\u01B0,`,
  `\u0110ang l\xFAc kh\xF4ng bi\u1EBFt \u0111i h\u01B0\u1EDBng n\xE0o,`,
  `m\u1ED9t ch\xE0ng trai tr\u1EBB ti\u1EBFn \u0111\u1EBFn g\u1EA7n n\xE0ng,`,
  `h\u1ECD c\u1EA3m th\u1EA5y r\u1EA5t t\xE2m \u0111\u1EA7u \xFD h\u1EE3p ngay t\u1EEB c\xE1i nh\xECn \u0111\u1EA7u ti\xEAn.`,
  `Anh \u0110\xE0i bi\u1EBFt ch\xE0ng trai t\xEAn l\xE0 L\u01B0\u01A1ng S\u01A1n B\xE1,`,
  `c\u0169ng mu\u1ED1n \u0111\u1EBFn h\u1ECDc \u1EDF tr\u01B0\u1EDDng Kh\u1ED5ng T\u1EED,`,
  `th\u1EBF l\xE0 hai ng\u01B0\u1EDDi c\xF9ng \u0111i ti\u1EBFp,`,
  `t\xE2m s\u1EF1 kh\xF4ng ng\u1EEBng. Anh \u0110\xE0i nh\u1EADn ra d\xF9 n\xE0ng c\u1EA3i trang th\xE0nh ng\u01B0\u1EDDi kh\xE1c,`,
  `nh\u01B0ng v\u1EABn c\xF3 th\u1EC3 l\xE0 ch\xEDnh m\xECnh m\u1ED9t c\xE1ch tho\u1EA3i m\xE1i tr\u01B0\u1EDBc S\u01A1n B\xE1.`,
  `\u0110\u1EC3 k\u1EF7 ni\u1EC7m t\xECnh b\u1EA1n l\xE2u d\xE0i v\xE0 ch\xE2n th\xE0nh n\xE0y,`,
  `hai ng\u01B0\u1EDDi quy\u1EBFt \u0111\u1ECBnh k\u1EBFt ngh\u0129a huynh \u0111\u1EC7.`,
  `\u1EDE tr\u01B0\u1EDDng, Anh \u0110\xE0i v\xF9i \u0111\u1EA7u v\xE0o s\xE1ch v\u1EDF,`,
  `c\xF9ng S\u01A1n B\xE1 h\u1ECDc h\xE0nh v\u1EA5t v\u1EA3 \u0111\u1EBFn t\u1EADn \u0111\xEAm khuya.`,
  `Khi hai ng\u01B0\u1EDDi \u1EDF b\xEAn nhau,`,
  `h\u1ECD \u0111\u1EC1u c\u1EA3m th\u1EA5y an t\xE2m v\xE0 tho\u1EA3i m\xE1i.`,
  `H\u1ECD s\u1ED1ng chung m\u1ED9t ph\xF2ng,`,
  `M\u1EB7c d\xF9 S\u01A1n B\xE1 t\u1ECF ra nghi ng\u1EDD,`,
  `nh\u01B0ng Anh \u0110\xE0i v\u1EABn ki\xEAn quy\u1EBFt t\u1EF1 m\xECnh \u0111i v\u1EC7 sinh v\xE0 t\u1EAFm r\u1EEDa,`,
  `v\xE0 d\xF9 tr\u1EDDi n\u1EAFng n\xF3ng \u0111\u1EBFn \u0111\xE2u c\u0169ng c\xE0i n\xFAt \xE1o \u0111\u1EBFn t\u1EADn c\u1ED5.`,
  `\u0110\xF4i khi Anh \u0110\xE0i c\u0169ng nghe b\u1EA1n h\u1ECDc b\xE0n t\xE1n ri\xEAng v\u1EC1 h\xE0nh vi k\u1EF3 l\u1EA1 c\u1EE7a c\xF4.`,
  `Th\u1EDDi gian tr\xF4i nhanh, Anh \u0110\xE0i h\u1ECDc h\xE0nh ch\u0103m ch\u1EC9,`,
  `lu\xF4n \u0111\u1EE9ng nh\u1EA5t l\u1EDBp.`,
  `C\xF4 c\u1EA3m th\u1EA5y kho\u1EA3ng c\xE1ch gi\u1EEFa nh\u1EEFng ng\xE0y \u0111\xE3 qua v\xE0 t\u01B0\u01A1ng lai mong \u0111\u1EE3i xa v\u1EDDi nh\u01B0 c\xE1ch bi\u1EC7t m\u1ED9t th\u1EBF gi\u1EDBi.`,
  `Tuy nhi\xEAn, nh\u1EEFng l\u1EDDi \u0111\u1ED3n \u0111\u1EA1i c\u1EE9 th\u1EBF m\xE0 lan truy\u1EC1n,`,
  `ng\xE0y c\xE0ng tr\u1EDF n\xEAn tr\u1EA7m tr\u1ECDng h\u01A1n. Ba n\u0103m sau,`,
  `Anh \u0110\xE0i bu\u1ED9c ph\u1EA3i r\u1EDDi tr\u01B0\u1EDDng h\u1ECDc,`,
  `c\xF4 v\xE0 S\u01A1n B\xE1 chia tay trong n\u01B0\u1EDBc m\u1EAFt,`,
  `hy v\u1ECDng anh s\u1EBD c\xF3 d\u1ECBp \u0111\u1EBFn th\u0103m c\xF4.`,
  `Khi Anh \u0110\xE0i tr\u1EDF v\u1EC1 nh\xE0,`,
  `cha m\u1EB9 c\xF4 n\xF3i r\u1EB1ng nh\xE0 h\u1ECD M\xE3 \u1EDF l\xE0ng b\xEAn \u0111\xE3 c\u1EED ng\u01B0\u1EDDi \u0111\u1EBFn h\u1ECFi c\u01B0\u1EDBi,`,
  `H\u1ECD mong nh\xE0 h\u1ECD Ch\xFAc g\u1EA3 con g\xE1i cho con trai m\xECnh.`,
  `Cha m\u1EB9 c\u1EA3m th\u1EA5y hai nh\xE0 m\xF4n \u0111\u0103ng h\u1ED9 \u0111\u1ED1i,`,
  `n\xEAn \u0111\xE3 \u0111\u1ED3ng \xFD. Anh \u0110\xE0i c\u1ED1 g\u1EAFng che gi\u1EA5u n\u1ED7i th\u1EA5t v\u1ECDng trong l\xF2ng,`,
  `t\xF4n tr\u1ECDng v\xE0 tu\xE2n theo s\u1EF1 s\u1EAFp \u0111\u1EB7t c\u1EE7a cha m\u1EB9.`,
  `N\xE0ng v\u1EEBa chu\u1EA9n b\u1ECB cho cu\u1ED9c s\u1ED1ng m\u1EDBi,`,
  `v\u1EEBa nh\u1EDB v\u1EC1 S\u01A1n B\xE1 n\u01A1i ph\u01B0\u01A1ng xa.`,
  `C\xF9ng l\xFAc \u0111\xF3, s\u1EF1 ra \u0111i c\u1EE7a Anh \u0110\xE0i c\u0169ng khi\u1EBFn S\u01A1n B\xE1 kh\xF4ng c\xF2n t\xE2m tr\xED h\u1ECDc h\xE0nh.`,
  `Khi cu\u1ED1i c\xF9ng ch\xE0ng \u0111\u1EBFn nh\xE0 Anh \u0110\xE0i,`,
  `ng\u01B0\u1EDDi m\u1EDF c\u1EEDa l\u1EA1i l\xE0 m\u1ED9t c\xF4 g\xE1i tr\u1EBB.`,
  `S\u01A1n B\xE1 \u0111\u1ECBnh h\u1ECFi anh m\xECnh c\xF3 \u1EDF nh\xE0 kh\xF4ng,`,
  `nh\u01B0ng trong kho\u1EA3nh kh\u1EAFc \u0111\u1ED1i m\u1EB7t,`,
  `ch\xE0ng nh\u1EADn ra \u0111\xE2y ch\xEDnh l\xE0 ng\u01B0\u1EDDi b\u1EA1n h\u1ECDc m\xE0 m\xECnh y\xEAu qu\xFD.`,
  `S\u01A1n B\xE1 bi\u1EBFt m\xECnh kh\xF4ng th\u1EC3 ch\u1ECBu \u0111\u1EF1ng th\xEAm m\u1ED9t l\u1EA7n chia ly n\xE0o n\u1EEFa v\u1EDBi Anh \u0110\xE0i,`,
  `li\u1EC1n c\u1EA7u h\xF4n n\xE0ng,`,
  `nh\u01B0ng Anh \u0110\xE0i \u0111au l\xF2ng n\xF3i v\u1EDBi ch\xE0ng r\u1EB1ng,`,
  `M\xECnh em \u0111\xE3 c\xF3 n\u01A1i c\xF3 ch\u1ED1n r\u1ED3i.`,
  `S\u01A1n B\xE1 \u0111au bu\u1ED3n nh\u01B0ng c\u0169ng hi\u1EC3u Anh \u0110\xE0i kh\xF4ng th\u1EC3 l\xE0m tr\xE1i \xFD cha m\u1EB9.`,
  `H\u1ECD l\u1EA1i m\u1ED9t l\u1EA7n n\u1EEFa chia ly.`,
  `S\u01A1n B\xE1 v\xEC th\u1EBF m\xE0 \u0111\u1ED5 b\u1EC7nh, ng\xE0y c\xE0ng tr\u1EA7m tr\u1ECDng.`,
  `Gia \u0111\xECnh ch\xE0ng lo l\u1EAFng nh\u01B0 l\u1EEDa \u0111\u1ED1t,`,
  `li\u1EC1n c\u1EED ng\u01B0\u1EDDi mai m\u1ED1i \u0111\u1EBFn nh\xE0 h\u1ECD Ch\xFAc c\u1EA7u h\xF4n.`,
  `Nh\u01B0ng v\xEC Anh \u0110\xE0i \u0111\xE3 c\xF3 h\xF4n \u01B0\u1EDBc,`,
  `cha n\xE0ng \u0111\xE3 t\u1EEB ch\u1ED1i h\xF4n s\u1EF1 n\xE0y, v\xEC n\u1EBFu h\u1EE7y h\xF4n s\u1EBD l\xE0m \xF4 danh c\u1EA3 gia t\u1ED9c.`,
  `B\u1EC7nh t\xECnh c\u1EE7a S\u01A1n B\xE1 v\xEC th\u1EBF m\xE0 chuy\u1EC3n bi\u1EBFn x\u1EA5u nhanh ch\xF3ng,`,
  `ch\xE0ng bi\u1EBFt m\xECnh kh\xF4ng th\u1EC3 s\u1ED1ng \u0111\u1EBFn ng\xE0y Anh \u0110\xE0i xu\u1EA5t gi\xE1,`,
  `li\u1EC1n vi\u1EBFt cho Anh \u0110\xE0i m\u1ED9t phong th\u01B0 cu\u1ED1i c\xF9ng.`,
  `Trong th\u01B0 n\xF3i r\u1EB1ng, n\u1EBFu Anh \u0110\xE0i y\xEAu ch\xE0ng,`,
  `ch\xE0ng hy v\u1ECDng tr\xEAn \u0111\u01B0\u1EDDng n\xE0ng v\u1EC1 nh\xE0 ch\u1ED3ng,`,
  `h\xE3y \u0111\u1EBFn th\u1EAFp m\u1ED9t n\xE9n h\u01B0\u01A1ng tr\u01B0\u1EDBc m\u1ED9 ch\xE0ng.`,
  `Ng\xE0y xu\u1EA5t gi\xE1,`,
  `Anh \u0110\xE0i c\u1EA3m th\u1EA5y h\xF4n l\u1EC5 nh\u01B0 m\u1ED9t \u0111\xE1m tang.`,
  `Trong gi\xF3 m\u01B0a v\u1EA7n v\u0169,`,
  `\u0111o\xE0n xe ng\u1EF1a l\u01B0\u1EE3n l\u1EDD qua th\u1ECB tr\u1EA5n,`,
  `Anh \u0110\xE0i tho\xE1t kh\u1ECFi \u0111o\xE0n r\u01B0\u1EDBc d\xE2u,`,
  `qu\u1EF3 xu\u1ED1ng tr\u01B0\u1EDBc m\u1ED9 S\u01A1n B\xE1 th\u1EAFp m\u1ED9t n\xE9n h\u01B0\u01A1ng,`,
  `v\xE0 kh\xF3c l\xF3c t\u1EBF b\xE1i.`,
  `\u0110\u1ED9t nhi\xEAn, m\u1ED9t ti\u1EBFng s\xE9t kinh ho\xE0ng n\u1ED5 vang tr\xEAn kh\xF4ng trung,`,
  `tia ch\u1EDBp \u0111\xE1nh v\xE0o m\u1ED9 S\u01A1n B\xE1, l\xE0m v\u1EE1 bia \u0111\xE1.`,
  `Anh \u0110\xE0i kh\xF4ng ch\xFAt do d\u1EF1 nh\u1EA3y xu\u1ED1ng m\u1ED9.`,
  `Khi cha m\u1EB9 n\xE0ng v\u1ED9i v\xE3 \u0111\u1EBFn c\u1EE9u con g\xE1i,`,
  `hai con b\u01B0\u1EDBm bay ra t\u1EEB khe \u0111\xE1.`,
  `L\u1EA7n n\xE0y, Anh \u0110\xE0i h\xF3a th\xE2n v\xEC t\xECnh y\xEAu,`,
  `cu\u1ED1i c\xF9ng \u0111\u01B0\u1EE3c t\u1EF1 do. T\u1EEB \u0111\xF3, n\xE0ng v\xE0 S\u01A1n B\xE1 v\u0129nh vi\u1EC5n kh\xF4ng xa r\u1EDDi nhau, \u0111\u1EDDi \u0111\u1EDDi ki\u1EBFp ki\u1EBFp.`,
  `Nh\u1EEFng c\xE2u chuy\u1EC7n truy\u1EC1n l\u1EA1i t\u1EEB qu\xE1 kh\u1EE9 gi\xFAp ch\xFAng ta hi\u1EC3u r\xF5 h\u01A1n v\u1EC1 qu\xE1 kh\u1EE9,`,
  `\u0111\xF4i khi c\xF2n gi\xFAp ch\xFAng ta hi\u1EC3u r\xF5 h\u01A1n v\u1EC1 hi\u1EC7n t\u1EA1i.`,
  `\u0110\u0103ng k\xFD k\xEAnh \u0111\u1EC3`,
  `kh\xF4ng b\u1ECF l\u1EE1 b\u1EA5t k\u1EF3 truy\u1EC1n thuy\u1EBFt th\xFA v\u1ECB n\xE0o.`
];
