var CHINA_HISTORY_CH01_H_TH_NG_CHU_P1_C9QIE0RFSLQ_TRANSLATIONS = [
  `Tr\u01B0\u1EDBc th\u1EDDi nh\xE0 H\u1EA1, Trung Qu\u1ED1c v\u1EABn \u1EDF trong x\xE3 h\u1ED9i nguy\xEAn th\u1EE7y.`,
  `Vi\u1EC7c ch\u1ECDn v\u1ECB vua ti\u1EBFp theo \u0111\u1EC1u th\u1EF1c hi\u1EC7n ch\u1EBF \u0111\u1ED9 thi\u1EC7n nh\u01B0\u1EE3ng,`,
  `T\u1EE9c l\xE0, anh h\xF9ng kh\xF4ng k\u1EC3 xu\u1EA5t th\xE2n,`,
  `Ai c\xF3 n\u0103ng l\u1EF1c th\xEC ng\u01B0\u1EDDi \u0111\xF3 s\u1EBD cai tr\u1ECB.`,
  `\u0110\u1EBFn \u0111\u1EDDi vua khai qu\u1ED1c nh\xE0 H\u1EA1 l\xE0 V\u0169,`,
  `\u0110\xFAng v\u1EADy, ch\xEDnh l\xE0 V\u0169 \u0111\xE3 tr\u1ECB th\u1EE7y \u0111\xF3,`,
  `M\u1ECDi vi\u1EC7c \u0111\xE3 kh\xF4ng c\xF2n nh\u01B0 tr\u01B0\u1EDBc n\u1EEFa.`,
  `V\u0169 qu\u1EA3 th\u1EADt l\xE0 m\u1ED9t nh\xE2n t\xE0i.`,
  `Sau khi l\xE0m vua,`,
  `C\xF4ng tr\u1EA1ng ng\xE0y c\xE0ng l\u1EABy l\u1EEBng,`,
  `Quy\u1EC1n l\u1EF1c c\u0169ng ng\xE0y c\xE0ng l\u1EDBn m\u1EA1nh.`,
  `\xD4ng ta kh\xF4ng cam t\xE2m truy\u1EC1n ng\xF4i v\u1ECB cho ng\u01B0\u1EDDi kh\xE1c n\u1EEFa,`,
  `Th\u1EBF l\xE0 ng\u1EA5m ng\u1EA7m b\u1ED3i d\u01B0\u1EE1ng con trai m\xECnh l\xE0 Kh\u1EA3i,`,
  `Nh\u01B0ng b\u1EC1 ngo\xE0i v\u1EABn ch\u1ECDn m\u1ED9t ng\u01B0\u1EDDi k\u1EBF v\u1ECB t\xEAn l\xE0 B\xE1 \xCDch theo \u0111\xFAng quy t\u1EAFc.`,
  `Cha con V\u0169 v\xE0 Kh\u1EA3i sau v\xE0i n\u0103m s\u1EAFp \u0111\u1EB7t k\u1EF9 l\u01B0\u1EE1ng,`,
  `\u1EA2nh h\u01B0\u1EDFng c\u1EE7a Kh\u1EA3i d\u1EA7n v\u01B0\u1EE3t qua B\xE1 \xCDch.`,
  `Sau khi V\u0169 qua \u0111\u1EDDi,`,
  `\u0111\xE1ng l\u1EBD B\xE1 \xCDch k\u1EBF v\u1ECB, nh\u01B0ng l\xFAc n\xE0y kh\xF4ng c\xF3 m\u1EA5y ai \u0111\u1EC3 \xFD \u0111\u1EBFn \xF4ng ta n\u1EEFa,`,
  `\u0111\u1EC1u \u0111i \u1EE7ng h\u1ED9 Kh\u1EA3i.`,
  `B\xE1 \xCDch c\u0169ng kh\xF4ng ng\u1ED1c, \u0111\u1ECBnh ch\u1ED1ng tr\u1EA3 m\u1ED9t ch\xFAt,`,
  `l\xFAc n\xE0y m\u1EDBi ph\xE1t hi\u1EC7n s\u1EE9c l\u1EF1c c\u1EE7a m\xECnh c\u0103n b\u1EA3n kh\xF4ng th\u1EC3 so s\xE1nh v\u1EDBi Kh\u1EA3i.`,
  `V\xEC \u0111\xE3 kh\xF4ng th\u1EC3 xoay chuy\u1EC3n t\xECnh th\u1EBF,`,
  `B\xE1 \xCDch r\u1EA5t bi\u1EBFt \u0111i\u1EC1u m\xE0 r\xFAt kh\u1ECFi cu\u1ED9c tranh gi\xE0nh, t\xF4i kh\xF4ng c\xF3 kh\u1EA3 n\u0103ng \u0111\u1EC3 Kh\u1EA3i l\xE0m vua.`,
  `C\u1EE9 nh\u01B0 v\u1EADy, Kh\u1EA3i thay th\u1EBF B\xE1 \xCDch thu\u1EADn l\u1EE3i k\u1EBF th\u1EEBa v\u01B0\u01A1ng v\u1ECB.`,
  `Kh\u1EA3i c\u0169ng l\xE0 m\u1ED9t ng\u01B0\u1EDDi c\xF3 d\xE3 t\xE2m, gi\u1ED1ng nh\u01B0 cha c\u1EE7a \xF4ng ta,`,
  `th\u1EE9c \u0103n \u0111\xE3 \u0111\u1EBFn tay sao c\xF3 th\u1EC3 \u0111\u1EC3 ng\u01B0\u1EDDi kh\xE1c c\u01B0\u1EDBp m\u1EA5t.`,
  `V\xEC v\u1EADy \xF4ng ta c\u0169ng truy\u1EC1n ng\xF4i v\u1ECB c\u1EE7a m\xECnh cho con trai.`,
  `Ch\u1EBF \u0111\u1ED9 thi\u1EC7n nh\u01B0\u1EE3ng t\u1EEB \u0111\xF3 bi\u1EBFn th\xE0nh ch\u1EBF \u0111\u1ED9 th\u1EBF t\u1EADp,`,
  `ch\u1EBF \u0111\u1ED9 th\u1EBF t\u1EADp t\u1EEB nh\xE0 H\u1EA1 \u0111\u1EBFn nh\xE0 Thanh t\u1ED5ng c\u1ED9ng \u0111\u01B0\u1EE3c \xE1p d\u1EE5ng h\u01A1n b\u1ED1n ngh\xECn n\u0103m,`,
  `cho \u0111\u1EBFn khi ho\xE0ng \u0111\u1EBF Thanh Tuy\xEAn Th\u1ED1ng Ph\u1ED5 Nghi tho\xE1i v\u1ECB m\u1EDBi k\u1EBFt th\xFAc.`,
  `H\u1EC7 th\u1ED1ng th\u1EBF t\u1EADp ra \u0111\u1EDDi \u0111\xE3 l\xE0m thay \u0111\u1ED5i h\xECnh th\xE1i x\xE3 h\u1ED9i ban \u0111\u1EA7u,`,
  `\u0110\xE1nh d\u1EA5u s\u1EF1 th\xE0nh l\u1EADp tri\u1EC1u \u0111\u1EA1i \u0111\u1EA7u ti\xEAn trong l\u1ECBch s\u1EED Trung Qu\u1ED1c l\xE0 nh\xE0 H\u1EA1.`,
  `Nh\xE0 H\u1EA1 k\xE9o d\xE0i h\u01A1n 400 n\u0103m,`,
  `Tr\u1EA3i qua 17 \u0111\u1EDDi vua,`,
  `V\u1ECB vua cu\u1ED1i c\xF9ng t\xEAn l\xE0 H\u1EA1 Ki\u1EC7t,`,
  `M\u1ED9t b\u1EA1o ch\xFAa n\u1ED5i ti\u1EBFng,`,
  `V\xEC qu\xE1 hoang d\xE2m b\u1EA1o ng\u01B0\u1EE3c, khi\u1EBFn d\xE2n ch\xFAng s\u1ED1ng kh\xF4ng b\u1EB1ng ch\u1EBFt.`,
  `C\xF3 \xE1p b\u1EE9c \u1EAFt c\xF3 \u0111\u1EA5u tranh,`,
  `Th\u1EBF l\xE0 c\xF3 m\u1ED9t ng\u01B0\u1EDDi t\xEAn Th\xE0nh Thang \u0111\u1EE9ng l\xEAn kh\u1EDFi ngh\u0129a,`,
  `\u0110\xE3 di\u1EC7t nh\xE0 H\u1EA1 th\xE0nh c\xF4ng.`,
  `Nh\xE0 Th\u01B0\u01A1ng sau \u0111\xF3 \u0111\u01B0\u1EE3c th\xE0nh l\u1EADp,`,
  `Khai qu\u1ED1c qu\xE2n ch\u1EE7 ch\xEDnh l\xE0 Th\xE0nh Thang.`,
  `Nh\xE0 Th\u01B0\u01A1ng c\xF3 m\u1ED9t \u0111\u1EB7c \u0111i\u1EC3m,`,
  `R\u1EA5t th\xEDch d\u1EDDi \u0111\xF4,`,
  `B\xECnh th\u01B0\u1EDDng ch\xFAng ta chuy\u1EC3n nh\xE0 \u0111\xE3 r\u1EA5t phi\u1EC1n ph\u1EE9c r\u1ED3i.`,
  `M\u1ED9t qu\u1ED1c gia r\u1ED9ng l\u1EDBn c\u1EE9 di chuy\u1EC3n h\u1EBFt l\u1EA7n n\xE0y \u0111\u1EBFn l\u1EA7n kh\xE1c,`,
  `Kh\xF4ng ph\u1EA3i v\xEC vui \u0111\xE2u nh\u1EC9?`,
  `C\xF3 hai c\xE1ch gi\u1EA3i th\xEDch,`,
  `M\u1ED9t l\xE0 v\u1ECB tr\xED \u0111\u1ECBa l\xFD c\u1EE7a nh\xE0 H\u1EA1 \u1EDF khu v\u1EF1c Trung Nguy\xEAn,`,
  `T\u1EE9c l\xE0 H\xE0 B\u1EAFc,`,
  `H\xE0 Nam v\xE0 S\u01A1n \u0110\xF4ng,`,
  `G\u1EA7n s\xF4ng Ho\xE0ng H\xE0,`,
  `Ho\xE0ng H\xE0 th\u01B0\u1EDDng xuy\xEAn l\u0169 l\u1EE5t,`,
  `Kinh \u0111\xF4 nh\xE0 Th\u01B0\u01A1ng th\u01B0\u1EDDng b\u1ECB ng\u1EADp \xFAng,`,
  `Kh\xF4ng c\xF2n c\xE1ch n\xE0o kh\xE1c, ch\u1EC9 c\xF3 th\u1EC3 di chuy\u1EC3n h\u1EBFt l\u1EA7n n\xE0y \u0111\u1EBFn l\u1EA7n kh\xE1c.`,
  `Tuy nhi\xEAn, c\xE1ch gi\u1EA3i th\xEDch n\xE0y kh\xE1 g\u01B0\u1EE3ng \xE9p.`,
  `M\u1ED9t c\xE1ch gi\u1EA3i th\xEDch \u0111\xE1ng tin c\u1EADy h\u01A1n l\xE0,`,
  `Vi\u1EC7c d\u1EDDi \u0111\xF4 l\xE0 do cu\u1ED9c \u0111\u1EA5u tranh gi\xE0nh ngai v\xE0ng c\u1EE7a nh\xE0 Th\u01B0\u01A1ng r\u1EA5t kh\u1ED1c li\u1EC7t,`,
  `H\xF4m nay con gi\u1EBFt b\u1ED1,`,
  `Ng\xE0y mai ch\xFA l\u1EA1i \u0111\u1EA7u \u0111\u1ED9c ch\xE1u,`,
  `M\u1ED7i l\u1EA7n c\xF3 t\xE2n v\u01B0\u01A1ng l\xEAn ng\xF4i l\u1EA1i ph\u1EA3i \u0111\u1ED5i \u0111\xF4.`,
  `V\xEC v\u1EADy, nguy\xEAn nh\xE2n th\u1EF1c s\u1EF1 c\u1EE7a vi\u1EC7c d\u1EDDi \u0111\xF4 li\xEAn t\u1EE5c l\xE0 do n\u1ED9i chi\u1EBFn trong ho\xE0ng t\u1ED9c.`,
  `Nh\xE0 Th\u01B0\u01A1ng \u0111\xE3 d\u1EDDi \u0111\xF4 n\u0103m l\u1EA7n,`,
  `cu\u1ED1i c\xF9ng ch\u1ECDn An D\u01B0\u01A1ng, H\xE0 Nam l\xE0m n\u01A1i \u0111\u1ECBnh c\u01B0 v\u0129nh vi\u1EC5n.`,
  `Sau g\u1EA7n 600 n\u0103m th\u1ED1ng tr\u1ECB,`,
  `x\xE3 h\u1ED9i nh\xE0 Th\u01B0\u01A1ng th\u1EDDi k\u1EF3 cu\u1ED1i d\u1EA7n suy t\xE0n,`,
  `v\u1ECB qu\xE2n ch\u1EE7 cu\u1ED1i c\xF9ng l\xE0 Tr\u1EE5 V\u01B0\u01A1ng \u0111\u1EA1i danh l\u1EEBng l\u1EABy.`,
  `N\xF3i v\u1EC1 s\u1EF1 t\xE0n b\u1EA1o, \xF4ng ta ch\u01B0a bao gi\u1EDD thua k\xE9m ai.`,
  `M\u1EB7c d\xF9 ti\u1EBFng t\u0103m kh\xF4ng t\u1ED1t,`,
  `nh\u01B0ng Tr\u1EE5 V\u01B0\u01A1ng trong l\u1ECBch s\u1EED kh\xF4ng ph\u1EA3i l\xE0 m\u1ED9t h\xF4n qu\xE2n.`,
  `Nguy\xEAn nh\xE2n di\u1EC7t vong c\u1EE7a nh\xE0 Th\u01B0\u01A1ng ch\u1EE7 y\u1EBFu l\xE0 do s\u1EF1 s\u1EE5p \u0111\u1ED5 c\u1EE7a n\u1ED9i b\u1ED9 t\u1EADp \u0111o\xE0n th\u1ED1ng tr\u1ECB,`,
  `n\u1ED9i chi\u1EBFn trong ho\xE0ng t\u1ED9c, qu\xFD t\u1ED9c chia r\u1EBD,`,
  `c\u1ED9ng th\xEAm giai c\u1EA5p th\u1ED1ng tr\u1ECB xa hoa th\u1ED1i n\xE1t,`,
  `trong cung \u0111\xECnh r\u1ED1i ren,`,
  `th\xEC l\xE0m sao \u0111\u1EA5t n\u01B0\u1EDBc c\xF3 th\u1EC3 \u0111\u01B0\u1EE3c cai tr\u1ECB t\u1ED1t.`,
  `X\xE3 h\u1ED9i b\u1EA5t \u1ED5n, d\xE2n ch\xFAng l\u1EA7m than.`,
  `Th\u1EBF l\xE0, Chu V\u0169 V\u01B0\u01A1ng, m\u1ED9t ch\u01B0 h\u1EA7u c\u1EE7a nh\xE0 Th\u01B0\u01A1ng, \u0111\xE3 th\xE0nh c\xF4ng trong vi\u1EC7c \u0111\xE1nh b\u1EA1i Tr\u1EE5 V\u01B0\u01A1ng,`,
  `L\u1EADp n\xEAn nh\xE0 Chu, s\u1EED g\u1ECDi l\xE0 T\xE2y Chu.`,
  `N\u01B0\u1EDBc \u0111\xE3 \u0111\u01B0\u1EE3c th\xE0nh l\u1EADp, nh\u01B0ng khi \u0111\xF3 nh\xE0 Chu kh\xF4ng ti\u1EBFp qu\u1EA3n to\xE0n b\u1ED9 l\xE3nh th\u1ED5 c\u1EE7a nh\xE0 Th\u01B0\u01A1ng,`,
  `V\xEC giao th\xF4ng th\u1EDDi \u0111\xF3 th\u1EF1c s\u1EF1 kh\xF4ng ph\xE1t tri\u1EC3n.`,
  `Ph\xE1 v\u1EE1 ho\xE0ng th\xE0nh th\xEC d\u1EC5,`,
  `Mu\u1ED1n thu ph\u1EE5c c\xE1c v\xF9ng \u0111\u1EA5t kh\xE1c th\xEC r\u1EA5t kh\xF3,`,
  `Th\xEAm v\xE0o \u0111\xF3, nh\xE0 Chu m\u1EDBi th\xE0nh l\u1EADp kh\xF4ng l\xE2u,`,
  `N\u1EC1n m\xF3ng ch\u01B0a v\u1EEFng ch\u1EAFc. Th\u1EBF l\xE0 Chu V\u0169 V\u01B0\u01A1ng ngh\u0129 ra m\u1ED9t c\xE1ch,`,
  `Phong nhi\u1EC1u ch\u01B0 h\u1EA7u h\u01A1n,`,
  `Chia \u0111\u1EA5t \u0111ai ch\u01B0a thu ph\u1EE5c \u0111\u01B0\u1EE3c cho h\u1ECD,`,
  `R\u1ED3i c\u1EA5p cho h\u1ECD m\u1ED9t s\u1ED1 binh l\xEDnh v\xE0 ng\u1EF1a,`,
  `Vi\u1EC7c c\xF3 nh\u1EADm ch\u1EE9c su\xF4n s\u1EBB hay kh\xF4ng l\xE0 t\xF9y v\xE0o kh\u1EA3 n\u0103ng c\u1EE7a t\u1EEBng ch\u01B0 h\u1EA7u.`,
  `C\xF2n Thi\xEAn t\u1EED nh\xE0 Chu ch\u1EC9 c\u1EA7n qu\u1EA3n l\xFD c\xE1c v\xF9ng l\xE2n c\u1EADn kinh \u0111\xF4 v\xE0 ki\u1EC3m so\xE1t c\xE1c ch\u01B0 h\u1EA7u n\xE0y l\xE0 \u0111\u01B0\u1EE3c.`,
  `Th\u1EBF l\xE0 Chu V\u0169 V\u01B0\u01A1ng \u0111\xE3 phong t\u1ED5ng c\u1ED9ng b\u1EA3y m\u01B0\u01A1i m\u1ED1t n\u01B0\u1EDBc ch\u01B0 h\u1EA7u.`,
  `\u0110\u1EEBng n\xF3i ph\u01B0\u01A1ng ph\xE1p n\xE0y th\u1EF1c s\u1EF1 hi\u1EC7u qu\u1EA3.`,
  `C\xE1c ch\u01B0 h\u1EA7u kh\xF4ng ng\u1EEBng n\u1ED7 l\u1EF1c hu\u1EA5n luy\u1EC7n qu\xE2n \u0111\u1ED9i v\xEC l\xE3nh th\u1ED5 c\u1EE7a m\xECnh.`,
  `V\xEC v\u1EADy, l\xE3nh th\u1ED5 nh\xE0 Chu sau n\xE0y kh\xF4ng ng\u1EEBng m\u1EDF r\u1ED9ng.`,
  `T\u01B0\u01A1ng truy\u1EC1n, l\xE3nh th\u1ED5 nh\xE0 Chu b\u1EA5y gi\u1EDD r\u1ED9ng t\u1EDBi m\u1ED9t tri\u1EC7u n\u0103m tr\u0103m ng\xE0n kilomet vu\xF4ng,`,
  `D\xE2n s\u1ED1 h\u01A1n ch\u1EE5c tri\u1EC7u ng\u01B0\u1EDDi.`,
  `Ng\xE0y nay, con s\u1ED1 n\xE0y nghe c\xF3 v\u1EBB kh\xF4ng nhi\u1EC1u,`,
  `Nh\u01B0ng \u0111\u1EEBng qu\xEAn, khi \u0111\xF3 n\u0103ng su\u1EA5t to\xE0n c\u1EA7u c\xF2n th\u1EA5p,`,
  `C\xE1c n\u01B0\u1EDBc ch\xE2u \xC2u \u0111\u1EC1u l\xE0 nh\u1EEFng th\xE0nh bang nh\u1ECF b\xE9,`,
  `M\u1ED9t qu\u1ED1c gia c\xF2n kh\xF4ng l\u1EDBn b\u1EB1ng m\u1ED9t th\xE0nh ph\u1ED1 c\u1EE7a nh\xE0 Chu.`,
  `T\xE2y Chu b\u1EA5y gi\u1EDD \u0111\xE3 l\xE0 m\u1ED9t si\xEAu c\u01B0\u1EDDng tr\xEAn th\u1EBF gi\u1EDBi,`,
  `M\u1ED9t th\u1EDDi h\u01B0ng th\u1ECBnh. Vua nh\xE0 Chu n\xF3i ri\xEAng v\u1EC1 hai ng\u01B0\u1EDDi,`,
  `Chu L\u1EC7 V\u01B0\u01A1ng v\xE0 Chu U V\u01B0\u01A1ng.`,
  `L\u1EC7 V\u01B0\u01A1ng l\xE0 m\u1ED9t ng\u01B0\u1EDDi k\u1EF3 l\u1EA1, \xF4ng ta cho r\u1EB1ng thi\xEAn h\u1EA1 l\xE0 c\u1EE7a m\xECnh,`,
  `Kh\xF4ng cho ph\xE9p d\xE2n ch\xFAng s\u0103n b\u1EAFn,`,
  `\u0110\u1ED9ng v\u1EADt tr\xEAn n\xFAi v\xE0 c\xE1 t\xF4m d\u01B0\u1EDBi n\u01B0\u1EDBc \u0111\u1EC1u l\xE0 c\u1EE7a \xF4ng ta,`,
  `Kh\xF4ng cho ph\xE9p d\xE2n ch\xFAng b\xE0n t\xE1n v\u1EC1 \xF4ng ta,`,
  `n\u1EBFu ai n\xF3i v\u1EC1 \xF4ng ta th\xEC ph\u1EA3i x\u1EED t\u1EED.`,
  `D\u01B0\u1EDBi s\u1EF1 t\xE0n b\u1EA1o c\u1EE7a Chu L\u1EC7 V\u01B0\u01A1ng,`,
  `cu\u1ED1i c\xF9ng \u0111\xE3 x\u1EA3y ra cu\u1ED9c b\u1EA1o lo\u1EA1n c\u1EE7a ng\u01B0\u1EDDi d\xE2n, \xF4ng ta b\u1ECB l\u1EADt \u0111\u1ED5.`,
  `Chu L\u1EC7 V\u01B0\u01A1ng cu\u1ED1i c\xF9ng ch\u1EBFt n\u01A1i \u0111\u1EA5t kh\xE1ch qu\xEA ng\u01B0\u1EDDi,`,
  `con trai \xF4ng l\xE0 Chu Tuy\xEAn V\u01B0\u01A1ng l\xEAn ng\xF4i.`,
  `Tuy\xEAn V\u01B0\u01A1ng th\u1EF1c ra kh\xE1 t\u1ED1t,`,
  `trong th\u1EDDi gian t\u1EA1i v\u1ECB qu\u1ED1c gia t\u1EEBng gi\xE0u m\u1EA1nh,`,
  `sau khi \xF4ng m\u1EA5t, con trai \xF4ng l\xE0 Chu U V\u01B0\u01A1ng l\xEAn ng\xF4i.`,
  `Chu U V\u01B0\u01A1ng c\xF3 m\u1ED9t s\u1EE7ng phi t\xEAn l\xE0 Bao T\u1EF1,`,
  `l\xE0 m\u1ED9t ng\u01B0\u1EDDi ph\u1EE5 n\u1EEF r\u1EA5t kh\xF3 c\u01B0\u1EDDi.`,
  `\u0110\u1EC3 l\xE0m n\xE0ng c\u01B0\u1EDDi,`,
  `U V\u01B0\u01A1ng \u0111\xE3 s\u1EAFp x\u1EBFp m\u1ED9t m\xE0n bi\u1EC3u di\u1EC5n l\u1EDBn,`,
  `ch\xEDnh l\xE0 \u0111\u1ED1t l\u1EEDa hi\u1EC7u tri\u1EC7u ch\u01B0 h\u1EA7u.`,
  `Th\u1EDDi c\u1ED5 \u0111\u1EA1i, \u0111\xE0i l\u1EEDa hi\u1EC7u l\xE0 d\xF9ng \u0111\u1EC3 truy\u1EC1n tin khi c\xF3 chi\u1EBFn tranh,`,
  `U V\u01B0\u01A1ng ra l\u1EC7nh cho binh l\xEDnh \u0111\u1ED1t \u0111\xE0i l\u1EEDa hi\u1EC7u,`,
  `C\xE1c ch\u01B0 h\u1EA7u c\xE1c n\u01A1i v\u1EEBa th\u1EA5y b\xE1o \u0111\u1ED9ng,`,
  `T\u01B0\u1EDFng r\u1EB1ng qu\xE2n \u0111\u1ECBch \u0111\u1EBFn x\xE2m ph\u1EA1m,`,
  `M\u1ECDi ng\u01B0\u1EDDi \u0111\u1EC1u d\u1EABn qu\xE2n \u0111\u1EBFn c\u1EE9u gi\xE1.`,
  `\u0110\u1EBFn n\u01A1i th\xEC th\u1EA5y, U V\u01B0\u01A1ng v\xE0 Bao T\u1EF1 \u0111ang u\u1ED1ng r\u01B0\u1EE3u \u1EDF \u0111\xF3,`,
  `L\xE0m g\xEC c\xF3 b\xF3ng d\xE1ng k\u1EBB \u0111\u1ECBch.`,
  `U V\u01B0\u01A1ng n\xF3i: "M\u1ECDi ng\u01B0\u1EDDi v\u1EA5t v\u1EA3 r\u1ED3i,`,
  `Kh\xF4ng c\xF3 chuy\u1EC7n g\xEC \u0111\xE2u,`,
  `Ch\u1EC9 l\xE0 ta v\xE0 \xE1i phi \u0111\xF9a ch\xFAt th\xF4i,`,
  `M\u1ECDi ng\u01B0\u1EDDi \u0111\u1EEBng \u0111\u1EC3 \xFD.`,
  `Bao T\u1EF1 th\xEC nh\xECn th\u1EA5y ng\xE0n v\u1EA1n qu\xE2n l\xEDnh,`,
  `G\u1ECDi \u0111\u1EBFn l\xE0 \u0111\u1EBFn, xua \u0111i l\xE0 \u0111i,`,
  `C\u1EE9 nh\u01B0 ch\u01A1i tr\xF2 tr\u1EBB con v\u1EADy,`,
  `C\u0169ng c\u1EA3m th\u1EA5y r\u1EA5t th\xFA v\u1ECB,`,
  `Cu\u1ED1i c\xF9ng c\u0169ng b\u1EADt c\u01B0\u1EDDi.`,
  `U V\u01B0\u01A1ng r\u1EA5t h\xE0i l\xF2ng,`,
  `Sau \u0111\xF3, nhi\u1EC1u l\u1EA7n d\xF9ng c\xE1ch n\xE0y \u0111\u1EC3 ch\u1ECDc Bao T\u1EF1 vui,`,
  `D\u1EA7n d\u1EA7n m\u1EA5t \u0111i s\u1EF1 \u1EE7ng h\u1ED9 c\u1EE7a c\xE1c ch\u01B0 h\u1EA7u.`,
  `Nh\u01B0 v\u1EADy v\u1EABn ch\u01B0a \u0111\u1EE7,`,
  `U V\u01B0\u01A1ng mu\u1ED1n l\u1EADp con c\u1EE7a Bao T\u1EF1 l\xE0m ng\u01B0\u1EDDi th\u1EEBa k\u1EBF,`,
  `Ph\u1EBF b\u1ECF th\xE1i t\u1EED Nghi C\u1EF1u tr\u01B0\u1EDBc \u0111\xF3.`,
  `\xD4ng ngo\u1EA1i c\u1EE7a Nghi C\u1EF1u l\xE0 Th\xE2n H\u1EA7u kh\xF4ng \u0111\u1ED3ng \xFD,`,
  `Th\u1EBF l\xE0 Th\xE2n H\u1EA7u li\xEAn k\u1EBFt v\u1EDBi c\xE1c b\u1ED9 t\u1ED9c du m\u1EE5c ph\xEDa B\u1EAFc,`,
  `Khuy\u1EC3n Nhung t\u1EA5n c\xF4ng kinh \u0111\xF4 T\xE2y Chu l\xE0 H\u1EA1o Kinh,`,
  `T\u1EE9c l\xE0 T\xE2y An ng\xE0y nay,`,
  `Gi\u1EBFt ch\u1EBFt U V\u01B0\u01A1ng,`,
  `T\xE2y Chu t\u1ED3n t\u1EA1i hai tr\u0103m b\u1EA3y m\u01B0\u01A1i l\u0103m n\u0103m di\u1EC7t vong.`,
  `Th\xE1i t\u1EED Nghi C\u1EF1u l\xEAn ng\xF4i d\u01B0\u1EDBi s\u1EF1 ph\xF2 t\xE1 c\u1EE7a c\xE1c \u0111\u1EA1i th\u1EA7n,`,
  `T\u1EF1 x\u01B0ng l\xE0 Chu B\xECnh V\u01B0\u01A1ng.`,
  `D\u1EDDi \u0111\xF4 v\u1EC1 L\u1EA1c \u1EA4p, t\u1EE9c l\xE0 L\u1EA1c D\u01B0\u01A1ng ng\xE0y nay.`,
  `T\xE2y Chu v\xE0 \u0110\xF4ng Chu \u0111\u1EC1u thu\u1ED9c nh\xE0 Chu,`,
  `\u0111i\u1EC3m kh\xE1c bi\u1EC7t l\xE0 \u0110\xF4ng Chu suy y\u1EBFu nghi\xEAm tr\u1ECDng sau khi d\u1EDDi \u0111\xF4 v\u1EC1 L\u1EA1c D\u01B0\u01A1ng.`,
  `Thi\xEAn t\u1EED nh\xE0 Chu ch\u1EC9 c\xF2n h\u01B0 danh,`,
  `\u0111\xE1nh m\u1EA5t quy\u1EC1n l\u1EF1c t\u1ED1i cao \u0111\u1EC3 cai tr\u1ECB,`,
  `tr\u1EDF th\xE0nh con r\u1ED1i. C\xE1c ch\u01B0 h\u1EA7u kh\xF4ng c\xF2n nghe l\u1EC7nh thi\xEAn t\u1EED n\u1EEFa,`,
  `khi th\u1EE7 l\u0129nh kh\xF4ng c\xF2n th\u1EF1c l\u1EF1c,`,
  `c\xE1c ch\u01B0 h\u1EA7u nh\xECn th\u1EA5y th\u1EDDi c\u01A1 li\u1EC1n n\u1ED5i d\u1EADy,`,
  `ai n\u1EA5y \u0111\u1EC1u tranh gi\xE0nh \u0111\u1EA5t \u0111ai v\xE0 d\xE2n s\u1ED1,`,
  `giao chi\u1EBFn l\u1EABn nhau. Trung Qu\u1ED1c t\u1EEB \u0111\xF3 b\u01B0\u1EDBc v\xE0o th\u1EDDi Xu\xE2n Thu Chi\u1EBFn Qu\u1ED1c v\u1EDBi c\u1EE5c di\u1EC7n qu\u1EA7n h\xF9ng c\xE1t c\u1EE9.`,
  `K\u1EC3 t\u1EEB khi Chu U V\u01B0\u01A1ng, v\u1ECB thi\xEAn t\u1EED g\xE2y ra tr\xF2 \u0111\xF9a 'phong h\u1ECFa h\xED ch\u01B0 h\u1EA7u', b\u1ECB d\xE2n t\u1ED9c thi\u1EC3u s\u1ED1 gi\u1EBFt ch\u1EBFt,`
];
