var CHINA_HISTORY_CH02_XU_N_THU_CHI_N_QU_C_P1_C9QIE0RFSLQ_TRANSLATIONS = [
  `nh\xE0 Chu bu\u1ED9c ph\u1EA3i d\u1EDDi \u0111\xF4 t\u1EEB H\u1EA1o Kinh v\u1EC1 L\u1EA1c \u1EA4p.`,
  `T\xE2y Chu di\u1EC7t vong, \u0110\xF4ng Chu b\u1EAFt \u0111\u1EA7u.`,
  `\u0110\xF4ng Chu l\u1EA1i \u0111\u01B0\u1EE3c chia th\xE0nh hai th\u1EDDi k\u1EF3 Xu\xE2n Thu v\xE0 Chi\u1EBFn Qu\u1ED1c,`,
  `trong th\u1EDDi gian n\xE0y, thi\xEAn t\u1EED nh\xE0 Chu \u0111\xE3 ho\xE0n to\xE0n m\u1EA5t h\u1EBFt th\u1EF1c l\u1EF1c,`,
  `ch\u1EC9 c\xF2n l\xE0 m\u1ED9t v\u1EADt trang tr\xED.`,
  `C\xE1c ti\u1EC3u \u0111\u1EC7 ch\u01B0 h\u1EA7u \u0111\u1EC1u kh\xF4ng m\u1EA5y b\u1EADn t\xE2m \u0111\u1EBFn \xF4ng ta,`,
  `M\u1ED7i ng\u01B0\u1EDDi l\u1EA7n l\u01B0\u1EE3t tr\u1ED7i d\u1EADy.`,
  `\u0110\u1EA7u th\u1EDDi Xu\xE2n Thu, trong v\xF4 s\u1ED1 ti\u1EC3u \u0111\u1EC7 ch\u01B0 h\u1EA7u, n\u01B0\u1EDBc T\u1EC1 l\xE0 n\u01B0\u1EDBc \u0111\u1EA7u ti\xEAn n\u1ED5i l\xEAn.`,
  `T\u1EA1i sao l\u1EA1i l\xE0 h\u1ECD, th\u1EF1c ra c\xF3 l\xFD do.`,
  `Tr\u01B0\u1EDBc h\u1EBFt, n\u01B0\u1EDBc T\u1EC1 c\xF3 xu\u1EA5t th\xE2n cao qu\xFD,`,
  `\u0110\u01B0\u1EE3c gi\xE1o d\u1EE5c t\u1ED1t.`,
  `V\u1ECB ch\u01B0 h\u1EA7u v\u01B0\u01A1ng \u0111\u1EA7u ti\xEAn c\u1EE7a T\u1EC1 l\xE0 Kh\u01B0\u01A1ng Th\xE1i c\xF4ng Kh\u01B0\u01A1ng T\u1EED Nha, ng\u01B0\u1EDDi \u0111\xE3 gi\xFAp Chu V\u0169 v\u01B0\u01A1ng x\xE2y d\u1EF1ng c\u01A1 \u0111\u1ED3, c\xF3 c\xF4ng l\u1EDBn kh\xF4ng th\u1EC3 b\u1ECF qua.`,
  `V\xEC v\u1EADy, n\u01B0\u1EDBc T\u1EC1 lu\xF4n ph\xE1t tri\u1EC3n t\u1ED1t.`,
  `Th\u1EE9 hai, n\u01B0\u1EDBc T\u1EC1 \u0111\xE3 t\xECm \u0111\u01B0\u1EE3c m\u1ED9t v\u1ECB th\u1EA7y r\u1EA5t l\u1EE3i h\u1EA1i l\xE0 Qu\u1EA3n Tr\u1ECDng.`,
  `Ngay khi Qu\u1EA3n Tr\u1ECDng l\xEAn n\u1EAFm quy\u1EC1n, \xF4ng \u0111\xE3 t\u1EADp trung ph\xE1t tri\u1EC3n kinh t\u1EBF v\xE0 qu\u1EA3n l\xFD.`,
  `M\u1ED9t lo\u1EA1t c\u1EA3i c\xE1ch \u0111\xE3 \u0111\u1EA1t \u0111\u01B0\u1EE3c hi\u1EC7u qu\u1EA3 r\xF5 r\u1EC7t.`,
  `D\u01B0\u1EDBi s\u1EF1 c\u1EA3i c\xE1ch v\xE0 ph\xE1t tri\u1EC3n c\u1EE7a Qu\u1EA3n Tr\u1ECDng,`,
  `S\u1EE9c m\u1EA1nh c\u1EE7a T\u1EC1 t\u0103ng v\u1ECDt, tr\u1EDF th\xE0nh m\u1ED9t si\xEAu c\u01B0\u1EDDng qu\u1ED1c.`,
  `C\xF3 th\u1EF1c l\u1EF1c r\u1ED3i b\u1EAFt \u0111\u1EA7u thu nh\u1EADn \u0111\xE0n em, l\xFAc b\u1EA5y gi\u1EDD m\u1ED9t s\u1ED1 ti\u1EC3u qu\u1ED1c ch\u01B0 h\u1EA7u th\u01B0\u1EDDng b\u1ECB c\xE1c d\xE2n t\u1ED9c thi\u1EC3u s\u1ED1 \u0111e d\u1ECDa.`,
  `N\u01B0\u1EDBc T\u1EC1 \u0111\xE3 ra m\u1EB7t gi\xFAp h\u1ECD gi\u1EA3i quy\u1EBFt nh\u1EEFng r\u1EAFc r\u1ED1i n\xE0y.`,
  `C\u1EE9 nh\u01B0 th\u1EBF, uy t\xEDn c\u1EE7a n\u01B0\u1EDBc T\u1EC1 trong s\u1ED1 c\xE1c ch\u01B0 h\u1EA7u ng\xE0y c\xE0ng cao,`,
  `tr\u1EDF th\xE0nh qu\u1ED1c gia \u0111\u1EA7u ti\xEAn x\u01B0ng b\xE1.`,
  `T\u1EC1 Ho\xE0n c\xF4ng, qu\xE2n v\u01B0\u01A1ng l\xFAc b\u1EA5y gi\u1EDD, v\u1EDBi t\u01B0 c\xE1ch l\xE0 m\u1ED9t b\xE1 ch\u1EE7 \u0111\u1EDDi,`,
  `oai phong l\u1EABm li\u1EC7t, nh\u01B0ng tu\u1ED5i gi\xE0 c\u1EE7a \xF4ng l\u1EA1i v\xF4 c\xF9ng th\xEA l\u01B0\u01A1ng.`,
  `Sau khi T\u1EC1 Ho\xE0n c\xF4ng v\u1EC1 gi\xE0, n\u0103m ng\u01B0\u1EDDi con trai c\u1EE7a \xF4ng b\u1EADn r\u1ED9n tranh gi\xE0nh \u0111\u1ECBa v\u1ECB,`,
  `t\xE0n s\xE1t l\u1EABn nhau, th\u1EADm ch\xED c\xF2n giam l\u1ECFng cha gi\xE0,`,
  `bu\u1ED9c T\u1EC1 Ho\xE0n c\xF4ng cu\u1ED1i c\xF9ng ph\u1EA3i t\u1EF1 s\xE1t.`,
  `M\xE0 \u0111\xE1ng th\u01B0\u01A1ng h\u01A1n l\xE0,`,
  `kh\xF4ng ai li\u1EC7m x\xE1c cho \xF4ng, m\xE3i \u0111\u1EBFn khi thi th\u1EC3 m\u1EE5c n\xE1t m\u1EDBi \u0111\u01B0\u1EE3c ph\xE1t hi\u1EC7n.`,
  `Nh\u1EDD \u01A1n c\u1EE7a \u0111\xE1m con b\u1EA5t hi\u1EBFu n\xE0y, n\u01B0\u1EDBc T\u1EC1 t\u1EEB sau c\xE1i ch\u1EBFt c\u1EE7a T\u1EC1 Ho\xE0n c\xF4ng d\u1EA7n d\u1EA7n suy y\u1EBFu.`,
  `Sau \u0111\xF3, n\u01B0\u1EDBc T\u1EA5n, n\u01B0\u1EDBc T\u1EA7n,`,
  `v\xE0 n\u01B0\u1EDBc S\u1EDF l\u1EA7n l\u01B0\u1EE3t tr\u1ED7i d\u1EADy.`,
  `Tr\u01B0\u1EDBc h\u1EBFt ph\u1EA3i n\xF3i r\u1EB1ng,`,
  `n\u01B0\u1EDBc S\u1EDF th\u1EF1c ch\u1EA5t kh\xF4ng thu\u1ED9c ch\u01B0 h\u1EA7u c\u1EE7a nh\xE0 Chu,`,
  `m\xE0 th\u1EF1c ch\u1EA5t l\xE0 m\u1ED9t b\u1ED9 l\u1EA1c l\u1EDBn \u1EDF ph\xEDa nam,`,
  `Sau \u0111\xF3 t\u1EF1 x\u01B0ng v\u01B0\u01A1ng.`,
  `D\xF9 huy\u1EBFt th\u1ED1ng kh\xF4ng thu\u1EA7n nh\u01B0ng th\u1EF1c l\u1EF1c h\xF9ng m\u1EA1nh,`,
  `c\xF3 th\u1EC3 \u0111\xE1nh nhau. Nh\xECn th\u1EA5y nh\xE0 Chu l\xE0 m\u1ED9t mi\u1EBFng m\u1ED3i b\xE9o b\u1EDF,`,
  `n\xEAn mu\u1ED1n chen ch\xE2n v\xE0o chia m\u1ED9t ph\u1EA7n.`,
  `B\xE2y gi\u1EDD n\xF3i v\u1EC1 n\u01B0\u1EDBc T\u1EA7n,`,
  `nh\xECn t\u1EA5m b\u1EA3n \u0111\u1ED3 n\xE0y,`,
  `c\xF3 th\u1EA5y v\u1ECB tr\xED \u0111\u1ECBa l\xFD c\u1EE7a T\u1EA7n r\u1EA5t quen thu\u1ED9c kh\xF4ng?`,
  `\u0110\xFAng, kh\xF4ng sai, ch\xEDnh l\xE0 \u0111\xF4 th\xE0nh H\u1EA1o Kinh c\u1EE7a T\xE2y Chu ng\xE0y x\u01B0a.`,
  `N\u0103m \u0111\xF3 n\u01B0\u1EDBc T\u1EA7n trong nh\xE0 Chu ch\u1EC9 l\xE0 m\u1ED9t \u0111\u1ED9i nh\u1ECF nu\xF4i ng\u1EF1a,`,
  `khi Chu Thi\xEAn T\u1EED b\u1ECB Khuy\u1EC3n Nhung b\u1EAFt n\u1EA1t \u0111\xE3 ch\u1EA1y \u0111\u1EBFn L\u1EA1c \u1EA4p,`,
  `ch\xEDnh n\u01B0\u1EDBc T\u1EA7n \u0111\xE3 h\u1ED9 t\u1ED1ng tr\xEAn \u0111\u01B0\u1EDDng \u0111i.`,
  `V\xEC v\u1EADy \u0111\u1EC3 th\u01B0\u1EDFng cho ti\u1EC3u \u0111\u1EC7 c\xF3 c\xF4ng h\u1ED9 ch\u1EE7,`,
  `Chu Thi\xEAn T\u1EED \u0111\xE3 phong \u0111\u1EA5t H\u1EA1o Kinh cho n\u01B0\u1EDBc T\u1EA7n.`,
  `Khi \u0111\xF3 n\u01B0\u1EDBc T\u1EA7n v\u1EABn l\xE0 m\u1ED9t \u0111\u1EE9a tr\u1EBB ngoan ngo\xE3n,`,
  `kh\xF4ng tranh gi\xE0nh, s\u1EB5n l\xF2ng gi\xFAp \u0111\u1EE1.`,
  `Trong khi \u0111\xF3, \u1EDF ph\xEDa t\xE2y, \xF4ng l\u1EB7ng l\u1EBD n\u1ED7 l\u1EF1c chinh ph\u1EE5c c\xE1c b\u1ED9 l\u1EA1c ngo\u1EA1i t\u1ED9c,`,
  `d\u1EA7n tr\u1EDF th\xE0nh b\xE1 ch\u1EE7 ph\xEDa t\xE2y.`,
  `C\xF2n n\u01B0\u1EDBc T\u1EA5n, v\u1EDBi t\u01B0 c\xE1ch l\xE0 b\xE1 ch\u1EE7 m\u1EDBi sau n\u01B0\u1EDBc T\u1EC1,`,
  `m\xE2u thu\u1EABn v\u1EDBi n\u01B0\u1EDBc S\u1EDF kh\xF4ng ng\u1EEBng ngh\u1EC9 t\u1EEB tr\u01B0\u1EDBc \u0111\u1EBFn nay,`,
  `\u0111\xE1nh nhau g\u1EA7n m\u1ED9t tr\u0103m n\u0103m,`,
  `s\u1EED g\u1ECDi l\xE0 T\u1EA5n S\u1EDF tranh b\xE1.`,
  `Cu\u1ED9c chi\u1EBFn gi\u1EB1ng co k\xE9o d\xE0i, n\u01B0\u1EDBc S\u1EDF th\u1EAFng \xEDt thua nhi\u1EC1u,`,
  `th\u1EF1c l\u1EF1c d\u1EA7n suy y\u1EBFu.`,
  `L\xFAc n\xE0y, Ng\xF4 v\u01B0\u01A1ng H\u1EA1p L\u01B0 \u1EDF b\xEAn c\u1EA1nh l\u1EA1i c\xF3 \u0111\u01B0\u1EE3c hai d\u0169ng t\u01B0\u1EDBng,`,
  `m\u1ED9t l\xE0 Ng\u0169 T\u1EED T\u01B0, m\u1ED9t l\xE0 T\xF4n V\u0169.`,
  `Ng\u0169 T\u1EED T\u01B0 v\u1ED1n l\xE0 ng\u01B0\u1EDDi n\u01B0\u1EDBc S\u1EDF,`,
  `cha v\xE0 anh trai \u0111\u1EC1u b\u1ECB S\u1EDF v\u01B0\u01A1ng gi\u1EBFt ch\u1EBFt,`,
  `\xF4ng b\xE8n ch\u1EA1y sang n\u01B0\u1EDBc Ng\xF4 n\u01B0\u01A1ng t\u1EF1a H\u1EA1p L\u01B0.`,
  `Ng\u0169 T\u1EED T\u01B0 v\u1ED1n l\xE0 ng\u01B0\u1EDDi n\u01B0\u1EDBc S\u1EDF, n\xEAn r\u1EA5t am hi\u1EC3u t\xECnh h\xECnh n\u1ED9i b\u1ED9 n\u01B0\u1EDBc S\u1EDF,`,
  `h\u01A1n n\u1EEFa \xF4ng c\xF2n c\xF3 t\xE0i n\u0103ng phi th\u01B0\u1EDDng.`,
  `V\u1EC1 T\xF4n V\u0169 th\xEC kh\xF4ng c\u1EA7n ph\u1EA3i n\xF3i r\u1ED3i,`,
  `T\xF4n V\u0169 ch\xEDnh l\xE0 t\xE1c gi\u1EA3 c\u1EE7a T\xF4n T\u1EED Binh Ph\xE1p.`,
  `Ngo\xE0i ra,`,
  `n\u01B0\u1EDBc T\u1EA5n, k\u1EBB th\xF9 kh\xF4ng \u0111\u1ED9i tr\u1EDDi chung c\u1EE7a n\u01B0\u1EDBc S\u1EDF, c\u0169ng ng\u1EA5m ng\u1EA7m gi\xFAp n\u01B0\u1EDBc Ng\xF4 h\u1ECDc h\u1ECFi k\u1EF9 thu\u1EADt ti\xEAn ti\u1EBFn,`,
  `t\u0103ng c\u01B0\u1EDDng s\u1EE9c m\u1EA1nh qu\xE2n s\u1EF1,`,
  `m\u1EE5c \u0111\xEDch l\xE0 \u0111\u1EC3 nu\xF4i d\u01B0\u1EE1ng m\u1ED9t qu\u1EA3 bom h\u1EB9n gi\u1EDD b\xEAn c\u1EA1nh n\u01B0\u1EDBc S\u1EDF.`,
  `Qu\u1EA3 nhi\xEAn, n\u01B0\u1EDBc Ng\xF4 sau \u0111\xF3 \u0111\xE3 ch\u1EDBp th\u1EDDi c\u01A1 xu\u1EA5t binh \u0111\xE1nh n\u01B0\u1EDBc S\u1EDF,`,
  `v\u1EEBa ra qu\xE2n \u0111\xE3 gi\xE1ng cho n\u01B0\u1EDBc S\u1EDF m\u1ED9t \u0111\xF2n n\u1EB7ng n\u1EC1, khi\u1EBFn n\u01B0\u1EDBc S\u1EDF nguy\xEAn kh\xED \u0111\u1EA1i th\u01B0\u01A1ng.`,
  `T\u1EEB \u0111\xF3 v\u1EC1 sau kh\xF4ng g\u01B0\u1EE3ng d\u1EADy n\u1ED5i, g\u1EA7n nh\u01B0 r\xFAt lui kh\u1ECFi v\u0169 \u0111\xE0i tranh b\xE1 cu\u1ED1i th\u1EDDi k\u1EF3.`,
  `N\u01B0\u1EDBc Ng\xF4 \u0111\u1EA1i b\u1EA1i n\u01B0\u1EDBc S\u1EDF xong c\u0169ng ch\u1EB3ng uy phong \u0111\u01B0\u1EE3c m\u1EA5y ng\xE0y,`,
  `n\u01B0\u1EDBc Vi\u1EC7t b\xEAn c\u1EA1nh \u0111\xE3 ra khi\xEAu chi\u1EBFn v\u1EDBi h\u1ECD.`,
  `Ng\xF4 Vi\u1EC7t Xu\xE2n Thu ph\u1EA3i b\u1EAFt \u0111\u1EA7u t\u1EEB vi\u1EC7c Vi\u1EC7t v\u01B0\u01A1ng C\xE2u Ti\u1EC5n \u0111\xE3 gi\u1EBFt Ng\xF4 v\u01B0\u01A1ng H\u1EA1p L\u01B0.`,
  `Sau khi H\u1EA1p L\u01B0 ch\u1EBFt, con trai Ph\xF9 Sai k\u1EBF v\u1ECB,`,
  `Ph\xF9 Sai v\xEC mu\u1ED1n b\xE1o th\xF9 cho cha n\xEAn \u0111\xE3 b\u1EAFt C\xE2u Ti\u1EC5n.`,
  `N\u1EBFu l\xFAc n\xE0y Ph\xF9 Sai gi\u1EBFt C\xE2u Ti\u1EC5n,`,
  `Sau \u0111\xF3 kh\xF4ng c\xF3 chuy\u1EC7n g\xEC n\u1EEFa.`,
  `Nh\u01B0ng Ph\xF9 Sai l\u1EA1i kh\xF4ng ch\u1ECBu.`,
  `M\u1EDBi c\xF3 c\xE2u chuy\u1EC7n v\u1EC1 sau C\xE2u Ti\u1EC5n n\u1EB1m gai n\u1EBFm m\u1EADt, d\xF9ng m\u1EF9 nh\xE2n k\u1EBF T\xE2y Thi \u0111\u1EC3 lo\u1EA1i b\u1ECF Ph\xF9 Sai,`,
  `Di\u1EC7t n\u01B0\u1EDBc Ng\xF4, c\xE2u chuy\u1EC7n truy\u1EC1n c\u1EA3m h\u1EE9ng v\u1EC1 s\u1EF1 ph\u1EA3n c\xF4ng th\xE0nh c\xF4ng.`,
  `Th\u1EDDi Xu\xE2n Thu \u0111\u1EBFn \u0111\xE2y l\xE0 k\u1EBFt th\xFAc.`,
  `Ti\u1EBFp theo l\xE0 th\u1EDDi Chi\u1EBFn Qu\u1ED1c,`,
  `Nh\xE2n ti\u1EC7n n\xF3i th\xEAm,`,
  `Trong th\u1EDDi Xu\xE2n Thu, c\xE1c n\u01B0\u1EDBc ch\u01B0 h\u1EA7u n\xE0y ch\u1EC9 \u0111\xE1nh nh\u1EEFng tr\u1EADn nh\u1ECF,`,
  `Kh\xF4ng ai ra tay t\xE0n nh\u1EABn, \u0111\xE1nh xong th\xEC ai v\u1EC1 nh\xE0 n\u1EA5y.`,
  `C\u0169ng ch\xEDnh v\xEC trong th\u1EDDi k\u1EF3 n\xE0y c\xF3 r\u1EA5t nhi\u1EC1u qu\u1ED1c gia,`,
  `M\u1ED7i qu\u1ED1c gia l\u1EA1i c\xF3 nh\u1EEFng t\u01B0 t\u01B0\u1EDFng v\u0103n h\xF3a kh\xE1c nhau \u0111\u01B0\u1EE3c \u0111\u1EC1 cao,`,
  `V\xEC v\u1EADy, v\xE0o th\u1EDDi Xu\xE2n Thu, b\xE1ch gia tranh minh, xu\u1EA5t hi\u1EC7n m\u1ED9t lo\u1EA1t c\xE1c nh\xE2n v\u1EADt ki\u1EC7t xu\u1EA5t,`,
  `L\xE3o T\u1EED, Kh\u1ED5ng T\u1EED, Trang T\u1EED, M\u1EA1nh T\u1EED, H\xE0n Phi T\u1EED,`,
  `M\u1EB7c T\u1EED, v.v. Nh\u01B0ng \u1EDF th\u1EDDi Chi\u1EBFn Qu\u1ED1c ti\u1EBFp theo,`,
  `C\xE1c ch\u01B0 h\u1EA7u kh\xF4ng c\xF2n ch\u1EC9 l\xE0 \u0111\xE1nh nhau nh\u1ECF n\u1EEFa.`,
  `Sau khi C\xE2u Ti\u1EC5n di\u1EC7t n\u01B0\u1EDBc Ng\xF4,`,
  `c\xE1c n\u01B0\u1EDBc ch\u01B0 h\u1EA7u kh\xE1c th\u1EA5y r\u1EB1ng,`,
  `\xE0, tr\xF2 ch\u01A1i c\xF3 th\u1EC3 ch\u01A1i nh\u01B0 th\u1EBF n\xE0y.`,
  `T\u1EEB \u0111\xF3 v\u1EC1 sau, nh\u1EEFng cu\u1ED9c chi\u1EBFn nh\u1ECF kh\xF4ng c\xF2n th\u1ECBnh h\xE0nh n\u1EEFa,`,
  `c\xE1c n\u01B0\u1EDBc ch\u01B0 h\u1EA7u c\xF3 th\u1EF1c l\u1EF1c b\u1EAFt \u0111\u1EA7u tr\u1EF1c ti\u1EBFp th\xF4n t\xEDnh c\xE1c n\u01B0\u1EDBc ch\u01B0 h\u1EA7u y\u1EBFu h\u01A1n.`,
  `V\xEC v\u1EADy, sau n\xE0y ch\xFAng ta g\u1ECDi th\u1EDDi k\u1EF3 h\u1ED7n lo\u1EA1n v\u1EDBi s\u1EF1 th\xF4n t\xEDnh l\u1EABn nhau n\xE0y l\xE0 th\u1EDDi Chi\u1EBFn Qu\u1ED1c.`,
  `B\u1EA1n c\xF2n nh\u1EDB nh\u1EEFng qu\u1ED1c gia \u0111\xE3 x\u01B0ng b\xE1 v\xE0o th\u1EDDi Xu\xE2n Thu kh\xF4ng?`,
  `T\u1EC1, T\u1EA5n, S\u1EDF, Ng\xF4, T\u1EA7n.`,
  `Khi \u0111\xF3, nh\xE0 Chu l\xE0 l\xE3nh \u0111\u1EA1o, \u0111\u1EA5t \u0111ai qu\xE1 r\u1ED9ng l\u1EDBn,`,
  `kh\xF4ng qu\u1EA3n l\xFD xu\u1EC3 n\xEAn \u0111\xE3 chia cho c\xE1c ch\u01B0 h\u1EA7u l\xE0 \u0111\xE0n em c\u1EE7a m\xECnh.`,
  `C\xE1c ch\u01B0 h\u1EA7u c\u0169ng c\xF3 c\xE1c \u0111\u1EA1i phu c\u1EE7a ri\xEAng m\xECnh.`,
  `N\u01B0\u1EDBc T\u1EA5n \u0111\xE3 nu\xF4i v\xF4 s\u1ED1 \u0111\u1EA1i phu v\xE0o th\u1EDDi Xu\xE2n Thu,`,
  `trong s\u1ED1 \u0111\xF3 c\xF3 ba gia t\u1ED9c, sau nhi\u1EC1u n\u0103m ph\u1EA5n \u0111\u1EA5u,`,
  `c\xF3 th\u1EF1c l\u1EF1c si\xEAu vi\u1EC7t, h\u1ECD l\xE0 H\xE0n,`,
  `Tri\u1EC7u v\xE0 Ng\u1EE5y. Ba gia t\u1ED9c n\xE0y m\u1EA1nh \u0111\u1EBFn m\u1EE9c n\xE0o?`,
  `M\u1EA1nh \u0111\u1EBFn m\u1EE9c cu\u1ED1i c\xF9ng \u0111\xE3 chia c\u1EAFt T\u1EA5n qu\u1ED1c, th\u1EE7 l\u0129nh c\u1EE7a m\xECnh,`,
  `th\xE0nh l\u1EADp ba qu\u1ED1c gia m\u1EDBi.`,
  `T\u1EA5n qu\u1ED1c di\u1EC7t vong. N\u01B0\u1EDBc T\u1EC1, m\u1ED9t c\u01B0\u1EDDng qu\u1ED1c kh\xE1c th\u1EDDi Xu\xE2n Thu, c\u0169ng ch\u1EB3ng kh\xE1 h\u01A1n l\xE0 bao.`,
  `B\u1ECB m\u1ED9t thu\u1ED9c h\u1EA1 h\u1ECD \u0110i\u1EC1n c\u1EE7a ch\xEDnh m\xECnh \xE1m h\u1EA1i,`,
  `quy\u1EC1n l\u1EF1c r\u01A1i v\xE0o tay k\u1EBB kh\xE1c, b\u1ECB h\u1ECD \u0110i\u1EC1n thay th\u1EBF.`,
  `N\xF3i r\xF5 h\u01A1n m\u1ED9t ch\xFAt,`,
  `N\u01B0\u1EDBc T\u1EC1 th\u1EDDi Xu\xE2n Thu l\xE0 n\u01B0\u1EDBc T\u1EC1 c\u1EE7a h\u1ECD Kh\u01B0\u01A1ng, h\u1EADu du\u1EC7 c\u1EE7a Kh\u01B0\u01A1ng T\u1EED Nha.`,
  `\u0110\u1EBFn th\u1EDDi Chi\u1EBFn Qu\u1ED1c, n\u01B0\u1EDBc T\u1EC1 tr\u1EDF th\xE0nh n\u01B0\u1EDBc T\u1EC1 c\u1EE7a h\u1ECD \u0110i\u1EC1n.`,
  `V\u1EDF k\u1ECBch Chi\u1EBFn Qu\u1ED1c c\xF3 v\xF4 s\u1ED1 nh\xE2n v\u1EADt,`,
  `ch\u1EB3ng qua l\xE0 s\xE1p nh\u1EADp v\xE0 b\u1ECB s\xE1p nh\u1EADp, cu\u1ED1i c\xF9ng c\xF2n l\u1EA1i b\u1EA3y si\xEAu c\u01B0\u1EDDng qu\u1ED1c:`,
  `H\xE0n, Tri\u1EC7u, Ng\u1EE5y, T\u1EA7n, T\u1EC1,`,
  `S\u1EDF v\xE0 Y\xEAn, s\u1EED g\u1ECDi l\xE0 Chi\u1EBFn Qu\u1ED1c Th\u1EA5t H\xF9ng.`,
  `Khi \u0111\xE3 tr\u1EDF th\xE0nh si\xEAu c\u01B0\u1EDDng qu\u1ED1c, kh\xF4ng th\u1EC3 ch\u1EC9 d\u1EF1a v\xE0o v\u0169 l\u1EF1c,`,
  `m\xE0 c\xF2n ph\u1EA3i c\xF3 \xFD th\u1EE9c \u0111\u1ED5i m\u1EDBi.`,
  `C\xE1c qu\u1ED1c gia n\xE0y\u7EB7\u7EB7 ti\u1EBFn h\xE0nh bi\u1EBFn ph\xE1p,`,
  `N\u01B0\u1EDBc T\u1EA7n c\xF3 v\u1EADn may \u0111\u1EB7c bi\u1EC7t khi g\u1EB7p \u0111\u01B0\u1EE3c Th\u01B0\u01A1ng \u01AF\u1EDFng.`,
  `Sau c\u1EA3i c\xE1ch c\u1EE7a Th\u01B0\u01A1ng \u01AF\u1EDFng, ch\u1EC9 trong h\u01A1n m\u01B0\u1EDDi n\u0103m, s\u1EE9c m\u1EA1nh c\u1EE7a n\u01B0\u1EDBc T\u1EA7n \u0111\xE3 ph\xE1t tri\u1EC3n v\u01B0\u1EE3t b\u1EADc,`,
  `Tr\u1EDF th\xE0nh m\u1ED9t si\xEAu si\xEAu si\xEAu si\xEAu c\u01B0\u1EDDng qu\u1ED1c.`,
  `Tr\u01B0\u1EDBc \u0111\xE2y, th\u1EF1c l\u1EF1c c\u1EE7a b\u1EA3y n\u01B0\u1EDBc ch\u01B0 h\u1EA7u t\u01B0\u01A1ng \u0111\u01B0\u01A1ng nhau,`,
  `\u0110\u1ED9t nhi\xEAn m\u1ED9t trong s\u1ED1 \u0111\xF3 tr\u1EDF n\xEAn c\u1EF1c k\u1EF3 m\u1EA1nh, v\u01B0\u1EE3t xa t\u1EA5t c\u1EA3 nh\u1EEFng ng\u01B0\u1EDDi kh\xE1c,`,
  `B\u1EA1n \u0111o\xE1n xem chuy\u1EC7n g\xEC s\u1EBD x\u1EA3y ra?`,
  `\u0110\u01B0\u01A1ng nhi\xEAn l\xE0 c\xF9ng nhau h\u1EE3p s\u1EE9c t\u1EA5n c\xF4ng h\u1EAFn.`,
  `Y\u1EBFn qu\u1ED1c c\xF3 m\u1ED9t m\u01B0u s\u0129 t\xEAn l\xE0 Th\u01B0 T\u1EA7n, \u0111\xE3 \u0111\u1EC1 ngh\u1ECB s\xE1u n\u01B0\u1EDBc li\xEAn minh \u0111\u1EC3 ch\u1ED1ng l\u1EA1i T\u1EA7n qu\u1ED1c.`,
  `S\xE1u n\u01B0\u1EDBc nghe xong, l\u1EADp t\u1EE9c \u0111\u1ED3ng \xFD, t\u1EA1o th\xE0nh c\u1EE5c di\u1EC7n s\xE1u \u0111\u1EA5u m\u1ED9t,`,
  `S\u1EED g\u1ECDi l\xE0 L\u1EE5c qu\u1ED1c h\u1EE3p tung.`,
  `N\u01B0\u1EDBc T\u1EA7n c\u0169ng kh\xF4ng ph\u1EA3i l\xE0 k\u1EBB ng\u1ED1c, m\u1ED9t m\u01B0u s\u0129 t\xEAn l\xE0 T\xF4n Nghi \u0111\xE3 hi\u1EBFn k\u1EBF cho T\u1EA7n v\u01B0\u01A1ng,`,
  `T\xEAn l\xE0 Li\xEAn ho\xE0nh. Th\u1EF1c ch\u1EA5t l\xE0 ch\u01A1i chi\u1EBFn thu\u1EADt t\xE2m l\xFD,`,
  `Chia r\u1EBD quan h\u1EC7 gi\u1EEFa s\xE1u n\u01B0\u1EDBc, \u0111\xE1nh b\u1EA1i t\u1EEBng n\u01B0\u1EDBc m\u1ED9t.`,
  `C\xF2n c\xF3 m\u1ED9t m\u01B0u s\u0129 t\xEAn l\xE0 Ph\u1EA1m Th\u01B0, c\u0169ng \u0111\u01B0a ra \xFD ki\u1EBFn cho T\u1EA7n l\xE0 Vi\u1EC5n giao c\u1EADn c\xF4ng,`,
  `C\xE1c n\u01B0\u1EDBc xa T\u1EA7n th\xEC k\u1EBFt giao h\u1EEFu h\u1EA3o,`,
  `C\xE1c n\u01B0\u1EDBc l\xE2n c\u1EADn T\u1EA7n kh\xF4ng c\xF3 vi\u1EC7c g\xEC l\xE0m l\xE0 \u0111\xE1nh n\u01B0\u1EDBc n\xE0y m\u1ED9t tr\u1EADn.`,
  `Tuy\u1EC7t chi\xEAu n\xE0y \u0111\u1EB7c bi\u1EC7t l\u1EE3i h\u1EA1i, c\xF4 l\u1EADp t\u1EA5t c\u1EA3 c\xE1c \u0111\u1ED1i th\u1EE7.`,
  `\u0110\xE3 h\xF3a gi\u1EA3i ho\xE0n h\u1EA3o c\u1EE5c di\u1EC7n b\u1EA5t l\u1EE3i s\xE1u \u0111\u1ED1i m\u1ED9t.`,
  `M\u1ED9t khi li\xEAn minh tan r\xE3, n\xF3i v\u1EC1 \u0111\xE1nh \u0111\u01A1n, kh\xF4ng ai l\xE0 \u0111\u1ED1i th\u1EE7 c\u1EE7a T\u1EA7n.`,
  `Nh\u1EEFng chuy\u1EC7n c\xF2n l\u1EA1i th\xEC m\u1ECDi ng\u01B0\u1EDDi \u0111\u1EC1u bi\u1EBFt r\u1ED3i,`,
  `S\xE1u n\u01B0\u1EDBc l\u1EA7n l\u01B0\u1EE3t b\u1ECB T\u1EA7n ti\xEAu di\u1EC7t theo th\u1EE9 t\u1EF1 H\xE0n,`,
  `Tri\u1EC7u, Ng\u1EE5y, S\u1EDF, Y\xEAn, T\u1EC1.`,
  `\xC0, c\xF2n c\xF3 Chu Thi\xEAn T\u1EED,`,
  `V\xEC qu\xE1 m\u1EDD nh\u1EA1t, Chu l\xE3o \u0111\u1EA1i \u0111\xE3 \u0111\xE1nh nhau h\u01A1n 500 n\u0103m trong th\u1EDDi Xu\xE2n Thu Chi\u1EBFn Qu\u1ED1c,`,
  `\u0110\xE3 b\u1ECB T\u1EA7n di\u1EC7t tr\u01B0\u1EDBc khi s\xE1u n\u01B0\u1EDBc di\u1EC7t vong.`,
  `T\u1EA7n cu\u1ED1i c\xF9ng \u0111\xE3 ti\xEAu di\u1EC7t h\u1EBFt v\xE0 th\u1ED1ng nh\u1EA5t giang h\u1ED3.`,
  `Th\u1EDDi Xu\xE2n Thu Chi\u1EBFn Qu\u1ED1c \u0111\u1EBFn \u0111\xE2y l\xE0 k\u1EBFt th\xFAc.`
];
