var CHINA_HISTORY_CH03_NH_T_N_P1_C9QIE0RFSLQ_TRANSLATIONS = [
  `N\xF3i v\u1EC1 nh\xE0 T\u1EA7n, ch\u1EE7 y\u1EBFu l\xE0 n\xF3i v\u1EC1 T\u1EA7n Th\u1EE7y Ho\xE0ng, v\xEC nh\xE0 T\u1EA7n qu\xE1 ng\u1EAFn ng\u1EE7i,`,
  `ch\u1EC9 c\xF3 m\u01B0\u1EDDi l\u0103m n\u0103m.`,
  `N\u0103m 221 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn,`,
  `T\u1EA7n di\u1EC7t s\xE1u n\u01B0\u1EDBc, ch\u1EA5m d\u1EE9t th\u1EDDi k\u1EF3 ch\u01B0 h\u1EA7u tranh gi\xE0nh k\xE9o d\xE0i h\u01A1n 500 n\u0103m th\u1EDDi Xu\xE2n Thu Chi\u1EBFn Qu\u1ED1c,`,
  `th\u1ED1ng nh\u1EA5t Trung Hoa. \u0110\u1EA5t n\u01B0\u1EDBc \u0111\xE3 th\u1ED1ng nh\u1EA5t, nh\u01B0ng tr\u01B0\u1EDBc l\u1ECBch s\u1EED \u0111\u1EABm m\xE1u c\u1EE7a nh\xE0 Chu, tri\u1EC1u \u0111\u1EA1i tr\u01B0\u1EDBc \u0111\xF3,`,
  `nh\xE0 T\u1EA7n suy ngh\u0129 l\xE0m th\u1EBF n\xE0o \u0111\u1EC3 kh\xF4ng \u0111i v\xE0o v\u1EBFt xe \u0111\u1ED5.`,
  `Th\u1EC3 ch\u1EBF c\u1EE7a nh\xE0 Chu khi \u0111\xF3 ch\u1EE7 y\u1EBFu l\xE0 ch\u1EBF \u0111\u1ED9 phong ki\u1EBFn,`,
  `Thi\xEAn t\u1EED nh\xE0 Chu phong \u0111\u1EA5t \u0111ai c\u1EE7a m\xECnh cho ng\u01B0\u1EDDi th\xE2n ho\u1EB7c th\u1EA7n t\u1EED,`,
  `m\u1ED7i phong \u0111\u1ECBa l\xE0 m\u1ED9t n\u01B0\u1EDBc ch\u01B0 h\u1EA7u.`,
  `N\xF3i c\xE1ch kh\xE1c, \u0111\u1EA5t \u0111ai kh\xF4ng ho\xE0n to\xE0n thu\u1ED9c v\u1EC1 ho\xE0ng th\u1EA5t,`,
  `c\xE1c v\u01B0\u01A1ng ch\u01B0 h\u1EA7u c\xF3 quy\u1EC1n l\u1EF1c tuy\u1EC7t \u0111\u1ED1i tr\xEAn \u0111\u1EA5t phong c\u1EE7a m\xECnh,`,
  `c\xF3 th\u1EC3 th\u1EBF t\u1EADp, c\xF3 th\u1EC3 c\xF3 qu\xE2n \u0111\u1ED9i ri\xEAng,`,
  `v\xE0 c\xE1c n\u01B0\u1EDBc ch\u01B0 h\u1EA7u ph\u1EA3i n\u1ED9p thu\u1EBF c\u1ED1ng cho ho\xE0ng th\u1EA5t.`,
  `Ch\u1EBF \u0111\u1ED9 n\xE0y ban \u0111\u1EA7u th\xEC v\u1EABn \u1ED5n,`,
  `v\xEC Thi\xEAn t\u1EED nh\xE0 Chu v\xE0 c\xE1c ch\u01B0 h\u1EA7u \u0111\u1EC1u l\xE0 ng\u01B0\u1EDDi th\xE2n, quen bi\u1EBFt,`,
  `nh\u01B0ng l\xE2u d\u1EA7n, c\xE1c n\u01B0\u1EDBc ch\u01B0 h\u1EA7u s\u1EBD c\xF3 th\u1EBF l\u1EF1c v\u01B0\u1EE3t qua ho\xE0ng th\u1EA5t,`,
  `d\u1EABn \u0111\u1EBFn c\u1EE5c di\u1EC7n c\xE1c ch\u01B0 h\u1EA7u l\u1EDBn h\xF9ng c\u1EE9 nhi\u1EC1u n\u01A1i.`,
  `Th\u1EDDi Xu\xE2n Thu Chi\u1EBFn Qu\u1ED1c l\xE0 v\xEC th\u1EBF m\xE0 c\xF3.`,
  `nh\xE0 T\u1EA7n r\xFAt kinh nghi\u1EC7m t\u1EEB s\u1EF1 s\u1EE5p \u0111\u1ED5 c\u1EE7a nh\xE0 Chu,`,
  `l\u1EA7n \u0111\u1EA7u ti\xEAn t\u1EA1o ra ch\u1EBF \u0111\u1ED9 qu\u1EADn huy\u1EC7n.`,
  `ch\u1EBF \u0111\u1ED9 qu\u1EADn huy\u1EC7n l\u1EA5y Ho\xE0ng \u0111\u1EBF l\xE0m ng\u01B0\u1EDDi \u0111\u1EE9ng \u0111\u1EA7u,`,
  `Tam C\xF4ng C\u1EEDu Khanh l\xE0m \u0111\u1EA1i di\u1EC7n c\u1EE7a ch\u1EBF \u0111\u1ED9 t\u1EADp quy\u1EC1n c\u1EE7a ch\xEDnh ph\u1EE7 trung \u01B0\u01A1ng,`,
  `chia \u0111\u1EA5t n\u01B0\u1EDBc th\xE0nh ba m\u01B0\u01A1i s\xE1u qu\u1EADn,`,
  `d\u01B0\u1EDBi qu\u1EADn l\u1EA1i chia th\xE0nh h\u01A1n m\u1ED9t ngh\xECn huy\u1EC7n,`,
  `quan l\u1EA1i \u0111\u1EE9ng \u0111\u1EA7u m\u1ED7i qu\u1EADn huy\u1EC7n \u0111\u1EC1u do trung \u01B0\u01A1ng b\u1ED5 nhi\u1EC7m,`,
  `kh\xF4ng c\xF3 b\u1EA5t k\u1EF3 m\u1ED1i quan h\u1EC7 huy\u1EBFt th\u1ED1ng n\xE0o v\u1EDBi nhau.`,
  `kh\xE1c v\u1EDBi vi\u1EC7c c\xE1c ch\u01B0 h\u1EA7u nh\xE0 Chu n\u1ED9p c\u1ED1ng n\u1EA1p cho nh\xE0 n\u01B0\u1EDBc,`,
  `ch\u1EBF \u0111\u1ED9 qu\u1EADn huy\u1EC7n c\u1EE7a Ho\xE0ng \u0111\u1EBF tr\u1EA3 b\u1ED5ng l\u1ED9c cho ho\u1EA1n quan.`,
  `m\xF4 h\xECnh ph\xE2n c\u1EA5p n\xE0y l\xE0m cho quy\u1EC1n l\u1EF1c trung \u01B0\u01A1ng t\u1EADp trung cao \u0111\u1ED9,`,
  `ng\u01B0\u1EDDi cai tr\u1ECB c\xF3 quy\u1EC1n l\u1EF1c tuy\u1EC7t \u0111\u1ED1i,`,
  `c\xF3 l\u1EE3i cho vi\u1EC7c t\u0103ng c\u01B0\u1EDDng t\u1EADp quy\u1EC1n trung \u01B0\u01A1ng v\xE0 th\u1ED1ng nh\u1EA5t \u0111\u1EA5t n\u01B0\u1EDBc.`,
  `c\xE1c n\u01B0\u1EDBc ch\u01B0 h\u1EA7u hi\u1EC7n nay c\xF3 th\u1EC3 ch\u1EBF ri\xEAng \u1EDF nhi\u1EC1u m\u1EB7t,`,
  `nh\u01B0ng sau khi th\u1ED1ng nh\u1EA5t c\u1EA3 n\u01B0\u1EDBc, c\xE1c th\u1EC3 ch\u1EBF n\xE0y s\u1EBD g\xE2y ra nhi\u1EC1u r\u1EAFc r\u1ED1i,`,
  `V\xED d\u1EE5, Ti\u1EC1n t\u1EC7 kh\xF4ng \u0111\u1ED3ng nh\u1EA5t,`,
  `Th\u01B0\u01A1ng m\u1EA1i v\xE0 c\xF4ng nghi\u1EC7p kh\xF4ng th\u1EC3 ph\xE1t tri\u1EC3n,`,
  `Khi \u0111\u01A1n v\u1ECB \u0111o l\u01B0\u1EDDng kh\xF4ng th\u1ED1ng nh\u1EA5t, vi\u1EC7c mua b\xE1n r\u1EA5t b\u1EA5t ti\u1EC7n,`,
  `Ng\xF4n ng\u1EEF b\u1EA5t \u0111\u1ED3ng th\xEC kh\xF4ng th\u1EC3 giao ti\u1EBFp.`,
  `V\xEC v\u1EADy, T\u1EA7n Th\u1EE7y Ho\xE0ng \u0111\xE3 th\u1ED1ng nh\u1EA5t ti\u1EC1n t\u1EC7 v\xE0 \u0111o l\u01B0\u1EDDng tr\xEAn to\xE0n qu\u1ED1c,`,
  `\u0110\u1EB7t n\u1EC1n m\xF3ng cho giao th\u01B0\u01A1ng kinh t\u1EBF c\u1EE7a nh\xE0 T\u1EA7n,`,
  `L\u1EA5y ch\u1EEF Ti\u1EC3u tri\u1EC7n l\xE0m v\u0103n t\u1EF1 chung tr\xEAn to\xE0n qu\u1ED1c,`,
  `C\xF3 l\u1EE3i cho vi\u1EC7c ph\u1ED5 c\u1EADp v\u0103n h\xF3a v\xE0 th\u1ED1ng nh\u1EA5t t\u01B0 t\u01B0\u1EDFng c\u1EE7a ng\u01B0\u1EDDi d\xE2n.`,
  `N\xF3i \u0111\u1EBFn th\u1ED1ng nh\u1EA5t t\u01B0 t\u01B0\u1EDFng, ti\u1EC7n th\u1EC3 nh\u1EAFc \u0111\u1EBFn vi\u1EC7c \u0111\u1ED1t s\xE1ch ch\xF4n Nho lu\xF4n.`,
  `Tr\u01B0\u1EDBc \u0111\xE2y, c\xE1c n\u01B0\u1EDBc ch\u01B0 h\u1EA7u c\xF3 c\xE1c quan ni\u1EC7m v\u0103n h\xF3a kh\xE1c nhau,`,
  `M\u1EDBi c\xF3`,
  `\u0110\u1EBFn khi T\u1EA7n th\u1ED1ng nh\u1EA5t,`,
  `Hai tr\xE0o l\u01B0u t\u01B0 t\u01B0\u1EDFng l\u1EDBn nh\u1EA5t l\xFAc b\u1EA5y gi\u1EDD l\xE0 v\u0103n h\xF3a Nho gia v\xE0 v\u0103n h\xF3a Ph\xE1p gia.`,
  `Nho gia nh\u1EA5n m\u1EA1nh tr\u1ECB n\u01B0\u1EDBc b\u1EB1ng l\xF2ng nh\xE2n, ph\u1EE5c ng\u01B0\u1EDDi b\u1EB1ng l\u1EC5 ngh\u0129a;`,
  `Ph\xE1p gia nh\u1EA5n m\u1EA1nh tr\u1ECB n\u01B0\u1EDBc b\u1EB1ng v\u0169 l\u1EF1c, cai tr\u1ECB con ng\u01B0\u1EDDi b\u1EB1ng quy\u1EC1n l\u1EF1c.`,
  `Th\u1EC3 ch\u1EBF Ph\xE1p gia \u0111\u01B0\u1EE3c nh\xE0 T\u1EA7n \u0111\u1EC1 cao \u0111\xE3 v\u1EA5p ph\u1EA3i s\u1EF1 ph\u1EA3n \u0111\u1ED1i c\u1EE7a c\xE1c nh\xE0 nho s\u0129,`,
  `T\u1EA7n Th\u1EE7y Ho\xE0ng \u0111\xE3 h\u1EE7y ho\u1EA1i s\xE1ch s\u1EED,`,
  `ch\xF4n s\u1ED1ng c\xE1c nh\xE0 nho \u0111\u1EC3 \u0111\xE0n \xE1p c\xE1c n\u1EC1n v\u0103n h\xF3a kh\xE1c,`,
  `nh\u1EB1m duy tr\xEC s\u1EF1 th\u1ED1ng nh\u1EA5t v\u0129 \u0111\u1EA1i.`,
  `Ch\xEDnh t\u01B0 t\u01B0\u1EDFng l\u1EA5y v\xF5 tr\u1ECB qu\u1ED1c c\u1EE7a T\u1EA7n Th\u1EE7y Ho\xE0ng n\xE0y,`,
  `c\u0169ng \u0111\xE3 \u0111\u1EB7t n\u1EC1n m\xF3ng cho s\u1EF1 s\u1EE5p \u0111\u1ED5 c\u1EE7a nh\xE0 T\u1EA7n sau n\xE0y.`,
  `\u0110\u1EC3 ch\u1ED1ng l\u1EA1i s\u1EF1 x\xE2m l\u01B0\u1EE3c c\u1EE7a ngo\u1EA1i t\u1ED9c,`,
  `nh\xE0 T\u1EA7n \u0111\xE3 huy \u0111\u1ED9ng h\xE0ng ch\u1EE5c v\u1EA1n lao c\xF4ng x\xE2y d\u1EF1ng V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh.`,
  `Th\u1EF1c ra, V\u1EA1n L\xFD Tr\u01B0\u1EDDng Th\xE0nh \u0111\u01B0\u1EE3c x\xE2y d\u1EF1ng s\u1EDBm nh\u1EA5t v\xE0o th\u1EDDi Xu\xE2n Thu,`,
  `sau khi nh\xE0 T\u1EA7n th\u1ED1ng nh\u1EA5t \u0111\xE3 c\u1EE7ng c\u1ED1 v\xE0 s\u1EEDa ch\u1EEFa n\xF3,`,
  `v\xE0 k\u1EBFt n\u1ED1i ho\xE0n ch\u1EC9nh.`,
  `Ngo\xE0i ra, nh\xE0 T\u1EA7n c\xF2n x\xE2y d\u1EF1ng cung A Ph\xF2ng, s\u1EEDa sang l\u0103ng m\u1ED9 ho\xE0ng gia,`,
  `huy \u0111\u1ED9ng h\xE0ng tri\u1EC7u lao \u0111\u1ED9ng,`,
  `lu\u1EADt ph\xE1p nh\xE0 T\u1EA7n h\xE0 kh\u1EAFc, lao d\u1ECBch n\u1EB7ng n\u1EC1 v\xE0 \xE1p b\u1EE9c khi\u1EBFn d\xE2n ch\xFAng l\u1EA7m than,`,
  `m\xE2u thu\u1EABn x\xE3 h\u1ED9i ng\xE0y c\xE0ng gia t\u0103ng.`,
  `N\u0103m 210 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn,`,
  `T\u1EA7n Th\u1EE7y Ho\xE0ng th\u1EF1c hi\u1EC7n chuy\u1EBFn tu\u1EA7n du cu\u1ED1i c\xF9ng,`,
  `v\xE0 \u0111\u1ED9t ng\u1ED9t b\u0103ng h\xE0 t\u1EA1i h\xE0nh cung Sa Kh\xE2u.`,
  `\u0110\xFAng v\u1EADy, ghi ch\xE9p ch\xEDnh s\u1EED ch\u1EC9 c\xF3 hai ch\u1EEF:`,
  `\u0111\u1ED9t t\u1EED. D\xE2n gian c\xF3 hai gi\u1EA3 thuy\u1EBFt v\u1EC1 nguy\xEAn nh\xE2n c\xE1i ch\u1EBFt c\u1EE7a \xF4ng,`,
  `m\u1ED9t l\xE0 \xF4ng ch\u1EBFt v\xEC b\u1EC7nh, hai l\xE0 \xF4ng b\u1ECB Tri\u1EC7u Cao m\u01B0u h\u1EA1i,`,
  `b\u1EDFi v\xEC c\xE1i ch\u1EBFt qu\xE1 \u0111\u1ED9t ng\u1ED9t.`,
  `Nguy\xEAn do di chi\u1EBFu c\u1EE7a \xF4ng l\xE0 mu\u1ED1n ho\xE0ng t\u1EED tr\u01B0\u1EDFng Ph\xF9 T\xF4 k\u1EBF v\u1ECB,`,
  `nh\u01B0ng khi T\u1EA7n Th\u1EE7y Ho\xE0ng \u0111\u1EC3 l\u1EA1i di chi\u1EBFu,`,
  `b\xEAn c\u1EA1nh \xF4ng ch\u1EC9 c\xF3 ho\xE0ng t\u1EED \xFAt H\u1ED3 H\u1EE3i,`,
  `th\xE1i gi\xE1m Tri\u1EC7u Cao v\xE0 th\u1EEBa t\u01B0\u1EDBng L\xFD T\u01B0.`,
  `Tri\u1EC7u Cao c\xF3 m\xE2u thu\u1EABn v\u1EDBi Ph\xF9 T\xF4,`,
  `n\xEAn h\u1EAFn s\u1EE3 Ph\xF9 T\xF4 k\u1EBF v\u1ECB s\u1EBD tr\u1EA3 th\xF9 m\xECnh,`,
  `v\xEC v\u1EADy Tri\u1EC7u Cao \u0111\xE3 thuy\u1EBFt ph\u1EE5c H\u1ED3 H\u1EE3i,`,
  `\u0111e d\u1ECDa L\xFD T\u01B0 s\u1EEDa \u0111\u1ED5i di chi\u1EBFu c\u1EE7a T\u1EA7n Th\u1EE7y Ho\xE0ng,`,
  `ra l\u1EC7nh cho Ph\xF9 T\xF4 t\u1EF1 s\xE1t,`,
  `do H\u1ED3 H\u1EE3i k\u1EBF v\u1ECB.`,
  `Sau \u0111\xF3, L\xFD T\u01B0 c\u0169ng b\u1ECB H\u1ED3 H\u1EE3i ch\xE9m ngang l\u01B0ng,`,
  `Tri\u1EC7u Cao \u0111\u1ED9c chi\u1EBFm quy\u1EC1n h\xE0nh.`,
  `Sau \u0111\xF3, chuy\u1EC7n g\xEC \u0111\xE3 x\u1EA3y ra?`,
  `Nh\xE0 T\u1EA7n \u0111\xE3 s\u1EE5p \u0111\u1ED5 nh\u01B0 th\u1EBF n\xE0o?`,
  `T\u1EA7n Nh\u1ECB Th\u1EBF H\u1ED3 H\u1EE3i sau khi l\xEAn ng\xF4i, ch\u1EC9 lo h\u01B0\u1EDFng l\u1EA1c,`,
  `kh\xF4ng m\xE0ng tri\u1EC1u ch\xEDnh, l\u1EA1i c\xF2n tin l\u1EDDi gi\xE8m pha c\u1EE7a Tri\u1EC7u Cao,`,
  `s\xE1t h\u1EA1i trung l\u01B0\u01A1ng. Tri\u1EC7u Cao trong tri\u1EC1u \u0111\xECnh nh\xE0 T\u1EA7n h\xF4 m\u01B0a g\u1ECDi gi\xF3,`,
  `l\xE0m \u0111\u1EE7 \u0111i\u1EC1u x\u1EB1ng b\u1EADy, l\xE0m t\u0103ng th\xEAm s\u1EF1 t\xE0n b\u1EA1o trong cai tr\u1ECB c\u1EE7a ho\xE0ng th\u1EA5t,`,
  `th\u1EADm ch\xED c\xF2n t\xE0n kh\u1ED1c h\u01A1n th\u1EDDi T\u1EA7n Th\u1EE7y Ho\xE0ng.`,
  `C\u1EA3 n\u01B0\u1EDBc l\u1EA7m than, d\xE2n ch\xFAng k\xEAu than kh\u1EAFp n\u01A1i,`,
  `d\u01B0\u1EDBi b\u1EA1o ch\xEDnh \u1EAFt s\u1EBD c\xF3 ph\u1EA3n kh\xE1ng.`,
  `Trong c\xE1c cu\u1ED9c ph\u1EA3n kh\xE1ng l\u1EDBn nh\u1ECF,`,
  `\u0111\xE1ng k\u1EC3 nh\u1EA5t l\xE0 cu\u1ED9c kh\u1EDFi ngh\u0129a \u0110\u1EA1i Tr\u1EA1ch H\u01B0\u01A1ng.`,
  `\u0110\u1EA1i Tr\u1EA1ch H\u01B0\u01A1ng c\xF3 th\u1EC3 b\u1EA1n kh\xF4ng bi\u1EBFt, nh\u01B0ng Tr\u1EA7n Th\u1EAFng,`,
  `Ng\xF4 Qu\u1EA3ng ch\u1EAFc ch\u1EAFn b\u1EA1n \u0111\xE3 t\u1EEBng nghe qua.`,
  `V\xE0o n\u0103m 209 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn, hai v\u1ECB t\u01B0\u1EDBng \u1EDF H\xE0 Nam \u0111\xE3 \xE1p gi\u1EA3i m\u1ED9t nh\xF3m 900 lao \u0111\u1ED9ng \u0111\u1EBFn B\u1EAFc Kinh.`,
  `Vi\xEAn quan \u0111\xE3 ch\u1ECDn hai lao \u0111\u1ED9ng trong s\u1ED1 \u0111\xF3 \u0111\u1EC3 qu\u1EA3n l\xFD nh\u1EEFng ng\u01B0\u1EDDi c\xF2n l\u1EA1i,`,
  `\u0111\xF3 ch\xEDnh l\xE0 Tr\u1EA7n Th\u1EAFng v\xE0 Ng\xF4 Qu\u1EA3ng.`,
  `Khi \u0111o\xE0n ng\u01B0\u1EDDi c\u1EE7a h\u1ECD \u0111\u1EBFn \u0110\u1EA1i Tr\u1EA1ch H\u01B0\u01A1ng,`,
  `tr\u1EDDi \u0111\u1ED5 m\u01B0a l\u1EDBn,`,
  `to\xE0n b\u1ED9 \u0111\u01B0\u1EDDng s\xE1 b\u1ECB ng\u1EADp n\u01B0\u1EDBc, m\u1ECDi ng\u01B0\u1EDDi kh\xF4ng th\u1EC3 \u0111\u1EBFn B\u1EAFc Kinh \u0111\xFAng th\u1EDDi h\u1EA1n quy \u0111\u1ECBnh.`,
  `Lu\u1EADt ph\xE1p nh\xE0 T\u1EA7n th\u1EDDi b\u1EA5y gi\u1EDD v\xF4 c\xF9ng h\xE0 kh\u1EAFc,`,
  `n\u1EBFu qu\xE1 th\u1EDDi h\u1EA1n \u0111\u1EBFn n\u01A1i s\u1EBD b\u1ECB ch\xE9m \u0111\u1EA7u.`,
  `Tr\u1EA7n Th\u1EAFng, Ng\xF4 Qu\u1EA3ng ngh\u0129,`,
  `ki\u1EC3u g\xEC c\u0169ng ch\u1EBFt, chi b\u1EB1ng c\u1EE9 li\u1EC1u m\u1ED9t phen.`,
  `Trong t\xECnh th\u1EBF c\u1EA5p b\xE1ch,`,
  `Tr\u1EA7n Th\u1EAFng, Ng\xF4 Qu\u1EA3ng \u0111\xE3 l\xE3nh \u0111\u1EA1o c\xE1c lao c\xF4ng kh\xE1c gi\u1EBFt ch\u1EBFt vi\xEAn t\u01B0\u1EDBng \xE1p b\u1EE9c h\u1ECD,`,
  `ph\xE1t \u0111\u1ED9ng binh bi\u1EBFn,`,
  `V\xE0 li\xEAn t\u1EE5c gi\xE0nh th\u1EAFng l\u1EE3i nh\u01B0 ch\u1EBB tre.`,
  `Qu\xE2n kh\u1EDFi ngh\u0129a d\u1EA7n l\u1EDBn m\u1EA1nh, chi\u1EBFm \u0111\u01B0\u1EE3c v\xE0i huy\u1EC7n l\xE2n c\u1EADn.`,
  `Ch\u01B0a \u0111\u1EA7y ba th\xE1ng sau kh\u1EDFi ngh\u0129a, nh\u1EEFng ng\u01B0\u1EDDi ch\u1ED1ng T\u1EA7n c\u0169ng nhao nhao n\u1ED5i d\u1EADy,`,
  `T\u1EA1i Tri\u1EC7u, T\u1EC1, Y\xEAn, Ng\u1EE5y v\xE0 c\xE1c n\u01A1i kh\xE1c \u0111\u1EC1u c\xF3 ng\u01B0\u1EDDi l\u1EA5y danh ngh\u0129a kh\xF4i ph\u1EE5c s\xE1u n\u01B0\u1EDBc m\xE0 t\u1EF1 x\u01B0ng v\u01B0\u01A1ng.`,
  `Sau \u0111\xF3, qu\xE2n c\u1EE7a Tr\u1EA7n Th\u1EAFng t\u1EA5n c\xF4ng v\u1EC1 ph\xEDa t\xE2y,`,
  `Ti\u1EBFn s\xE1t kinh \u0111\xF4 H\xE0m D\u01B0\u01A1ng c\u1EE7a n\u01B0\u1EDBc T\u1EA7n.`,
  `H\u1ED3 H\u1EE3i li\u1EC1n ph\xE1i qu\xE2n tr\u1EA5n \xE1p,`,
  `B\u1EDFi v\xEC ph\u1EA7n l\u1EDBn qu\xE2n kh\u1EDFi ngh\u0129a l\xE0 n\xF4ng d\xE2n,`,
  `C\u0169ng kh\xF4ng ph\u1EA3i qu\xE2n ch\xEDnh quy.`,
  `V\xEC v\u1EADy cu\u1ED1i c\xF9ng, qu\xE2n kh\u1EDFi ngh\u0129a \u0111\xE3 th\u1EA5t b\u1EA1i,`,
  `Tr\u1EA7n Th\u1EAFng, Ng\xF4 Qu\u1EA3ng b\u1ECB gi\u1EBFt.`,
  `M\u1EB7c d\xF9 h\u1ECD th\u1EA5t b\u1EA1i, nh\u01B0ng cu\u1ED9c kh\u1EDFi ngh\u0129a n\xF4ng d\xE2n quy m\xF4 l\u1EDBn n\xE0y \u0111\xE3 l\xE0m lung lay n\u1EC1n th\u1ED1ng tr\u1ECB c\u0103n b\u1EA3n c\u1EE7a nh\xE0 T\u1EA7n,`,
  `T\u1EA1o \u0111i\u1EC1u ki\u1EC7n thu\u1EADn l\u1EE3i cho L\u01B0u Bang v\xE0 H\u1EA1ng V\u0169 di\u1EC7t T\u1EA7n sau n\xE0y.`,
  `L\xFAc n\xE0y n\xF3i v\u1EC1 tri\u1EC1u \u0111\xECnh nh\xE0 T\u1EA7n,`,
  `Hai n\u0103m sau cu\u1ED9c kh\u1EDFi ngh\u0129a \u0110\u1EA1i Tr\u1EA1ch H\u01B0\u01A1ng,`,
  `H\u1ED3 H\u1EE3i b\u1ECB Tri\u1EC7u Cao \xE9p t\u1EF1 s\xE1t.`,
  `Tri\u1EC7u Cao th\u1EF1c ra mu\u1ED1n t\u1EF1 m\xECnh x\u01B0ng \u0111\u1EBF, nh\u01B0ng b\u1ECB tri\u1EC1u th\u1EA7n k\u1ECBch li\u1EC7t ph\u1EA3n \u0111\u1ED1i.`,
  `Kh\xF4ng c\xF2n c\xE1ch n\xE0o, Tri\u1EC7u Cao b\xE8n t\xECm con c\u1EE7a Ph\xF9 T\xF4 l\xE0 T\u1EED Anh,`,
  `mu\u1ED1n \u0111\u01B0a h\u1EAFn l\xEAn ng\xF4i l\xE0m b\xF9 nh\xECn.`,
  `Nh\u01B0ng \u0111i\u1EC1u Tri\u1EC7u Cao kh\xF4ng ng\u1EDD l\xE0,`,
  `T\u1EED Anh kh\xF4ng h\u1EC1 ngu ng\u1ED1c.`,
  `V\xE0o ng\xE0y th\u1EE9 n\u0103m sau khi T\u1EED Anh \u0111\u0103ng c\u01A1,`,
  `\xF4ng \u0111\xE3 l\u1EADp k\u1EBF ho\u1EA1ch lo\u1EA1i b\u1ECF Tri\u1EC7u Cao.`,
  `\u0110\xE1ng ti\u1EBFc, nh\xE0 T\u1EA7n l\xFAc b\u1EA5y gi\u1EDD \u0111\xE3 lung lay s\u1EAFp \u0111\u1ED5,`,
  `d\xF9 T\u1EED Anh c\xF3 t\xE0i gi\u1ECFi \u0111\u1EBFn m\u1EA5y c\u0169ng kh\xF4ng th\u1EC3 c\u1EE9u v\xE3n \u0111\u01B0\u1EE3c n\u1EEFa.`,
  `Kh\u1EAFp n\u01A1i tr\xEAn \u0111\u1EA5t n\u01B0\u1EDBc, c\xE1c cu\u1ED9c kh\u1EDFi ngh\u0129a n\u1ED5i d\u1EADy,`,
  `trong \u0111\xF3 c\xF3 L\u01B0u Bang \u1EDF B\xE1i huy\u1EC7n v\xE0 H\u1EA1ng V\u0169, qu\xFD t\u1ED9c c\u1EE7a n\u01B0\u1EDBc S\u1EDF c\u0169.`,
  `T\u1EED Anh t\u1EA1i v\u1ECB ch\u1EC9 v\u1ECFn v\u1EB9n 46 ng\xE0y th\xEC b\u1ECB L\u01B0u Bang, ng\u01B0\u1EDDi \u0111\xE3 t\u1EA5n c\xF4ng H\xE0m D\u01B0\u01A1ng, b\u1EAFt gi\u1EEF.`,
  `T\u1EED Anh \u0111\u1EA7u h\xE0ng, nh\xE0 T\u1EA7n di\u1EC7t vong.`,
  `Sau \u0111\xF3, H\u1EA1ng V\u0169 c\u0169ng d\u1EABn qu\xE2n t\u1EA5n c\xF4ng H\xE0m D\u01B0\u01A1ng,`,
  `T\u1EED Anh b\u1ECB H\u1EA1ng V\u0169 gi\u1EBFt ch\u1EBFt,`,
  `Cung \u0111i\u1EC7n nh\xE0 T\u1EA7n c\u0169ng b\u1ECB H\u1EA1ng V\u0169 san b\u1EB1ng.`,
  `\u0110\u1EBFn \u0111\xE2y, nh\xE0 T\u1EA7n v\u0129nh vi\u1EC5n r\xFAt kh\u1ECFi v\u0169 \u0111\xE0i l\u1ECBch s\u1EED.`
];
