var CHINA_HISTORY_CH05_NH_H_N_T_Y_H_N_T_N_TRI_U_NG_H_N_P1_C9QIE0RFSLQ_TRANSLATIONS = [
  `L\u01B0u Bang x\u01B0ng \u0111\u1EBF, s\u1EED g\u1ECDi l\xE0 T\xE2y H\xE1n,`,
  `sau n\xE0y c\xF2n c\xF3 \u0110\xF4ng H\xE1n, \u0111i\u1EC1u n\xE0y s\u1EBD \u0111\u01B0\u1EE3c n\xF3i \u0111\u1EBFn sau.`,
  `C\u0169ng nh\u01B0 c\xE1c tri\u1EC1u \u0111\u1EA1i kh\xE1c, sau khi L\u01B0u Bang l\xEAn ng\xF4i,`,
  `\xF4ng \u0111\xE3 phong th\u01B0\u1EDFng cho c\xE1c c\xF4ng th\u1EA7n d\u01B0\u1EDBi tr\u01B0\u1EDBng,`,
  `v\xE0 ch\u1ECDn c\u1ED1 \u0111\xF4 c\u1EE7a T\u1EA7n tri\u1EC1u c\u0169,`,
  `nay l\xE0 T\xE2y An \u0111\u1EC3 x\xE2y d\u1EF1ng kinh \u0111\xF4.`,
  `Th\xE0nh ph\u1ED1 m\u1EDBi n\xE0y l\xE0 Tr\u01B0\u1EDDng An,`,
  `sau khi \u0111\u1ECBnh \u0111\xF4 \u1EDF Tr\u01B0\u1EDDng An, khi L\u01B0u Bang chu\u1EA9n b\u1ECB cai tr\u1ECB t\u1ED1t tri\u1EC1u \u0111\u1EA1i \u0110\u1EA1i H\xE1n c\u1EE7a m\xECnh,`,
  `th\xEC l\xE1ng gi\u1EC1ng ph\xEDa b\u1EAFc l\xE0 Hung N\xF4 l\u1EA1i ra g\xE2y s\u1EF1,`,
  `chi\u1EBFm \u0111\xF3ng v\xE0i th\xE0nh tr\xEC \u1EDF bi\xEAn gi\u1EDBi \u0110\u1EA1i H\xE1n.`,
  `Hung N\xF4 l\xE0 k\u1EBB th\xF9 c\u0169 c\u1EE7a v\xF9ng Trung Nguy\xEAn,`,
  `lu\xF4n l\xE0 m\u1ED1i \u0111e d\u1ECDa l\u1EDBn.`,
  `L\u01B0u Bang ngh\u0129: "Ta \u0111\xE3 \u0111\xE1nh b\u1EA1i T\xE2y S\u1EDF B\xE1 v\u01B0\u01A1ng H\u1EA1ng V\u0169,`,
  `T\xF4i c\xF2n ph\u1EA3i s\u1EE3 c\xE1c ng\u01B0\u1EDDi \xE0?`,
  `Th\u1EBF n\xEAn L\u01B0u Bang quy\u1EBFt \u0111\u1ECBnh \u0111\xEDch th\xE2n xu\u1EA5t chinh.`,
  `\u0110\u1EA1i qu\xE2n c\u1EE7a \xF4ng ta ti\u1EBFn \u0111\u1EBFn bi\xEAn \u1EA3i, giao chi\u1EBFn v\u1EDBi qu\xE2n Hung N\xF4.`,
  `V\u1ED1n d\u0129 L\u01B0u Bang gi\xE0nh thi\xEAn h\u1EA1 b\u1EB1ng v\u0169 l\u1EF1c,`,
  `H\xE1n qu\xE2n c\u1EE7a \xF4ng ta kh\xF4ng ph\u1EA3i d\u1EA1ng v\u1EEBa, nhanh ch\xF3ng gi\xE0nh l\u1EA1i c\xE1c th\xE0nh tr\xEC bi\xEAn c\u01B0\u01A1ng,`,
  `v\xE0 truy \u0111u\u1ED5i qu\xE2n Hung N\xF4 \u0111ang b\u1ECF ch\u1EA1y.`,
  `N\u1EBFu cu\u1ED9c chi\u1EBFn c\u1EE9 thu\u1EADn l\u1EE3i nh\u01B0 v\u1EADy,`,
  `th\xEC \u0111\xE3 kh\xF4ng c\xF3 c\xE2u chuy\u1EC7n v\u1EC1 sau.`,
  `H\xE1n qu\xE2n truy \u0111u\u1ED5i qu\xE2n Hung N\xF4 \u0111\u1EBFn B\xECnh Th\xE0nh,`,
  `th\xEC b\u1ECB m\u1ED9t \u0111\u1EA1o qu\xE2n Hung N\xF4 d\u1EE5 v\xE0o n\xFAi B\u1EA1ch \u0110\u0103ng.`,
  `Sau khi ti\u1EBFn v\xE0o con \u0111\u01B0\u1EDDng n\xFAi ch\u1EADt h\u1EB9p, \u01B0u th\u1EBF t\xE1c chi\u1EBFn c\u1EE7a H\xE1n qu\xE2n ho\xE0n to\xE0n kh\xF4ng th\u1EC3 ph\xE1t huy,`,
  `l\u1EA1i th\xEAm \u0111\u1ECBa h\xECnh xa l\u1EA1, qu\xE2n Hung N\xF4 ph\u1EA7n l\u1EDBn l\xE0 k\u1EF5 binh,`,
  `sau khi v\xE0o n\xFAi ch\u1EC9 ch\u1EDBp m\u1EAFt \u0111\xE3 bi\u1EBFn m\u1EA5t.`,
  `L\xFAc n\xE0y, M\u1EB7c \u0110\u1ED1n Thi\u1EC1n Vu c\u1EE7a Hung N\xF4 quy\u1EBFt \u0111\u1ECBnh t\xF3m g\u1ECDn qu\xE2n L\u01B0u Bang trong m\u1ED9t m\u1EBB l\u01B0\u1EDBi,`,
  `c\xF3 l\u1EBD l\xE0 \xFD tr\u1EDDi.`,
  `\u0110\xFAng v\xE0o th\u1EDDi kh\u1EAFc nguy hi\u1EC3m n\xE0y, tr\xEAn tr\u1EDDi \u0111\u1ED9t nhi\xEAn s\u01B0\u01A1ng m\xF9 d\xE0y \u0111\u1EB7c,`,
  `l\xE0m \u0111\u1EA3o l\u1ED9n k\u1EBF ho\u1EA1ch c\u1EE7a M\u1EB7c \u0110\u1ED9c.`,
  `Qu\xE2n L\u01B0u Bang nh\xE2n l\xFAc s\u01B0\u01A1ng m\xF9 d\xE0y \u0111\u1EB7c \u0111\xE3 ph\xE1 v\xE2y,`,
  `tho\xE1t ch\u1EBFt trong gang t\u1EA5c. Sau \u0111\xF3 hai b\xEAn r\xFAt qu\xE2n,`,
  `\u0111\xE2y ch\xEDnh l\xE0 s\u1EF1 ki\u1EC7n Bao V\xE2y B\u1EA1ch \u0110\u0103ng n\u1ED5i ti\u1EBFng trong l\u1ECBch s\u1EED.`,
  `Sau s\u1EF1 ki\u1EC7n Bao V\xE2y B\u1EA1ch \u0110\u0103ng, L\u01B0u Bang nh\u1EADn ra qu\xE2n \u0111\u1ED9i c\u1EE7a m\xECnh ch\u01B0a \u0111\u1EE7 m\u1EA1nh,`,
  `qu\u1ED1c gia c\u0169ng ch\u01B0a \u0111\u1EE7 th\u1ECBnh v\u01B0\u1EE3ng,`,
  `n\xEAn nh\u1EEFng ng\u01B0\u1EDDi Hung N\xF4 n\xE0y m\u1EDBi d\xE1m th\u1EC9nh tho\u1EA3ng \u0111\u1EBFn th\xE1ch th\u1EE9c.`,
  `Sau khi v\u1EC1 nh\xE0, L\u01B0u Bang \u0111\xE3 v\u1EA1ch ra m\u1ED9t lo\u1EA1t c\xE1c bi\u1EC7n ph\xE1p \u0111\u1EC3 ngh\u1EC9 ng\u01A1i, ph\u1EE5c h\u1ED3i,`,
  `th\xFAc \u0111\u1EA9y n\u0103ng su\u1EA5t,`,
  `\u0111\u1ED3ng th\u1EDDi d\xF9ng ph\u01B0\u01A1ng th\u1EE9c h\xF2a th\xE2n v\u1EDBi Hung N\xF4 \u0111\u1EC3 t\u1EA1m th\u1EDDi xoa d\u1ECBu m\xE2u thu\u1EABn,`,
  `nh\u1EB1m t\xECm ki\u1EBFm m\u1ED9t m\xF4i tr\u01B0\u1EDDng b\xEAn ngo\xE0i \u1ED5n \u0111\u1ECBnh.`,
  `C\xE1c m\u1ED1i \u0111e d\u1ECDa b\xEAn ngo\xE0i \u0111\xE3 \u0111\u01B0\u1EE3c gi\u1EA3i quy\u1EBFt, nh\u01B0ng v\u1EA5n \u0111\u1EC1 n\u1ED9i b\u1ED9 l\u1EA1i n\u1EA3y sinh.`,
  `V\xE0o \u0111\u1EA7u th\u1EDDi H\xE1n, sau khi L\u01B0u Bang ph\xE2n phong,`,
  `c\xF3 v\xE0i ch\u01B0 h\u1EA7u kh\xF4ng ph\u1EE5c \u0111\xE3 n\u1ED5i d\u1EADy ch\u1ED1ng \u0111\u1ED1i,`,
  `M\u1EB7c d\xF9 cu\u1ED1i c\xF9ng b\u1ECB L\u01B0u Bang tr\u1EA5n \xE1p, nh\u01B0ng qua nh\u1EEFng vi\u1EC7c n\xE0y,`,
  `L\u01B0u Bang n\u1EA3y sinh t\xE2m b\u1EC7nh.`,
  `Nh\u1EEFng ch\u01B0 h\u1EA7u kh\xF4ng c\xF3 b\u1EA3n l\u0129nh g\xEC \u0111\xE1ng k\u1EC3 n\xE0y \u0111\u1EC1u n\u1ED5i d\u1EADy m\u01B0u ph\u1EA3n.`,
  `V\u1EADy c\xF4ng th\u1EA7n l\u1EDBn H\xE0n T\xEDn, ng\u01B0\u1EDDi t\u1EEBng gi\xFAp m\xECnh gi\xE0nh thi\xEAn h\u1EA1,`,
  `li\u1EC7u c\xF3 \xFD ngh\u0129 t\u01B0\u01A1ng t\u1EF1 kh\xF4ng?`,
  `H\xE0n T\xEDn kh\xE1c v\u1EDBi nh\u1EEFng k\u1EBB ti\u1EC3u t\u1ED1t n\xE0y,`,
  `\xF4ng l\xE0 \u0111\u1EA1i l\xE3o s\u1ED1 m\u1ED9t trong qu\xE2n \u0111\u1ED9i, c\xF3 uy t\xEDn tuy\u1EC7t \u0111\u1ED1i.`,
  `Ngo\xE0i L\u01B0u Bang ra, th\u1EF1c ra c\xF2n c\xF3 m\u1ED9t ng\u01B0\u1EDDi kh\xE1c c\u0169ng r\u1EA5t ki\xEAng k\u1EF5 H\xE0n T\xEDn,`,
  `\u0111\xF3 ch\xEDnh l\xE0 L\u1EEF Tr\u0129, v\u1EE3 c\u1EE7a L\u01B0u Bang.`,
  `V\xEC l\xFAc \u0111\xF3 L\u01B0u Bang \u0111\xE3 s\xE1u m\u01B0\u01A1i tu\u1ED5i,`,
  `m\xE0 H\xE0n T\xEDn m\u1EDBi ba m\u01B0\u01A1i t\u01B0 tu\u1ED5i.`,
  `N\u1EBFu m\u1ED9t ng\xE0y L\u01B0u Bang qua \u0111\u1EDDi,`,
  `sau khi con trai L\u1EEF Tr\u0129 l\xE0 L\u01B0u Doanh l\xEAn ng\xF4i,`,
  `li\u1EC7u c\xF3 b\u1ECB H\xE0n T\xEDn uy hi\u1EBFp kh\xF4ng?`,
  `L\u1EEF Tr\u0129 l\xE0 m\u1ED9t ng\u01B0\u1EDDi t\xE0n nh\u1EABn, \u0111\u1EC3 gi\xFAp con trai b\u1EDBt \u0111i ch\u01B0\u1EDBng ng\u1EA1i,`,
  `\xD4ng ta l\u1EEBa H\xE0n T\xEDn v\xE0o cung r\u1ED3i gi\u1EBFt ch\u1EBFt.`,
  `Sau \u0111\xF3 L\u01B0u Bang c\u0169ng lo s\u1EE3 quy\u1EC1n l\u1EF1c c\u1EE7a m\xECnh kh\xF4ng v\u1EEFng ch\u1EAFc,`,
  `b\u1EAFt \u0111\u1EA7u \u0111\xE0n \xE1p c\xE1c ch\u01B0 h\u1EA7u d\u1ECB h\u1ECD kh\xE1c.`,
  `N\u0103m 195 TCN,`,
  `sau khi L\u01B0u Bang ti\xEAu di\u1EC7t v\u1ECB v\u01B0\u01A1ng d\u1ECB h\u1ECD ph\u1EA3n lo\u1EA1n cu\u1ED1i c\xF9ng,`,
  `\xF4ng l\xE2m b\u1EC7nh n\u1EB7ng. Gi\u1EEFa th\xE1ng T\u01B0,`,
  `H\xE1n Cao T\u1ED5 L\u01B0u Bang qua \u0111\u1EDDi t\u1EA1i Tr\u01B0\u1EDDng L\u1EA1c Cung,`,
  `Th\xE1i t\u1EED, t\u1EE9c H\xE1n Hu\u1EC7 \u0110\u1EBF L\u01B0u Doanh sau n\xE0y, l\xEAn ng\xF4i.`,
  `L\u01B0u Doanh kh\xE1c h\u1EB3n cha m\xECnh,`,
  `t\xEDnh t\xECnh qu\xE1 nh\xE2n h\u1EADu, l\u1EA1i r\u1EA5t nhu nh\u01B0\u1EE3c v\xE0 nh\xFAt nh\xE1t.`,
  `M\u1ED9t v\u1ECB ho\xE0ng \u0111\u1EBF y\u1EBFu \u1EDBt nh\u01B0 v\u1EADy l\u1EA1i c\xF3 m\u1ED9t ng\u01B0\u1EDDi m\u1EB9 r\u1EA5t m\u1EA1nh m\u1EBD l\xE0 L\xE3 Tr\u0129.`,
  `Trong tay L\xE3 Tr\u0129, L\u01B0u Doanh g\u1EA7n nh\u01B0 l\xE0 m\u1ED9t con r\u1ED1i.`,
  `Thu\u1EDF nh\u1ECF L\xE3 Tr\u0129 th\u1EF1c ra c\u0169ng l\xE0 m\u1ED9t ti\u1EC3u th\u01B0 khu\xEA c\xE1c,`,
  `cha b\xE0 l\xE0 l\xE3o L\xE3 \u0111\xE3 \u0111\u1EC3 m\u1EAFt \u0111\u1EBFn L\u01B0u Bang, l\xFAc \u0111\xF3 v\u1EABn l\xE0 m\u1ED9t k\u1EBB lang thang tu\u1ED5i trung ni\xEAn \u1EDF huy\u1EC7n B\xE1i,`,
  `v\xE0 g\u1EA3 L\xE3 Tr\u0129 cho L\u01B0u Bang.`,
  `Kh\xF4ng th\u1EC3 kh\xF4ng n\xF3i, t\u1EA7m nh\xECn c\u1EE7a L\xE3o L\u1EEF \u0111\xFAng l\xE0 r\u1EA5t tinh t\u01B0\u1EDDng.`,
  `Nh\u01B0ng sau khi k\u1EBFt h\xF4n, L\u01B0u Bang ch\u1EC9 m\u1ED9t l\xF2ng lo s\u1EF1 nghi\u1EC7p c\u1EE7a m\xECnh,`,
  `\u0110\u1EC3 L\xE3 Tr\u0129 v\xE0 con c\xE1i \u1EDF l\u1EA1i qu\xEA nh\xE0, kh\xF4ng h\u1EC1 quan t\xE2m \u0111\u1EBFn h\u1ECD.`,
  `Trong th\u1EDDi lo\u1EA1n, L\xE3 Tr\u0129 ch\u1EADt v\u1EADt c\u1EA7u sinh,`,
  `V\xE0i n\u0103m sau, cu\u1ED1i c\xF9ng c\u0169ng tr\u1EDF v\u1EC1 b\xEAn L\u01B0u Bang,`,
  `Nh\u01B0ng l\xFAc n\xE0y L\u01B0u Bang \u0111\xE3 l\xE0 H\xE1n v\u01B0\u01A1ng c\xF3 m\u1EF9 nh\xE2n Th\xEDch phu nh\xE2n \u1EDF b\xEAn.`,
  `Ch\u1ED3ng b\u1ECB c\u01B0\u1EDBp \u0111\xE3 \u0111\xE0nh,`,
  `Th\xEDch phu nh\xE2n c\xF2n mu\u1ED1n L\u01B0u Bang ph\u1EBF tru\u1EA5t th\xE1i t\u1EED L\u01B0u Doanh,`,
  `L\u1EADp con trai m\xECnh l\xE0 Tri\u1EC7u V\u01B0\u01A1ng Nh\u01B0 \xDD l\xE0m th\xE1i t\u1EED.`,
  `M\u1EB7c d\xF9 cu\u1ED1i c\xF9ng kh\xF4ng th\xE0nh c\xF4ng, nh\u01B0ng L\xE3 Tr\u0129 \u0111\xE3 ghi nh\u1EDB m\u1ED1i th\xF9 n\xE0y.`,
  `Sau khi L\u01B0u Bang ch\u1EBFt, L\xE3 Tr\u0129 \u0111\xE3 giam l\u1ECFng Th\xEDch phu nh\xE2n,`,
  `\u0110\u1EC3 b\xE0 t\u01B0\u1EDBi hoa qu\xE9t d\u1ECDn, t\xF3m l\u1EA1i l\xE0 l\xE0m nh\u1EEFng c\xF4ng vi\u1EC7c n\u1EB7ng nh\u1ECDc c\u1EE7a ng\u01B0\u1EDDi h\u1EA7u.`,
  `C\xF2n Th\xEDch phu nh\xE2n th\xEC c\u0169ng l\xE0 m\u1ED9t k\u1EBB n\xE3o t\xE0n, kh\xF4ng bi\u1EBFt b\xE0 ta b\xE2y gi\u1EDD \u0111\xE3 kh\xF4ng c\xF2n ch\u1ED7 d\u1EF1a sao?`,
  `Trong l\xFAc d\u1ECDn d\u1EB9p,`,
  `B\xE0 ta c\xF2n t\u1EF1 m\xECnh s\xE1ng t\xE1c m\u1ED9t b\xE0i h\xE1t,`,
  `Ng\xE0y n\xE0o c\u0169ng h\xE1t, n\xF3i r\u1EB1ng: \u201CCon \u01A1i, con c\xF3 bi\u1EBFt m\u1EB9 con kh\u1ED5 s\u1EDF l\u1EAFm kh\xF4ng?`,
  `Con l\xE0 Tri\u1EC7u V\u01B0\u01A1ng, c\xF2n m\u1EB9 th\xEC l\xE0m vi\u1EC7c \u1EDF \u0111\xE2y, nh\u01B0 m\u1ED9t n\xF4 l\u1EC7,`,
  `\u0111\u1EE7 th\u1EE9 chuy\u1EC7n.`,
  `Th\u1EBF n\xE0y th\xEC hay r\u1ED3i, b\xE0 ta \u0111\xE3 th\xE0nh c\xF4ng ch\u1ECDc gi\u1EADn L\xE3 H\u1EADu.`,
  `L\xE3 H\u1EADu \u0111\xE3 h\u1EA1 \u0111\u1ED9c Tri\u1EC7u V\u01B0\u01A1ng Nh\u01B0 \xDD, ch\u1EB7t \u0111\u1EE9t tay ch\xE2n T\xEDch phu nh\xE2n,`,
  `m\xF3c m\u1EAFt, c\u1EAFt l\u01B0\u1EE1i,`,
  `bi\u1EBFn th\xE0nh \u201Cng\u01B0\u1EDDi heo\u201D r\u1ED3i n\xE9m v\xE0o nh\xE0 x\xED.`,
  `Nh\xECn th\u1EA5y m\u1ED9t lo\u1EA1t h\xE0nh \u0111\u1ED9ng c\u1EE7a m\u1EB9 m\xECnh,`,
  `L\u01B0u Doanh v\u1ED1n \u0111\xE3 y\u1EBFu \u0111u\u1ED1i l\u1EA1i c\xE0ng th\xEAm n\u1EB7ng g\xE1nh t\xE2m l\xFD,`,
  `s\u1EE9c kh\u1ECFe c\u0169ng ng\xE0y c\xE0ng t\u1ED3i t\u1EC7,`,
  `m\u1EDBi hai m\u01B0\u01A1i ba tu\u1ED5i \u0111\xE3 b\u1EC7nh ch\u1EBFt.`,
  `Sau \u0111\xF3 L\xE3 H\u1EADu \u0111\xE3 \u0111\u01B0a con trai ba tu\u1ED5i c\u1EE7a L\u01B0u Doanh l\xE0 L\u01B0u Cung l\xEAn k\u1EBF v\u1ECB,`,
  `nh\u01B0ng L\u01B0u Cung kh\xF4ng \u0111\u01B0\u1EE3c v\xE2ng l\u1EDDi,`,
  `sau b\u1ED1n n\u0103m t\u1EA1i v\u1ECB \u0111\xE3 b\u1ECB L\xE3 H\u1EADu gi\u1EBFt ch\u1EBFt,`,
  `l\u1EA1i \u0111\u01B0a m\u1ED9t ng\u01B0\u1EDDi con kh\xE1c c\u1EE7a L\u01B0u Doanh l\xEAn.`,
  `L\u01B0u H\u1ED3ng 4 tu\u1ED5i \u0111\u01B0\u1EE3c l\u1EADp l\xE0m ho\xE0ng \u0111\u1EBF.`
];
