var CHINA_HISTORY_CH05_NH_H_N_T_Y_H_N_T_N_TRI_U_NG_H_N_P2_C9QIE0RFSLQ_TRANSLATIONS = [
  `M\u1EB7c d\xF9 \u0111\xE3 c\xF3 qu\xE2n c\u1EDD l\xE0 ho\xE0ng \u0111\u1EBF, nh\u01B0ng c\xE1c \u0111\u1EA1i th\u1EA7n trong tri\u1EC1u \u0111\xECnh \u0111\u1EC1u l\xE0 thu\u1ED9c h\u1EA1 c\u1EE7a L\u01B0u Bang,`,
  `h\u1ECD c\u0169ng kh\xF4ng nghe l\u1EDDi L\u1EEF Tr\u0129.`,
  `L\u1EEF Tr\u0129 t\u1EF1 m\xECnh bi\u1EBFt \u0111i\u1EC1u n\xE0y,`,
  `ch\u1EC9 n\u1EAFm quy\u1EC1n ho\xE0ng \u0111\u1EBF v\u1EABn ch\u01B0a \u0111\u1EE7, c\xF2n ph\u1EA3i c\xF3 ng\u01B0\u1EDDi trong tri\u1EC1u.`,
  `V\xEC v\u1EADy, sau khi L\u01B0u Doanh m\u1EA5t,`,
  `L\u1EEF Tr\u0129 \u0111\xE3 c\u1EA5t nh\u1EAFc nhi\u1EC1u ng\u01B0\u1EDDi th\xE2n c\u1EE7a h\u1ECD L\u1EEF,`,
  `d\u1EA7n d\u1EA7n c\xE1c v\u1ECB tr\xED quan tr\u1ECDng trong v\xE0 ngo\xE0i tri\u1EC1u \u0111\xECnh \u0111\u1EC1u \u0111\u01B0\u1EE3c thay th\u1EBF b\u1EB1ng ng\u01B0\u1EDDi h\u1ECD L\u1EEF.`,
  `Trong t\xECnh hu\u1ED1ng n\xE0y,`,
  `li\u1EC7u c\xE1c c\u1EF1u th\u1EA7n c\u1EE7a L\u01B0u Bang v\xE0 h\u1EADu du\u1EC7 nh\xE0 L\u01B0u c\xF3 cam t\xE2m nh\xECn quy\u1EC1n l\u1EF1c r\u01A1i v\xE0o tay k\u1EBB kh\xE1c,`,
  `m\xE0 kh\xF4ng ra tay ch\u1ED1ng \u0111\u1ED1i sao?`,
  `Kh\xF4ng ph\u1EA3i h\u1ECD kh\xF4ng mu\u1ED1n, ch\u1EC9 l\xE0 L\u1EEF Tr\u0129 qu\xE1 l\u1EE3i h\u1EA1i,`,
  `lu\xF4n kh\xF4ng t\xECm \u0111\u01B0\u1EE3c c\u01A1 h\u1ED9i.`,
  `Tuy nhi\xEAn, con ng\u01B0\u1EDDi ai r\u1ED3i c\u0169ng ph\u1EA3i ch\u1EBFt, L\u1EEF Tr\u0129 c\u0169ng \u0111\u1EBFn ng\xE0y \u0111\xF3.`,
  `Sau khi L\u1EEF Tr\u0129 ch\u1EBFt, hai ch\xE1u trai c\u1EE7a b\xE0 l\xE0 L\u1EEF L\u1ED9c v\xE0 L\u1EEF S\u1EA3n \u0111\xE3 d\u1EF1a v\xE0o vi\u1EC7c n\u1EAFm gi\u1EEF tr\u1ECDng binh chu\u1EA9n b\u1ECB l\xE0m ph\u1EA3n,`,
  `\u0110\u1EC3 giang s\u01A1n ho\xE0n to\xE0n mang h\u1ECD L\u1EEF.`,
  `Nh\u01B0ng h\u1ECD v\u1EABn c\xF2n qu\xE1 non n\u1EDBt,`,
  `Tuy c\xF3 d\xE3 t\xE2m nh\u01B0ng kh\xF4ng c\xF3 \u0111\u1EA7u \xF3c,`,
  `Ho\xE0n to\xE0n kh\xF4ng ph\u1EA3i l\xE0 \u0111\u1ED1i th\u1EE7 c\u1EE7a c\xE1c l\xE3o th\u1EA7n L\u01B0u Bang.`,
  `Sau \u0111\xF3, c\xE1c anh em h\u1ECD L\u1EEF l\u1EA7n l\u01B0\u1EE3t b\u1ECB gi\u1EBFt,`,
  `Nh\xE0 h\u1ECD L\u1EEF b\u1ECB di\u1EC7t to\xE0n t\u1ED9c ch\u01B0a \u0111\u1EA7y n\u1EEDa n\u0103m sau khi L\u1EEF H\u1EADu ch\u1EBFt,`,
  `\u0110\xE3 gi\u1EA3i quy\u1EBFt nh\xE0 h\u1ECD L\u1EEF xong.`,
  `V\u1EA5n \u0111\u1EC1 l\u1EDBn nh\u1EA5t ti\u1EBFp theo l\xE0 ch\u1ECDn ai l\xE0m t\xE2n ho\xE0ng \u0111\u1EBF.`,
  `Th\u1EF1c ra l\xFAc n\xE0y kh\xF4ng ph\u1EA3i l\xE0 kh\xF4ng c\xF3 ho\xE0ng \u0111\u1EBF,`,
  `Ch\u1EB3ng ph\u1EA3i v\u1EABn c\xF2n m\u1ED9t ti\u1EC3u ho\xE0ng \u0111\u1EBF b\xF9 nh\xECn L\u01B0u H\u1ED3ng do L\u1EEF H\u1EADu l\u1EADp ra sao?`,
  `\u0110\u1EC3 L\u01B0u H\u1ED3ng tho\xE1i v\u1ECB, \u0111\xE1m l\xE3o th\u1EA7n n\xE0y \u0111\xE3 tung tin \u0111\u1ED3n,`,
  `N\xF3i r\u1EB1ng L\u01B0u H\u1ED3ng kh\xF4ng ph\u1EA3i con ru\u1ED9t c\u1EE7a L\u01B0u Anh.`,
  `C\u1EE9 nh\u01B0 v\u1EADy, h\u1ECD \u0111\xE3 l\u1EADp t\xE2n ho\xE0ng \u0111\u1EBF H\xE1n Hi\u1EBFu V\u0103n \u0110\u1EBF L\u01B0u H\u1EB1ng,`,
  `C\xF3 ph\u1EA3i v\xEC L\u01B0u H\u1EB1ng r\u1EA5t \u01B0u t\xFA, r\u1EA5t anh d\u0169ng, r\u1EA5t m\u1EA1nh m\u1EBD,`,
  `N\xEAn m\u1EDBi l\u1EADp \xF4ng \u1EA5y kh\xF4ng?`,
  `Ho\xE0n to\xE0n ng\u01B0\u1EE3c l\u1EA1i, L\u01B0u H\u1EB1ng l\xFAc \u0111\xF3 ch\u1EC9 l\xE0 m\u1ED9t ng\u01B0\u1EDDi v\xF4 danh.`,
  `L\u01B0u H\u1EB1ng l\xE0 con trai c\u1EE7a L\u01B0u Bang v\xE0 B\u1EA1c C\u01A1, m\u1ED9t n\u1EEF c\xF4ng l\xE0m ngh\u1EC1 d\u1EC7t v\u1EA3i trong cung.`,
  `L\u01B0u Bang v\xE0 B\u1EA1c C\u01A1 kh\xF4ng c\xF3 t\xECnh c\u1EA3m g\xEC v\u1EDBi nhau.`,
  `Ch\u1EC9 l\xE0 m\u1ED9t ng\xE0y n\u1ECD, L\u01B0u Bang nh\xECn th\u1EA5y B\u1EA1c C\u01A1,`,
  `nh\u1EA5t th\u1EDDi h\u1EE9ng th\xFA \u0111\xE3 s\u1EE7ng \xE1i b\xE0.`,
  `Sau khi L\u01B0u H\u1EB1ng ra \u0111\u1EDDi, \xF4ng c\u0169ng kh\xF4ng \u0111\u01B0\u1EE3c coi tr\u1ECDng nh\u01B0 m\u1EB9 m\xECnh.`,
  `Nh\u01B0ng d\xF9 sao \xF4ng c\u0169ng l\xE0 con trai c\u1EE7a L\u01B0u Bang,`,
  `sau n\xE0y \u0111\u01B0\u1EE3c phong l\xE0m \u0110\u1EA1i V\u01B0\u01A1ng \u1EDF \u0111\u1EA5t \u0110\u1EA1i.`,
  `C\xE1c l\xE3o th\u1EA7n ch\u1ECDn L\u01B0u H\u1EB1ng v\xEC nh\xECn tr\xFAng s\u1EF1 khi\xEAm t\u1ED1n, kh\xF4ng ph\xF4 tr\u01B0\u01A1ng c\u1EE7a \xF4ng,`,
  `d\u1EC5 ki\u1EC3m so\xE1t. M\u1EB7c d\xF9 L\u01B0u H\u1EB1ng khi\xEAm t\u1ED1n nh\u01B0ng \xF4ng kh\xF4ng ng\u1ED1c.`,
  `Sau khi l\xEAn ng\xF4i ho\xE0ng \u0111\u1EBF, \xF4ng c\u0169ng bi\u1EBFt r\u1EB1ng nh\xF3m l\xE3o th\u1EA7n n\xE0y r\u1EA5t m\u1EA1nh,`,
  `ho\xE0ng quy\u1EC1n c\u1EE7a m\xECnh kh\xF4ng v\u1EEFng ch\u1EAFc.`,
  `V\xEC v\u1EADy, \u0111\u1EC3 t\u0103ng c\u01B0\u1EDDng t\u1EADp quy\u1EC1n, \xF4ng \u0111\xE3 th\u1EF1c hi\u1EC7n m\u1ED9t s\u1ED1 ch\xEDnh s\xE1ch,`,
  `t\u1EEBng b\u01B0\u1EDBc l\xE0m suy y\u1EBFu th\u1EBF l\u1EF1c c\u1EE7a c\xE1c ch\u01B0 h\u1EA7u v\u01B0\u01A1ng, v\xE0 trong vi\u1EC7c cai tr\u1ECB \u0111\u1EA5t n\u01B0\u1EDBc,`,
  `L\u01B0u H\u1EB1ng \u0111\xE3 gi\u1EA3m thu\u1EBF,`,
  `Khuy\u1EBFn kh\xEDch s\u1EA3n xu\u1EA5t n\xF4ng nghi\u1EC7p,`,
  `sau n\xE0y th\u1EADm ch\xED c\xF2n mi\u1EC5n to\xE0n b\u1ED9 thu\u1EBF ru\u1ED9ng cho n\xF4ng d\xE2n.`,
  `Nh\u1EDD \u0111\xF3, kinh t\u1EBF c\u1EA3 n\u01B0\u1EDBc ph\xE1t tri\u1EC3n v\u01B0\u1EE3t b\u1EADc,`,
  `d\xE2n ch\xFAng an c\u01B0 l\u1EA1c nghi\u1EC7p, nh\u1EEFng vi\u1EC7c l\xE0m n\xE0y \u0111\xE3 \u0111\u1EB7t n\u1EC1n m\xF3ng v\u1EEFng ch\u1EAFc cho m\u1ED9t th\u1EDDi k\u1EF3 th\u1ECBnh v\u01B0\u1EE3ng sau n\xE0y.`,
  `N\u0103m 157 tr\u01B0\u1EDBc C\xF4ng nguy\xEAn,`,
  `L\u01B0u H\u1EB1ng qua \u0111\u1EDDi v\xEC b\u1EC7nh, con trai \xF4ng l\xE0 H\xE1n C\u1EA3nh \u0110\u1EBF L\u01B0u Kh\u1EA3i l\xEAn ng\xF4i.`,
  `L\u01B0u Kh\u1EA3i t\u1EEB nh\u1ECF \u0111\xE3 kh\xF4ng ph\u1EA3i l\xE0 m\u1ED9t \u0111\u1EE9a tr\u1EBB ngoan ngo\xE3n.`,
  `Khi c\xF2n l\xE0 th\xE1i t\u1EED, c\xF3 l\u1EA7n \xF4ng ch\u01A1i c\u1EDD v\u1EDBi con trai c\u1EE7a Ng\xF4 v\u01B0\u01A1ng L\u01B0u T\u1EF5,`,
  `hai b\xEAn x\u1EA3y ra tranh c\xE3i,`,
  `L\u01B0u Kh\u1EA3i li\u1EC1n c\u1EA7m b\xE0n c\u1EDD,`,
  `\u0111\u1EADp ch\u1EBFt con trai c\u1EE7a L\u01B0u T\u1EF5 ngay t\u1EA1i ch\u1ED7.`,
  `Chuy\u1EC7n n\xE0y khi\u1EBFn L\u01B0u T\u1EF5 lu\xF4n ghi h\u1EADn trong l\xF2ng,`,
  `nh\u01B0ng L\u01B0u Kh\u1EA3i l\xE0 th\xE1i t\u1EED, \xF4ng c\u0169ng kh\xF4ng th\u1EC3 l\xE0m g\xEC \u0111\u01B0\u1EE3c.`,
  `Sau khi L\u01B0u Kh\u1EA3i l\xEAn ng\xF4i,`,
  `th\u1EBF l\u1EF1c c\u1EE7a c\xE1c ch\u01B0 h\u1EA7u \u0111e d\u1ECDa nghi\xEAm tr\u1ECDng \u0111\u1EBFn quy\u1EC1n l\u1EF1c t\u1EADp trung c\u1EE7a tri\u1EC1u \u0111\xECnh,`,
  `L\u01B0u Kh\u1EA3i l\u1EADp t\u1EE9c quy\u1EBFt \u0111\u1ECBnh c\u1EAFt gi\u1EA3m phi\xEAn tr\u1EA5n.`,
  `L\xFAc n\xE0y, h\u1EADn m\u1EDBi ch\u1ED3ng h\u1EADn c\u0169, L\u01B0u B\u1ECB l\u1EADp t\u1EE9c d\u1EA5y binh l\xE0m ph\u1EA3n,`,
  `C\xF3 b\u1EA3y v\u01B0\u01A1ng h\u1EA7u tham gia v\xE0o cu\u1ED9c n\u1ED5i lo\u1EA1n, s\u1EED g\u1ECDi l\xE0 Lo\u1EA1n b\u1EA3y n\u01B0\u1EDBc.`,
  `L\u01B0u Kh\u1EA3i ph\xE1i danh t\u01B0\u1EDBng Chu \xC1 Phu \u0111i d\u1EB9p lo\u1EA1n,`,
  `Chu \xC1 Phu qu\u1EA3 th\u1EF1c l\xE0 th\u1EA7n t\u01B0\u1EDBng,`,
  `Ch\u1EC9 m\u1EA5t ba th\xE1ng \u0111\u1EC3 d\u1EB9p y\xEAn Lo\u1EA1n b\u1EA3y n\u01B0\u1EDBc,`,
  `C\u1EE7ng c\u1ED1 quy\u1EC1n l\u1EF1c t\u1EADp trung c\u1EE7a tri\u1EC1u \u0111\xECnh.`,
  `Tr\u1EADn chi\u1EBFn n\xE0y c\u0169ng khi\u1EBFn L\u01B0u Kh\u1EA3i tr\u01B0\u1EDFng th\xE0nh h\u01A1n,`,
  `\xD4ng \u1EA5y hi\u1EC3u r\u1EB1ng \u0111\u1EC3 m\u1EDF ra m\u1ED9t th\u1EDDi k\u1EF3 th\u1ECBnh v\u01B0\u1EE3ng, \xF4ng \u1EA5y ph\u1EA3i \u0111i theo con \u0111\u01B0\u1EDDng m\xE0 cha m\xECnh \u0111\xE3 \u0111i,`,
  `Ph\xE1t tri\u1EC3n n\xF4ng nghi\u1EC7p, chu\u1EA9n h\xF3a ph\xE1p lu\u1EADt,`,
  `\u1EE6ng h\u1ED9 c\xE1c tr\u01B0\u1EDDng ph\xE1i t\u01B0 t\u01B0\u1EDFng kh\xE1c nhau.`,
  `Trong th\u1EDDi gian \xF4ng tr\u1ECB v\xEC, kinh t\u1EBF \u0111\u1EA5t n\u01B0\u1EDBc,`,
  `V\u0103n h\xF3a, th\u1EC3 ch\u1EBF \u0111\u1EC1u ph\xE1t tri\u1EC3n nhanh ch\xF3ng.`,
  `Sau khi L\u01B0u Kh\u1EA3i \u0111\xE3 d\u1ECDn s\u1EB5n m\u1ECDi con \u0111\u01B0\u1EDDng cho con trai m\xECnh,`,
  `C\u0169ng \u0111\xE3 gi\xE3 t\u1EEB v\u0169 \u0111\xE0i l\u1ECBch s\u1EED.`,
  `Sau \u0111\xF3, L\u01B0u Tri\u1EC7t, ph\xFA tam \u0111\u1EA1i th\u1EEBa k\u1EBF gia s\u1EA3n c\u1EE7a cha v\xE0 \xF4ng n\u1ED9i, l\xEAn ng\xF4i.`,
  `\xD4ng ch\xEDnh l\xE0 H\xE1n V\u0169 \u0110\u1EBF n\u1ED5i ti\u1EBFng.`,
  `Tr\u1EA3i qua hai \u0111\u1EDDi \xF4ng v\xE0 cha tr\u1ECB v\xEC \u1ED5n \u0111\u1ECBnh, t\xEDch l\u0169y ban \u0111\u1EA7u,`,
  `\u0111\u1EBFn th\u1EDDi H\xE1n V\u0169 \u0110\u1EBF L\u01B0u Tri\u1EC7t ti\u1EBFp qu\u1EA3n,`,
  `gia nghi\u1EC7p \u0111\xE3 l\u1EDBn m\u1EA1nh.`,
  `L\u01B0u Tri\u1EC7t kh\xF4ng mu\u1ED1n l\xE0m m\u1ED9t ph\xFA tam \u0111\u1EA1i t\u1EA7m th\u01B0\u1EDDng,`,
  `\xF4ng c\xF3 ho\xE0i b\xE3o, c\xF3 tham v\u1ECDng,`,
  `sau n\xE0y s\u1EF1 th\u1EADt c\u0169ng ch\u1EE9ng minh \xF4ng c\xE0ng c\xF3 n\u0103ng l\u1EF1c.`,
  `Vi\u1EC7c \u0111\u1EA7u ti\xEAn L\u01B0u Tri\u1EC7t l\xE0m sau khi nh\u1EADm ch\u1EE9c l\xE0 tuy\u1EC3n ch\u1ECDn nh\xE2n t\xE0i,`,
  `\xF4ng \u0111\xE3 t\u1ED5 ch\u1EE9c m\u1ED9t k\u1EF3 thi tuy\u1EC3n ch\u1ECDn ch\u01B0a t\u1EEBng c\xF3 trong l\u1ECBch s\u1EED tr\xEAn to\xE0n qu\u1ED1c,`,
  `m\u1ED9t nho sinh t\xEAn \u0110\u1ED5ng Tr\u1ECDng Th\u01B0 \u0111\xE3 xu\u1EA5t s\u1EAFc v\u01B0\u1EE3t qua.`,
  `Khi \u0110\u1ED5ng Tr\u1ECDng Th\u01B0 \u0111\u01B0a ra m\u1ED9t b\u1ED9 l\xFD lu\u1EADn tr\u1ECB qu\u1ED1c Nho h\u1ECDc ho\xE0n ch\u1EC9nh tr\u01B0\u1EDBc m\u1EB7t L\u01B0u Tri\u1EC7t,`,
  `L\u01B0u Tri\u1EC7t t\xE2m ph\u1EE5c kh\u1EA9u ph\u1EE5c.`,
  `Sau \u0111\xF3, \xF4ng \u0111\xE3 ch\u1EA5p nh\u1EADn ki\u1EBFn ngh\u1ECB c\u1EE7a \u0110\u1ED5ng Tr\u1ECDng Th\u01B0,`,
  `b\xE3i b\u1ECF tr\u0103m nh\xE0, \u0111\u1ED9c t\xF4n Nho thu\u1EADt,`,
  `khi\u1EBFn Nho gi\xE1o tr\u1EDF th\xE0nh t\u01B0 t\u01B0\u1EDFng ch\xEDnh th\u1ED1ng c\u1EE7a x\xE3 h\u1ED9i phong ki\u1EBFn Trung Qu\u1ED1c,`,
  `\u0111\xE3 k\xE9o d\xE0i h\u01A1n hai ng\xE0n n\u0103m,`,
  `\u1EA3nh h\u01B0\u1EDFng s\xE2u r\u1ED9ng \u0111\u1EBFn Trung Qu\u1ED1c \u0111\u1EDDi sau.`,
  `Tuy nhi\xEAn, ph\u1EA3i n\xF3i r\u1EB1ng,`,
  `vi\u1EC7c \u0111\u1ED9c t\xF4n Nho gi\xE1o c\u0169ng c\xF3 nh\u01B0\u1EE3c \u0111i\u1EC3m, \u0111\xF3 l\xE0 kh\xF4ng c\xF3 l\u1EE3i cho s\u1EF1 \u0111a d\u1EA1ng t\u01B0 t\u01B0\u1EDFng.`,
  `T\u1EEB H\xE1n Cao T\u1ED5 L\u01B0u Bang tr\u1EDF \u0111i,`,
  `T\xE2y H\xE1n v\xE0 Hung N\xF4 \u0111\xE3 duy tr\xEC m\u1ED1i quan h\u1EC7 h\xF4n nh\xE2n,`,
  `nh\u01B0ng Hung N\xF4 kh\xF4ng bi\u1EBFt \u0111\u1EE7,`,
  `v\u1EABn th\u01B0\u1EDDng xuy\xEAn qu\u1EA5y ph\xE1 bi\xEAn gi\u1EDBi \u0110\u1EA1i H\xE1n,`,
  `c\u01B0\u1EDBp b\xF3c ti\u1EC1n b\u1EA1c, gia s\xFAc, v.v.`,
  `L\u01B0u Tri\u1EC7t c\u0169ng lu\xF4n coi th\u01B0\u1EDDng h\u1ECD.`,
  `C\xF3 l\u1EA7n \xF4ng nghe n\xF3i,`,
  `\u1EDF T\xE2y V\u1EF1c c\xF3 t\u1ED5ng c\u1ED9ng m\u01B0\u1EDDi s\xE1u qu\u1ED1c gia,`,
  `trong \u0111\xF3 c\xF3 m\u1ED9t qu\u1ED1c gia th\xF9 gh\xE9t Hung N\xF4 gi\u1ED1ng nh\u01B0 \u0110\u1EA1i H\xE1n,`,
  `g\u1ECDi l\xE0 \u0110\u1EA1i Nh\u1EE5c Chi. K\u1EBB th\xF9 c\u1EE7a k\u1EBB th\xF9 ch\xEDnh l\xE0 b\u1EA1n.`
];
