var CHINA_HISTORY_CH05_NH_H_N_T_Y_H_N_T_N_TRI_U_NG_H_N_P4_C9QIE0RFSLQ_TRANSLATIONS = [
  `Th\u1EBF l\xE0 L\u01B0u Tri\u1EC7t c\u1EED L\xFD Qu\u1EA3ng L\u1EE3i \u0111i \u0111\xE1nh \u0110\u1EA1i Uy\xEAn \u0111\u1EC3 c\u01B0\u1EDBp ng\u1EF1a.`,
  `Th\u1EF1c ra L\xFD Qu\u1EA3ng L\u1EE3i kh\xF4ng c\xF3 t\xE0i c\xE1n g\xEC, anh ta ch\u1EC9 g\u1EB7p may.`,
  `Khi \u0111\xE1nh \u0111\u1EBFn \u0110\u1EA1i Uy\xEAn, \u0110\u1EA1i Uy\xEAn \u0111ang x\u1EA3y ra n\u1ED9i chi\u1EBFn.`,
  `L\xFD Qu\u1EA3ng L\u1EE3i \u0111\xE3 ch\u1EDBp th\u1EDDi c\u01A1, kh\xF4ng ch\u1EC9 c\u01B0\u1EDBp \u0111\u01B0\u1EE3c ng\u1EF1a v\u1EC1,`,
  `m\xE0 c\xF2n khi\u1EBFn c\xE1c n\u01B0\u1EDBc T\xE2y V\u1EF1c \u0111\u1EC1u th\u1EA7n ph\u1EE5c nh\xE0 \u0110\u1EA1i H\xE1n.`,
  `Sau khi tr\u1EDF v\u1EC1, anh ta \u0111\u01B0\u1EE3c L\u01B0u Tri\u1EC7t phong l\xE0m H\u1EA3i T\xE2y H\u1EA7u.`,
  `L\xFD Qu\u1EA3ng L\u1EE3i t\u1EEB \u0111\xF3 tr\u1EDF n\xEAn ki\xEAu ng\u1EA1o. H\u1EAFn ngh\u0129 m\xECnh t\xE0i gi\u1ECFi nh\u01B0 v\u1EADy,`,
  `ho\xE0ng th\u01B0\u1EE3ng l\u1EA1i y\xEAu qu\xFD em g\xE1i m\xECnh \u0111\u1EBFn th\u1EBF,`,
  `m\u1EB7c d\xF9 em g\xE1i \u0111\xE3 qua \u0111\u1EDDi, nh\u01B0ng v\u1EABn \u0111\u1EC3 l\u1EA1i m\u1ED9t ng\u01B0\u1EDDi con trai l\xE0 X\u01B0\u01A1ng \u1EA4p V\u01B0\u01A1ng.`,
  `\u0110\u1EC1u l\xE0 con c\u1EE7a L\u01B0u Tri\u1EC7t, t\u1EA1i sao con trai c\u1EE7a V\u1EC7 T\u1EED Phu l\xE0 L\u01B0u C\u1EE9 c\xF3 th\u1EC3 l\xE0m th\xE1i t\u1EED,`,
  `c\xF2n ch\xE1u ngo\u1EA1i c\u1EE7a m\xECnh l\xE0 X\u01B0\u01A1ng \u1EA4p V\u01B0\u01A1ng l\u1EA1i kh\xF4ng th\u1EC3?`,
  `Th\u1EBF l\xE0 m\u1ED9t \xE2m m\u01B0u d\u1EA7n \u0111\u01B0\u1EE3c nung n\u1EA5u d\u01B0\u1EDBi s\u1EF1 thao t\xFAng c\u1EE7a L\xFD Qu\u1EA3ng L\u1EE3i v\xE0 b\xE8 \u0111\u1EA3ng.`,
  `M\u1ED9t h\xF4m, L\u01B0u Tri\u1EC7t \u0111ang \u0111i d\u1EA1o trong cung,`,
  `b\u1ED7ng nhi\xEAn nh\xECn th\u1EA5y m\u1ED9t ng\u01B0\u1EDDi \u0111\xE0n \xF4ng kh\u1EA3 nghi,`,
  `\xF4ng li\u1EC1n sai ng\u01B0\u1EDDi \u0111i b\u1EAFt nh\u01B0ng ng\u01B0\u1EDDi \u0111\xE0n \xF4ng \u0111\xF3 \u0111\xE3 tr\u1ED1n tho\xE1t,`,
  `m\xE0 trong cung kh\xF4ng ai bi\u1EBFt ng\u01B0\u1EDDi \u0111\xE0n \xF4ng \u0111\xF3 v\xE0o b\u1EB1ng c\xE1ch n\xE0o.`,
  `M\u1ED9t ng\u01B0\u1EDDi \u0111\xE0n \xF4ng kh\xF4ng r\xF5 th\xE2n ph\u1EADn v\xE0o trong cung,`,
  `r\u1ED3i l\u1EA1i bi\u1EBFn m\u1EA5t m\u1ED9t c\xE1ch kh\xF3 hi\u1EC3u,`,
  `th\u1EADm ch\xED kh\xF4ng m\u1ED9t ai bi\u1EBFt.`,
  `L\u01B0u Tri\u1EC7t n\u1ED5i gi\u1EADn, l\u1EADp t\u1EE9c \u0111\xF3ng c\u1EEDa th\xE0nh Tr\u01B0\u1EDDng An,`,
  `th\u1EC1 ph\u1EA3i t\xECm ra ng\u01B0\u1EDDi \u0111\xE0n \xF4ng \u0111\xF3.`,
  `L\xFAc n\xE0y, t\u1EC3 t\u01B0\u1EDBng nh\xE0 H\xE1n l\xE0 C\xF4ng T\xF4n H\u1EA1, \xF4ng c\xF3 m\u1ED9t ng\u01B0\u1EDDi con trai t\xEAn l\xE0 C\xF4ng T\xF4n K\xEDnh S\xE2m.`,
  `C\xF4ng T\xF4n K\xEDnh S\xE2m \u0111\xE3 bi\u1EC3n th\u1EE7 c\xF4ng qu\u1EF9 n\xEAn b\u1ECB t\u1ED1ng v\xE0o ng\u1EE5c.`,
  `C\xF4ng T\xF4n H\u1EA1 mu\u1ED1n l\u1EADp c\xF4ng chu\u1ED9c t\u1ED9i cho con trai,`,
  `n\xEAn \u0111\xE3 t\u1EF1 m\xECnh xung phong \u0111i b\u1EAFt ng\u01B0\u1EDDi \u0111\xE0n \xF4ng \u0111\xE3 bi\u1EBFn m\u1EA5t trong cung.`,
  `Ng\u01B0\u1EDDi m\xE0 L\u01B0u Tri\u1EC7t \u0111\xE3 m\u1EA5t bao c\xF4ng s\u1EE9c v\u1EABn kh\xF4ng t\xECm th\u1EA5y,`,
  `\u0110\xE3 b\u1ECB C\xF4ng T\xF4n H\u1EA1 b\u1EAFt m\u1ED9t c\xE1ch d\u1EC5 d\xE0ng.`,
  `T\u1EA5t nhi\xEAn, b\xE2y gi\u1EDD t\u1EEB g\xF3c \u0111\u1ED9 c\u1EE7a ch\xFAng ta,`,
  `\u0110\xE2y l\xE0 m\u1ED9t c\xE1i b\u1EABy, nh\u01B0ng C\xF4ng T\xF4n H\u1EA1 l\xFAc \u0111\xF3 kh\xF4ng h\u1EC1 hay bi\u1EBFt.`,
  `Ng\u01B0\u1EDDi b\u1ECB b\u1EAFt t\xEAn l\xE0 Chu Th\u1EBF An,`,
  `Sau khi b\u1ECB b\u1EAFt, h\u1EAFn d\xE2ng th\u01B0 v\u1EA1ch tr\u1EA7n, n\xF3i C\xF4ng T\xF4n K\xEDnh Th\xE2m v\xE0 con g\xE1i c\u1EE7a V\u1EC7 T\u1EED Phu, c\xF4ng ch\xFAa D\u01B0\u01A1ng th\u1ECB, t\u01B0 th\xF4ng.`,
  `Hai ng\u01B0\u1EDDi h\u1EE3p s\u1EE9c d\xF9ng thu\u1EADt ph\xF9 th\u1EE7y nguy\u1EC1n r\u1EE7a H\xE1n V\u0169 \u0110\u1EBF L\u01B0u Tri\u1EC7t.`,
  `Thu\u1EADt ph\xF9 th\u1EE7y l\xE0 vi\u1EBFt t\xEAn m\u1ED9t ng\u01B0\u1EDDi l\xEAn h\xECnh n\u1ED9m,`,
  `Sau \u0111\xF3 ch\xF4n xu\u1ED1ng \u0111\u1EA5t,`,
  `Thi tri\u1EC3n ph\xE9p thu\u1EADt v\xE0 ni\u1EC7m ch\xFA, ng\u01B0\u1EDDi b\u1ECB vi\u1EBFt t\xEAn s\u1EBD g\u1EB7p xui x\u1EBBo.`,
  `L\u01B0u Tri\u1EC7t nghe l\u1EDDi Chu Th\u1EBF An, li\u1EC1n ph\xE1i ng\u01B0\u1EDDi \u0111i \u0111i\u1EC1u tra,`,
  `T\u1EA1i n\u01A1i Chu Th\u1EBF An n\xF3i, qu\u1EA3 nhi\xEAn t\xECm th\u1EA5y h\xECnh n\u1ED9m,`,
  `D\xE1m nguy\u1EC1n r\u1EE7a ho\xE0ng \u0111\u1EBF, k\u1EBFt qu\u1EA3 th\xEC kh\u1ECFi ph\u1EA3i n\xF3i,`,
  `L\u01B0u Tri\u1EC7t l\u1EADp t\u1EE9c tru di tam t\u1ED9c nh\xE0 h\u1ECD C\xF4ng T\xF4n.`,
  `V\u1EE3 c\u1EE7a C\xF4ng T\xF4n H\u1EA1 l\xE0 ch\u1ECB ru\u1ED9t c\u1EE7a V\u1EC7 T\u1EED Phu v\xE0 V\u1EC7 Thanh,`,
  `V\xEC v\u1EADy, nh\xE0 h\u1ECD V\u1EC7 c\u0169ng b\u1ECB li\xEAn l\u1EE5y.`,
  `Con g\xE1i V\u1EC7 T\u1EED Phu v\xE0 con trai c\u1EA3 c\u1EE7a V\u1EC7 Thanh l\u1EA7n l\u01B0\u1EE3t b\u1ECB gi\u1EBFt.`,
  `V\u1EC7 Thanh v\xE0 Ho\u1EAFc Kh\u1EE9 B\u1EC7nh, ni\u1EC1m t\u1EF1 h\xE0o c\u1EE7a gia t\u1ED9c h\u1ECD V\u1EC7, c\u0169ng \u0111\xE3 qua \u0111\u1EDDi.`,
  `Cu\u1ED1i c\xF9ng, nh\xE0 h\u1ECD V\u1EC7 ch\u1EC9 c\xF2n l\u1EA1i duy nh\u1EA5t ho\xE0ng h\u1EADu V\u1EC7 T\u1EED Phu.`,
  `Chuy\u1EC7n ch\u01B0a d\u1EEBng l\u1EA1i \u1EDF \u0111\xF3,`,
  `Trong tri\u1EC1u c\xF3 m\u1ED9t \u0111\u1EA1i th\u1EA7n t\xEAn Tr\u01B0\u01A1ng An, c\xF3 m\u1ED1i quan h\u1EC7 kh\xF4ng t\u1ED1t v\u1EDBi th\xE1i t\u1EED L\u01B0u C\u1EE9.`,
  `\xD4ng ta s\u1EE3 r\u1EB1ng sau khi L\u01B0u Tri\u1EC7t m\u1EA5t, L\u01B0u C\u1EE9 l\xEAn ng\xF4i s\u1EBD gi\u1EBFt m\xECnh,`,
  `Quy\u1EBFt \u0111\u1ECBnh ra tay tr\u01B0\u1EDBc \u0111\u1EC3 chi\u1EBFm \u01B0u th\u1EBF,`,
  `L\u1EE3i d\u1EE5ng v\u1EE5 \xE1n Vu c\u1ED5 \u0111\u1EC3 vu oan cho L\u01B0u C\u1EE9.`,
  `Tr\u01B0\u01A1ng An gi\u1EA3 th\u1EA7n gi\u1EA3 qu\u1EF7, l\xE9n l\xFAt \u0111\xE0o \u0111\u01B0\u1EE3c m\u1ED9t con r\u1ED1i g\u1ED7 \u1EDF ch\u1ED7 c\u1EE7a L\u01B0u C\u1EE9.`,
  `L\u01B0u C\u1EE9 l\xE0 ng\u01B0\u1EDDi \xF4n h\xF2a, th\u1EADt th\xE0, s\u1EE3 m\xECnh kh\xF4ng gi\u1EA3i th\xEDch r\xF5 r\xE0ng \u0111\u01B0\u1EE3c,`,
  `L\u1EA1i ngh\u0129 \u0111\u1EBFn k\u1EBFt c\u1EE5c bi th\u1EA3m c\u1EE7a nh\u1EEFng ng\u01B0\u1EDDi t\u1EEBng b\u1ECB li\xEAn l\u1EE5y b\u1EDFi thu\u1EADt Vu c\u1ED5 tr\u01B0\u1EDBc \u0111\xE2y.`,
  `Trong l\xFAc ho\u1EA3ng lo\u1EA1n, L\u01B0u C\u1EE9 \u0111\xE3 t\u1EF1 \xFD x\u1EED t\u1EED Tr\u01B0\u01A1ng An,`,
  `\u0110\u1EC3 t\u1EF1 b\u1EA3o v\u1EC7 m\xECnh c\xF2n ph\xE1t \u0111\u1ED9ng binh bi\u1EBFn.`,
  `C\xF2n \u0111\u1ED1i v\u1EDBi L\u01B0u Tri\u1EC7t,`,
  `L\u01B0u C\u1EE9 l\xE0 ng\u01B0\u1EDDi k\u1EBF nhi\u1EC7m \u0111\u01B0\u1EE3c L\u01B0u Tri\u1EC7t b\u1ED3i d\u01B0\u1EE1ng nhi\u1EC1u n\u0103m,`,
  `\xD4ng \u1EA5y ch\u01B0a bao gi\u1EDD ngh\u0129 \u0111\u1EBFn vi\u1EC7c gi\u1EBFt L\u01B0u C\u1EE9.`,
  `Tuy nhi\xEAn, l\xFAc n\xE0y m\u1ECDi vi\u1EC7c \u0111\xE3 v\u01B0\u1EE3t kh\u1ECFi t\u1EA7m ki\u1EC3m so\xE1t,`,
  `Hi\u1EC7n t\u1EA1i \u0111\xE3 bi\u1EBFn th\xE0nh L\u01B0u Tri\u1EC7t v\xE0 L\u01B0u C\u1EE9 hai cha con \u0111\u1ED1i \u0111\u1EA7u binh \u0111ao.`,
  `Sau \u0111\xF3, L\u01B0u C\u1EE9 th\u1EA5t b\u1EA1i v\xE0 t\u1EF1 s\xE1t,`,
  `M\u1EB9 \xF4ng l\xE0 V\u1EC7 T\u1EED Phu c\u0169ng t\u1EF1 s\xE1t trong \u0111au bu\u1ED3n v\xE0 ph\u1EABn u\u1EA5t.`,
  `Gia \u0111\xECnh L\u01B0u C\u1EE9 b\u1ECB di\u1EC7t m\xF4n,`,
  `Ch\u1EC9 c\xF3 m\u1ED9t \u0111\u1EE9a ch\xE1u nh\u1ECF c\u1EE7a L\u01B0u C\u1EE9 may m\u1EAFn tho\xE1t n\u1EA1n,`,
  `\u0110\xE2y l\xE0 chuy\u1EC7n sau n\xE0y.`,
  `Tai h\u1ECDa Vu C\u1ED5 \u0111\xE3 khi\u1EBFn h\xE0ng v\u1EA1n ng\u01B0\u1EDDi ch\u1EBFt oan.`,
  `Sau khi tai h\u1ECDa l\u1EAFng xu\u1ED1ng,`,
  `L\u01B0u Tri\u1EC7t nh\u1EADn ra r\u1EB1ng m\u1ECDi chuy\u1EC7n c\xF3 l\u1EBD kh\xF4ng \u0111\u01A1n gi\u1EA3n nh\u01B0 \xF4ng ngh\u0129,`,
  `Th\u1EBF l\xE0 \xF4ng cho \u0111i\u1EC1u tra l\u1EA1i to\xE0n b\u1ED9 s\u1EF1 vi\u1EC7c,`,
  `M\u1EDBi ph\xE1t hi\u1EC7n m\xECnh \u0111\xE3 oan u\u1ED5ng cho L\u01B0u C\u1EE9.`,
  `Nh\u01B0ng t\u1EA5t c\u1EA3 \u0111\xE3 qu\xE1 mu\u1ED9n r\u1ED3i,`,
  `L\u01B0u Tri\u1EC7t tu\u1ED5i gi\xE0 s\u1EE9c y\u1EBFu v\xF4 c\xF9ng t\u1EF1 tr\xE1ch b\u1EA3n th\xE2n,`,
  `v\xE0 \u0111\u1ED1i m\u1EB7t v\u1EDBi vi\u1EC7c ng\xE2n kh\u1ED1 tr\u1ED1ng r\u1ED7ng sau khi chinh ph\u1EA1t Hung N\xF4,`,
  `m\xE2u thu\u1EABn trong n\u01B0\u1EDBc ng\xE0y c\xE0ng gay g\u1EAFt.`,
  `L\xFAc n\xE0y, L\u01B0u Tri\u1EC7t nh\xECn l\u1EA1i cu\u1ED9c \u0111\u1EDDi m\xECnh,`,
  `\xF4ng quy\u1EBFt \u0111\u1ECBnh th\u1EF1c hi\u1EC7n ch\xEDnh s\xE1ch ph\u1EE5c h\u01B0ng,`,
  `ngh\u1EC9 ng\u01A1i d\u01B0\u1EE1ng s\u1EE9c. H\xE0nh \u0111\u1ED9ng n\xE0y \u0111\xE3 phanh g\u1EA5p cho nh\xE0 H\xE1n \u0111ang tr\xEAn \u0111\xE0 suy t\xE0n.`,
  `Sau \u0111\xF3, \xF4ng \u0111\u01B0a ra quy\u1EBFt \u0111\u1ECBnh cu\u1ED1i c\xF9ng trong cu\u1ED9c \u0111\u1EDDi,`,
  `l\u1EADp con trai \xFAt L\u01B0u Ph\u1EA5t L\u0103ng l\xE0m th\xE1i t\u1EED.`,
  `\u0110\u1EC3 ng\u0103n ch\u1EB7n s\u1EF1 vi\u1EC7c L\xE3 Tr\u0129 thao t\xFAng ho\xE0ng \u0111\u1EBF n\u0103m x\u01B0a t\xE1i di\u1EC5n,`,
  `L\u01B0u Tri\u1EC7t \u0111\xE3 gi\u1EBFt m\u1EB9 ru\u1ED9t c\u1EE7a L\u01B0u Ph\u1EA5t L\u0103ng l\xE0 Tri\u1EC7u Ti\u1EC7p D\u01B0,`,
  `t\u1EE9c C\xE2u D\u1EB7c phu nh\xE2n,`,
  `v\xE0 ch\u1ECDn b\u1ED1n \u0111\u1EA1i th\u1EA7n ph\u1EE5 ch\xEDnh,`,
  `trong \u0111\xF3 c\xF3 Ho\u1EAFc Quang.`,
  `Ho\u1EAFc Quang l\xE0 em c\xF9ng cha kh\xE1c m\u1EB9 v\u1EDBi Ho\u1EAFc Kh\u1EE9 B\u1EC7nh,`,
  `trong khi anh trai t\u1ECFa s\xE1ng tr\xEAn chi\u1EBFn tr\u01B0\u1EDDng,`,
  `Ho\u1EAFc Quang l\xE0m m\u1ED9t ch\u1EE9c quan nh\u1ECF trong cung.`,
  `\xD4ng ta l\xE0 ng\u01B0\u1EDDi c\u1EA9n tr\u1ECDng, t\u1EC9 m\u1EC9,`,
  `r\u1EA5t th\u1EA5u hi\u1EC3u \u0111\u1EA1o l\xE0m quan,`,
  `d\u1EA7n d\u1EA7n \u0111\u01B0\u1EE3c L\u01B0u Tri\u1EC7t tin t\u01B0\u1EDFng s\xE2u s\u1EAFc.`,
  `V\xEC v\u1EADy, cu\u1ED1i c\xF9ng \xF4ng ta \u0111\xE3 giao ph\xF3 con trai \xFAt L\u01B0u Ph\xFAc L\xE2m cho Ho\u1EAFc Quang.`,
  `Ho\xE0n th\xE0nh t\u1EA5t c\u1EA3 nh\u1EEFng vi\u1EC7c n\xE0y, H\xE1n V\u0169 \u0110\u1EBF L\u01B0u Tri\u1EC7t c\u0169ng \u0111i \u0111\u1EBFn cu\u1ED1i \u0111\u1EDDi.`,
  `H\xE1n Chi\xEAu \u0110\u1EBF L\u01B0u Ph\xFAc L\xE2m l\xE0 m\u1ED9t v\u1ECB ho\xE0ng \u0111\u1EBF \u0111\xE1ng \u0111\u01B0\u1EE3c k\u1EF3 v\u1ECDng,`,
  `\xF4ng ta tr\u1EBB tu\u1ED5i t\xE0i cao, r\u1EA5t gi\u1ED1ng H\xE1n V\u0169 \u0110\u1EBF khi c\xF2n tr\u1EBB,`,
  `d\u01B0\u1EDBi s\u1EF1 gi\xFAp \u0111\u1EE1 c\u1EE7a Ho\u1EAFc Quang, \u0111\xE3 qu\u1EA3n l\xFD \u0111\u1EA5t n\u01B0\u1EDBc r\u1EA5t t\u1ED1t,`,
  `l\xE0m d\u1ECBu \u0111i c\xE1c m\xE2u thu\u1EABn x\xE3 h\u1ED9i cu\u1ED1i th\u1EDDi H\xE1n V\u0169 \u0110\u1EBF.`,
  `Nh\u01B0ng \xF4ng ta ch\u1EC9 s\u1ED1ng \u0111\u1EBFn hai m\u01B0\u01A1i m\u1ED1t tu\u1ED5i th\xEC l\xE2m b\u1EC7nh qua \u0111\u1EDDi,`,
  `l\u1EA1i kh\xF4ng c\xF3 con trai.`,
  `L\xFAc n\xE0y, Ho\u1EAFc Quang \u0111\xE3 tr\u1EDF th\xE0nh quy\u1EC1n th\u1EA7n s\u1ED1 m\u1ED9t c\u1EE7a nh\xE0 H\xE1n,`,
  `\xF4ng ta \u0111\xE3 ch\u1ECDn m\u1ED9t ng\u01B0\u1EDDi ch\xE1u c\u1EE7a L\u01B0u Tri\u1EC7t l\xE0 L\u01B0u H\u1EA1 l\xEAn k\u1EBF v\u1ECB.`
];
