var CHINA_HISTORY_CH08_NH_NG_NG_I_TH_P_QU_C_P1_C9QIE0RFSLQ_TRANSLATIONS = [
  `Nh\xE0 \u0110\u01B0\u1EDDng c\xF3 t\u1ED5ng c\u1ED9ng hai m\u01B0\u01A1i m\u1ED1t v\u1ECB ho\xE0ng \u0111\u1EBF,`,
  `tr\u1EA3i qua hai tr\u0103m t\xE1m m\u01B0\u01A1i ch\xEDn n\u0103m.`,
  `H\xF4m nay ch\xFAng ta s\u1EBD chia hai m\u01B0\u01A1i m\u1ED1t v\u1ECB ho\xE0ng \u0111\u1EBF n\xE0y th\xE0nh ba nh\xF3m \u0111\u1EC3 n\xF3i:`,
  `nh\u1EEFng ng\u01B0\u1EDDi r\u1EF1c r\u1EE1 bu\u1ED5i \u0111\u1EA7u, nh\u1EEFng ng\u01B0\u1EDDi t\u1EA7m th\u01B0\u1EDDng \u1EDF gi\u1EEFa v\xE0 nh\u1EEFng ng\u01B0\u1EDDi \u0111i\xEAn r\u1ED3 cu\u1ED1i c\xF9ng.`,
  `Tr\u01B0\u1EDBc ti\xEAn h\xE3y n\xF3i v\u1EC1 \u0110\u01B0\u1EDDng Cao T\u1ED5 L\xFD Uy\xEAn,`,
  `nh\xE0 h\u1ECD L\xFD l\xE0 m\u1ED9t gia t\u1ED9c qu\xFD t\u1ED9c, m\u1ED7i th\u1EBF h\u1EC7 \u0111\u1EC1u c\xF3 ng\u01B0\u1EDDi l\xE0m quan l\u1EDBn.`,
  `Cu\u1ED1i th\u1EDDi nh\xE0 T\xF9y, T\xF9y D\u1EA1ng \u0110\u1EBF D\u01B0\u01A1ng Qu\u1EA3ng \u0111\xE3 c\u1EED L\xFD Uy\xEAn \u0111i tr\u1EA5n \xE1p c\xE1c cu\u1ED9c n\u1ED5i d\u1EADy,`,
  `\xD4ng ta \u0111\xE3 \u0111\xE1nh b\u1EA1i nhi\u1EC1u l\u1EF1c l\u01B0\u1EE3ng ch\u1ED1ng nh\xE0 T\xF9y th\xE0nh c\xF4ng,`,
  `v\xE0 kh\xF4ng ng\u1EEBng t\u0103ng c\u01B0\u1EDDng s\u1EE9c m\u1EA1nh b\u1EB1ng c\xE1ch thu nh\u1EADn c\xE1c \u0111\u1ED9i qu\xE2n b\u1EA1i tr\u1EADn.`,
  `C\xF9ng v\u1EDBi s\u1EF1 l\u1EDBn m\u1EA1nh c\u1EE7a th\u1EBF l\u1EF1c, c\u1ED9ng th\xEAm s\u1EF1 t\xE0n b\u1EA1o trong cai tr\u1ECB c\u1EE7a D\u01B0\u01A1ng Qu\u1EA3ng,`,
  `nh\xE0 T\xF9y \u0111\xE3 s\u1EDBm m\u1EE5c ru\u1ED7ng.`,
  `L\xFD Uy\xEAn n\u1EAFm b\u1EAFt th\u1EDDi c\u01A1, d\xF9ng danh ngh\u0129a ph\u1EBF b\u1ECF h\xF4n qu\xE2n,`,
  `c\u0169ng b\u1EAFt \u0111\u1EA7u ch\u1ED1ng \u0111\u1ED1i nh\xE0 T\xF9y.`,
  `N\u0103m 618 c\xF4ng nguy\xEAn,`,
  `T\xF9y D\u1EA1ng \u0110\u1EBF D\u01B0\u01A1ng Qu\u1EA3ng b\u1ECB t\u01B0\u1EDBng ph\u1EA3n lo\u1EA1n V\u0169 V\u0103n H\xF3a C\u1EADp th\u1EAFt c\u1ED5.`,
  `L\xFD Uy\xEAn sau khi nghe tin n\xE0y, li\u1EC1n l\u1EADp t\u1EE9c d\u1EABn qu\xE2n chi\u1EBFm Tr\u01B0\u1EDDng An,`,
  `l\xEAn ng\xF4i ho\xE0ng \u0111\u1EBF, th\xE0nh l\u1EADp nh\xE0 \u0110\u01B0\u1EDDng.`,
  `Sau \u0111\xF3, L\xFD Uy\xEAn d\u1EB9p y\xEAn t\u1EA5t c\u1EA3 th\u1EBF l\u1EF1c \u1EDF c\xE1c v\xF9ng,`,
  `Trung Qu\u1ED1c ch\xEDnh th\u1EE9c b\u01B0\u1EDBc v\xE0o th\u1EDDi k\u1EF3 cai tr\u1ECB c\u1EE7a nh\xE0 L\xFD \u0110\u01B0\u1EDDng.`,
  `M\u1EB7c d\xF9 L\xFD Uy\xEAn r\u1EA5t gi\u1ECFi \u0111\xE1nh tr\u1EADn, nh\u01B0ng \xF4ng ta c\xF3 th\u1EC3 m\u1EAFc ch\u1EE9ng r\u1ED1i lo\u1EA1n l\u1EF1a ch\u1ECDn.`,
  `Trong v\u1EA5n \u0111\u1EC1 ng\u01B0\u1EDDi th\u1EEBa k\u1EBF c\u1EE7a m\xECnh, \xF4ng ta lu\xF4n do d\u1EF1, thay \u0111\u1ED5i \xFD \u0111\u1ECBnh nhi\u1EC1u l\u1EA7n,`,
  `d\u1EABn \u0111\u1EBFn con trai l\u1EDBn c\u1EE7a \xF4ng ta l\xE0 L\xFD Ki\u1EBFn Th\xE0nh,`,
  `Con trai th\u1EE9 hai L\xFD Th\u1EBF D\xE2n v\xE0 con trai th\u1EE9 t\u01B0 L\xFD Nguy\xEAn C\xE1t th\u01B0\u1EDDng xuy\xEAn m\xE2u thu\u1EABn.`,
  `N\u0103m 626 sau C\xF4ng Nguy\xEAn,`,
  `L\xFD Th\u1EBF D\xE2n ph\xE1t \u0111\u1ED9ng s\u1EF1 bi\u1EBFn Huy\u1EC1n V\u0169 M\xF4n, gi\u1EBFt ch\u1EBFt anh c\u1EA3 L\xFD Ki\u1EBFn Th\xE0nh v\xE0 em trai th\u1EE9 t\u01B0 L\xFD Nguy\xEAn C\xE1t, nh\u1EEFng ng\u01B0\u1EDDi ch\u1ED1ng \u0111\u1ED1i \xF4ng,`,
  `c\u0169ng \xE9p cha \xF4ng l\xE0 L\xFD Uy\xEAn tho\xE1i v\u1ECB,`,
  `l\xEAn ng\xF4i ho\xE0ng \u0111\u1EBF, \u0111\u1ED5i ni\xEAn hi\u1EC7u th\xE0nh Trinh Qu\xE1n.`,
  `L\xFD Th\u1EBF D\xE2n t\u1EEB nh\u1ECF \u0111\xE3 theo L\xFD Uy\xEAn chinh chi\u1EBFn kh\u1EAFp n\u01A1i,`,
  `hi\u1EC3u r\xF5 n\u1ED7i kh\u1ED5 c\u1EE7a d\xE2n ch\xFAng, n\xEAn sau khi \xF4ng k\u1EBF v\u1ECB,`,
  `\u0111\u1ED1i n\u1ED9i tr\u1ECDng d\u1EE5ng hi\u1EC1n t\xE0i, ti\u1EBFn h\xE0nh c\u1EA3i c\xE1ch \u0111\u1EA5t n\u01B0\u1EDBc,`,
  `th\u1EF1c h\xE0nh ti\u1EBFt ki\u1EC7m, gi\u1EA3m thu\u1EBF m\xE1 lao d\u1ECBch,`,
  `b\xE1ch t\xEDnh \u0111\u01B0\u1EE3c ngh\u1EC9 ng\u01A1i, \u0111\u1EA5t n\u01B0\u1EDBc th\xE1i b\xECnh th\u1ECBnh v\u01B0\u1EE3ng.`,
  `\u0110\u1ED1i ngo\u1EA1i, \xF4ng chinh ph\u1EA1t Cao C\xE2u Ly, di\u1EC7t \u0110\xF4ng \u0110\u1ED9t Quy\u1EBFt,`,
  `t\u1EEB \u0111\xF3 x\xF3a b\u1ECF m\u1ED1i \u0111e d\u1ECDa c\u1EE7a c\xE1c d\xE2n t\u1ED9c T\xE2y V\u1EF1c \u0111\u1ED1i v\u1EDBi Trung Nguy\xEAn,`,
  `khi\u1EBFn \u0111\u1EBF qu\u1ED1c \u0110\u1EA1i \u0110\u01B0\u1EDDng ph\u1ED3n vinh t\u1ED9t b\u1EADc,`,
  `s\u1EED g\u1ECDi l\xE0 Trinh Qu\xE1n Chi Tr\u1ECB.`,
  `Sau khi \u0110\u01B0\u1EDDng Th\xE1i T\xF4ng L\xFD Th\u1EBF D\xE2n b\u0103ng h\xE0, con trai \xF4ng l\xE0 \u0110\u01B0\u1EDDng Cao T\xF4ng L\xFD Tr\u1ECB k\u1EBF v\u1ECB.`,
  `L\xFD Tr\u1ECB l\xE0 m\u1ED9t trong nh\u1EEFng ho\xE0ng \u0111\u1EBF t\u01B0\u01A1ng \u0111\u1ED1i b\xECnh th\u01B0\u1EDDng v\xE0o \u0111\u1EA7u th\u1EDDi nh\xE0 \u0110\u01B0\u1EDDng,`,
  `nh\u01B0ng \xF4ng l\u1EA1i c\xF3 m\u1ED9t ng\u01B0\u1EDDi v\u1EE3 c\u1EF1c k\u1EF3 t\xE0i gi\u1ECFi l\xE0 V\xF5 T\u1EAFc Thi\xEAn.`,
  `L\xFD Tr\u1ECB tr\u1ECB v\xEC kh\xF4ng c\xF3 c\xF4ng tr\u1EA1ng hay sai l\u1EA7m l\u1EDBn, \xF4ng k\u1EBF th\u1EEBa s\u1EF1 nghi\u1EC7p huy ho\xE0ng c\u1EE7a cha l\xE0 L\xFD Th\u1EBF D\xE2n,`,
  `\u0111\u1EA9y nh\xE0 \u0110\u01B0\u1EDDng ti\u1EBFn xa h\u01A1n \u0111\u1EBFn s\u1EF1 th\u1ECBnh v\u01B0\u1EE3ng.`,
  `L\xFD Tr\u1ECB v\xE0 V\xF5 T\u1EAFc Thi\xEAn c\xF3 t\u1ED5ng c\u1ED9ng s\xE1u ng\u01B0\u1EDDi con,`,
  `hai trai, b\u1ED1n g\xE1i, h\u1ECD l\u1EA7n l\u01B0\u1EE3t l\xE0 C\xF4ng ch\xFAa An \u0110\u1ECBnh T\u01B0,`,
  `Th\xE1i B\xECnh C\xF4ng ch\xFAa, L\xFD Ho\u1EB1ng,`,
  `L\xFD Hi\u1EC1n, L\xFD Hi\u1EC3n v\xE0 L\xFD \u0110\xE1n.`,
  `Cu\u1ED9c \u0111\u1EDDi V\xF5 T\u1EAFc Thi\xEAn c\xF3 th\u1EC3 g\u1ECDi l\xE0 truy\u1EC1n k\u1EF3, b\xE0 v\u1ED1n l\xE0 phi t\u1EA7n c\u1EE7a L\xFD Th\u1EBF D\xE2n.`,
  `Sau khi L\xFD Th\u1EBF D\xE2n qua \u0111\u1EDDi,`,
  `t\u1EA5t c\u1EA3 c\xE1c phi t\u1EA7n ch\u01B0a sinh con \u0111\u1EC1u ph\u1EA3i xu\u1EA5t gia l\xE0m ni c\xF4,`,
  `V\xF5 T\u1EAFc Thi\xEAn l\xE0 m\u1ED9t trong s\u1ED1 \u0111\xF3.`,
  `Tuy nhi\xEAn, con trai c\u1EE7a L\xFD Th\u1EBF D\xE2n l\xE0 L\xFD Tr\u1ECB l\u1EA1i ph\u1EA3i l\xF2ng ng\u01B0\u1EDDi m\u1EB9 k\u1EBF n\xE0y,`,
  `n\xEAn \u0111\xE3 \u0111\xF3n V\xF5 T\u1EAFc Thi\xEAn \u0111\xE3 xu\u1EA5t gia tr\u1EDF v\u1EC1 cung,`,
  `v\xE0 phong l\xE0m phi t\u1EA7n c\u1EE7a m\xECnh.`,
  `\u0110\u01B0\u01A1ng th\u1EDDi, L\xFD Tr\u1ECB c\xF3 V\u01B0\u01A1ng ho\xE0ng h\u1EADu.`,
  `V\xF5 T\u1EAFc Thi\xEAn \u0111\u1EC3 gi\xE0nh quy\u1EC1n, \u0111\xE3 t\u1EF1 tay gi\u1EBFt ch\u1EBFt con g\xE1i \u0111\u1EA7u l\xF2ng c\u1EE7a m\xECnh,`,
  `l\xE0 c\xF4ng ch\xFAa An \u0110\u1ECBnh T\u01B0 c\xF2n l\xE0 tr\u1EBB s\u01A1 sinh,`,
  `\u0111\u1ED5 t\u1ED9i cho V\u01B0\u01A1ng ho\xE0ng h\u1EADu.`,
  `V\u01B0\u01A1ng ho\xE0ng h\u1EADu b\u1ECB ph\u1EBF,`,
  `V\xF5 T\u1EAFc Thi\xEAn \u0111\u01B0\u1EE3c l\u1EADp l\xE0m ho\xE0ng h\u1EADu.`,
  `Sau \u0111\xF3, V\xF5 T\u1EAFc Thi\xEAn l\u1EA1i b\u1EAFt \u0111\u1EA7u can thi\u1EC7p v\xE0o tri\u1EC1u ch\xEDnh,`,
  `L\xFD Tr\u1ECB y\u1EBFu \u0111u\u1ED1i, kh\xF4ng nh\u1EEFng kh\xF4ng ng\u0103n c\u1EA3n,`,
  `sau n\xE0y c\xF2n m\u1EDDi V\xF5 T\u1EAFc Thi\xEAn c\xF9ng m\xECnh qu\u1EA3n l\xFD tri\u1EC1u ch\xEDnh.`,
  `T\u1EEB \u0111\xF3 tr\u1EDF \u0111i, V\xF5 T\u1EAFc Thi\xEAn th\xE2u t\xF3m \u0111\u1EA1i quy\u1EC1n.`,
  `Sau khi L\xFD Tr\u1ECB qua \u0111\u1EDDi, th\xE1i t\u1EED L\xFD Hi\u1EC3n k\u1EBF v\u1ECB,`,
  `n\u0103m m\u01B0\u01A1i t\u01B0 ng\xE0y sau \u0111\xE3 b\u1ECB m\u1EB9 gi\xE0 V\xF5 T\u1EAFc Thi\xEAn ph\u1EBF tru\u1EA5t,`,
  `gi\xE1ng l\xE0m L\u01B0 L\u0103ng V\u01B0\u01A1ng, \u0111u\u1ED5i ra kh\u1ECFi Tr\u01B0\u1EDDng An.`,
  `Sau \u0111\xF3 l\u1EADp L\xFD \u0110\xE1n l\xE0m ho\xE0ng \u0111\u1EBF, nh\u01B0ng c\u0169ng ch\u01B0a \u0111\u01B0\u1EE3c v\xE0i n\u0103m,`,
  `L\xFD \u0110\xE1n c\u0169ng b\u1ECB V\xF5 T\u1EAFc Thi\xEAn ph\u1EBF tru\u1EA5t,`,
  `B\xE0 t\u1EF1 x\u01B0ng \u0111\u1EBF, \u0111\u1ED5i qu\u1ED1c hi\u1EC7u l\xE0 Chu, tr\u1EDF th\xE0nh n\u1EEF ho\xE0ng \u0111\u1EBF \u0111\u1EA7u ti\xEAn v\xE0 duy nh\u1EA5t trong l\u1ECBch s\u1EED Trung Qu\u1ED1c.`,
  `Trong th\u1EDDi gian t\u1EA1i v\u1ECB, V\xF5 T\u1EAFc Thi\xEAn ti\u1EBFp t\u1EE5c th\u1EF1c hi\u1EC7n c\xE1c l\xFD t\u01B0\u1EDFng tr\u1ECB qu\u1ED1c c\u1EE7a L\xFD Th\u1EBF D\xE2n v\xE0 L\xFD Tr\u1ECB,`,
  `\u0111\u01B0a \u0111\u1EBF ch\u1EBF l\xEAn m\u1ED9t t\u1EA7m cao m\u1EDBi,`,
  `\u0111\u1EB7t n\u1EC1n m\xF3ng v\u1EEFng ch\u1EAFc cho th\u1EDDi k\u1EF3 Khai Nguy\xEAn th\u1ECBnh tr\u1ECB sau n\xE0y.`,
  `Sau khi V\xF5 T\u1EAFc Thi\xEAn qua \u0111\u1EDDi, b\xE0 kh\xF4ng giao l\u1EA1i quy\u1EC1n l\u1EF1c cho ng\u01B0\u1EDDi nh\xE0 h\u1ECD V\xF5,`,
  `m\xE0 tr\u1EA3 l\u1EA1i quy\u1EC1n ch\xEDnh tr\u1ECB cho ho\xE0ng t\u1ED9c L\xFD \u0110\u01B0\u1EDDng.`,
  `Sau \u0111\xF3, L\u01B0 L\u0103ng V\u01B0\u01A1ng L\xFD Hi\u1EC3n b\u1ECB ph\u1EBF tru\u1EA5t \u0111\u01B0\u1EE3c tri\u1EC7u v\u1EC1 Tr\u01B0\u1EDDng An,`,
  `m\u1ED9t l\u1EA7n n\u1EEFa l\xEAn ng\xF4i.`,
  `Tuy nhi\xEAn, s\u1ED1 ph\u1EADn c\u1EE7a L\xFD Hi\u1EC3n v\xF4 c\xF9ng bi th\u1EA3m,`,
  `kh\xF4ng l\xE2u sau khi l\xEAn ng\xF4i,`,
  `l\u1EA1i b\u1ECB Ho\xE0ng h\u1EADu Vi H\u1EADu c\u1EE7a m\xECnh \u0111\u1EA7u \u0111\u1ED9c ch\u1EBFt.`,
  `Vi H\u1EADu mu\u1ED1n h\u1ECDc theo V\xF5 T\u1EAFc Thi\xEAn, m\u1EDF ra m\u1ED9t k\u1EF7 nguy\xEAn n\u1EEF quy\u1EC1n kh\xE1c.`,
  `Sau khi \u0111\u1EA7u \u0111\u1ED9c L\xFD Hi\u1EC3n, b\xE0 l\u1EA1i l\u1EADp m\u1ED9t ng\u01B0\u1EDDi con trai c\u1EE7a L\xFD Hi\u1EC3n l\xE0 L\xFD Tr\u1ECDng M\u1EADu l\xE0m ho\xE0ng \u0111\u1EBF b\xF9 nh\xECn,`,
  `nh\u01B0ng V\xF5 T\u1EAFc Thi\xEAn l\xE0 duy nh\u1EA5t, Vi H\u1EADu kh\xF4ng ph\u1EA3i l\xE0 b\xE0 \u1EA5y th\u1EE9 hai.`,
  `Sau \u0111\xF3, con trai c\u1EE7a L\xFD \u0110\xE1n l\xE0 L\xFD Long C\u01A1 v\xE0 c\xF4 ru\u1ED9t c\u1EE7a \xF4ng l\xE0 C\xF4ng ch\xFAa Th\xE1i B\xECnh \u0111\xE3 ph\xE1t \u0111\u1ED9ng ch\xEDnh bi\u1EBFn,`,
  `Gi\u1EBFt Vi H\u1EADu, \u1EE7ng h\u1ED9 L\xFD \u0110\xE1n l\xEAn ng\xF4i.`,
  `C\xF3 th\u1EC3 L\xFD \u0110\xE1n t\xEDnh c\xE1ch kh\xE1 an ph\u1EADn, ho\u1EB7c c\xF3 l\u1EBD \xF4ng \u0111\xE3 ch\xE1n gh\xE9t nh\u1EEFng cu\u1ED9c tranh gi\xE0nh trong ho\xE0ng t\u1ED9c.`,
  `Ch\u1EB3ng bao l\xE2u sau, b\xE0 \u0111\xE3 nh\u01B0\u1EDDng ng\xF4i cho con trai m\xECnh l\xE0 L\xFD Long C\u01A1.`,
  `L\xFD Long C\u01A1 l\xEAn ng\xF4i, ni\xEAn hi\u1EC7u l\xE0 Khai Nguy\xEAn.`,
  `\xD4ng ch\xEDnh l\xE0 ng\u01B0\u1EDDi \u0111\xE3 t\u1EA1o n\xEAn th\u1EDDi k\u1EF3 Khai Nguy\xEAn th\u1ECBnh tr\u1ECB.`,
  `S\u1EF1 cai tr\u1ECB s\xE1ng su\u1ED1t c\u1EE7a L\xFD Long C\u01A1, c\xF9ng v\u1EDBi n\u1EC1n t\u1EA3ng v\u1EEFng ch\u1EAFc do L\xFD Th\u1EBF D\xE2n,`,
  `L\xFD Tr\u1ECB, V\xF5 T\u1EAFc Thi\xEAn \u0111\xE3 g\xE2y d\u1EF1ng tr\u01B0\u1EDBc \u0111\xF3,`,
  `khi\u1EBFn kinh t\u1EBF,`,
  `v\u0103n h\xF3a, ngh\u1EC7 thu\u1EADt, khoa h\u1ECDc k\u1EF9 thu\u1EADt c\u1EE7a nh\xE0 \u0110\u01B0\u1EDDng \u0111\u1EC1u ph\xE1t tri\u1EC3n r\u1EF1c r\u1EE1.`,
  `C\xE1c n\u01B0\u1EDBc l\xE1ng gi\u1EC1ng \u0111\u1EC1u \u0111\u1EBFn th\xF4ng th\u01B0\u01A1ng tri\u1EC1u c\u1ED1ng.`,
  `V\u0103n tr\u1ECB v\xF5 c\xF4ng \u0111\u1EC1u h\u01B0ng th\u1ECBnh.`,
  `Nh\xE0 \u0110\u01B0\u1EDDng tr\u1EDF th\xE0nh \u0111\u1EBF qu\u1ED1c h\xF9ng m\u1EA1nh nh\u1EA5t th\u1EBF gi\u1EDBi l\xFAc b\u1EA5y gi\u1EDD.`,
  `Tuy nhi\xEAn, v\xE0o cu\u1ED1i \u0111\u1EDDi, L\xFD Long C\u01A1 qu\xE1 s\u1EE7ng \xE1i Qu\xFD phi D\u01B0\u01A1ng Ng\u1ECDc Ho\xE0n.`,
  `Khi\u1EBFn nh\xE0 h\u1ECD D\u01B0\u01A1ng c\xF3 th\u1EBF l\u1EF1c.`
];
