var CHINA_HISTORY_CH08_NH_NG_NG_I_TH_P_QU_C_P2_C9QIE0RFSLQ_TRANSLATIONS = [
  `D\u01B0\u01A1ng Qu\u1ED1c Trung, anh h\u1ECD c\u1EE7a D\u01B0\u01A1ng Ng\u1ECDc Ho\xE0n, gi\u1EEF ch\u1EE9c t\u1EC3 t\u01B0\u1EDBng.`,
  `H\u1EAFn tham \xF4 x\xE3 h\u1ED9i,`,
  `b\xE0i tr\u1EEB ng\u01B0\u1EDDi ch\u1ED1ng \u0111\u1ED1i, l\xE0m lo\u1EA1n tri\u1EC1u ch\xEDnh,`,
  `x\xE3 h\u1ED9i d\u1EA7n d\u1EA7n xu\u1EA5t hi\u1EC7n xu h\u01B0\u1EDBng suy b\u1EA1i.`,
  `D\u01B0\u01A1ng Qu\xFD Phi c\xF2n c\xF3 m\u1ED9t ng\u01B0\u1EDDi con nu\xF4i l\xE0 An L\u1ED9c S\u01A1n,`,
  `l\xE0 m\u1ED9t ng\u01B0\u1EDDi H\u1ED3 lai,`,
  `\xF4ng ta l\xE0 t\u1ED5ng qu\u1EA3n ki\xEAm th\u1ED1ng l\u0129nh ba t\u1EC9nh,`,
  `n\u1EAFm gi\u1EEF binh quy\u1EC1n. An L\u1ED9c S\u01A1n c\xF3 th\xF9 v\u1EDBi D\u01B0\u01A1ng Qu\u1ED1c Trung,`,
  `khi th\u1EA5y D\u01B0\u01A1ng Qu\u1ED1c Trung l\xE0m lo\u1EA1n tri\u1EC1u ch\xEDnh,`,
  `li\u1EC1n l\u1EA5y danh ngh\u0129a th\u1EA3o ph\u1EA1t D\u01B0\u01A1ng Qu\u1ED1c Trung m\xE0 d\u1EA5y binh t\u1EA5n c\xF4ng Tr\u01B0\u1EDDng An.`,
  `L\xFD Long C\u01A1 b\xE8n v\u1ED9i v\xE0ng \u0111\u01B0a D\u01B0\u01A1ng Qu\xFD Phi ch\u1EA1y \u0111\u1EBFn M\xE3 Ng\xF4i Pha,`,
  `nay l\xE0 T\xE2n B\xECnh, Thi\u1EC3m T\xE2y.`,
  `C\xE1c t\u01B0\u1EDBng s\u0129 qu\xE2n T\xF9y c\u1EA3m th\u1EA5y t\u1EA5t c\u1EA3 l\xE0 l\u1ED7i c\u1EE7a D\u01B0\u01A1ng Ng\u1ECDc Ho\xE0n,`,
  `th\u1EBF l\xE0 b\u1EE9c b\xE1ch L\xFD Long C\u01A1 gi\u1EBFt D\u01B0\u01A1ng Ng\u1ECDc Ho\xE0n.`,
  `M\u1ED9t n\u0103m sau binh bi\u1EBFn,`,
  `An L\u1ED9c S\u01A1n g\u1EB7p h\u1ECDa t\u1EEB n\u1ED9i b\u1ED9, b\u1ECB con trai An Kh\xE1nh T\u1EF1 gi\u1EBFt.`,
  `Nh\u01B0ng cu\u1ED9c binh bi\u1EBFn v\u1EABn ch\u01B0a k\u1EBFt th\xFAc,`,
  `Sau khi An L\u1ED9c S\u01A1n ch\u1EBFt, ph\u1EA3i m\u1EA5t th\xEAm b\u1EA3y n\u0103m,`,
  `nh\xE0 \u0110\u01B0\u1EDDng m\u1EDBi d\u1EADp t\u1EAFt ho\xE0n to\xE0n lo\u1EA1n An S\u1EED n\u1ED5i ti\u1EBFng.`,
  `Cu\u1ED9c n\u1ED5i lo\u1EA1n n\xE0y \u0111\xE3 l\xE0m suy y\u1EBFu \u0111\xE1ng k\u1EC3 s\u1EE9c m\u1EA1nh c\u1EE7a nh\xE0 \u0110\u01B0\u1EDDng,`,
  `khi\u1EBFn nh\xE0 \u0110\u01B0\u1EDDng t\u1EEB th\u1ECBnh v\u01B0\u1EE3ng suy tho\xE1i,`,
  `v\xE0 tr\u1EF1c ti\u1EBFp d\u1EABn \u0111\u1EBFn c\u1EE5c di\u1EC7n c\xE1t c\u1EE9 phi\xEAn tr\u1EA5n sau n\xE0y.`,
  `M\u1ED9t lo\u1EA1t c\xE1c ho\xE0ng \u0111\u1EBF nh\xE0 \u0110\u01B0\u1EDDng gi\u1EEFa th\u1EDDi L\xFD Long C\u01A1 \u0111\u1EC1u s\u1EE7ng \xE1i ho\u1EA1n quan,`,
  `xa l\xE1nh hi\u1EC1n t\xE0i. T\u1EEB sau th\u1EDDi \u0110\u1EE9c T\xF4ng,`,
  `nhi\u1EC1u ho\xE0ng \u0111\u1EBF nh\xE0 \u0110\u01B0\u1EDDng sau n\xE0y ho\u1EB7c do ho\u1EA1n quan l\u1EADp,`,
  `ho\u1EB7c b\u1ECB ho\u1EA1n quan ph\u1EBF, th\u1EADm ch\xED b\u1ECB ho\u1EA1n quan gi\u1EBFt.`,
  `Ho\u1EA1n quan tr\u1EDF th\xE0nh ng\u01B0\u1EDDi n\u1EAFm quy\u1EC1n th\u1EF1c s\u1EF1 c\u1EE7a ho\xE0ng th\u1EA5t nh\xE0 \u0110\u01B0\u1EDDng l\xFAc b\u1EA5y gi\u1EDD,`,
  `\u0111i\u1EC1u n\xE0y khi\u1EBFn s\u1EF1 th\u1ED1ng tr\u1ECB c\u1EE7a \u0111\u1EBF qu\u1ED1c nh\xE0 \u0110\u01B0\u1EDDng c\xE0ng th\xEAm t\u1ED3i t\u1EC7,`,
  `c\xE1c d\xE2n t\u1ED9c ngo\u1EA1i bang nh\u01B0 Th\u1ED5 Ph\u1ED3n, H\u1ED3i H\u1ED9t li\xEAn t\u1EE5c \u0111e d\u1ECDa nh\xE0 \u0110\u01B0\u1EDDng.`,
  `\u0110\u1EBFn cu\u1ED1i th\u1EDDi, t\u1EEB th\u1EDDi M\u1EE5c T\xF4ng,`,
  `c\xE1c ho\xE0ng \u0111\u1EBF b\u1EAFt \u0111\u1EA7u th\u1ECBnh h\xE0nh vi\u1EC7c d\xF9ng thu\u1ED1c tr\u01B0\u1EDDng sinh.`,
  `Trong s\u1ED1 m\u01B0\u1EDDi v\u1ECB ho\xE0ng \u0111\u1EBF sau n\xE0y,`,
  `c\xF3 ba ng\u01B0\u1EDDi ch\u1EBFt v\xEC u\u1ED1ng \u0111an d\u01B0\u1EE3c.`,
  `C\xF9ng v\u1EDBi t\xECnh tr\u1EA1ng c\xE1t c\u1EE9 phi\xEAn tr\u1EA5n k\xE9o d\xE0i, khi\u1EBFn s\u1EF1 th\u1ED1ng tr\u1ECB c\u1EE7a nh\xE0 \u0110\u01B0\u1EDDng ch\u1EC9 c\xF2n tr\xEAn danh ngh\u0129a.`,
  `C\xE1c phi\xEAn tr\u1EA5n \u0111\u1ECBa ph\u01B0\u01A1ng tr\xEAn c\u1EA3 n\u01B0\u1EDBc t\u1EF1 n\u1EAFm quy\u1EC1n,`,
  `h\u1ECD \u0111\u1EC1u c\xF3 binh quy\u1EC1n ri\xEAng.`,
  `V\xEC v\u1EADy, ho\xE0ng t\u1ED9c cu\u1ED1i nh\xE0 \u0110\u01B0\u1EDDng ch\u1EE7 y\u1EBFu t\u1EADp trung d\u1EB9p lo\u1EA1n,`,
  `kh\xF4ng c\xF2n th\u1EDDi gian lo \u0111\u1EBFn ph\xE1t tri\u1EC3n kinh t\u1EBF,`,
  `v\u0103n h\xF3a v\xE0 c\xE1c m\u1EB7t kh\xE1c.`,
  `S\u1EE9c m\u1EA1nh qu\u1ED1c gia c\u1EE7a nh\xE0 \u0110\u01B0\u1EDDng ng\xE0y c\xE0ng suy y\u1EBFu,`,
  `kh\xF4ng th\u1EC3 g\u01B0\u1EE3ng d\u1EADy n\u1ED5i. Qu\u1ED1c gia suy y\u1EBFu, d\xE2n ch\xFAng kh\u1ED1n kh\u1ED5,`,
  `nh\u1EEFng cu\u1ED9c kh\u1EDFi ngh\u0129a n\xF4ng d\xE2n quen thu\u1ED9c l\u1EA1i xu\u1EA5t hi\u1EC7n,`,
  `nh\xE0 \u0110\u01B0\u1EDDng c\u0169ng kh\xF4ng ngo\u1EA1i l\u1EC7.`,
  `Cu\u1ED1i nh\xE0 \u0110\u01B0\u1EDDng x\u1EA3y ra c\xE1c cu\u1ED9c kh\u1EDFi ngh\u0129a n\xF4ng d\xE2n quy m\xF4 l\u1EDBn,`,
  `trong \u0111\xF3 m\u1EA1nh nh\u1EA5t l\xE0 kh\u1EDFi ngh\u0129a Ho\xE0ng S\xE0o.`,
  `Ho\xE0ng S\xE0o xu\u1EA5t th\xE2n t\u1EEB gia \u0111\xECnh bu\xF4n mu\u1ED1i.`,
  `Th\u1EDDi c\u1ED5 \u0111\u1EA1i, nh\u1EEFng ng\u01B0\u1EDDi b\xE1n mu\u1ED1i \u0111\u1EC1u r\u1EA5t gi\xE0u c\xF3,`,
  `v\xEC v\u1EADy Ho\xE0ng S\xE0o \u0111\xE3 \u0111\u01B0\u1EE3c gi\xE1o d\u1EE5c t\u1ED1t,`,
  `r\u1EA5t c\xF3 t\xE0i. Thu\u1EDF nh\u1ECF, Ho\xE0ng S\xE0o nhi\u1EC1u l\u1EA7n tham gia c\xE1c k\u1EF3 thi khoa b\u1EA3ng,`,
  `nh\u01B0ng \xF4ng \u0111\u1EC1u kh\xF4ng \u0111\u1ED7,`,
  `v\u1EEBa hay l\xFAc \u0111\xF3 c\xF3 ng\u01B0\u1EDDi t\xEAn V\u01B0\u01A1ng Ti\xEAn Chi ph\xE1t \u0111\u1ED9ng kh\u1EDFi ngh\u0129a n\xF4ng d\xE2n,`,
  `c\xF3 l\u1EBD v\xEC lu\xF4n thi tr\u01B0\u1EE3t, nh\u1EA5t th\u1EDDi kh\xF4ng cam l\xF2ng,`,
  `Ho\xE0ng S\xE0o li\u1EC1n tham gia kh\u1EDFi ngh\u0129a.`,
  `Sau khi V\u01B0\u01A1ng Ti\xEAn Chi ch\u1EBFt,`,
  `Ho\xE0ng S\xE0o \u0111\u01B0\u1EE3c b\u1EA7u l\xE0m th\u1EE7 l\u0129nh m\u1EDBi c\u1EE7a qu\xE2n kh\u1EDFi ngh\u0129a.`,
  `Sau hai m\u01B0\u01A1i l\u0103m n\u0103m \u0111\u1EA5u tranh,`,
  `cu\u1ED9c kh\u1EDFi ngh\u0129a c\u1EE7a Ho\xE0ng S\xE0o v\u1EABn k\u1EBFt th\xFAc b\u1EB1ng th\u1EA5t b\u1EA1i,`,
  `nh\u01B0ng cu\u1ED9c kh\u1EDFi ngh\u0129a quy m\xF4 l\u1EDBn v\xE0 k\xE9o d\xE0i ch\u01B0a t\u1EEBng c\xF3 n\xE0y,`,
  `\u0111\xE3 gi\xE1ng m\u1ED9t \u0111\xF2n ch\xED m\u1EA1ng tr\u1EF1c ti\u1EBFp v\xE0o ho\xE0ng th\u1EA5t nh\xE0 \u0110\u01B0\u1EDDng v\u1ED1n \u0111\xE3 lung lay.`,
  `N\u0103m 907 sau C\xF4ng nguy\xEAn,`,
  `Chu \xD4n, t\u01B0\u1EDBc L\u01B0\u01A1ng V\u01B0\u01A1ng, t\u1EEBng l\xE0 b\u1ED9 t\u01B0\u1EDBng c\u1EE7a Ho\xE0ng S\xE0o v\xE0 sau n\xE0y \u0111\u1EA7u h\xE0ng nh\xE0 \u0110\u01B0\u1EDDng, \u0111\xE3 \xE9p \u0110\u01B0\u1EDDng Ai \u0110\u1EBF tho\xE1i v\u1ECB,`,
  `T\u1EF1 l\u1EADp x\u01B0ng \u0111\u1EBF, l\u1EADp ra tri\u1EC1u L\u01B0\u01A1ng.`,
  `\u0110\u1EBFn \u0111\xE2y, nh\xE0 L\xFD \u0110\u01B0\u1EDDng di\u1EC7t vong,`,
  `Trung Qu\u1ED1c b\u01B0\u1EDBc v\xE0o m\u1ED9t th\u1EDDi k\u1EF3 chia c\u1EAFt kh\xE1c,`,
  `Ng\u0169 \u0110\u1EA1i Th\u1EADp Qu\u1ED1c. Ng\u0169 \u0110\u1EA1i Th\u1EADp Qu\u1ED1c nghe c\xF3 v\u1EBB h\u01A1i ph\u1EE9c t\u1EA1p,`,
  `th\u1EF1c ra n\xF3 th\u1EF1c s\u1EF1 h\u01A1i ph\u1EE9c t\u1EA1p, n\xEAn t\xF4i s\u1EBD n\xF3i m\u1ED9t c\xE1ch \u0111\u01A1n gi\u1EA3n nh\u1EA5t.`,
  `Ng\u0169 \u0110\u1EA1i l\xE0 n\u0103m tri\u1EC1u \u0111\u1EA1i l\u1EA7n l\u01B0\u1EE3t n\u1EAFm quy\u1EC1n \u1EDF v\xF9ng Trung Nguy\xEAn sau khi nh\xE0 \u0110\u01B0\u1EDDng di\u1EC7t vong,`,
  `\u0111\u1EA7u ti\xEAn l\xE0 H\u1EADu L\u01B0\u01A1ng, tri\u1EC1u \u0111\u1EA1i \u0111\xE3 l\u1EADt \u0111\u1ED5 nh\xE0 \u0110\u01B0\u1EDDng.`,
  `Cu\u1ED1i th\u1EDDi \u0110\u01B0\u1EDDng kh\xF4ng ph\u1EA3i t\xECnh tr\u1EA1ng c\xE1t c\u1EE9 phi\xEAn tr\u1EA5n r\u1EA5t nghi\xEAm tr\u1ECDng sao?`,
  `C\xE1c phi\xEAn v\u01B0\u01A1ng \u1EDF kh\u1EAFp n\u01A1i \u0111\u1EC1u r\u1EA5t c\xF3 th\u1EF1c l\u1EF1c,`,
  `L\xFD Kh\u1EAFc D\u1EE5ng, chi\u1EBFn h\u1EEFu n\u0103m x\u01B0a c\u1EE7a Chu \xD4n, \u0111\xE3 c\xE1t c\u1EE9 ph\u01B0\u01A1ng B\u1EAFc,`,
  `th\u1EF1c l\u1EF1c h\xF9ng m\u1EA1nh. Sau khi L\xFD Kh\u1EAFc D\u1EE5ng qua \u0111\u1EDDi, con trai \xF4ng l\xE0 L\xFD T\u1ED3n \xDAc k\u1EBF v\u1ECB,`,
  `L\xFD T\u1ED3n \xDAc t\u1EF1 x\u01B0ng \u0111\u1EBF, l\u1EADp ra H\u1EADu \u0110\u01B0\u1EDDng.`,
  `Ngay trong n\u0103m L\xFD T\u1ED3n \xDAc x\u01B0ng \u0111\u1EBF,`,
  `\xF4ng \u0111\xE3 di\u1EC7t H\u1EADu L\u01B0\u01A1ng,`,
  `tr\u1EDF th\xE0nh ch\xEDnh quy\u1EC1n th\u1EE9 hai c\u1EE7a Ng\u0169 \u0110\u1EA1i.`,
  `\u0110\u1EBFn \u0111\u1EDDi L\xFD T\xF2ng Khoa, v\u1ECB vua cu\u1ED1i c\xF9ng c\u1EE7a H\u1EADu \u0110\u01B0\u1EDDng,`,
  `\u0111\u1EA1i t\u01B0\u1EDBng Th\u1EA1ch K\xEDnh \u0110\u01B0\u1EDDng trong tri\u1EC1u c\xF3 quy\u1EC1n l\u1EF1c r\u1EA5t l\u1EDBn.`,
  `\u0110\u1EC3 chi\u1EBFm ng\xF4i, Th\u1EA1ch K\xEDnh \u0110\u01B0\u1EDDng \u0111\xE3 t\xF4n Gia Lu\u1EADt \u0110\u1EE9c Quang, th\u1EE7 l\u0129nh ng\u01B0\u1EDDi Khi\u1EBFt \u0110an k\xE9m \xF4ng m\u01B0\u1EDDi m\u1EA5y tu\u1ED5i, l\xE0m cha nu\xF4i,`,
  `v\xE0 \u0111\u1ED5i l\u1EA5y s\u1EF1 \u1EE7ng h\u1ED9 c\u1EE7a ng\u01B0\u1EDDi Khi\u1EBFt \u0110an v\u1EDBi c\xE1i gi\xE1 l\xE0 16 ch\xE2u Y\xEAn V\xE2n.`,
  `Cu\u1ED1i c\xF9ng, \xF4ng di\u1EC7t H\u1EADu \u0110\u01B0\u1EDDng v\xE0 l\u1EADp ra H\u1EADu T\u1EA5n, nh\u01B0ng kh\xF4ng l\xE2u sau \u0111\xF3,`,
  `ng\u01B0\u1EDDi Khi\u1EBFt \u0110an \u0111\xE3 quay l\u1EA1i \u0111\xE1nh con nu\xF4i c\u1EE7a \xF4ng,`,
  `di\u1EC7t H\u1EADu T\u1EA5n. Ng\u01B0\u1EDDi Khi\u1EBFt \u0110an kh\xF4ng c\xF3 h\u1EE9ng th\xFA v\u1EDBi tri\u1EC1u \u0111\xECnh Trung Nguy\xEAn,`,
  `sau khi c\u01B0\u1EDBp s\u1EA1ch ti\u1EC1n th\xEC b\u1ECF \u0111i.`,
  `V\xEC v\u1EADy, L\u01B0u Tri Vi\u1EC5n, m\u1ED9t \u0111\u1EA1i t\u01B0\u1EDBng c\u0169 c\u1EE7a H\u1EADu T\u1EA5n, \u0111\xE3 n\u1EAFm b\u1EAFt c\u01A1 h\u1ED9i n\xE0y,`,
  `trong th\u1EDDi k\u1EF3 tr\u1ED1ng tr\u1EA3i c\u1EE7a tri\u1EC1u \u0111\xECnh, \u0111\xE3 l\u1EADp ra H\u1EADu H\xE1n.`,
  `Sau khi \xF4ng m\u1EA5t,`,
  `con trai \xF4ng l\xE0 L\u01B0u Th\u1EEBa l\u1EA1i k\u1EBF v\u1ECB.`,
  `L\u01B0u Th\u1EEBa l\u1EA1i mu\u1ED1n ra tay v\u1EDBi \u0111\u1EA1i t\u01B0\u1EDBng Qu\xE1ch Uy trong tri\u1EC1u.`,
  `Qu\xE1ch Uy \u0111\xE3 ph\u1EA3n c\xF4ng, tr\u1EF1c ti\u1EBFp kh\u1EDFi binh di\u1EC7t H\u1EADu H\xE1n,`,
  `v\xE0 l\u1EADp ra H\u1EADu Chu.`,
  `Sau \u0111\xF3, H\u1EADu Chu b\u1ECB nh\xE0 T\u1ED1ng thay th\u1EBF.`,
  `Ng\u0169 \u0110\u1EA1i c\u1EE9 th\u1EBF k\u1EBFt th\xFAc vui v\u1EBB,`,
  `C\xF3 ph\u1EA3i b\u1EA1n c\u1EA3m th\u1EA5y v\u1EABn thi\u1EBFu g\xEC \u0111\xF3 kh\xF4ng?`,
  `Kh\xF4ng ph\u1EA3i c\xF2n Th\u1EADp Qu\u1ED1c sao?`,
  `Th\u1EADp Qu\u1ED1c th\u1EF1c ra kh\xF4ng ch\u1EC9 c\xF3 m\u01B0\u1EDDi qu\u1ED1c gia, n\xF3 l\xE0 t\xEAn g\u1ECDi chung c\u1EE7a h\u01A1n m\u01B0\u1EDDi qu\u1ED1c gia \u0111\u01B0\u1EE3c th\xE0nh l\u1EADp ngo\xE0i khu v\u1EF1c trung nguy\xEAn trong th\u1EDDi k\u1EF3 \u0111\xF3.`,
  `Nh\u1EEFng qu\u1ED1c gia n\xE0y kh\xF4ng n\u1EAFm gi\u1EEF quy\u1EC1n l\u1EF1c trung \u01B0\u01A1ng,`,
  `Cho n\xEAn, ch\xFAng t\u1ED3n t\u1EA1i \u0111\u1ED3ng th\u1EDDi v\u1EDBi Ng\u0169 \u0110\u1EA1i,`,
  `v\xE0 ch\u1EC9 \u0111\xF3ng vai tr\xF2 th\u1EE9 y\u1EBFu \u1EDF c\xE1c v\xF9ng xung quanh ngo\xE0i trung nguy\xEAn.`
];
