var CHINA_HISTORY_CH11_NH_MINH_P1_C9QIE0RFSLQ_TRANSLATIONS = [
  `Trong t\u1EA5t c\u1EA3 c\xE1c ho\xE0ng \u0111\u1EBF khai qu\u1ED1c, Chu Nguy\xEAn Ch\u01B0\u01A1ng c\xF3 l\u1EBD l\xE0 ng\u01B0\u1EDDi c\xF3 th\xE2n th\u1EBF bi th\u1EA3m nh\u1EA5t.`,
  `Cha \xF4ng l\xE0 m\u1ED9t n\xF4ng d\xE2n ch\xEDnh hi\u1EC7u,`,
  `Khi c\xF2n nh\u1ECF, \xF4ng t\u1EEBng ch\u0103n tr\xE2u cho nh\xE0 \u0111\u1ECBa ch\u1EE7.`,
  `D\xF9 cu\u1ED9c s\u1ED1ng gian kh\u1ED5, nh\u01B0ng \xEDt nh\u1EA5t c\u0169ng c\xF3 c\xE1i \u0103n,`,
  `Ng\xE0y th\xE1ng c\u1EE9 th\u1EBF tr\xF4i \u0111i b\xECnh l\u1EB7ng.`,
  `Ch\u1EB3ng bao l\xE2u, cu\u1ED9c s\u1ED1ng b\xECnh y\xEAn n\xE0y b\u1ECB ph\xE1 v\u1EE1.`,
  `M\u1ED9t n\u0103m n\u1ECD, qu\xEA h\u01B0\u01A1ng h\u1EA1n h\xE1n n\u1EB7ng,`,
  `Th\xEAm v\xE0o n\u1EA1n ch\xE2u ch\u1EA5u, h\u01A1n n\u1EEDa gia \u0111\xECnh h\u1ECD Chu ch\u1EBFt \u0111\xF3i.`,
  `Th\u1EF1c s\u1EF1 kh\xF4ng c\xF2n \u0111\u01B0\u1EDDng n\xE0o kh\xE1c, Chu Nguy\xEAn Ch\u01B0\u01A1ng \u0111\xE0nh ph\u1EA3i \u0111\u1EBFn Ho\xE0ng Gi\xE1c T\u1EF1 l\xE0m h\xF2a th\u01B0\u1EE3ng,`,
  `Nh\u01B0ng trong ch\xF9a c\u0169ng r\u1EA5t ngh\xE8o,`,
  `C\xE1c h\xF2a th\u01B0\u1EE3ng ph\u1EA3i \u0111i kh\u1EA5t th\u1EF1c \u0111\u1EC3 t\u1EF1 nu\xF4i s\u1ED1ng b\u1EA3n th\xE2n.`,
  `Th\u1EF1c ra l\xE0 \u0111i \u0103n xin.`,
  `L\xFAc n\xE0y, c\xE1c cu\u1ED9c kh\u1EDFi ngh\u0129a n\xF4ng d\xE2n cu\u1ED1i th\u1EDDi Nguy\xEAn \u0111ang di\u1EC5n ra \xE1c li\u1EC7t,`,
  `\u0110\u1EB7c bi\u1EC7t l\xE0 qu\xE2n Kh\u0103n \u0110\u1ECF.`,
  `Chu Nguy\xEAn Ch\u01B0\u01A1ng \u0111\xE3 \u0103n xin nhi\u1EC1u n\u0103m, n\u1EBFm tr\u1EA3i m\u1ECDi s\u1EF1 \u1EA5m l\u1EA1nh c\u1EE7a \u0111\u1EDDi ng\u01B0\u1EDDi,`,
  `C\u0169ng lo l\u1EAFng b\u1EA5t c\u1EE9 l\xFAc n\xE0o c\u0169ng c\xF3 th\u1EC3 b\u1ECB qu\xE2n Nguy\xEAn b\u1EAFt \u0111i,`,
  `T\xEDnh m\u1EA1ng kh\xF3 gi\u1EEF, l\u1EA1i nh\u1EADn \u0111\u01B0\u1EE3c th\u01B0 c\u1EE7a ng\u01B0\u1EDDi b\u1EA1n thu\u1EDF nh\u1ECF Thang H\xF2a m\u1EDDi \xF4ng tham gia ngh\u0129a qu\xE2n.`,
  `Do nhi\u1EC1u nguy\xEAn nh\xE2n kh\xE1c nhau,`,
  `Th\xFAc \u0111\u1EA9y Chu Nguy\xEAn Ch\u01B0\u01A1ng c\u1EDFi b\u1ECF c\xE0 sa, ki\xEAn quy\u1EBFt gia nh\u1EADp qu\xE2n Kh\u0103n \u0110\u1ECF c\u1EE7a Qu\xE1ch T\u1EED H\u01B0ng.`,
  `Do Chu l\xE3o gia t\xE1c chi\u1EBFn d\u0169ng m\xE3nh, \u0111\u1EA7u \xF3c l\u1EA1i r\u1EA5t linh ho\u1EA1t,`,
  `R\u1EA5t nhanh \u0111\xE3 \u0111\u01B0\u1EE3c Qu\xE1ch T\u1EED H\u01B0ng\u8CDE\u8BC6,`,
  `Th\u1EADm ch\xED c\xF2n g\u1EA3 con g\xE1i nu\xF4i M\xE3 th\u1ECB cho Chu Nguy\xEAn Ch\u01B0\u01A1ng,`,
  `Ch\xEDnh l\xE0 M\xE3 Ho\xE0ng h\u1EADu sau n\xE0y.`,
  `C\xE1nh c\u1EE7a Chu Nguy\xEAn Ch\u01B0\u01A1ng d\u1EA7n d\u1EA7n c\u1EE9ng c\xE1p,`,
  `Quy\u1EBFt \u0111\u1ECBnh t\u1EF1 m\xECnh l\u1EADp nghi\u1EC7p ri\xEAng,`,
  `D\xE1m l\xE0m. Cha v\u1EE3 Qu\xE1ch T\u1EED H\u01B0ng c\u0169ng \u1EE7ng h\u1ED9 \xF4ng.`,
  `Sau khi t\u1EF1 l\u1EADp, Chu Nguy\xEAn Ch\u01B0\u01A1ng nh\u01B0 \u201Chack\u201D v\u1EADy,`,
  `chi\xEAu m\u1ED9 r\u1EA5t nhi\u1EC1u binh l\xEDnh, k\u1EBFt giao r\u1EA5t nhi\u1EC1u b\u1EA1n b\xE8,`,
  `c\u0169ng \u0111\xE1nh th\u1EAFng r\u1EA5t nhi\u1EC1u tr\u1EADn.`,
  `Sau n\xE0y, Qu\xE1ch T\u1EED H\u01B0ng l\xE2m b\u1EC7nh qua \u0111\u1EDDi, nh\u1EDD n\u1ED7 l\u1EF1c c\u1EE7a b\u1EA3n th\xE2n v\xE0 t\xE0i nguy\xEAn t\u1EEB cha v\u1EE3 \u0111\u1EC3 l\u1EA1i,`,
  `Chu Nguy\xEAn Ch\u01B0\u01A1ng nhanh ch\xF3ng x\xE2y d\u1EF1ng \u0111\u01B0\u1EE3c m\u1ED9t \u0111\u1ED9i qu\xE2n h\xF9ng m\u1EA1nh.`,
  `L\xFAc n\xE0y, Chu Nguy\xEAn Ch\u01B0\u01A1ng kh\xF4ng v\u1ED9i b\xE0nh tr\u01B0\u1EDBng,`,
  `d\u01B0\u1EDBi s\u1EF1 ch\u1EC9 d\u1EABn c\u1EE7a m\u01B0u s\u0129 Chu Th\u0103ng, ki\xEAn \u0111\u1ECBnh v\u1EDBi ph\u01B0\u01A1ng ch\xE2m \u201Ccao tr\xFAc t\u01B0\u1EDDng\u201D,`,
  `ngh\u0129a l\xE0 t\u0103ng c\u01B0\u1EDDng ph\xF2ng b\u1ECB qu\xE2n s\u1EF1;`,
  `\u201Cqu\u1EA3ng t\xEDch l\u01B0\u01A1ng\u201D, ngh\u0129a l\xE0 ph\xE1t tri\u1EC3n s\u1EA3n xu\u1EA5t, t\xEDch tr\u1EEF l\u01B0\u01A1ng th\u1EF1c;`,
  `\u201Cho\xE3n x\u01B0ng v\u01B0\u01A1ng\u201D, ngh\u0129a l\xE0 kh\xF4ng v\u1ED9i x\u01B0ng \u0111\u1EBF s\u1EDBm,`,
  `tr\xE1nh g\xE2y qu\xE1 nhi\u1EC1u k\u1EBB th\xF9.`,
  `V\u1EDBi c\u01B0\u01A1ng l\u0129nh c\xE1ch m\u1EA1ng t\u1EF1 r\u0103n m\xECnh n\xE0y, l\xE3o Chu ti\u1EBFp t\u1EE5c \xE2m th\u1EA7m ph\xE1t tri\u1EC3n l\u1EF1c l\u01B0\u1EE3ng c\u1EE7a m\xECnh.`,
  `L\xFAc n\xE0y, ngo\xE0i Chu Nguy\xEAn Ch\u01B0\u01A1ng ra,`,
  `qu\xE2n kh\u1EDFi ngh\u0129a c\xF2n c\xF3 hai th\u1EBF l\u1EF1c c\u1EF1c k\u1EF3 l\u1EDBn m\u1EA1nh kh\xE1c,`,
  `l\xE0 Tr\u01B0\u01A1ng S\u0129 Th\xE0nh chi\u1EBFm gi\u1EEF m\u1ED9t v\xF9ng ph\xEDa \u0110\xF4ng v\xE0 Tr\u1EA7n H\u1EEFu L\u01B0\u1EE3ng n\u1EAFm gi\u1EEF b\xE1 quy\u1EC1n ph\xEDa T\xE2y.`,
  `Chu Nguy\xEAn Ch\u01B0\u01A1ng \u1EDF gi\u1EEFa hai ng\u01B0\u1EDDi h\u1ECD.`,
  `Tr\u01B0\u01A1ng Th\xE0nh v\xE0 qu\xE2n c\u1EE7a \xF4ng th\u1EA5y Chu Nguy\xEAn Ch\u01B0\u01A1ng th\u1EADt ng\u1EE9a m\u1EAFt,`,
  `t\xEDnh to\xE1n tr\u01B0\u1EDBc h\u1EBFt l\xE0 ph\u1EA3i h\u1EA1 g\u1EE5c \xF4ng, nh\u01B0ng h\u1ECD \u0111\xE3 t\xEDnh to\xE1n sai.`,
  `Chu Nguy\xEAn Ch\u01B0\u01A1ng ti\xEAn di\u1EC7t Tr\u1EA7n H\u1EEFu L\u01B0\u1EE3ng, k\u1EBB m\u1EA1nh nh\u1EA5t,`,
  `sau \u0111\xF3 \u0111\xE1nh Tr\u01B0\u01A1ng S\u0129 Th\xE0nh.`,
  `C\u1EE9 nh\u01B0 v\u1EADy, sau v\xE0i n\u0103m chinh chi\u1EBFn, Chu Nguy\xEAn Ch\u01B0\u01A1ng \u0111\xE3 ki\u1EC3m so\xE1t m\u1ED9t v\xF9ng \u0111\u1EA5t r\u1ED9ng l\u1EDBn, gi\xE0u c\xF3 nh\u1EA5t \u1EDF trung v\xE0 h\u1EA1 l\u01B0u s\xF4ng Tr\u01B0\u1EDDng Giang,`,
  `c\xF3 m\u1ED9t \u0111\u1ED9i qu\xE2n h\xF9ng m\u1EA1nh,`,
  `\u0111\xE3 c\xF3 \u0111\u1EE7 s\u1EE9c m\u1EA1nh \u0111\u1EC3 l\u1EADt \u0111\u1ED5 nh\xE0 Nguy\xEAn, th\u1ED1ng nh\u1EA5t \u0111\u1EA5t n\u01B0\u1EDBc.`,
  `N\u0103m 1368 sau C\xF4ng nguy\xEAn,`,
  `qu\xE2n Chu l\u1EA1i c\xF4ng chi\u1EBFm \u0110\u1EA1i \u0110\xF4 nh\xE0 Nguy\xEAn,`,
  `\u0111\xE1nh cho v\u1ECB ho\xE0ng \u0111\u1EBF cu\u1ED1i c\xF9ng c\u1EE7a nh\xE0 Nguy\xEAn ph\u1EA3i ch\u1EA1y v\u1EC1 th\u1EA3o nguy\xEAn.`,
  `Nh\xE0 Nguy\xEAn tuy\xEAn b\u1ED1 di\u1EC7t vong,`,
  `L\xE3o Chu \u0111\u0103ng c\u01A1, l\u1EADp ra nh\xE0 Minh.`,
  `Chu Nguy\xEAn Ch\u01B0\u01A1ng l\xE0 m\u1ED9t s\u1EF1 qu\u1EADt kh\u1EDFi th\u1EF1c s\u1EF1 c\u1EE7a k\u1EBB xu\u1EA5t th\xE2n th\u1EA5p k\xE9m, nh\u01B0ng s\u1EF1 tr\u1ED7i d\u1EADy c\u1EE7a \xF4ng kh\xF4ng ch\u1EC9 d\u1EF1a v\xE0o may m\u1EAFn.`,
  `Tr\u01B0\u1EDBc h\u1EBFt, \xF4ng hi\u1EC3u \u0111\u01B0\u1EE3c c\xE1ch m\u01B0\u1EE3n th\u1EBF,`,
  `M\u01B0\u1EE3n danh ngh\u0129a qu\xE2n Kh\u0103n \u0110\u1ECF \u0111\u1EC3 ph\xE1t tri\u1EC3n b\u1EA3n th\xE2n;`,
  `Th\u1EE9 hai, \xF4ng k\u1EBFt giao r\u1ED9ng r\xE3i v\u1EDBi nh\u1EEFng ng\u01B0\u1EDDi t\xE0i gi\u1ECFi, bi\u1EBFt c\xE1ch d\xF9ng ng\u01B0\u1EDDi.`,
  `L\u01B0u B\xE1 \xD4n, Thang H\xF2a, T\u1EEB \u0110\u1EA1t v\xE0 nh\u1EEFng c\xF4ng th\u1EA7n khai qu\u1ED1c kh\xE1c \u0111\xE3 c\xF3 \u1EA3nh h\u01B0\u1EDFng quan tr\u1ECDng \u0111\u1EBFn th\xE0nh c\xF4ng c\u1EE7a \xF4ng;`,
  `Ngo\xE0i ra, qu\xE2n \u0111\u1ED9i c\u1EE7a \xF4ng c\xF3 k\u1EF7 lu\u1EADt nghi\xEAm minh,`,
  `V\u1EEBa \u0111\u01B0\u1EE3c d\xE2n ch\xFAng \u1EE7ng h\u1ED9, v\u1EEBa \u0111\u01B0\u1EE3c \u0111\u1ECBa ch\u1EE7, h\xE0o ph\xFA \u1EE7ng h\u1ED9.`,
  `Thi\xEAn th\u1EDDi, \u0111\u1ECBa l\u1EE3i, nh\xE2n h\xF2a \u0111\xE3 t\u1EA1o n\xEAn th\xE0nh c\xF4ng c\u1EE7a Chu Nguy\xEAn Ch\u01B0\u01A1ng.`,
  `Gi\xE0nh \u0111\u01B0\u1EE3c giang s\u01A1n ch\u1EC9 l\xE0 kh\u1EDFi \u0111\u1EA7u,`,
  `L\xE0m th\u1EBF n\xE0o \u0111\u1EC3 cai tr\u1ECB l\u1EA1i l\xE0 m\u1ED9t th\u1EED th\xE1ch m\u1EDBi \u0111\u1ED1i v\u1EDBi Chu Nguy\xEAn Ch\u01B0\u01A1ng.`,
  `L\xE0 m\u1ED9t ho\xE0ng \u0111\u1EBF xu\u1EA5t th\xE2n t\u1EEB n\xF4ng d\xE2n, Chu Nguy\xEAn Ch\u01B0\u01A1ng kh\xF4ng qu\xEAn g\u1ED1c g\xE1c,`,
  `Sau khi l\xEAn ng\xF4i, \xF4ng khuy\u1EBFn kh\xEDch khai hoang, th\u1EF1c hi\u1EC7n ch\xEDnh s\xE1ch \u0111\u1ED3n \u0111i\u1EC1n,`,
  `X\xE2y d\u1EF1ng th\u1EE7y l\u1EE3i, gi\u1EA3m thu\u1EBF v\xE0 lao d\u1ECBch.`,
  `Nh\u1EEFng ch\xEDnh s\xE1ch c\xF3 l\u1EE3i cho d\xE2n n\xE0y \u0111\xE3 khi\u1EBFn nh\u1EEFng ng\u01B0\u1EDDi n\xF4ng d\xE2n b\u1ECB \xE1p b\u1EE9c tr\xE0n \u0111\u1EA7y hy v\u1ECDng v\xE0o cu\u1ED9c s\u1ED1ng.`,
  `Nh\xE0 Minh d\u1EA7n d\u1EA7n h\u1ED3i sinh t\u1EEB n\u1ED7i s\u1EE3 h\xE3i c\u1EE7a s\u1EF1 cai tr\u1ECB c\u1EE7a ngo\u1EA1i t\u1ED9c nh\xE0 Nguy\xEAn,`,
  `V\xE0 vi\u1EC7c Chu Nguy\xEAn Ch\u01B0\u01A1ng c\u0103m gh\xE9t quan l\u1EA1i tham nh\u0169ng c\u0169ng l\xE0 \u0111i\u1EC1u ai c\u0169ng bi\u1EBFt,`,
  `V\u1EABn c\xF2n li\xEAn quan \u0111\u1EBFn nh\u1EEFng tr\u1EA3i nghi\u1EC7m th\u1EDDi tr\u1EBB c\u1EE7a \xF4ng.`,
  `B\u1ECB b\xF3c l\u1ED9t \u0111\u1EBFn s\u1EE3 h\xE3i, \u0111\u1EC3 tr\u1EEBng tr\u1ECB tham quan, \xF4ng \u0111\xE3 ph\xE1t minh ra \u0111\u1EE7 lo\u1EA1i h\xECnh ph\u1EA1t kinh ho\xE0ng.`,
  `M\u1ED7i l\u1EA7n \u0111i\u1EC1u tra quan l\u1EA1i b\u1EA9n th\u1EC9u \u0111\u1EC1u ph\u1EA3i gi\u1EBFt ch\u1EBFt h\xE0ng v\u1EA1n ng\u01B0\u1EDDi,`,
  `V\xEC v\u1EADy \xF4ng c\u0169ng \u0111\u01B0\u1EE3c g\u1ECDi l\xE0 b\u1EA1o ch\xFAa.`,
  `M\u01B0\u1EE3n c\u1EDB tr\u1EA5n \xE1p tham nh\u0169ng, l\xE3o Chu \u0111\xE3 gi\u1EBFt s\u1EA1ch m\u1ED9t lo\u1EA1t c\xE1c anh em khai qu\u1ED1c \u0111\xE3 c\xF9ng m\xECnh g\xE2y d\u1EF1ng thi\xEAn h\u1EA1.`,
  `\u0110\u01B0\u01A1ng nhi\xEAn, kh\xF4ng ch\u1EC9 v\xEC h\u1ECD tham lam,`,
  `Quan tr\u1ECDng h\u01A1n l\xE0 l\xE3o Chu s\u1EE3 m\xECnh b\u1ECB \u0111o\u1EA1t quy\u1EC1n.`,
  `N\u1EBFu kh\xF4ng x\u1EED l\xFD nh\u1EEFng ng\u01B0\u1EDDi n\xE0y, nh\xE0 h\u1ECD Chu c\xF3 th\u1EC3 kh\xF4ng gi\u1EEF v\u1EEFng \u0111\u01B0\u1EE3c giang s\u01A1n.`,
  `Ngo\xE0i ra, Chu Nguy\xEAn Ch\u01B0\u01A1ng c\xF2n b\xE3i b\u1ECF ch\u1EE9c t\u1EC3 t\u01B0\u1EDBng,`,
  `Phong c\xE1c con trai c\u1EE7a m\xECnh l\xE0m phi\xEAn v\u01B0\u01A1ng,`,
  `M\u1ED7i ng\u01B0\u1EDDi \u0111\u1EC1u n\u1EAFm gi\u1EEF tr\u1ECDng binh,`,
  `N\u1EAFm ch\u1EAFc quy\u1EC1n l\u1EF1c qu\u1ED1c gia trong tay nh\xE0 h\u1ECD Chu c\u1EE7a h\u1ECD.`,
  `\u0110i\u1EC3m n\xE0y c\u0169ng \u0111\u1EB7t n\u1EC1n m\xF3ng cho vi\u1EC7c Chu \u0110\u1EC7 sau n\xE0y thu\u1EADn l\u1EE3i so\xE1n ng\xF4i.`,
  `Tuy nhi\xEAn, \u0111\xF3 l\xE0 chuy\u1EC7n sau n\xE0y.`,
  `\u0110\u1EBFn cu\u1ED1i \u0111\u1EDDi, Chu Nguy\xEAn Ch\u01B0\u01A1ng c\xF3 l\u1EBD \u0111\xE3 l\u1EA9n th\u1EA9n,`,
  `Ch\u1EE9ng hoang t\u01B0\u1EDFng b\u1ECB h\u1EA1i th\u01B0\u1EDDng xuy\xEAn t\xE1i ph\xE1t.`,
  `\xD4ng ta th\xE0nh l\u1EADp C\u1EA9m y v\u1EC7, m\u1ED9t c\u01A1 quan m\u1EADt v\u1EE5,`,
  `gi\xFAp ho\xE0ng \u0111\u1EBF theo d\xF5i v\xE0 t\u1ED1 gi\xE1c.`,
  `D\u01B0\u1EDBi s\u1EF1 gi\xE1m s\xE1t c\u1EE7a Chu Nguy\xEAn Ch\u01B0\u01A1ng,`,
  `nhi\u1EC1u \u0111\u1EA1i th\u1EA7n khai qu\u1ED1c ho\u1EB7c l\xE0 ch\u1EBFt kh\xF4ng to\xE0n th\xE2y,`,
  `ho\u1EB7c l\xE0 cu\u1ED1i \u0111\u1EDDi th\xEA th\u1EA3m.`,
  `Cu\u1ED1i c\xF9ng, c\xE1c c\xF4ng th\u1EA7n trung l\u01B0\u01A1ng \u0111\u1EC1u b\u1ECB gi\u1EBFt g\u1EA7n h\u1EBFt,`,
  `Chu Nguy\xEAn Ch\u01B0\u01A1ng c\u0169ng \u0111i \u0111\u1EBFn cu\u1ED1i cu\u1ED9c \u0111\u1EDDi.`,
  `N\u0103m 1398 sau C\xF4ng nguy\xEAn,`,
  `Chu Nguy\xEAn Ch\u01B0\u01A1ng l\xE2m b\u1EC7nh qua \u0111\u1EDDi,`,
  `h\u01B0\u1EDFng th\u1ECD b\u1EA3y m\u01B0\u01A1i tu\u1ED5i.`,
  `Sau khi Chu Nguy\xEAn Ch\u01B0\u01A1ng m\u1EA5t,`,
  `ch\xE1u c\u1EE7a \xF4ng l\xE0 Chu Do\xE3n V\u0103n k\u1EBF v\u1ECB.`,
  `C\xF3 nhi\u1EC1u con nh\u01B0 v\u1EADy, v\xEC sao l\u1EA1i ch\u1ECDn ch\xE1u?`,
  `B\u1EDFi v\xEC Chu Do\xE3n V\u0103n l\xE0 con trai c\u1EE7a Chu Ti\xEAu, tr\u01B0\u1EDFng t\u1EED c\u1EE7a Chu Nguy\xEAn Ch\u01B0\u01A1ng.`,
  `Chu Ti\xEAu v\u1ED1n l\xE0 th\xE1i t\u1EED, nh\u01B0ng \xF4ng \u1EA5y m\u1EA5t s\u1EDBm,`,
  `Tu\xE2n theo nguy\xEAn t\u1EAFc l\u1EADp \u0111\xEDch l\u1EADp tr\u01B0\u1EDFng (ch\u1ECDn con n\u1ED1i d\xF5i l\xE0 con d\xF2ng ch\xEDnh, l\u1EDBn nh\u1EA5t),`,
  `ng\xF4i b\xE1u r\u01A1i v\xE0o tay ch\xE1u tr\u01B0\u1EDFng c\u1EE7a ho\xE0ng \u0111\u1EBF.`,
  `Sau khi Chu Do\xE3n V\u0103n l\xEAn ng\xF4i, \xF4ng c\u1EA3m th\u1EA5y quy\u1EC1n l\u1EF1c c\u1EE7a c\xE1c phi\xEAn v\u01B0\u01A1ng th\xFAc th\xFAc qu\xE1 l\u1EDBn,`,
  `\u0111e d\u1ECDa \u0111\u1EBFn m\xECnh,`,
  `n\xEAn \xF4ng nhanh ch\xF3ng b\u1EAFt \u0111\u1EA7u c\u1EAFt gi\u1EA3m phi\xEAn v\u01B0\u01A1ng.`
];
