// src/lib/mcp/tools/list-dictation-videos.ts
var list_dictation_videos_default = defineTool3({
  name: "list_dictation_videos",
  title: "List dictation videos",
  description: "Browse HSK Hub's Chinese dictation (\u542C\u5199) library: title, level, topic category, duration and number of practice sentences.",
  inputSchema: {
    query: z3.string().optional().describe("Filter by title text (Chinese or Vietnamese)."),
    level: z3.string().optional().describe("Level filter: beginner, intermediate or advanced."),
    category: z3.string().optional().describe("Category filter: news, vlog, cartoon, drama, education, history, discovery, other."),
    limit: z3.number().int().optional().describe("Maximum number of videos to return (default 25, max 100).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, level, category, limit }) => {
    const max = Math.min(Math.max(limit ?? 25, 1), 100);
    const q = (query ?? "").trim().toLowerCase();
    const rows = DICTATION_VIDEOS.filter((v) => {
      if (level && v.level !== level) return false;
      if (category && v.category !== category) return false;
      if (q && !(v.title.toLowerCase().includes(q) || (v.titleVi ?? "").toLowerCase().includes(q))) return false;
      return true;
    }).slice(0, max).map((v) => ({
      id: v.id,
      title: v.title,
      titleVi: v.titleVi ?? null,
      level: v.level,
      category: v.category,
      durationLabel: v.durationLabel ?? null,
      sentenceCount: v.segments?.length ?? 0,
      youtubeUrl: `https://www.youtube.com/watch?v=${v.youtubeId}`
    }));
    return {
      content: [
        {
          type: "text",
          text: rows.length === 0 ? "No dictation video matched the filters." : rows.map(
            (r) => `${r.title}${r.titleVi ? ` (${r.titleVi})` : ""} \u2014 ${r.level}/${r.category} \xB7 ${r.sentenceCount} sentences${r.durationLabel ? ` \xB7 ${r.durationLabel}` : ""} \xB7 id=${r.id}`
          ).join("\n")
        }
      ],
      structuredContent: { count: rows.length, videos: rows }
    };
  }
});

// src/lib/mcp/tools/get-dictation-transcript.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z4 } from "npm:zod@^3.25.76";
var get_dictation_transcript_default = defineTool4({
  name: "get_dictation_transcript",
  title: "Get dictation transcript",
  description: "Return the sentence-by-sentence Chinese transcript (with Vietnamese translation when available) of one dictation video from HSK Hub. Use list_dictation_videos first to get the video id.",
  inputSchema: {
    videoId: z4.string().describe("The dictation entry id returned by list_dictation_videos."),
    from: z4.number().int().optional().describe("First sentence index to return (0-based, default 0)."),
    count: z4.number().int().optional().describe("How many sentences to return (default 40, max 200).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ videoId, from, count }) => {
    const video = DICTATION_VIDEOS.find((v) => v.id === videoId || v.youtubeId === videoId);
    if (!video) {
      return { content: [{ type: "text", text: `No dictation video with id "${videoId}".` }], isError: true };
    }
    const segments = video.segments ?? [];
    const start = Math.max(from ?? 0, 0);
    const take = Math.min(Math.max(count ?? 40, 1), 200);
    const slice = segments.slice(start, start + take).map((s, i) => ({
      index: start + i,
      start: s.start,
      duration: s.dur,
      hanzi: s.hanzi,
      vi: video.translations?.[start + i] ?? null
    }));
    return {
      content: [
        {
          type: "text",
          text: slice.length === 0 ? `"${video.title}" has no prepared transcript in this range.` : `${video.title} (${slice.length}/${segments.length} sentences)
` + slice.map((s) => `${s.index + 1}. [${s.start.toFixed(1)}s] ${s.hanzi}${s.vi ? `
   ${s.vi}` : ""}`).join("\n")
        }
      ],
      structuredContent: {
        videoId: video.id,
        title: video.title,
        totalSentences: segments.length,
        sentences: slice
      }
    };
  }
});

