// src/lib/mcp/tools/get-province.ts
var get_province_default = defineTool5({
  name: "get_province",
  title: "Explore a Chinese province",
  description: "Look up one of China's 34 provincial-level units in HSK Hub's \u63A2\u7D22\u4E2D\u56FD dataset: capital, population, area, cuisine, landmarks, universities and the Chinese reading passage when available. Omit the name to list all units.",
  inputSchema: {
    name: z5.string().optional().describe("Province name in Chinese, pinyin or Vietnamese. Omit to list every unit.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ name }) => {
    const q = (name ?? "").trim().toLowerCase();
    if (!q) {
      const list = PROVINCES.map((p2) => `${p2.nameCn} (${p2.nameVn}) \u2014 ${p2.kind}${p2.capital ? ` \xB7 th\u1EE7 ph\u1EE7 ${p2.capital}` : ""}`);
      return {
        content: [{ type: "text", text: list.join("\n") }],
        structuredContent: { count: PROVINCES.length, provinces: PROVINCES.map((p2) => ({ id: p2.id, nameCn: p2.nameCn, nameVn: p2.nameVn, kind: p2.kind })) }
      };
    }
    const p = PROVINCES.find((x) => x.nameCn.includes(q) || x.geoName.includes(q)) ?? PROVINCES.find(
      (x) => x.namePinyin.toLowerCase().includes(q) || x.nameVn.toLowerCase().includes(q) || x.id.toLowerCase() === q
    );
    if (!p) {
      return { content: [{ type: "text", text: `No provincial-level unit matched "${name}".` }], isError: true };
    }
    const h = p.highlights ?? {};
    const lines = [
      `${p.nameCn} / ${p.geoName} (${p.nameVn}) \u2014 ${p.kind}`,
      p.capital ? `Th\u1EE7 ph\u1EE7: ${p.capital}${p.capitalVn ? ` (${p.capitalVn})` : ""}` : null,
      p.population ? `D\xE2n s\u1ED1: ${p.population}` : null,
      p.area ? `Di\u1EC7n t\xEDch: ${p.area}` : null,
      p.majorCities?.length ? `Th\xE0nh ph\u1ED1 l\u1EDBn: ${p.majorCities.map((c) => `${c.cn} (${c.vn})`).join(", ")}` : null,
      h.cuisine?.length ? `\u1EA8m th\u1EF1c: ${h.cuisine.join(", ")}` : null,
      h.landmarks?.length ? `\u0110\u1ECBa danh: ${h.landmarks.join(", ")}` : null,
      h.universities?.length ? `\u0110\u1EA1i h\u1ECDc: ${h.universities.join(", ")}` : null,
      h.industries?.length ? `Kinh t\u1EBF: ${h.industries.join(", ")}` : null,
      h.famousPeople?.length ? `Nh\xE2n v\u1EADt: ${h.famousPeople.join(", ")}` : null,
      h.historical ? `L\u1ECBch s\u1EED: ${h.historical}` : null,
      p.reading ? `
B\xE0i \u0111\u1ECDc:
${p.reading.cn}

D\u1ECBch:
${p.reading.vn}` : null
    ].filter(Boolean);
    return {
      content: [{ type: "text", text: lines.join("\n") }],
      structuredContent: { province: p }
    };
  }
});

// src/lib/mcp/tools/list-saved-words.ts
import { defineTool as defineTool6 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z6 } from "npm:zod@^3.25.76";

// src/lib/mcp/supabase.ts
import { createClient } from "npm:@supabase/supabase-js@^2.103.3";
function supabaseForUser(ctx) {
  return createClient(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}
var notAuthenticated = {
  content: [{ type: "text", text: "Not authenticated. Sign in to HSK Hub through the OAuth flow first." }],
  isError: true
};

// src/lib/mcp/tools/list-saved-words.ts
var list_saved_words_default = defineTool6({
  name: "list_saved_words",
  title: "List my saved words",
  description: "List the signed-in user's saved vocabulary notebook (\u751F\u8BCD\u672C) entries from HSK Hub.",
  inputSchema: {
    limit: z6.number().int().optional().describe("Maximum number of entries to return (default 50, max 200).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ limit }, ctx) => {
    if (!ctx.isAuthenticated()) return notAuthenticated;
    const max = Math.min(Math.max(limit ?? 50, 1), 200);
    const { data, error } = await supabaseForUser(ctx).from("saved_words").select("id, text, note, created_at").order("created_at", { ascending: false }).limit(max);
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    const rows = data ?? [];
    return {
      content: [
        {
          type: "text",
          text: rows.length === 0 ? "\u751F\u8BCD\u672C is empty." : rows.map((r) => `${r.text}${r.note ? ` \u2014 ${r.note}` : ""}`).join("\n")
        }
      ],
      structuredContent: { count: rows.length, words: rows }
    };
  }
});

// src/lib/mcp/tools/save-word.ts
import { defineTool as defineTool7 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z7 } from "npm:zod@^3.25.76";
var save_word_default = defineTool7({
  name: "save_word",
  title: "Save a word to my notebook",
  description: "Add a Chinese word, phrase or sentence (with an optional note) to the signed-in user's HSK Hub \u751F\u8BCD\u672C.",
  inputSchema: {
    text: z7.string().trim().describe("The Chinese word, phrase or sentence to save."),
    note: z7.string().optional().describe("Optional note, meaning or translation.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: true, openWorldHint: false },
  handler: async ({ text, note }, ctx) => {
    if (!ctx.isAuthenticated()) return notAuthenticated;
    const value = text.trim();
    if (!value) return { content: [{ type: "text", text: "text must not be empty." }], isError: true };
    const { data, error } = await supabaseForUser(ctx).from("saved_words").upsert(
      { user_id: ctx.getUserId(), text: value, note: note?.trim() || null },
      { onConflict: "user_id,text" }
    ).select("id, text, note, created_at").maybeSingle();
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: `Saved "${value}" to \u751F\u8BCD\u672C.` }],
      structuredContent: { word: data }
    };
  }
});

// src/lib/mcp/tools/list-exam-results.ts
import { defineTool as defineTool8 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z8 } from "npm:zod@^3.25.76";
var list_exam_results_default = defineTool8({
  name: "list_exam_results",
  title: "List my mock exam results",
  description: "List the signed-in user's HSK mock exam results from HSK Hub, newest first, with score per section.",
  inputSchema: {
    limit: z8.number().int().optional().describe("Maximum number of results to return (default 20, max 100).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ limit }, ctx) => {
    if (!ctx.isAuthenticated()) return notAuthenticated;
    const max = Math.min(Math.max(limit ?? 20, 1), 100);
    const { data, error } = await supabaseForUser(ctx).from("exam_results").select("exam_id, exam_title, section, total_questions, correct_answers, score_percent, elapsed_seconds, submitted_at").order("submitted_at", { ascending: false }).limit(max);
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    const rows = data ?? [];
    return {
      content: [
        {
          type: "text",
          text: rows.length === 0 ? "No mock exam results yet." : rows.map(
            (r) => `${new Date(r.submitted_at).toISOString().slice(0, 10)} \xB7 ${r.exam_title} \xB7 ${r.section}: ${r.correct_answers}/${r.total_questions} (${r.score_percent}%)`
          ).join("\n")
        }
      ],
      structuredContent: { count: rows.length, results: rows }
    };
  }
});

